pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 1000.0;
    } else if post_residual <= 15 {
        score += 300.0;
    } else if post_residual <= 25 {
        score += 80.0;
    }

    // Dead space relative to the lookahead item: if the leftover cannot
    // hold the next item, the gap is likely to become permanent waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Perfect fit reward: leaving exactly zero or a near-perfect fill.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight-fit reward: using most of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fill_ratio;

    // Open-bin pressure: penalize spreading across many open bins,
    // but relax pressure as the stream progresses (endgame consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (8.0 * (1.0 - progress) + 3.0);

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    // An empty bin wastes its full residual; penalize unless open bins
    // are nearly full on average.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let pressure = mean_fill / bin_capacity as f64;
        // Reward opening a new bin only when existing bins are > 70% full.
        if pressure > 0.7 {
            score -= 120.0 * (pressure - 0.7);
        } else {
            score += 150.0 * (0.7 - pressure);
        }
        // If the item would leave severe dead space in every fitting bin,
        // opening a fresh bin becomes more attractive.
        if post_residual < 10 && post_residual > 0 {
            score -= 200.0;
        }
    }

    // Mild coupling with mean residual: prefer bins whose residual is
    // close to the item (best-fit flavor) relative to fleet average.
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.2 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Tightness ratio: reward high fill fraction of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 8.0;
    }
    // If next item would be blocked by the dead space left here, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: keep it attractive unless an open bin is a great fit.
    if bin_residual == bin_capacity {
        // Base preference for new bin, modulated by how bad existing fits are.
        score = 8.0 + 0.2 * open_bins_count as f64;
        if post_residual == 0 { score = -100.0; } // unreachable, keeps type
        // If the only fitting bin is this new one, opening is fine.
        if fitting_bins_count <= 1 {
            score -= 5.0;
        }
    }

    // Stream progression: early on, be more willing to open bins (exploration).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    // Mean residual coupling: if open bins are already slack, avoid adding more slack.
    if bin_residual != bin_capacity && (post_residual as f64) > mean_residual {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
