            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 25.0;
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 120.0;
            score += 1.0 * mean_residual;
            score += 150.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            // Dead-space control: penalize new bins opened for large items more strongly
            let frac = item / cap;
            if frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            }
            // Discourage a new bin whose leftover cannot hold the next item
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
            }
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
