            // next item fits: strong reward, scaled by how snug the fit is
            let slack = (pr - next_item_size) as f64;
            score -= 40.0;
            if slack < 10.0 {
                score -= 30.0; // near-perfect chain
            }
            if (pr - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize more if this was the only fitting bin
            score += 15.0;
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

