                } else if post > 0.0 && post < 5.0 {
                    score -= 90.0;
                }
            }
            // discourage new bin whose leftover can't hold the next item
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                let deadness = (next_item_size - post_residual) as f64 / cap;
                score += 55.0 * deadness * (1.0 + progress);
            }
            // reward near-perfect opening fits
            if item / cap > 0.9 {
                score -= 30.0 * (item / cap - 0.9) * 10.0;
            }
            // avoid opening a bin when an existing bin would be left with an unusable sliver
            if fitting_bins_count > 0 && mean_residual < 10.0 && post_residual > 20 {
                score += 35.0;
            }
        }
    } else {
        // open-bin branch: reward tiny residuals harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item even if it doesn't fit now
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals few items can fill
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
        // combined feature: extra tightness pressure when many bins compete for the item
        if fitting_bins_count > 3 {
            score += 6.0 * (post / cap) * (1.0 - progress);
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..=10) are nearly unusable for future
    // items (sizes 1..=100 but typically chunky), so punish them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 20.0;
    }

    // Reward tight fits: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // residual that cannot hold the next item is more likely dead space
        score += 10.0;
    }

    // Open-bin pressure: discourage spreading across too many bins, but a
    // brand-new bin candidate (residual == capacity) is exempt since opening
    // it does not add pressure beyond itself.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.5;
    }

    // Slight preference for fuller bins relative to the fleet mean residual.
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
