    // 2-step lookahead: chain rewards scaled by how exact the fit is
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0; // exact 2-step chain closure
            }
        } else {
            // next item cannot follow: dead-space penalty grows with gap
            let gap = nxt - post;
            score += 40.0 * (nxt / cap);
            score += 0.5 * gap * gap;
        }
    }

    // Penalize stranded slivers that few future items can use
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }
    if post_residual > 0 && next_item_size > post_residual {
        let slack = post / cap;
        score += 25.0 * slack * slack;
    }

    // Last-chance bonus: only fitting bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Avoid wasting large-residual bins on small items when mean residual is high
    if (bin_residual as f64) > mean_residual + 30.0 && item_size < 40 {
        score += 100.0;
    }

    // Slight preference for filling tighter bins relative to capacity
    score += (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate gating
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0; // no open bin fits: definitely open a new one
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
