                        } else if post3 <= 4 {
                            score -= 4.0;
                        }
                    }
                }
                // triple-fill: item + 2x next nearly fills bin
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 14.0;
                }
                // near-mean alignment
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                // tiny unusable residual penalty
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
                // large leftover is still usable
                if new_post > 18 && (new_post as f64) > nx * 2.5 {
                    score += 6.0;
                }
                // usability vs mean residual — dead-space control late in stream
                if progress > 0.3 && (new_post as f64) < mean_residual * 0.5 && new_post < 12 {
                    score += 5.0 * progress;
                }
            }
            // next item fits elsewhere: safe to leave residual here
            let next_fits_elsewhere = mean_residual >= nx && open_bins_count > 1;
            if next_fits_elsewhere && new_post > 0 {
                score += 3.0;
            } else if !next_fits_elsewhere {
                score -= 12.0;
            }
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap * cap;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // Alignment with mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: neutral base so it only wins when open bins score poorly
    if bin_residual == bin_capacity {
        score = 57.0 + (pr / cap) * 10.0;
        if post_residual >= 56 {
            score -= 12.0;
        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if post_residual >= 96 {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 2000.0;
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 16.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // near-perfect pair fill with next item: prefer this bin over a new one
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.45 {
            score -= 6.0;
        }
        // aggregate-space pressure: if total open slack is large, prefer reusing bins
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                score += 9.0;
            }
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            score -= 6.0;
        }
        if progress > 0.55 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 5.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (post_residual as f64 - it) / cap;
            if snug_fit <= 0.12 {
                score += 20.0;
            }
            if snug_fit > 0.12 && snug_fit <= 0.30 && open_bins_count > 2 {
                score += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            score += 6.0;
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 60.0;
        }
        // small item into a fresh bin wastes capacity unless stream is early
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            score += 12.0;
        }
        // MUTATION: scale new-bin base with fitting count and mean slack
        score += 60.0 * (fitting_bins_count as f64).min(5.0);
        score += 80.0 * progress * (mean_residual / cap);
        // MUTATION: strong next-item snugness reward on open bins (from best heuristic)
        if next_item_size > 0 && next_item_size <= post_residual {
            let diff = (pr - next_item_size as f64).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else if next_item_size > 0 {
            score += 40.0 * (next_item_size as f64 / cap);
            score += 30.0 * ((pr - next_item_size as f64) / cap);
        }
        // MUTATION: consolidate open slack late in the stream
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits tightly into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Next item does NOT fit after this placement: penalize proportionally to wasted opportunity.
    if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Reward bins that are tighter than the mean residual (consolidating waste).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score -= 10.0 * (mean_residual - residual_f) / bin_capacity as f64;
    }

    // Penalize leaving tiny unusable dead space (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are quite full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        score = 40.0 - 30.0 * avg_fill;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // a fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (post_residual as f64 - next_item_size as f64).min(20.0);
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer keeping large residual bins for large items
    if item_size >= 50 {
        score += 0.2 * (post_residual as f64);
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score += 150.0 / scarcity;
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual >= next_item_size {
            score -= 100.0; // fresh bin chains well with next item
        }
    }

    // Late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping in progress
    let mut score = pr * (0.9 + 0.6 * progress * progress);

    // Quadratic penalty for medium dead space (unusable gaps), smooth via progress
    let dead = norm_pr * (1.0 - norm_pr);
    score += 60.0 * dead * (0.5 + 0.5 * progress);

    // Reward tight fits: subtract when post_residual is small
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.6 + 0.4 * progress);

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 25.0 * (1.0 - (next_item_size as f64) / cap) * (1.0 - progress * 0.5);
        } else {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open relative to stream length (encourage consolidation early)
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // Mean residual coupling: penalize bins far from the mean residual
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate handling: make empty bins moderately attractive only early or for large items
    if bin_residual == bin_capacity {
        let attract = 0.35 * cap * (1.0 - progress) + 0.5 * item_size as f64;
        score = pr - attract + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tight = post_residual as f64 / bin_capacity as f64;
        score += tight * tight * 120.0;
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or current residuals are all poor fits.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        let poor_state = if mean_residual > 0.0 { (mean_residual - item_size as f64) / mean_residual.max(1.0) } else { 0.0 };
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = 40.0 - big_item * 30.0 - poor_state.max(0.0) * 25.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Lookahead: reward bins whose leftover could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (mean_residual / bin_capacity as f64);

    // Penalize spreading across many open bins when residuals are small.
    if (bin_residual as f64) < mean_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 12.0 * coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize leaving dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) * (0.5 + progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - norm_pr) * (0.5 + progress);
    }

    // Slight preference to fill bins when many bins are open
    score -= 2.0 * (1.0 - norm_pr) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Smooth mean-residual alignment bonus
    let align = (mean_residual - pr).abs() / cap;
    score -= 3.0 * (1.0 - align).max(0.0) * progress;

    // New-bin candidate: penalize mildly unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 - 18.0 * norm_pr.min(1.0) * 0.0; // empty bin: norm_pr=1
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post;

    // Dead-space classing (perfect fills rewarded more aggressively)
    let class: f64 = if post_residual == 0 { -68.0 }
        else if post_residual <= 5 { -49.0 }
        else if post_residual < 10 { -41.0 }
        else if post_residual <= 20 { -21.0 }
        else if post_residual <= 46 { 0.0 }
        else { 29.0 };
    score += class;

    // Harmonic alignment: round residuals are more reusable
    if post_residual % 10 == 0 { score -= 10.0; }
    else if post_residual % 25 == 0 { score -= 8.0; }
    else if post_residual % 20 == 0 { score -= 5.0; }
    else if post_residual % 15 == 0 { score -= 3.0; }

    // Lookahead: how well does the next item land here after this one?
    if next_item_size > 0 {
        if next_item_size as u64 == post_residual as u64 {
            score -= 76.0;
        } else if (next_item_size as u64) <= (post_residual as u64) {
            let new_post = post_residual - next_item_size;
            if new_post == 0 { score -= 33.0; }
            else if new_post <= 10 { score -= 28.0; }
            else if new_post <= 25 { score -= 14.0; }
            else { score += (new_post as f64) * 0.18; }
            if new_post > 0 && new_post < 4 { score -= 11.0; }
            let next_fits_elsewhere = mean_residual >= next_item_size as f64 && open_bins_count > 1;
            if !next_fits_elsewhere && post_residual >= next_item_size { score -= 13.0; }
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 { score -= 42.0; }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 { score -= 22.0; }
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 { score -= 7.0; }
            // dead-space penalty scaled by stream progress
            if new_post > 0 && new_post < item_size {
                score += (item_size - new_post) as f64 * 0.06;
                if progress > 0.5 { score += (item_size - new_post) as f64 * 0.05 * progress; }
            }
        } else {
            score += (post / cap) * 35.0;
            if post_residual > 60 { score += 6.0; }
        }
    }

    // Consolidation pressure
    score += 0.6 * open_bins_count as f64;
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity { score += 7.0; }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 60.0; }

    // New-bin candidate gating
    if bin_residual == bin_capacity {
        score = 56.0 + (post / cap) * 10.0;
        let item_frac = item_size as f64 / cap;
        score -= 60.0 * item_frac;
        score += 0.4 * mean_residual;
        if post_residual >= 56 { score -= 12.0; }
        if post_residual >= 85 { score -= 9.0; }
        if post_residual >= 96 { score -= 6.0; }
        if fitting_bins_count == 0 { score -= 86.0; }
        if progress > 0.85 { score -= 7.0; }
        if progress > 0.9 && open_bins_count > 3 { score += 15.0; }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 { score += 14.0; }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 { score -= 10.0; }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 { score += 8.0; }
    }

    // Late-stream tightening
    if total_items > 0 {
        score += 10.0 * progress * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in the post residual,
    // this is a perfect chaining placement — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits, leaving a further residual; mild reward proportional
            // to how compact the two-step packing is.
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 - two_step_waste;
        } else {
            // Next item does NOT fit after this placement: penalize leaving a
            // residual that is too small for the upcoming item (dead space risk),
            // scaled by how close the miss is.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 2.0;
        }
    }

    // Compare residual to mean residual across open bins: placing into a bin
    // with below-average residual (tight bin) is good consolidation.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize creating small unusable residuals relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins for
    // large items (keeps future flexibility); late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if the item is large or open bins
        // are all quite full (mean residual small).
        score += 60.0; // base reluctance to open a new bin
        if item_size >= 60 {
            score -= 40.0 * (1.0 - progress);
        }
        if mean_residual < 15.0 {
            score -= 80.0;
        }
    }

    // Slight preference for bins with more residual when many bins are open
    // (spread load), but only mildly.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

