    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        } else {
            // next item cannot fit here: penalize small dead space
            score += 40.0 * (1.0 - (next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer minimal waste
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize creating tiny unusable residuals (below min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late in stream: be more conservative, prefer tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
