    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Non-linear penalty for post_residual that is unusable relative to the smallest plausible item
    // Reward post_residual that could still fit the lookahead item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (1.0 - (n / cap)) * (pr / cap).sqrt();
        } else {
            // dead space relative to lookahead item: quadratic penalty
            let gap = (n - pr) / cap;
            score += 25.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation early)
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good "filler" target
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;

    // Reward high fill ratio smoothly
    score -= 5.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size (1) is worthless; penalize moderate waste.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste * waste;

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward when the next item fills the bin almost exactly.
        let combo_gap = post_residual - next_item_size;
        score -= 4.0 * (1.0 - combo_gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize small dead space.
        score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.05 * diff;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large post_residual everywhere) or late in stream
    // with many open bins. Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        let poor_fits = (mean_residual - item_size as f64).max(0.0);
        score += 25.0
            - 15.0 * pressure
            - 0.3 * poor_fits
            - 5.0 * progress
            - 0.5 * open_bins_count as f64;
    }

    // Mild bonus for using bins that are already partially filled early on
    // (keeps bin count low); slightly relax later to allow consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 2.0 * (1.0 - progress);
    }

    score
}

