            score -= 12.0; // good chain fit, small new dead space
        } else if post_residual < next_item_size && post_residual >= eighth.min(next_item_size) / 2 {
            score += 5.0; // lookahead can't follow; mild penalty
        }
        // Class-complement pairing: item_class + next_class covering capacity
        if item_size + next_item_size <= bin_capacity && post_residual == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for large items or when existing
        // residuals are all in awkward harmonic classes (not multiples of quarter).
        let awkward = mean_residual > 0.0 && (mean_residual % quarter as f64) > 3.0 && (mean_residual % quarter as f64) < (quarter as f64 - 3.0);
