    // Tight-fit reward: the fuller the bin becomes, the better.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 14.0 * fill_frac;

    // Lookahead coupling: if the next item fits into the leftover space, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // extra reward if next item fills the remainder almost exactly
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // leftover too small for lookahead item: penalize proportional dead-space risk
            score += 6.0 + 10.0 * (next_item_size as f64 / 100.0);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer it heavily
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when existing
    // bins are crowded (low mean residual) or when a fresh bin enables a good lookahead fit.
    if bin_residual == bin_capacity {
        score += 28.0;
        score += 0.35 * mean_residual;
        score += 0.6 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Dynamic time horizon: late in the stream, be more conservative and consolidate
    // (slightly flatten score differences so tight fits dominate).
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.18 * progress;

    // Global fragmentation pressure: more open bins with large residuals means
    // spreading risk; mildly penalize placing into bins that keep residuals high.
    score += 0.08 * (mean_residual - post_residual as f64).max(0.0);

    // Small deterministic tie-breaker based on item size (bigger items want tighter homes).
    score -= 0.03 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, scaled by smooth progress polynomial
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear coupling: small post-residuals are dead space; penalize quadratically
    score += 40.0 * (1.0 - x) * (1.0 - x) * (1.0 - progress);

    // Reward tight fits smoothly: interaction of post_residual with item fraction
    let fill_frac = item_size as f64 / cap;
    score -= 25.0 * fill_frac * fill_frac * (1.0 + progress);

    // Last-chance bonus: smooth reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: penalize if next item cannot use this post-residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n > pr as f64 {
            let gap = (n - pr as f64) / cap;
            score += 20.0 * gap * (1.0 + gap);
        } else {
            score -= 10.0 * (1.0 - (pr as f64 - n) / cap);
        }
    }

    // Spread from mean residual: prefer bins deviating smoothly from mean
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev - 8.0 * dev;

    // New-bin candidate: mildly penalize so we prefer good existing fits, but allow late opening
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Reward placements whose post_residual falls into "usable" harmonic classes
    // Classes via integer division on residual: 0 (perfect), <=10 (near-perfect),
    // <=25 (small-item friendly), <=50 (half-capacity), else dead.
    let class: f64 = if post_residual == 0 {
        -60.0
    } else if post_residual <= 10 {
        -40.0
    } else if post_residual <= 25 {
        -18.0
    } else if post_residual <= 50 {
        0.0
    } else {
        25.0
    };
    score += class;

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item sizes (10, 20, 25, 50) are more likely to be exactly filled later.
    let harmonic_bonus = if post_residual % 10 == 0 { -8.0 }
        else if post_residual % 25 == 0 { -6.0 }
        else if post_residual % 20 == 0 { -5.0 }
        else { 0.0 };
    score += harmonic_bonus;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            // Prefer chains that keep landing in good classes
            if new_post <= 10 { score -= 25.0; }
            else if new_post <= 25 { score -= 12.0; }
            else { score += (new_post as f64) * 0.15; }
            // If next item cannot fit anywhere else (this bin is its only home)
            let next_fits_elsewhere = (mean_residual >= next_item_size as f64) && open_bins_count > 1;
            if !next_fits_elsewhere && post_residual >= next_item_size {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize leaving large awkward residual
            score += frac * 30.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is a last resort.
    if bin_residual == bin_capacity {
        score = 55.0 + frac * 10.0;
        // Opening is acceptable late in stream or when existing fits are terrible
        if post_residual >= 60 { score -= 10.0; }
        if fitting_bins_count == 0 { score -= 80.0; }
        if step_index as f64 / (total_items.max(1) as f64) > 0.9 { score -= 5.0; }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    // Prefer filling bins that deviate from mean residual (tighter packing)
    score += ((bin_residual as f64 - mean_residual) * 0.05).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or too small for
    // the next item) are heavily penalized; exact fills are heavily rewarded.
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else if (post_residual as f64) < 10.0 {
        score += 200.0; // tiny dead space, unusable
    } else if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 60.0; // gap cannot host the lookahead item
    } else {
        // Usable gap: mildly reward leaving room for the next item
        if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
            score -= 15.0;
        }
        // Reward tight fits relative to capacity
        score -= 30.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    score += 4.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item is
    // large and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        score += 120.0;
        let item_frac = item_size as f64 / cap;
        // Large items leave little dead space in a fresh bin; allow opening.
        score -= 100.0 * item_frac;
        // If mean residual across open bins is large, consolidation is easy:
        // discourage new bins.
        score += 0.5 * mean_residual;
    }

    // Mild stream-progression tilt: late in the stream, tighten up and avoid
    // spreading across many bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    } else if post_residual <= 15 {
        score -= 150.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 900.0;
        } else if post_residual >= next_item_size {
            score -= 250.0 / (1.0 + gap);
        } else {
            score += gap * 2.0; // next item cannot follow here; penalize dead space
        }
    }

    // Compare against mean residual across open bins: prefer tighter-than-average fits.
    score -= (mean_residual - post_residual as f64) * 3.0;

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent existing bins exist.
    if bin_residual == bin_capacity {
        score += 80.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 && post_residual <= 40 {
            score -= 60.0; // still allow new bin if it leaves small residual
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize dead space that is too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits in the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // penalize leaving residual that wastes capacity for the next item
            let wasted = (post_residual as f64).min(next_item_size as f64);
            score += 0.3 * wasted;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer it only when open bins fit poorly
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 25.0;
        // cheaper to open new bin when few bins open or late in stream with big mean residual
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer bins above mean (consolidate)
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.1 * diff;
        // discourage spreading across many open bins
        score += 0.5 * open_bins_count as f64;
    }

    // Slight time decay: early on, be more exploratory (favor new bins slightly)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: post residual, weighted more strongly as stream progresses
    let mut score = pr * (1.0 + 0.8 * p2 + 0.6 * p3);

    // Smooth non-linear coupling: penalize residuals that are "awkward" sizes
    // (near half-capacity, useless for typical items), smoothly via sin-like polynomial
    let awkward = pr_norm * (1.0 - pr_norm); // peaks at 0.5
    score += 25.0 * awkward * awkward * (1.0 + progress);

    // Reward tight fits with smooth saturating term
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead: reward if next item fits the post residual (smooth quadratic)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = pr - nx;
        if fit_gap >= 0.0 {
            let g = fit_gap / cap;
            score -= 15.0 * (1.0 - 4.0 * g * (1.0 - g)) * (1.0 - 0.5 * progress);
        } else {
            let g = (-fit_gap) / cap;
            score += 10.0 * g * (1.0 + g) * (0.5 + progress);
        }
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Crowd penalty: mildly discourage scattering across many bins early
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // New-bin candidate: neutral-ish baseline with smooth progress-dependent cost
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.5 * progress) - 5.0 * mean_residual / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets via integer division thresholds
    let pr = post_residual;
    let class = pr / 10; // 0..=10 harmonic class
    // Dead-space penalty grows superlinearly for small residuals that are hard to fill
    if pr > 0 {
        let fillable = (next_item_size <= pr && next_item_size > 0) as i32;
        score += match class {
            0 => 30.0, // unusable sliver
            1 => if fillable == 1 { -18.0 } else { 22.0 },
            2 => if fillable == 1 { -14.0 } else { 14.0 },
            3 => if fillable == 1 { -10.0 } else { 6.0 },
            4 => if fillable == 1 { -7.0 } else { 2.0 },
            5 => if fillable == 1 { -5.0 } else { 0.0 },
            6 => if fillable == 1 { -4.0 } else { 0.0 },
            _ => if fillable == 1 { -3.0 } else { 0.0 },
        };
    } else {
        score -= 40.0; // perfect fit: bin closed
    }

    // Exact modulo harmony: post_residual divisible by common item classes (10/20/25/50)
    if pr > 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 50 == 0) {
        score -= 6.0;
    }

    // Next-item lookahead coupling: reward if next item lands in a harmonic class
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            // next item fits here too: reward proportional to how snugly both pack
            score -= 4.0 * (1.0 - (pr as f64 - nx) / cap);
        } else {
            // next item won't fit here: mildly penalize leaving this bin
            score += 3.0 * (nx - pr as f64) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins, more when many open bins have room
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // but if mean residual across open bins is too small to fit future items, new bin is fine
        if mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
    }

    // Mild tie-breaker: prefer bins whose residual is close to the item (snug fit)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.05;

    // Prefer bins below mean residual (consolidating emptier bins)
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum plausible item size) are pure waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 40 {
        score -= 6.0;
    } else {
        score -= 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead space relative to capacity: quadratic penalty on unusable fraction.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    if dead_frac > 0.0 && dead_frac < 0.25 {
        score += 30.0 * (0.25 - dead_frac) * 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise this item forces a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless fit is excellent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot use the leftover, penalize leaving medium gaps.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter than average bins are worth closing out).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= 0.5 * dev;
    } else {
        score += 0.3 * (-dev);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when open-bin count is high
        // (consolidation is hopeless anyway) or the fit elsewhere would be terrible.
        score += 20.0 - 0.5 * open_bins_count as f64;
        if post_residual == bin_capacity {
            score -= 5.0; // empty bin is at least fully flexible
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact / near-exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect match for next item is highly desirable.
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual >= next_item_size {
            // Can also fit the next item: reward proportionally to tightness.
            score -= 50.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leftover dead space relative to mean residual.
            score += diff * 0.5;
        }
    }

    // Tight fit reward: small post_residual relative to capacity is good (first-fit-decreasing spirit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize bins whose residual is far below the mean residual (already well-used bins
    // should be prioritized to consolidate waste).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized more as more bins are already open,
        // but slightly cheaper early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 150.0 + 20.0 * open_bins_count as f64 - 50.0 * (1.0 - progress);
        // If the item perfectly consumes a fresh bin, opening is fine.
        if item_size == bin_capacity {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post-residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (item_size as f64);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 20 {
        score -= 6.0;
    }

    // Dead-space penalty: post-residual that no plausible item (1..100) can
    // use well is costly, especially very small slivers.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 8.0 / (1.0 + slack); // next item chains well here
        } else {
            let miss = nxt - pr;
            if miss <= 20.0 {
                score += 0.4 * miss; // next item almost fit; wasted potential
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0 + 0.15 * (item_size as f64);
    }

    // Crowding pressure: many open bins with high mean residual -> prefer
