            // Residual can't hold next item: likely dead space.
            score += 10.0 + frac * 25.0;
        }
    }

    // Open-bin pressure, exempting the new-bin candidate.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.5;
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score = 56.0 + frac * 10.0;
        if post_residual >= 56 {
            score -= 12.0;
        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if fitting_bins_count == 0 {
            score -= 86.0;
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
    }

    // Fragmentation pressure when many bins are open.
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future items
    // are wasted. Penalize unusable gaps super-linearly.
    let dead_threshold = 12.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: residual just above the item.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless the fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by open bins and bad fit.
        score += 30.0 + pressure * 4.0;
        // Allow a new bin when item is large relative to residual of others.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    } else {
        score -= pressure.min(10.0);
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Prefer bins with residual below mean (fill the emptiest-ish bins,
    // keep big-residual bins flexible).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.5;
        } else {
            score += (-diff) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact 2-step match: post_residual equals next item size -> perfect chain fill
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // bonus if next item fits exactly after this one
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // last item: prefer tightest fill
        score -= 20.0;
    }

    // Penalize post_residual that is small but unusable (dead space)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        if gap < item_size as f64 {
            score += 8.0 * (1.0 - gap / item_size as f64);
        }
    }

    // Reward filling bins below mean residual (tighter than average)
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    if bin_residual == bin_capacity {
        let avg_load = bin_capacity as f64 - mean_residual;
        let openness = open_bins_count as f64;
        // penalize more early in the stream; allow new bins when open bins are well used
        score += 15.0 + 10.0 * (1.0 - progress) + 0.15 * openness - 0.2 * avg_load;
        // if nothing else fits well, opening is fine: reduce penalty when fitting bins scarce
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 8.0;
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
            // dead space the known next item cannot use
            score += 10.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer consolidating
    // into existing bins rather than spreading.
    let spread = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * spread;

    if open_bins_count > 4 && mean_residual > item_size as f64 {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is large
    // and existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fitting_bins_count == 0 || (fitting_bins_count == 1 && fit_ratio < 0.3);
        if poor_fit {
            score -= 6.0;
        } else {
            score += 20.0 + 15.0 * (1.0 - progress);
        }
    }

    // Late stream: prefer tight packing as stream ends approach.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
