    // reusable by later items.
    let harmonic_bonus = if post_residual % 10 == 0 {
        -10.0
    } else if post_residual % 25 == 0 {
        -8.0
    } else if post_residual % 20 == 0 {
        -5.0
    } else if post_residual % 15 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: two-item coupling with the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 76.0; // next item exactly fills the gap
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 33.0;
            } else if new_post <= 10 {
                score -= 28.0;
            } else if new_post <= 25 {
                score -= 14.0;
            } else {
                score += (new_post as f64) * 0.18;
