            // If the next item cannot fit anywhere else, secure this bin.
            let next_fits_elsewhere = (mean_residual >= next_item_size as f64) && open_bins_count > 1;
            if !next_fits_elsewhere && post_residual >= next_item_size {
                score -= 13.0;
            }
            // Pairing: item + next exactly fills the current bin.
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 42.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 22.0;
            }
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 7.0;
            }
        } else {
            score += frac * 35.0;
        }
    }

    // Last-chance bin: only open bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score = 56.0 + frac * 10.0;
        if post_residual >= 56 {
            score -= 12.0;
        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if fitting_bins_count == 0 {
            score -= 86.0;
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 15.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 14.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // Large items pack well in fresh bins; mean residual pressure.
        let item_frac = item_size as f64 / cap;
        score -= 40.0 * item_frac;
        score += 0.3 * mean_residual;
    }

    // Consolidation pressure: many open bins with small residuals relative
    // to capacity should be discouraged.
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 7.0;
    }

    // Late-stream tightening.
    if total_items > 0 {
        score += 10.0 * progress * frac;
    }

