}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: post residual, mildly devalued as stream progresses (tight packing matters more early)
    let mut score = post * (1.0 + 0.5 * (1.0 - progress));

    // Non-linear polynomial coupling: penalize small-but-not-zero post residuals
    // (dead space) with a quartic well; reward perfect fits (post ~ 0) and
    // large usable residuals.
    let dead_well = (norm_post * (1.0 - norm_post)).powi(2) * 4.0; // peaks at norm_post = 0.5
    score += dead_well * cap * (0.3 + 0.7 * (1.0 - progress));

    // Reward tight fits more strongly as the stream advances
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * item_size as f64 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: penalize if next item can't fit in the post residual (fragmentation risk)
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            let waste = (next_item_size as f64 - post).max(0.0);
            score += waste * (0.4 + 0.6 * progress);
        } else {
            score -= 3.0; // next item chains nicely here
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (consolidate small spaces)
    let dev = (mean_residual - post) / cap;
    score += dev * dev * cap * 0.5;

    // Mild penalty for proliferating bins
    score += (open_bins_count as f64).sqrt() * 0.5;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (fitting_bins_count as f64);
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
