    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items (>50% capacity) justify a fresh bin.
        if item_frac > 0.5 {
            score -= 10.0 * (item_frac - 0.5);
        } else {
