    let fill_quotient = (bin_capacity - bin_residual) / (bin_capacity / 4).max(1);
    score -= fill_quotient as f64 * 1.5;

    // Mild pressure against accumulating too many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

