    let post = post_residual as f64;
    let frac = post / cap;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - frac;
    score -= 32.0 * tightness * tightness;

    // Dead-space classification: exact fills and near-dead gaps dominate.
    let class: f64 = if post_residual == 0 {
        -68.0
    } else if post_residual <= 5 {
        -49.0
    } else if post_residual <= 10 {
        -41.0
    } else if post_residual <= 20 {
        -21.0
    } else if post_residual <= 46 {
        0.0
    } else {
        29.0
    };
    score += class;

    // Harmonic residual bonus: gaps matching common item sizes stay usable.
    let harmonic_bonus = if post_residual % 10 == 0 {
        -10.0
    } else if post_residual % 25 == 0 {
        -8.0
    } else if post_residual % 20 == 0 {
        -5.0
    } else if post_residual % 15 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: simulate placing the next item into this gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 76.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 33.0;
            } else if new_post <= 10 {
                score -= 28.0;
            } else if new_post <= 25 {
                score -= 14.0;
            } else {
                score += (new_post as f64) * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 11.0;
            }
            let next_fits_elsewhere = (mean_residual >= next_item_size as f64) && open_bins_count > 1;
            if !next_fits_elsewhere && post_residual >= next_item_size {
                score -= 13.0;
            }
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 42.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 22.0;
            }
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 7.0;
            }
            // Residual that can host the next item multiple times cleanly
            if new_post > 0 && new_post >= next_item_size && new_post % next_item_size == 0 {
