    if bin_residual == bin_capacity {
        score = 56.0 + frac * 10.0;
        if post_residual >= 56 {
            score -= 12.0;
        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if fitting_bins_count == 0 {
            score -= 86.0;
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 15.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 14.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // Late stream: only open new bins for large items that leave a useful gap
        if progress > 0.8 && fitting_bins_count >= 1 && post_residual < next_item_size as u32 {
            score += 8.0;
        }
        // NEW: discourage new bins when an existing bin achieves an exact fit for the next item
        if next_item_size > 0 && fitting_bins_count >= 1 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
    }

    // Gap unusable by the next item: mild penalty scaled by scarcity of bins.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += if fitting_bins_count <= 2 { 5.0 } else { 3.0 };
    }

    // Fragmentation pressure: many open bins with small residuals.
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 7.0;
    }

    // Consolidation coupling: prefer bins above mean residual when spreading is high.
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.1 * diff;
        score += 0.5 * open_bins_count as f64;
    }

    // Slight time decay: early on, be more exploratory (favor new bins slightly)
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual quadratically, scaled by capacity
    let tight_fit = (post_residual as f64) / (bin_capacity as f64);
    score += 60.0 * tight_fit * tight_fit;

    // Reward exact fills
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement;
    // if next item is large and post_residual too small, penalize wasted residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            let waste = next_item_size as f64 - post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty to prefer best-fit discrimination
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Penalize placing into bins whose residual deviates far below mean residual
    // (keeps residuals balanced unless it's a tight fit)
    let dev = mean_residual - bin_residual as f64;
    score += 0.10 * dev.abs();

    // Early in stream: encourage opening/using fresh bins with room; late: consolidate tightly
    let early_bonus = (1.0 - progress) * (bin_residual as f64 - item_size as f64) * 0.05;
    score -= early_bonus;
    let late_penalty = progress * (post_residual as f64) * 0.10;
    score += late_penalty;

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no open bin offers a decent fit (post_residual of empty bin = capacity - item_size)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // penalize opening a new bin unless the item is big
        score += 18.0 * (1.0 - fill_ratio);
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let coupling = norm_pr * (1.0 + 2.0 * progress + 3.0 * p2 + 1.5 * p3);
    score += coupling * 10.0;

    // Penalize wasted capacity more as stream progresses (fewer chances to fill)
    score += norm_pr * norm_pr * (progress * 25.0 + 5.0);

    // Reward tight fits: small post_residual relative to item size
    let tight = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= tight * (8.0 + 12.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 + 8.0 * progress * (1.0 - pr / cap);
        } else {
            // dead space risk: penalize proportional to unusable gap
            let gap = (nxt - pr) / cap;
            score += gap * (10.0 + 15.0 * progress);
        }
    }

    // Mean residual deviation: prefer bins near the mean (balance residuals)
    let dev = (pr - mean_residual).abs();
    score += dev * (0.05 + 0.10 * progress);

    // New-bin candidate handling: only attractive early or when residuals are tiny
    if bin_residual == bin_capacity {
        let avg_fit = mean_residual / cap;
        score = 15.0 + 40.0 * progress * (1.0 - avg_fit) - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes by integer division.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    // Class 1: post_residual in 1..=10 (near-perfect) -> reward.
    // Class 2: 11..=30 -> mild penalty (awkward small gap).
    // Class 3: >30 -> large penalty (big waste).
    let class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 30 { 2 }
        else { 3 };

    match class {
        0 => score -= 25.0,
        1 => score -= 8.0,
        2 => score += 6.0,
        _ => score += 18.0,
    }

    // Harmonic compatibility: does next_item_size fit exactly or well in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // chains perfectly
        } else if next_item_size <= post_residual {
            let gap_after_next = post_residual - next_item_size;
            let nclass = if gap_after_next == 0 { 0 }
                else if gap_after_next <= 10 { 1 }
                else if gap_after_next <= 30 { 2 }
                else { 3 };
            score -= match nclass { 0 => 14.0, 1 => 6.0, 2 => 0.0, _ => 4.0 };
        } else {
            // next item cannot use this bin's remainder; residual becomes dead space
            score += post_residual as f64 * 0.25;
        }
    } else {
        // last item: only the exact-fill matters
        if post_residual > 0 { score += post_residual as f64 * 0.1; }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this placement would leave a large dead residual in a tight regime.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New bin: baseline moderate score; penalize so it's chosen only
        // when open bins score worse (poor fits / big residuals).
        score = 55.0 + 10.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // new bin can host the next item too
        }
    }

    // Prefer filling bins whose residual is close to the item (tight fit signal).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Slight preference for reducing the number of open bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // Nudge toward bins below mean residual (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: residuals that can't fit much (below min item size 10)
    if post_residual < 10 {
        score += 40.0; // dead space penalty
    } else {
        // Gradual penalty for residuals that can only fit very small items
        if post_residual <= 20 {
            score += 12.0 * (1.0 - (post_residual as f64) / 20.0);
