        // Reward residuals that can fit the lookahead item exactly
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size as u32;
            if slack < 10 {
                score -= 15.0; // perfect two-item pairing
            } else {
                score -= 6.0 / (slack as f64).sqrt().max(1.0);
            }
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0; // lookahead item won't fit here
        }
    }

    // Reward tight fits (low post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: penalize placements in bins when many bins are open,
    // encouraging consolidation unless it's a good fit
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New bin candidate handling: neutral-ish baseline, only preferred when
    // all open bins would leave bad dead space
    if bin_residual == bin_capacity {
        score -= 5.0;
        if next_item_size > 0 {
            // new bin fits next item comfortably
            score -= 3.0;
        }
        // Discourage opening new bins early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference toward bins with low mean residual spread (consolidation)
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.05 * dev;
    }

    score
}

