            score -= 25.0 * (1.0 - (next_item_size as f64) / cap) * (1.0 - progress * 0.5);
        } else {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open relative to stream length (encourage consolidation early)
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

