    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate handling: make empty bins moderately attractive only early or for large items
    if bin_residual == bin_capacity {
        let attract = 0.35 * cap * (1.0 - progress) + 0.5 * item_size as f64;
        score = pr - attract + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: classify leftover space ---
    // Class 0: perfect fit (0) -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // "Dead space" classes: residuals that are hard to fill later.
        // Small residuals (< 10) are nearly dead; medium residuals are usable.
        let dead = if post_residual < 10 {
            3.0
        } else if post_residual < 25 {
            1.0
        } else if post_residual < 50 {
            0.0
        } else {
            -0.5 // large residual is flexible, mild reward
        };
        score += dead * 10.0;

        // Modulo-10 harmonic band: residuals near multiples of 10 pair well
        // with the common small-item sizes (10..=25).
        let m = post_residual % 10;
        let harmonic_bonus = match m {
            0 => 4.0,
            1 | 9 => -1.0,
            2 | 8 => -0.5,
            5 => 1.0, // halves pair with odd sizes
            _ => 0.0,
        };
        score -= harmonic_bonus;

        // Integer-division threshold on post_residual / next_item_size:
        // how many copies of the NEXT item could this residual hold?
        if next_item_size > 0 {
            let copies = post_residual / next_item_size.max(1);
            match copies {
                0 => score += 15.0, // residual can't host next item: dead-ish
                1 => score -= 6.0,  // exactly hosts next item: excellent chaining
                2 => score -= 3.0,
                _ => score -= 1.0,
            }
            // Perfect match: residual equals next item exactly -> reserve it.
            if post_residual == next_item_size {
                score -= 20.0;
            }
            // Penalize wasting a big residual on a small item when next item
            // is large and won't fit here afterwards.
            if next_item_size > post_residual && post_residual > 0 {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // or the fit here would be terrible.
        let crowd = open_bins_count as f64;
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Penalize new bins mildly; reward when mean residual is low (bins full)
        score = 100.0 - mean_residual * 0.5 - crowd * 2.0 + fit_quality * 20.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
