pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post;

    // Dead-space class table (borrowed from best heuristic, retuned)
    let class: f64 = if post_residual == 0 {
        -70.0
    } else if post_residual <= 5 {
        -50.0
    } else if post_residual <= 10 {
        -40.0
    } else if post_residual <= 20 {
        -20.0
    } else if post_residual <= 46 {
        0.0
    } else {
        30.0
    };
    score += class;

    // Harmonic divisibility bonus: residuals that are likely to be exactly
    // filled by common item sizes are rewarded.
    let harmonic_bonus = if post_residual % 10 == 0 {
        -10.0
    } else if post_residual % 25 == 0 {
        -8.0
    } else if post_residual % 20 == 0 {
        -5.0
    } else if post_residual % 15 == 0 {
        -3.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead on next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 78.0; // next item exactly fills this bin
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 35.0;
            } else if new_post <= 10 {
                score -= 28.0;
            } else if new_post <= 25 {
                score -= 14.0;
            } else {
                score += (new_post as f64) * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 12.0;
            }
            let next_fits_elsewhere = (mean_residual >= next_item_size as f64) && open_bins_count > 1;
            if !next_fits_elsewhere && post_residual >= next_item_size {
                score -= 14.0;
            }
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 44.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 22.0;
            }
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 7.0;
            }
            // Dead-space lookahead: penalize residuals no plausible item can fill
            if new_post > 0 && new_post < item_size {
                score += (item_size - new_post) as f64 * 0.06;
            }
            if new_post > 0 && new_post < item_size && progress > 0.5 {
                score += (item_size - new_post) as f64 * 0.05 * progress;
            }
        } else {
            score += frac * 35.0;
            if post_residual > 60 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor the only fitting open bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    // New empty bin candidate handling
    if bin_residual == bin_capacity {
        score = 56.0 + frac * 10.0;
        if post_residual >= 56 {
            score -= 12.0;
        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if post_residual >= 96 {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 88.0;
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 16.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 14.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // Defer new bin when open bins still have room comparable to next item
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 9.0;
        }
        // Large items in a fresh bin leave little dead space; allow opening
        let item_frac = item_size as f64 / cap;
        score -= 40.0 * item_frac;
        // Consolidation pressure with many open bins
        score += 2.0 * open_bins_count as f64;
    }

    // Consolidation pressure for large residuals in open bins
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual squared relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Many fitting bins: mild penalty for wasting a scarce large residual.
    if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 45.0 * (1.0 - gap / 10.0);
        } else {
            score += gap * 0.15;
        }
    }
    // If next item cannot fit in post_residual, residual is likely dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += (post_residual as f64) * 0.5;
    }

    // Time horizon: early in stream, prefer keeping residuals flexible (favor new bins less);
    // late in stream, consolidate into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize mildly, more so later when consolidation matters.
        score += 15.0 + 35.0 * progress;
        // But if open bins all have small residuals and item is large, opening is fine.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0;
        }
    } else {
        // Reward placing into bins whose residual is near mean (keeps bin profile uniform).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1 * progress;
        // Late in stream, favor filling open bins aggressively.
        score -= 20.0 * progress;
    }

    // Avoid proliferating bins when few are open early on.
    if open_bins_count > 20 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty on dead space
    let mut score = pr * (1.0 + 0.8 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post-residual with stream progress:
    // late in the stream, small residuals are penalized more (dead space matters more)
    let coupling = 1.0 + progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += 30.0 * progress * pr_norm * pr_norm * coupling;

    // Reward tight fits with smooth decay
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: penalize if post-residual cannot fit next item (smoothly)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - pr / nxt) * (1.0 - pr / nxt);
        } else {
            score -= 5.0 * (pr - nxt) / cap;
        }
    }

    // Slight preference for balancing residuals across open bins
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, penalized when open bins exist and fit is decent
    if bin_residual == bin_capacity {
        score = cap * (1.0 + 0.5 * progress) + 10.0 * (open_bins_count as f64).sqrt();
        if fitting_bins_count == 1 {
            score += 40.0; // avoid opening new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual into residue classes
    // modulo 10 (typical granularity of item sizes). Residues that are "dead"
    // (small, unusable) should be penalized.
    let dead_limit: u32 = 9;
    if post_residual <= dead_limit {
        // Perfectly packed bin: excellent, reward strongly.
        score -= 40.0;
    } else {
        // Residue class: how well can a typical next item fit into post_residual?
        let cls = post_residual % 10;
        // Residues 0..9 mod 10; class 0 (multiples of 10) is most reusable.
        let class_bonus: f64 = match cls {
            0 => 12.0,
            1..=3 => 4.0,
            4..=6 => 0.0,
            _ => -3.0,
        };
        score -= class_bonus;
    }

    // Lookahead: does next_item_size fit exactly or nearly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect lookahead fit: strong reward.
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item would not fit here: if this bin becomes nearly empty
            // of usable space, penalize leaving a trap.
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Fraction-of-capacity coupling: prefer filling bins past the halfway mark.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    if residual_frac < 0.5 {
        // Bin is more than half full; placing here is very good.
        score -= 10.0 * (1.0 - residual_frac);
    }
    // Reward large items (they are hard to place later).
    score -= 8.0 * fill_frac;

    // New-bin candidate: empty bin gets a moderate penalty so it is only chosen
    // when open bins offer genuinely poor fits (high post_residual / dead space).
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in the stream, opening bins is cheap; late, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Coupling with mean residual: if this bin is far below the mean residual
    // (i.e., unusually full), reward using it to balance the pool.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
