        if post_residual >= 56 { score -= 12.0; }
        if post_residual >= 85 { score -= 9.0; }
        if post_residual >= 96 { score -= 6.0; }
        if fitting_bins_count == 0 { score -= 86.0; }
        if progress > 0.85 { score -= 7.0; }
        if progress > 0.9 && open_bins_count > 3 { score += 15.0; }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 { score += 14.0; }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 { score -= 10.0; }
        // defer new bin when open bins have room comparable to the next item
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 { score += 8.0; }
    }

