}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium gaps that only fit tiny items are semi-dead.
    if post_residual >= 10 && post_residual < 20 {
        score += 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize opening a new bin unless it enables a good future fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count > 0 {
            // Prefer existing bins unless the new bin would fit next item better.
            score += 60.0;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 25.0;
            }
            // Early in stream, new bins are cheaper.
            score -= 30.0 * (1.0 - progress);
        } else {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with residual close to item usage (tight packing).
    score += (mean_residual - bin_residual as f64).abs() * 0.2;

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // Extra reward for near-exact fit of next item.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with little slack left.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportional to how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 * (miss / bin_capacity as f64).min(1.0);
    }

    // Penalize unusable dead space (post_residual smaller than smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we prefer filling existing bins,
    // unless the current bin would leave a bad residual.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is huge relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 30.0;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    score -= (mean_residual - post_residual as f64).clamp(0.0, 50.0) * 0.3;

    // Late-stream urgency: fill bins more aggressively as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual favored).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space: post_residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // tiny unusable slivers are wasted space
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement is excellent; if next item would be stranded, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here regardless; mild penalty scaled by how
            // much of the residual is wasted relative to next item size
            let waste = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 4.0 * waste.min(3.0);
        }
    }

    // Global state: when mean residual is high, prefer consolidating into
    // fuller bins (large item_size relative to bin_residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize using an existing bin slightly); late in the stream, pack
    // tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= 20.0 * (1.0 - progress);
        score += 15.0 * progress;
        // Opening a new bin is worse when many bins are already open.
        score += (open_bins_count as f64).sqrt() * 2.0;
    } else {
        score -= 6.0 * progress;
    }

    // Mild penalty for very fragmented bin state (many open bins).
    score += (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to item_size (near-perfect fill).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * diff;

    score
}

