    // Mild penalty for spreading across many open bins vs consolidating
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Alignment with mean residual: prefer bins whose post residual approaches mean
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: neutral base so it only wins when open bins score poorly
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress_ramp) + 10.0 * norm_it;
    }

    score
}

