pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic fraction: reward tight fits with a harmonic-like term
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.0 {
        score -= 30.0 / (1.0 + (1.0 - fit_ratio) * 20.0);
    }

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 500.0;
    }

    // Modulo classes on post_residual: small dead space classes are more tolerable
    let pr = post_residual;
    let class = pr % 10;
    if pr > 0 {
        match class {
            0 => score -= 40.0,           // round residual, likely reusable
