            _ => {}
        }
    }

    // Harmonic class on post_residual / capacity fraction
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.10 && pr > 0 {
        score += 60.0 * (0.10 - frac); // penalize leaving <10% unusable
    }

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        score -= 45.0;
        // harmonic bonus if next item leaves another exact-ish fill
        let npr = pr - next_item_size;
        if npr == 0 {
            score -= 120.0;
        } else if npr % 10 == 0 {
            score -= 30.0;
        }
    } else if next_item_size > pr {
        // next item won't fit here; residual becomes dead space risk
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: only open a new bin when this is early
    // in the stream or current bin fits are all poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // new empty bin baseline: slightly worse than a good existing fit
        score = 70.0 + 50.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // new bin keeps good room for lookahead
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * 2.0;

    // Mean residual deviation: prefer bins whose residual is below average
    // (concentrate fill in tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small gaps that likely cannot host any future item.
    // Treat gaps below a "useful threshold" as partially wasted.
    let useful_threshold = 20u32;
    if post_residual > 0 && post_residual < useful_threshold {
        // Quadratic-ish penalty so tiny gaps are heavily punished.
        let waste = (useful_threshold - post_residual) as f64;
        score += waste * waste * 2.0;
    }

    // Reward leaving room for the lookahead item if it fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + next_item_size as f64 * 0.5;
    }

    // Penalize if post-residual is just barely too small for the next item
    // (near-miss creates unusable gap for the known future demand).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 3.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes progressively more expensive.
    score += open_bins_count as f64 * 5.0;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: empty bin gets a moderate base cost so it
    // only wins when open bins offer genuinely bad fits (large dead space).
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 8.0;
    }

    // Mild preference for bins with below-average residual (filling fuller
    // bins first keeps many mid-size gaps available).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Progress scaling: as the stream nears its end, tighten up more
    // aggressively since leftover bins are less likely to be reused.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post;

