    let class: f64 = if post_residual == 0 { -68.0 }
        else if post_residual <= 5 { -49.0 }
        else if post_residual <= 10 { -41.0 }
        else if post_residual <= 20 { -21.0 }
        else if post_residual <= 46 { 0.0 }
        else { 29.0 };
    score += class;

    // Harmonic residual bonus (divisible residuals more likely to be reused)
    let harmonic_bonus: f64 = if post_residual % 10 == 0 { -10.0 }
        else if post_residual % 25 == 0 { -8.0 }
        else if post_residual % 20 == 0 { -5.0 }
        else if post_residual % 15 == 0 { -3.0 }
        else { 0.0 };
    score += harmonic_bonus;

    // Lookahead: how well does the next item land here after this one?
    if next_item_size > 0 {
        if next_item_size as u64 == post_residual as u64 {
            score -= 76.0;
        } else if (next_item_size as u64) <= (post_residual as u64) {
            let new_post = post_residual - next_item_size;
            if new_post == 0 { score -= 33.0; }
            else if new_post <= 10 { score -= 28.0; }
            else if new_post <= 25 { score -= 14.0; }
            else { score += (new_post as f64) * 0.18; }
            if new_post > 0 && new_post < 4 { score -= 11.0; }
            let next_fits_elsewhere = mean_residual >= next_item_size as f64 && open_bins_count > 1;
            if !next_fits_elsewhere && post_residual >= next_item_size { score -= 13.0; }
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 { score -= 42.0; }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 { score -= 22.0; }
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 { score -= 7.0; }
            // dead-space lookahead: penalize residuals too small for plausible items
            if new_post > 0 && new_post < item_size {
                score += (item_size - new_post) as f64 * 0.06;
                if progress > 0.5 { score += (item_size - new_post) as f64 * 0.05 * progress; }
            }
        } else {
            score += frac * 35.0;
            if post_residual > 60 { score += 6.0; }
        }
    }

    // Consolidation pressure
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 40.0; }

    // New-bin candidate gating
    if bin_residual == bin_capacity {
        score = 56.0 + frac * 10.0;
        if post_residual >= 56 { score -= 12.0; }
        if post_residual >= 85 { score -= 9.0; }
        if post_residual >= 96 { score -= 6.0; }
        if fitting_bins_count == 0 { score -= 86.0; }
        if progress > 0.85 { score -= 7.0; }
        if progress > 0.9 && open_bins_count > 3 { score += 15.0; }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 { score += 14.0; }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 { score -= 10.0; }
        // defer new bin when open bins have room comparable to the next item
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 { score += 8.0; }
        // resist opening a new bin when some open bin already fits the item snugly
        if fitting_bins_count >= 1 && mean_residual >= item_size as f64 && mean_residual < (item_size + 8) as f64 { score += 16.0; }
