        if progress < 0.25 && open_bins_count < 5 { score += 12.0; }
    }

    // Fragmentation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity { score += 7.0; }

    // Prefer bins whose residual is an exact multiple of common item sizes
    if post_residual > 0 && item_size > 0 && post_residual % item_size == 0 { score -= 5.0; }

    // Late-stream tightening
    score += 10.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

