            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 { score -= 7.0; }
            // dead-space penalty scaled by stream progress (from best heuristic)
            if new_post > 0 && new_post < item_size {
                score += (item_size - new_post) as f64 * 0.06;
                if progress > 0.5 { score += (item_size - new_post) as f64 * 0.05 * progress; }
            }
        } else {
            score += frac * 35.0;
            if post_residual > 60 { score += 6.0; }
        }
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 40.0; }

    if bin_residual == bin_capacity {
        score = 56.0 + frac * 10.0;
        if post_residual >= 56 { score -= 12.0; }
        if post_residual >= 85 { score -= 9.0; }
        if post_residual >= 96 { score -= 6.0; }
        if fitting_bins_count == 0 { score -= 86.0; }
        if progress > 0.85 { score -= 7.0; }
        if progress > 0.9 && open_bins_count > 3 { score += 15.0; }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 { score += 14.0; }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 { score -= 10.0; }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 { score += 8.0; }
    }

    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity { score += 7.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual close to next item size (within a small tolerance band).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if gap <= 5 {
            score -= 25.0 - 5.0 * gap as f64;
        } else if post_residual < next_item_size {
            // Dead space relative to the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize small unusable residues that likely fit nothing (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    // (large dead space would be created elsewhere); otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            // A fresh bin can absorb the next item too: slight bonus.
            score -= 10.0;
        }
    }

    // Early in the stream, allow slightly more bin spreading; late, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

