    }

    // Time horizon: early in the stream, prefer keeping residuals large/flexible
    // (open new bins cheaply); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 15.0;              // late: favor filling existing bins
    score += (1.0 - progress) * (post_residual as f64) * 0.10; // early: value flexibility

    // Global state: many open bins -> consolidation pressure (penalize high residual).
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * (post_residual as f64) * 0.05;
    }

    // Compare against mean residual: bins with residual well below mean are
    // "almost full" — prefer placing into them to close them out.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: opening a fresh bin is attractive when the
    // item is large or all existing fits are poor; otherwise discourage it.
    if bin_residual == bin_capacity {
        let waste_vs_best = (mean_residual - item_size as f64).max(0.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
