            score -= 30.0 + waste_vs_best * 0.5; // fresh bin serves lookahead pair
        } else if item_size >= 60 {
            score -= 10.0;
        } else {
            score += 45.0 + waste_vs_best * 0.3; // prefer existing bins for small items
        }
    }

    score
}

