pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize leftover space, with non-linear shaping
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses (smooth sigmoid-like ramp)
    let tight = (item_size as f64 / cap) * (1.0 - x);
    let ramp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 30.0 * tight * (0.5 + ramp);

    // Last-chance bin: strong smooth reward amplified late in stream
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 25.0 * last_chance * (1.0 + progress);

    // Lookahead: reward leaving room for the next item (smooth quadratic match)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = x - nx;
        let match_q = 1.0 - (diff * diff) / (1.0 + nx * nx);
        score -= 15.0 * match_q.max(0.0) * (1.0 - progress * 0.5);
    }

    // Penalize creating dead space far from mean residual (non-linear divergence)
    let dev = (x - mean_residual / cap).abs();
    score += 10.0 * dev * dev;

    // Mild penalty for many open bins, smoothly increasing with progress
    score += (open_bins_count as f64).ln1p() * (2.0 + 6.0 * progress);

    // New-bin candidate: prefer it only when it would be very full (smooth gate)
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    let fill = item_size as f64 / cap;
    score += new_bin * 20.0 * (1.0 - fill * fill);

    score
}

