pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (1/4, 1/2, 3/4 of C=100)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let threeq = 3 * quarter;

    // Item class via integer division thresholds
    let item_class = (item_size + quarter - 1) / quarter; // 1..=4
    let next_class = ((next_item_size + quarter - 1) / quarter) as f64;

    // Reward tight fits (small post_residual), especially modulo-aligned ones
    let tight_bonus = match post_residual {
        0 => 60.0,
        r if r <= quarter / 2 => 30.0,
        r if r < quarter => 15.0,
        _ => 0.0,
