    // common small item class (1..=quarter) can fill exactly.
    let dead = post_residual % quarter;
    if post_residual > 0 && dead != 0 {
        // residual not a multiple of a quarter: harder to pair
        score += 6.0;
        if dead < 10 {
            score += 8.0; // sliver smaller than min item size
        }
    } else if post_residual > 0 {
        score -= 5.0; // quarter-aligned residual is reusable
