    // Harmonic pairing: if the NEXT item fits exactly into post_residual,
    // strongly reward this placement (lookahead chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap <= quarter / 2 {
            score -= 20.0;
        }
        // class-complement: next item of complementary harmonic class
        if item_class + next_class as u32 == 4 && post_residual >= next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: this residual becomes dead space
        score += 10.0;
