        score += (open_bins_count as f64) * 1.5;
    }

    // Prefer bins whose residual is close to the mean residual (keep balance)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Slight preference for fuller bins (smaller residual before placement)
    score += (bin_residual as f64) * 0.1;

    score
}

