    score += class_bonus;

    // Small residuals are almost dead space; penalize nonlinearily below threshold.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 3.0;
    }

    // Lookahead coupling: reward when post_residual exactly or nearly fits next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (pr as f64) >= ni {
            let gap = pr as f64 - ni;
            if gap == 0.0 {
                score -= 45.0;
            } else if gap < 10.0 {
                score -= 25.0 - gap * 1.5;
            } else if (pr % next_item_size) == 0 {
                score -= 15.0; // next item divides residual: harmonic match
            } else {
                score += gap * 0.15;
            }
        } else {
            // next item won't fit here anyway; mildly prefer larger leftovers
            score += (ni - pr as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling already-open bins when many are open (bin-count pressure).
    score -= (open_bins_count as f64) * 0.6;

    // Reward bins tighter than the mean residual (concentrating fullness).
    score += (mean_residual - post_residual as f64) * 0.25;

    // Early in the stream, be pickier about tight fits; later, just pack.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    // Slight preference for high fill ratio of this placement.
    score -= (item_size as f64 / cap) * 10.0;

    score
}

