            // Next item can also go here: small leftover gap is good.
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot fit: penalize proportionally to wasted capacity.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(60.0);
        }
    }

    // Compare post_residual relative to mean residual: avoid leaving this bin
    // far above the average (fragmenting space) unless it's a near-perfect fit.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.1 * dev; // slight reward for below-average residual
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
