            if new_post > 0 && (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                score += 10.0;
            }
            // dead-space ratio guard vs next item
            if new_post > 0 && (new_post as f64) > (next_item_size as f64) * 2.5 && new_post > 18 {
                score += 6.0;
            }
            if new_post > 0 && new_post < item_size {
                score += (item_size - new_post) as f64 * 0.06;
                if progress > 0.5 {
                    score += (item_size - new_post) as f64 * 0.05 * progress;
                }
            }
            if new_post > 0 {
                let usable = (new_post as f64) >= mean_residual * 0.5;
                if !usable && progress > 0.3 {
                    score += 5.0 * progress;
                }
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
            }
            // tightness coupling: prefer residuals near the mean
            if new_post > 0 && (new_post as f64 - mean_residual).abs() < 3.0 {
                score -= 7.0;
            }
            // NEW: reward leaving residuals that still fit the mean-size future item
            if new_post > 0 && mean_residual > 0.0 && (new_post as f64) >= mean_residual && (new_post as f64) < mean_residual * 1.4 {
                score -= 6.0 * (1.0 - progress);
            }
        } else {
            score += (post / cap) * 35.0;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap = next_item_size - post_residual;
            if gap <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            // NEW: penalize bins that will almost surely become dead space
            if gap > 40 && progress > 0.6 {
                score += 8.0;
