    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    if bin_residual == bin_capacity {
        score = 57.0 + (post / cap) * 10.0;
