            score -= 88.0;
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 16.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // fresh bin that can absorb next item too while open bins are tight
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0 && next_item_size <= post_residual && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 9.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 6.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        // NEW: discourage new bins when the item fits snugly in some open bin
        if fitting_bins_count >= 1 && item_size as f64 >= mean_residual * 0.8 && open_bins_count > 1 {
            score += 14.0;
        }
        // NEW: allow a fresh bin late when open residuals are all too small for next item
        if next_item_size > 0 && mean_residual < next_item_size as f64 && progress < 0.85 && open_bins_count > 3 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
