            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 32.0;
            } else if new_post <= 10 {
                score -= 27.0;
            } else if new_post <= 25 {
                score -= 14.0;
            } else {
                score += new_post as f64 * 0.16;
