    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 7.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // New empty bin candidate: default to keeping items in open bins,
    // open a fresh bin only when it clearly pays off.
    if bin_residual == bin_capacity {
        score = 60.0 + (post / cap) * 10.0;
        if post_residual >= 56 {
            score -= 11.0;
        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if post_residual >= 96 {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
