        let item_frac = item_size as f64 / cap;
        if item_frac > 0.7 {
            score -= 14.0;
        }
    }

    // Mild late-stream tilt: prefer tight fits as the stream ends
    score += 8.0 * progress * (post / cap);

    score
}

