pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual can still fit the next item: reward proportionally
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space relative to mean residual
        score += 15.0 * (1.0 - post_residual as f64 / mean_residual.max(1.0));
    }

    // Penalize leaving tiny unusable gaps (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer packing into already-crowded bins (tighten packing)
    score -= 8.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Mild preference to keep bin count low when many bins are open
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bin leaves bad dead space
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
