        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if next_item_size > bin_residual {
            // next item can't fit here anyway; less pressure to conserve this bin
            score -= 3.0;
        }
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 25.0;
