pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement.
    let mut score = pr;

    // Smooth polynomial coupling: residual normalized by capacity, shaped by progress.
    let r = pr / cap; // in [0,1]
    let p = progress;
    // Early in the stream, waste is more forgivable; late, dead space is costly.
    let waste_penalty = r * r * (1.0 + 3.0 * p) + r * p * 2.0;
    score += waste_penalty * cap;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - r;
    score -= 8.0 * tightness * tightness * (0.5 + p);

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            let slack = (pr as f64 - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
