        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening a new bin when open bins could fit; relax slightly late in stream.
    if is_new_bin {
        score += 60.0 - 25.0 * progress;
    } else {
        // Reward fuller placements (larger filled fraction).
        score -= (item_size as f64 / cap) * 15.0;
    }

    // Lookahead coupling: if the next item can still fit here, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 4.0 * progress;
