    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let next_ratio = next_item_size as f64 / cap;
    let pr_norm = pr / cap;
    let mean_norm = mean_residual / cap;

    // Base: penalize wasted post residual, with a quadratic shaping so
    // very small residuals are strongly rewarded (tight fits).
    let mut score = pr_norm * (1.0 + 0.8 * pr_norm) * cap;

    // Smooth non-linear coupling of post residual with stream progress:
    // early in the stream, keep bins flexible (penalize small residuals more),
    // late in the stream, prioritize tight packing harder.
    let flexibility = 0.5 + 0.5 * (1.0 - progress);
    let tightness = 0.5 + 0.5 * progress;
    score += flexibility * (pr_norm * pr_norm) * cap;
    score -= tightness * (1.0 - pr_norm) * (1.0 - pr_norm) * 6.0;

    // Reward bins whose post residual can still host the lookahead item
    // (smooth logistic-like coupling instead of a hard threshold).
    if next_item_size > 0 && post_residual > 0 {
        let gap = (pr - next_item_size as f64) / cap;
        let usable = 1.0 / (1.0 + (-8.0 * gap).exp());
        score -= 4.0 * usable;
    }

    // Penalize bins that are the last fitting option less harshly when the
    // fit is good (avoid forcing new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 2.0 * fit_ratio;
    }

    // Mild coupling with mean residual: prefer bins deviating below the mean
    // (fill fuller-than-average bins first), smoothly weighted.
    score += 1.5 * (pr_norm - mean_norm).abs() * (pr_norm - mean_norm).signum();

    // Slight penalty for very full open-bin population relative to progress.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64).ln().max(1.0);
