        0 => score -= 25.0,           // near-perfect fill (0..10 dead space)
        1 => score -= 15.0,           // excellent
        2 => score -= 8.0,            // good
        3 => score -= 3.0,            // decent
        4 | 5 => score += 2.0,        // mediocre: half-bin dead zone
        6 | 7 => score += 6.0,        // poor
        8 | 9 => score += 12.0,       // very poor
        _ => score += 18.0,           // nearly empty bin chosen wastefully
