pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space: residuals that likely can't fit
    // typical future items (assume minimum useful chunk ~ small fraction of capacity).
    let dead_threshold = (bin_capacity as f64 * 0.15).max(1.0);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Last-chance bin: strongly favor using it, otherwise item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * fit_ratio;
    }

    // Many open bins: discourage opening yet another bin.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 25.0 + 10.0 * open_pressure;
        // But if no existing bin fits well (this call's bin IS the new bin context),
        // allow opening when mean residual of open bins is small (they're nearly full).
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 45.0 * mean_tightness;
    } else {
        // Existing bin: reward using it, more so when bins are crowded.
        score -= 10.0 + 5.0 * open_pressure;
    }

    // Lookahead: if next item would fit the post-residual exactly, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits after placement: mild reward proportional to leftover usefulness.
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here: penalize leaving dead space that blocks it.
        score += 5.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Late in the stream: prefer consolidating into existing bins (avoid new bins).
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 15.0 * progress;
    } else if progress > 0.7 && bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    // Mild preference for bins with residual near mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

