pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are gold.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space class: post_residual that no future item (min size ~1..10) can use well
        let harmonic_class = post_residual % 10;
        // class 0 (10,20,...): highly reusable -> reward
        score -= 8.0 * (1.0 - harmonic_class as f64 / 10.0);
        // tiny unusable slivers (< 10) are dead space -> penalize
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Next-item lookahead: post_residual must accommodate next item, else waste
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // chain fit reward, stronger when post_residual lands exactly in next item's class
            score -= 12.0;
            if post_residual == next_item_size {
                score -= 30.0;
            }
            let gap = (post_residual - next_item_size) as f64;
            score += 0.15 * gap; // prefer tight chain fits
        } else {
            // next item won't fit here: this residual likely becomes dead space
            score += 10.0 + 0.2 * (post_residual as f64).min(30.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins with slack: discourage spreading into bins with large residual
    let frac = post_residual as f64 / cap;
    score += 10.0 * frac * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));

    // Prefer bins whose residual deviates from the mean toward tightness
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when no open bin fits tightly
    if bin_residual == bin_capacity {
        let early = step_index as f64 / (total_items.max(1) as f64);
        // default mild penalty; lifted if existing fits are bad (fitting_bins_count==1 handled above)
        score += 20.0 - 10.0 * early;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // room for a chain in fresh bin
        }
    }

    score
}

