    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // New empty bin candidate: calibrated against best bins' residual profile
    if bin_residual == bin_capacity {
        score = 57.0 + (post / cap) * 10.0;
