        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 6 {
            score += 22.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Non-linear penalty on dead space, amplified for small residuals.
        let r = post_residual as f64;
        score += 200.0 / r;
    }

    // Lookahead: reward residuals that can still host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space the next item cannot use; penalize more late in stream.
            let t = step_index as f64 / total_items.max(1) as f64;
            score += 40.0 + 60.0 * t;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the fullest bin (smallest residual).
        score -= (bin_capacity - bin_residual) as f64 * 0.5;
    }

    // New-bin candidate handling: only attractive when open bins fit badly
    // (large residual left behind relative to mean) or late in the stream
    // with many open bins.
    if bin_residual == bin_capacity {
        let t = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (mean_residual - item_size as f64).max(0.0);
        score = bin_capacity as f64 - 150.0 * bad_fit / bin_capacity as f64
              + 120.0 * t
              + 5.0 * open_bins_count as f64;
        // If this is the only option, make it clearly viable.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Mild preference for balancing residual against global mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

