    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity divided into 10 classes.
    let cap = bin_capacity as f64;
    let class = (post_residual as f64 / (cap / 10.0)).floor() as f64;

    // Reward small classes (tight fits) non-linearly.
    score -= (10.0 - class) * (10.0 - class) * 0.6;

    // Perfect fit gets a huge reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic pairing: next item exactly fills the leftover class.
            let pair_class = (post_residual as f64 / (cap / 10.0)).floor() as f64
                - (next_item_size as f64 / (cap / 10.0)).floor() as f64;
            score -= 40.0 + pair_class * 8.0;
            // Exact pairing (next item == post residual) is ideal.
            if next_item_size == post_residual {
                score -= 150.0;
            }
        } else {
            // Leftover that the next item cannot use is dead space.
            let waste = post_residual as f64 - (post_residual % next_item_size.max(1)) as f64;
            score += waste * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize spreading across too many open bins with large mean residual.
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64).abs() * 0.15;
    }

