    // (i.e., when the current bin's residual is tiny relative to the item).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; discounted late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.9 - progress * 20.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // forced new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Small integer-division threshold coupling: residues in the lowest
    // harmonic band (< capacity/10) are nearly perfect fits.
    if post_residual < bin_capacity / 10 {
        score -= 60.0;
    }

    score
}

