        score += 12.0;
    }
    // Bonus if post_residual exactly accommodates the next item (chained fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading (avoid new bins),
    // with few open bins, consolidation is cheaper.
    let ob = open_bins_count as f64;
    score += ob * 1.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is justified only if the current bin's post-fit is dead space
        // or the item fits very poorly everywhere; otherwise penalize new bins.
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 30.0 - fit_quality * 30.0;
        if post_residual >= 10 && fitting_bins_count > 1 {
            score += 15.0; // an existing usable alternative exists; don't open a bin
        }
    }

