    // many half-empty bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Slight late-stream tightening: as the stream progresses, prefer perfect packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

