pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Dead-space penalty: super-linear in leftover space (small leftovers are good).
    score += (post_residual as f64).powf(1.35) * 0.02;

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // bonus scaled by how snugly the next item nests
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 + 10.0 * snug;
        } else {
            // next item won't fit here; slight penalty for wasting capacity now
            score += 2.0 + 0.03 * next_item_size as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: mild bonus, resolved by best-fit term
        score -= 1.0;
    }

    // Global state coupling: many open bins with high mean residual -> discourage
    // opening new bins, encourage consolidating into existing space.
    if bin_residual == bin_capacity {
        // new-bin candidate: base handicap that grows with open bins & mean residual
        let mut nb = 12.0 + 0.6 * open_bins_count as f64 + 0.08 * mean_residual;
        // early in stream, opening bins is cheaper; late in stream, consolidate
        nb *= 1.2 - 0.5 * progress;
        // but if this item is large and would leave a tight fit, opening fresh is fine
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            nb -= 6.0;
        }
        score += nb;
    } else {
        // existing bin: small reward when it sits below mean residual (uses the fullest bins first)
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
        // consolidation pressure late in the stream
        score -= 2.0 * progress;
    }

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 4.0; // nearly-perfect fit: dead space smaller than min item size
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let res = post_residual as f64;
    let x = res / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (t small): prefer tight fits aggressively (waste penalized more).
    // Late (t large): slightly relax, favoring bins that leave mid-range residuals.
    let progress_weight = 1.0 + 0.8 * t * t - 0.4 * t;
    let quadratic_waste = 4.0 * x * x * progress_weight;
    let cubic_damp = -1.5 * x * x * x * (1.0 - t);
    score += quadratic_waste + cubic_damp;

    // Smooth interaction: residual relative to mean residual of open bins.
    let mean_norm = mean_residual / cap;
    let mean_coupling = 0.6 * (x - mean_norm) * (x - mean_norm) - 0.3 * (x - mean_norm);
    score += mean_coupling;

    // Lookahead: penalize leaving a residual that just barely misses next item;
    // reward leaving residual that can host next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = res - nxt;
        if gap >= 0.0 {
            score -= 0.8 * (1.0 - (gap / cap).abs().min(1.0)) * (1.0 - t);
        } else {
            score += 0.5 * (-gap / nxt).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 2.5;
    }

    // New-bin candidate: base penalty that grows with how many bins already fit the item
    // and with stream progress (consolidation pressure), softened when current fit is bad.
    if bin_residual == bin_capacity {
        let fit_pressure = fitting_bins_count as f64;
        let fit_badness = (res - item_size as f64) / cap;
        score += 1.5 + 0.6 * fit_pressure + 2.0 * t - 1.0 * fit_badness.max(0.0);
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.02 * open_bins_count as f64 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
