    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A post_residual in [1, 15] is nearly worthless for future items.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (15.0 - post_residual as f64) / 15.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if lookahead would fill it exactly.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // lookahead can't use leftover space
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let bin_is_new = bin_residual == bin_capacity;
    if !bin_is_new {
        score -= 3.0; // prefer using existing bins slightly
        if fitting_bins_count == 1 {
            // last-chance bin: strongly favor using it before opening a new bin
            score -= 15.0;
        }
    } else {
        // Opening a new bin: penalize when many bins are already open,
        // and when existing mean residual is large (space is being wasted elsewhere).
        score += 8.0 + 0.8 * open_bins_count as f64 + 0.15 * mean_residual;
        // But allow new bin if current item leaves a bad gap in any existing bin.
        if post_residual >= 30 {
            score -= 10.0; // fresh bin keeps large usable residual
        }
    }

    // Late in the stream, tighten up: avoid opening bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_is_new && progress > 0.85 {
        score += 10.0 * (progress - 0.85) / 0.15;
    }

    // Mild preference for bins with residual close to item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    score
}

