    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Refined dead-space class bands
    let class: f64 = if post_residual == 0 {
        -74.0
    } else if post_residual <= 4 {
        -52.0
    } else if post_residual <= 8 {
        -46.0
    } else if post_residual <= 10 {
        -41.0
    } else if post_residual <= 20 {
        -23.0
    } else if post_residual <= 46 {
        0.0
    } else {
        29.0
    };
    score += class;

    // Round residuals are easier to fill later
    if post_residual % 10 == 0 {
        score -= 11.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual % 20 == 0 {
        score -= 5.0;
    } else if post_residual % 15 == 0 {
        score -= 3.0;
    }

    // Dead-space ratio term
    let dead_ratio = post / cap;
    if dead_ratio > 0.55 {
        score += dead_ratio * 7.0;
    } else if dead_ratio < 0.08 {
        score -= 4.5 * (1.0 - dead_ratio);
    }

    // Lookahead: simulate placing the next item
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 82.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 37.0;
            } else if new_post <= 10 {
                score -= 30.0;
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
