pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post_residual (non-linear).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot use the leftover space.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0; // dead space for the lookahead
        } else {
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize leftover strictly.
        score += 30.0 * fit_ratio;
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin guarantees lookahead fits
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    } else {
        // Crowding pressure: prefer filling bins when many are open.
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Prefer bins with residuals below the mean (consolidate emptier space).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

