            }
        } else {
            score += (post / cap) * 35.0;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap = next_item_size - post_residual;
            if gap <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap <= 12 && gap >= post_residual / 2 && mean_residual >= gap as f64 {
