        }
    }

    // Mutation: exact-fit bonus scaled by stream position — late in the stream,
    // zeroing out residuals matters more since leftovers can't be recovered.
    if post_residual == 0 && progress > 0.6 {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth non-linear polynomial coupling of post_residual with progress.
    // Early on: mild preference for compact residual; late: stronger (waste matters more).
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let poly = pr_norm * pr_norm * (0.5 + 2.0 * progress) + pr_norm * (1.0 - progress);
    score += 20.0 * poly;

    // Reward tight fits more aggressively as stream progresses (non-linear in progress)
    let tightness = 1.0 - pr_norm;
    score -= 15.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead: penalize if next item cannot fit in the post residual (dead space risk)
    if next_item_size > 0 {
        if (post_residual as u64) < next_item_size as u64 {
            score += 6.0 * (1.0 - progress) + 3.0;
        } else {
            // Reward leaving room for the next item, scaled by how well it fits
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 * (1.0 - slack) * (1.0 - progress);
        }
    }

    // Last chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins could fit, more so early in the stream
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 * (1.0 - progress) + 10.0 + 0.5 * open_bins_count as f64;
    }

    // Nudge toward bins with residuals near the mean (balanced packing)
    score += 0.15 * (pr - mean_residual).abs();

    score
}

