    // ---- Harmonic class of the post residual ----
    // Residuals on coarse capacity fractions (1/2, 1/4, multiples of 10) are
    // statistically easier to fill later; nudge scores toward them.
    if post_residual > 0 {
        if post_residual % 50 == 0 {
            score -= 1.0;
        } else if post_residual % 25 == 0 {
            score -= 0.6;
        } else if post_residual % 10 == 0 {
            score -= 0.3;
        }
        // Awkward sliver classes: 1..4 units and odd fine remainders are near-dead space.
        let fine_class = (post_residual % 10) as f64;
        if post_residual < 10 {
            score += 1.5 + 0.2 * fine_class; // tiny unusable sliver
        } else if fine_class >= 1.0 && fine_class <= 3.0 {
            score += 0.4; // hard-to-match remainder class
        }
    }

    // ---- Lookahead chaining (k=2) ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item also lands here: reward, strongest when the chain is tight.
            let chain_tightness = nxt / post.max(1.0);
            score -= 4.0 + 6.0 * chain_tightness.min(1.0);
            if post_residual % next_item_size == 0 {
                score -= 3.0; // exact harmonic fill: post is an integer multiple of next
            }
        } else {
            // Chain broken: this placement strands the residual for at least one step.
            score += 0.5;
        }
    }

    // ---- Last-chance bin: avoid opening a new bin when only one bin fits ----
    if bin_residual >= item_size && bin_residual != bin_capacity && fitting_bins_count == 1 {
        score -= 3.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening cost: an empty bin must beat existing bins by a clear margin.
        score += 2.0;
        // But a fresh bin that promises a perfect two-item harmonic fill is worth it.
        if next_item_size > 0 && next_item_size <= post_residual && post_residual % next_item_size == 0 {
            score -= 5.0;
        }
    }

    // ---- Consolidation pressure vs. the crowd of open bins ----
    // Prefer bins whose residual sits below the fleet mean (fill fuller bins first).
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap);
    // Early in the stream, mildly favor packing into existing capacity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    score += 0.5 * (1.0 - progress) * (post / cap);

    // ---- Crowded-fit penalty: wasteful loose fit when many bins compete ----
    if fitting_bins_count > 1 && post > 0.5 * cap {
        score += 1.0;
    }

    score
}

