pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item's size (perfect chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // exact 2-step match: near-perfect fill
        } else {
            score += diff * 0.8; // penalize mismatch with lookahead
        }
        // Reward bins where post_residual can still fit the next item comfortably
        if post_residual as f64 >= nxt {
            score -= 10.0;
        } else if post_residual > 0 {
            // small dead space that cannot host next item
            score += (post_residual as f64) * 0.5;
        }
    }

    // Penalize post_residual far below mean residual (wasting a roomy bin on a tight fit
    // is fine, but leaving the bin unusable is not) — favor low post_residual overall.
    score -= (mean_residual - post_residual as f64).abs().min(mean_residual) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If the item is large relative to capacity, a fresh bin is more attractive.
        let frac = item_size as f64 / bin_capacity as f64;
        score -= frac * 20.0;
        // If next item is large and current bin would leave tiny residual, new bin helps.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size / 2 {
            score -= 15.0;
        }
    }

    // Mild stream-progress calibration: early on, be slightly conservative about
    // filling bins tightly; later, pack aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * (post_residual as f64) * 0.1;
    }

    // Reward using bins that are already substantially filled (low residual).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
