pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalize the brand-new empty bin candidate strongly, but relax over time
    // so late in the stream we may prefer fresh bins over terrible fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let openness = 0.55 + 0.45 * progress;
        score += openness * bin_capacity as f64 * 1.6;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.2 * tightness * tightness * item_size as f64;

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 * (1.0 - progress);
    }

    // Lookahead coupling: if next item fits the post-residual, big reward;
    // if next item barely doesn't fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bonus: this is the only bin that fits -> strong reward.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, emphasize best-fit discrimination.
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global state: many open bins with high mean residual -> prefer using
    // existing space rather than opening new bins.
    score += 0.15 * (mean_residual - post_residual as f64);
    score -= 0.4 * open_bins_count as f64 * tightness;

    // Early in the stream, keep bins flexible (avoid tiny leftovers);
    // late in the stream, squeeze hard.
    score += (1.0 - progress) * 0.35 * post_residual as f64;

    // Slight preference to fill bins with larger residual capacity first
    // when the item is large.
    score -= 0.05 * (bin_residual as f64 / bin_capacity as f64) * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_pr * (1.0 - progress);
    score -= 18.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);
    score += 6.0 * norm_pr * p3;
    // penalize large dead space more as stream progresses
    score += 8.0 * norm_pr * norm_pr * norm_pr * (1.0 + 2.0 * p2);
    // tight fit reward, smoothed
    let fit = 1.0 - (pr / cap - 0.05).abs();
    score -= 10.0 * fit.max(0.0) * (1.0 - p2);
    // last-chance bonus
    if fitting_bins_count == 1 { score -= 15.0 * (1.0 - 0.5 * progress); }
    // lookahead: reward leaving space for next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = (pr - ni).abs();
        score -= 6.0 * (1.0 - gap / cap) * (1.0 - progress);
    }
    // mild penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: post residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    let progress_ramp = progress * progress * (3.0 - 2.0 * progress);
    score += 30.0 * progress_ramp * norm_pr * norm_pr;

    // Perfect-fit reward
    let fit_bump = (-norm_pr * norm_pr * 12.0).exp();
    score -= 25.0 * fit_bump;

    // Dead-space class bands (tightened small-residual rewards)
    let class: f64 = if post_residual == 0 {
        -74.0
    } else if post_residual <= 4 {
        -52.0
    } else if post_residual <= 8 {
        -46.0
    } else if post_residual <= 10 {
        -41.0
    } else if post_residual <= 20 {
        -22.0
    } else if post_residual <= 46 {
        0.0
    } else {
        28.0
    };
    score += class;

    // Round residuals are easier to fill later
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual % 20 == 0 {
        score -= 5.0;
    } else if post_residual % 15 == 0 {
        score -= 3.0;
    }

    // Dead-space ratio term
    if norm_pr > 0.55 {
        score += norm_pr * 6.0;
    } else if norm_pr < 0.08 {
        score -= 4.0 * (1.0 - norm_pr);
    }

    // Penalize leaving a residual that is too small for typical future items
    let mid = 0.25;
    score += 15.0 * (norm_pr - mid) * (norm_pr - mid);

    // Next-item lookahead with snug tiers
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 82.0;
        } else if pr >= nx {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 38.0;
            } else if new_post <= 10 {
                score -= 30.0;
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
                score += new_post as f64 * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 13.0;
            }
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 10.0 * snug * snug;
            // pair-fill bonus
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 48.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 25.0;
            }
            // divisibility: residual reusable in multiples of next item
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 9.0;
            }
            // second/third-order lookahead: residual can absorb next item repeatedly
            if new_post > 0 {
                if new_post < item_size {
                    score += (item_size - new_post) as f64 * 0.06;
                    if progress > 0.5 {
                        score += (item_size - new_post) as f64 * 0.05 * progress;
                    }
                }
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
