        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if post_residual >= 96 {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 88.0;
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 16.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // near-perfect pair fill with next item: prefer this bin over a new one
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.45 {
            score -= 6.0;
        }
        // aggregate-space pressure: if total open slack is large, prefer reusing bins
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                score += 9.0;
            }
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            score -= 6.0;
        }
        if progress > 0.55 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 5.0;
        }
        // new: mid-stream consolidation — resist opening bins when slack is plentiful
        if progress < 0.65 && open_bins_count > 4 && mean_residual > cap * 0.3 {
            score += 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        score -= 72.0; // perfect fit: stronger reward
    } else {
        score -= (item_size as f64 / cap) * 25.0;
    }

    // Lookahead: two-item chain planning.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 36.0;
            } else if new_post <= 10 {
                score -= 29.0;
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
                score += new_post as f64 * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 12.0;
            }
            let next_fits_elsewhere = mean_residual >= next_item_size as f64 && open_bins_count > 1;
            if !next_fits_elsewhere && post_residual >= next_item_size {
                score -= 15.0;
            }
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 46.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 24.0;
            }
            if new_post > 0 && new_post < item_size {
                score += (item_size - new_post) as f64 * 0.06;
                if progress > 0.5 {
                    score += (item_size - new_post) as f64 * 0.05 * progress;
                }
            }
            if new_post > 0 {
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
                if new_post >= next_item_size {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 10.0;
                    } else if post2 <= 5 {
                        score -= 6.0;
                    } else if post2 >= next_item_size {
                        let post3 = post2 - next_item_size;
                        if post3 == 0 {
                            score -= 7.0;
                        } else if post3 <= 4 {
                            score -= 4.0;
                        }
                    }
                }
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 14.0;
                }
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
            }
        } else {
            // next item does NOT fit this bin's post-gap
            score += (post / cap) * 35.0;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap = next_item_size - post_residual;
            if gap <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap > 5 && gap <= 20 && mean_residual >= gap as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance pressure: only fitting bin -> use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 42.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    let ob = open_bins_count as f64;
    score += ob * 1.5;
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score = 57.0 + (post / cap) * 10.0;
        if post_residual >= 56 {
            score -= 12.0;
        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if post_residual >= 96 {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 88.0; // no alternative: must open
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 16.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        if open_bins_count > 1 {
            let aggregate = mean_residual * ob;
            if aggregate > cap * 1.2 && progress < 0.8 {
                score += 9.0;
            }
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            score -= 6.0;
        }
        if progress > 0.55 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 5.0;
        }
    }

    // Mild preference to fill bins below the mean residual.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening.
    score -= progress * 5.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: how "reusable" is the post residual?
    // Residuals that are multiples of common item sizes (10,20,25,50) are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 8.0; }
        if pr % 20 == 0 { harmony += 6.0; }
        if pr % 25 == 0 { harmony += 6.0; }
        if pr % 50 == 0 { harmony += 5.0; }
        // small dead space is bad; large residual is reusable
        if pr < 10 { harmony -= 25.0; }
        score -= harmony;

        // Integer-division threshold: residual >= typical next item is a good slot
        if next_item_size > 0 && pr >= next_item_size {
            score -= 12.0 + 0.25 * (pr - next_item_size) as f64;
        } else if next_item_size > 0 {
            score += 10.0; // cannot host lookahead item
        }

        // Modulo coupling between post_residual and next item: exact class match
        if next_item_size > 0 && (pr % next_item_size.max(1)) == 0 && pr > 0 {
            score -= 9.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize wasting a nearly empty bin's potential when many bins are open
    if (bin_residual as f64) > mean_residual + 30.0 && post_residual > 0 {
        score += 8.0;
    }

