    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin while others could fit the item.
        score += 150.0;
        // Larger items fill a fresh bin better: soften reluctance.
        score -= 120.0 * (item_size as f64 / cap);
