        score -= (item / cap) * 25.0;
    }

    // Lookahead coupling with the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
