pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual > 0 && post_residual < 10 {
        // Dead space too small for smallest item.
        score += 80.0;
    } else {
        // Reward tight fits by fill fraction.
        score -= (item / cap) * 30.0;
    }

    // Lookahead: strongly prefer residuals that can host the next item tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // Residual becomes dead space for the lookahead item.
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
        }
    }

    // Last-chance pressure: only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling (residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0; // no alternative: must open
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
    }

    // Mild mean-residual balancing.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post / cap);

    score
}

