        if fitting_bins_count > 0 && it >= 25.0 && mean_residual >= it * 0.8 && open_bins_count > 1 {
            score += 10.0;
        }
        // NEW: if total open slack exceeds remaining expected demand, keep compacting
        let remaining = (total_items - step_index) as f64;
        if open_bins_count > 1 && remaining > 0.0 && mean_residual * (open_bins_count as f64) > remaining * (mean_residual.max(1.0)).sqrt() * 2.0 {
            score += 5.0;
        }
    }

    score
}

