pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: post residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    let progress_ramp = progress * progress * (3.0 - 2.0 * progress);
    score += 30.0 * progress_ramp * norm_pr * norm_pr;

    // Perfect-fit reward (strengthened: exact fills are the biggest win)
    let fit_bump = (-norm_pr * norm_pr * 12.0).exp();
    score -= 40.0 * fit_bump;

    // Dead-space class bands (tightened small-residual rewards)
    let class: f64 = if post_residual == 0 {
        -900.0
    } else if post_residual <= 4 {
        -52.0
    } else if post_residual <= 8 {
        -46.0
    } else if post_residual <= 10 {
        -41.0
    } else if post_residual <= 20 {
        -22.0
    } else if post_residual <= 46 {
        0.0
    } else {
        28.0
    };
    score += class;

    // Round residuals are easier to fill later
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual % 20 == 0 {
        score -= 5.0;
    } else if post_residual % 15 == 0 {
        score -= 3.0;
    }

