    if norm_pr > 0.55 {
        score += norm_pr * 6.0;
    } else if norm_pr < 0.08 {
        score -= 4.0 * (1.0 - norm_pr);
    }

    // Penalize leaving a residual that is too small for typical future items
    let mid = 0.25;
    score += 15.0 * (norm_pr - mid) * (norm_pr - mid);

    // Next-item lookahead with snug tiers (dominant term, borrowed strength)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 250.0;
        } else if pr >= nx {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 120.0;
            } else if new_post <= 10 {
                score -= 60.0 * (1.0 - new_post as f64 / 12.0);
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
                score += new_post as f64 * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 13.0;
            }
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 30.0 * snug * snug;
            // pair-fill bonus
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 90.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 40.0;
            }
            // divisibility: residual reusable in multiples of next item
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 9.0;
            }
            // second/third-order lookahead
            if new_post > 0 {
                if new_post < item_size {
                    score += (item_size - new_post) as f64 * 0.06;
                    if progress > 0.5 {
                        score += (item_size - new_post) as f64 * 0.05 * progress;
                    }
                }
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 25.0;
                    } else if post2 <= 5 {
                        score -= 10.0;
                    } else if post2 >= next_item_size {
                        let post3 = post2 - next_item_size;
                        if post3 == 0 {
                            score -= 14.0;
                        } else if post3 <= 4 {
                            score -= 6.0;
                        }
                    }
                }
                // triple-fill: item + 2x next nearly fills bin
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 25.0;
                }
                // near-mean alignment
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                // tiny unusable residual penalty
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
                // large leftover is still usable
                if new_post > 18 && (new_post as f64) > nx * 2.5 {
                    score += 6.0;
                }
                let usable = new_post as f64 >= mean_residual * 0.5;
                if !usable && progress > 0.3 {
                    score += 5.0 * progress;
                }
            }
            // next item fits elsewhere: safe to leave residual here
            let next_fits_elsewhere = mean_residual >= nx && open_bins_count > 1;
            if next_fits_elsewhere && new_post > 0 {
                score += 3.0;
            } else if !next_fits_elsewhere {
                score -= 15.0;
            }
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap * cap;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // Alignment with mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate handling (rebalanced, borrowed from best heuristic)
    if bin_residual == bin_capacity {
        score = 70.0 + (pr / cap) * 10.0;
        // penalize opening bins when a good fit exists elsewhere
        if fitting_bins_count > 0 {
            score += 60.0 + 20.0 * (fitting_bins_count as f64).min(5.0);
        }
        if fitting_bins_count == 0 {
            score -= 900.0;
        }
        score += 120.0 * progress;
        score += 40.0 * progress * (mean_residual / cap);
        // resist opening bins when aggregate slack is plentiful
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.85 {
                score += 25.0;
            }
        }
        // large next item with little mean slack: opening a fresh bin may be right
        if next_item_size > 0 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 && progress < 0.7 {
            score -= 12.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
    }

    score
}

