pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual (best fit), with slight non-linear sharpening.
    let mut score = post * (1.0 + 0.15 * (post / cap));

    // Smooth polynomial coupling of residual waste with stream progress:
    // later in the stream, dead space becomes more costly.
    let waste_norm = post / cap;
    let coupling = waste_norm * waste_norm * (0.5 + 2.0 * progress);
    score += 20.0 * coupling;

    // Reward near-perfect fits with a smooth saturating bonus.
    let fit_quality = 1.0 - waste_norm;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Penalize opening a new bin more strongly as the stream progresses,
    // but allow it early when open bins have large residuals.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (1.0 + mean_residual / cap)).ln_1p();
        score += (30.0 - 20.0 * progress) * (1.0 + 0.2 * open_pressure);
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap < 1.0 {
            score -= 12.0;
        } else if post >= nxt {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 5.0 * (1.0 - gap / cap);
        }
    }

    // Mild penalty for very tight residual that likely becomes dead space.
    if post > 0.0 && post < 10.0 {
        score += 6.0 * (1.0 - post / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into dead-space tiers.
    // Residuals <= 20 are nearly useless (items are >= 1 but typically larger), so penalize
    // them super-linearly; mid-range residuals are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 200.0; // perfect fit, ideal
    } else if pr <= 10 {
        score += 60.0; // tiny dead space, hard to fill later
    } else if pr <= 20 {
        score += 25.0;
    } else if pr <= 40 {
        score -= 10.0; // sweet zone: can still fit small/medium items
    } else {
        score -= 5.0;
    }

    // Modulo-based harmonic penalty: residuals that are awkward fractions of capacity
    // (not multiples of 10) tend to be harder to pair with future items.
    if pr > 0 && pr % 10 != 0 {
        score += 8.0;
    }

    // Lookahead: strongly reward bins whose post_residual can exactly fit the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 150.0;
        } else if pr >= next_item_size {
            let slack = pr - next_item_size;
            // harmonic tier of the resulting chain residual
            if slack <= 10 { score += 20.0; } else { score -= 25.0; }
        } else {
            score += 30.0; // next item won't fit here afterwards
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and we want many bins for future flexibility.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count == 0) as i32;
        score = 100.0
            - 90.0 * pressure as f64
            - 40.0 * (1.0 - progress)
            + 10.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin keeps room for a large follower
        }
    }

    // Mild tie-break toward bins below mean residual (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            score += 60.0 * (11.0 - gap); // dead space in [1,10] is nearly unusable
        } else if gap < item_size as f64 {
