    }

    // Penalize new-bin opening when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0 + mean_residual * 0.2;
    }

    // Slight preference for larger post_residual when lookahead unknown
    if next_item_size == 0 {
        score -= post_residual as f64 * 0.05;
    }

    score
}

