    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; reward it strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins that are already relatively full (larger residual
    // usage relative to mean residual of open bins).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, avoid opening new bins; early on,
    // be more willing to spread out (best-fit behavior still dominates).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress;

    // Penalize opening a new bin when open bins already exist and the item
    // is small relative to capacity (encourages consolidation mid-stream).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 + 15.0 * progress;
    }

    // Slight preference for bins with residuals close to the item size
    // (exact-ish fit shaping).
    let fit_gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 3.0 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
