    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += (bin_residual as f64 / cap) * 2.0;

    // Slight noise-free harmonic tiebreak via integer division of residual
    score += ((post_residual / 10) as f64) * 0.1;

    score
}

