        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.45 {
            score -= 6.0;
        }
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                score += 9.0;
            }
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            score -= 6.0;
        }
        if progress > 0.55 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 5.0;
        }
        // Snug current fit blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (post_residual as f64 - it) / cap;
            if snug_fit <= 0.12 {
                score += 20.0;
            }
            if snug_fit > 0.12 && snug_fit <= 0.30 && open_bins_count > 2 {
                score += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // Aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            score += 6.0;
        }
        // Exact fit available -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 60.0;
        }
        // Small item into a fresh bin wastes capacity
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            score += 12.0;
        }
        // Large items early may justify a fresh bin
        if it > 60.0 && progress < 0.5 && open_bins_count < 3 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // Gaps below 10 (min item size) are pure waste; gaps that cannot fit
    // the lookahead item are also penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward strongly; if it almost fits, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= (next_item_size as f64) * 0.5;
        } else if post_residual > 0 {
            score += (next_item_size as f64) * 0.3;
        }
    }

    // Tightness reward: favor bins that are well filled.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Open bins pressure: when many bins are open, discourage spreading
    // into new bins / barely-fitting bins.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: penalize unless current bin would leave
    // a large usable residual anyway.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.2;
    }

    // Mean residual coupling: if mean residual is high, prefer compacting
    // (favor bins with residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    // Stream progression: later in the stream, be more conservative about
    // leaving dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (1.0 + progress * 0.5);

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 { let cap = bin_capacity as f64 ; let post = post_residual as f64 ; let item = item_size as f64 ; let mut score = post ; if post_residual == 0 { score -= 1000.0 ; } if next_item_size > 0 { let nxt = next_item_size as f64 ; if next_item_size <= post_residual { let diff = (post - nxt) . abs () ; score -= 900.0 * (1.0 - diff / cap) ; if diff == 0.0 { score -= 50.0 ; } } else { score += 40.0 * (nxt / cap) ; score += 30.0 * ((post - nxt) / cap) ; } } // refine dead-space ratio: penalize bins whose residual is too small to be useful
