pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 1.2 * (1.0 - gap / bin_capacity as f64).max(0.0) * 20.0;
        // Penalize post_residual that is unusable for the next item (dead space).
        if (post_residual as i64 - next_item_size as i64) < 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving room compatible with mean residual pattern.
        let dev = (post_residual as f64 - mean_residual).abs();
        score -= 0.15 * (1.0 - dev / bin_capacity as f64).max(0.0) * 10.0;
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // fresh bin fine if it can host the next item too
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with residuals below mean (fill emptier-ish bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill * fill;

    // Penalize leaving dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // tiny slivers are fine (nearly perfect fit)
    } else if post_residual >= 10 {
        // dead space penalty grows if it can't host the next item
        if (next_item_size > 0) && post_residual < next_item_size {
            score += 8.0;
        } else {
            score += 2.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded or the item fits nothing well.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let avg_tightness = 1.0 - mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin, discounted when bins are scarce/crowded
        // or the item is large and would leave open bins shredded anyway.
        let mut new_bin_cost = 25.0
            - 8.0 * avg_tightness
            - 5.0 * progress
            - 10.0 * big_item * big_item;
        if open_bins_count == 0 {
            new_bin_cost -= 30.0;
        }
        if fitting_bins_count > 0 {
            // discourage skipping usable open bins unless they're all poor fits
            new_bin_cost += 10.0 * (1.0 - fill);
        }
        score = new_bin_cost.max(-5.0) + post_residual as f64 * 0.5;
    }

    // Mild preference for consolidating residual mass across the stream:
    // favor bins whose residual is far from the mean (absorb outliers early).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 1.5 * dev / bin_capacity as f64;

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 2.0 * t * t + 1.5 * t * norm_pr;
    score *= poly;
    // reward tight fits
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (1.0 + t);
    // penalize dead space that next item cannot use
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 6.0 * (1.0 + t);
    } else if next_item_size > 0 {
        score -= 4.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / cap).abs();
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }
    // discourage scattering when many bins open
    score += 0.5 * open_bins_count as f64 * norm_pr;
    // prefer bins below mean residual (tighter)
    score += 0.3 * (mean_residual - pr);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.13;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by common item sizes are "reusable".
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Reward residuals that form harmonic classes with typical item sizes (multiples of 10/20/25/50).
    let mut harmony_bonus = 0.0;
    for m in [10u32, 20, 25, 50, 100].iter() {
        if pr > 0 && pr % m == 0 {
            harmony_bonus += 8.0;
        }
    }
    score -= harmony_bonus;

    // Penalize dead space in awkward classes (prime-ish residuals like 1..9 mod 10).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit is best.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward (harmonic pair).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            let leftover = pr - next_item_size;
            score += leftover as f64 * 0.5;
            if leftover % 10 == 0 { score -= 10.0; }
        } else {
            // next item cannot use this bin's remainder; mild penalty scaled by waste
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless existing bins are crowded / bad fits.
    if bin_residual == bin_capacity {
        score += cap * 0.6;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if mean_residual < item_size as f64 * 1.2 {
            score -= cap * 0.8; // open bins nearly full -> new bin reasonable
        }
        if fitting_bins_count == 0 { score -= cap; }
        let _ = progress;
    }

    // Prefer bins whose residual is close to item size (tight fit) beyond raw post_residual.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 20.0;

    // Mean-residual coupling: if this bin is below mean residual (fuller), slight preference.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Large items early: prefer compacting them into partially filled bins.
    if item_size >= 50 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = post / cap;

    // Base: post residual with smooth non-linear shaping
    let mut score = post * (1.0 + 0.8 * norm_pr * norm_pr);

    // Perfect-fit reward
    let fit_bump = (-norm_pr * norm_pr * 12.0).exp();
    score -= 25.0 * fit_bump;
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class bands
    let class: f64 = if post_residual == 0 {
        -72.0
    } else if post_residual <= 4 {
        -50.0
    } else if post_residual <= 8 {
        -45.0
    } else if post_residual <= 10 {
        -40.0
    } else if post_residual <= 20 {
        -22.0
    } else if post_residual <= 46 {
        0.0
    } else {
        28.0
    };
    score += class;

    // Round residuals are easier to fill later
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual % 20 == 0 {
        score -= 5.0;
    } else if post_residual % 15 == 0 {
        score -= 3.0;
    }

    // Penalize leaving a residual that is too small for typical future items
    let mid = 0.25;
    score += 15.0 * (norm_pr - mid) * (norm_pr - mid);

    // COMBINED: strong next-item snugness (from best) layered with parent lookahead tiers
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nx).abs();
            // dominant snugness gradient from best heuristic
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 36.0;
            } else if new_post <= 10 {
                score -= 29.0;
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
                score += new_post as f64 * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 12.0;
            }
            // pair-fill bonus
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 46.0;
            }
            // second/third-order lookahead
            if new_post > 0 {
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 10.0;
                    } else if post2 <= 5 {
                        score -= 6.0;
                    }
                }
                // triple-fill
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 14.0;
                }
                // near-mean alignment
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                // tiny unusable residual penalty
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
            }
        } else {
            let gap = (nx - post) / cap;
            score += 40.0 * (nx / cap);
            score += 30.0 * ((post - nx) / cap);
            score += 12.0 * gap * gap * cap;
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    // Alignment with mean residual
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate
    if bin_residual == bin_capacity {
        score = 57.0 + norm_pr * 10.0;
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if progress > 0.9 && open_bins_count > 3 {
            score += 16.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // near-perfect pair fill with next item: prefer this bin over a new one
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (post - item) / cap;
            if snug_fit <= 0.12 {
                score += 20.0;
            }
            if snug_fit > 0.12 && snug_fit <= 0.30 && open_bins_count > 2 {
                score += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 60.0;
        }
        // small item into a fresh bin wastes capacity
        if item < 25.0 && open_bins_count > 1 && mean_residual >= item {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps much harder
    // than large residual space. A gap is "dead" if no plausible future item
    // (sizes 1..=100) can use it efficiently; smallest items are rare, so
    // gaps below ~15 are nearly worthless.
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap < 15.0 {
            // Almost certainly dead space: heavy penalty.
            score += (15.0 - gap) * 6.0;
        } else if gap < 30.0 {
            // Risky zone: moderate super-linear penalty.
            let t = (30.0 - gap) / 15.0;
            score += t * t * 12.0;
        }
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items
    // into fresh bins; with few open bins, allow consolidation.
    score += (open_bins_count as f64) * 0.8;

    // Mean-residual coupling: if the average open residual is high, we have
    // slack everywhere, so slightly favor this bin proportionally to how far
    // below the mean its post-residual lands (encourages balanced packing).
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.3;

    // Lookahead: if the next item could exactly fill the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot fit here anyway; slightly penalize leaving a gap
        // the next item overshoots (wasted potential).
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.2;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer it when the current open bins are crowded (high count,
    // low mean residual) or the fit into open bins is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // Relax cost when many bins are open and residuals are tight.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (open_bins_count as f64) * 0.5;
        score -= (bin_capacity as f64 - mean_residual) * 0.4;
        score -= progress * 5.0;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    score
}

