pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect exact match for the next item is highly desirable.
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual means we packed this bin tighter than typical -> reward.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 6.0 * (mean_residual - pr) / bin_capacity as f64;
    } else {
        score += 4.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // but allow it when the fit would be very tight (dead space risk).
    if bin_residual == bin_capacity {
        let waste = pr / bin_capacity as f64;
        if waste > 0.25 {
            score += 20.0 * waste; // too much dead space in a fresh bin
        } else {
            score -= 3.0; // fresh bin is fine for large items
        }
    }

    // Slight preference to fill older bins as the stream progresses.
    score += 2.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
