                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // ---- New-bin candidate: adopt the best heuristic's compact structure ----
    if bin_residual == bin_capacity {
        let mut nb = 150.0
            - 120.0 * (it / cap)
            + 1.0 * mean_residual
            + 200.0 * progress;
        if fitting_bins_count == 0 {
            nb -= 2000.0;
        } else {
            nb += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        nb += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        nb += 90.0 * progress * (1.0 - open_frac.min(1.0));

        // Parent refinements kept on top of the best's base
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            nb += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            nb -= 10.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (pr - it) / cap;
            if snug_fit <= 0.12 {
                nb += 20.0;
            } else if snug_fit <= 0.30 && open_bins_count > 2 {
                nb += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            nb += 60.0;
        }
        // small item into a fresh bin wastes capacity unless stream is early
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            nb += 12.0;
        }
        // next-item snugness on an open bin should beat a fresh bin
        if next_item_size > 0 && next_item_size <= post_residual {
            let diff = (pr - next_item_size as f64).abs();
            if diff <= 3.0 {
                nb += 16.0;
            }
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead: reward if next item can fit into the resulting residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
            // Perfect pairing bonus.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Waste: residual too small for the known next item.
            let waste = (next_item_size as f64 - post_residual as f64).min(30.0);
            score += 0.4 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Prefer bins with residuals near the item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.25 * gap;

    // Global state: when many bins are open with large mean residual,
    // discourage opening yet another bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, softened when few bins fit the item
        // or when open bins are mostly full.
        let crowd = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (mean_residual / bin_capacity as f64);
        score += 18.0 + 35.0 * crowd - 10.0 * (1.0 - progress);
        // If item is huge, opening a fresh bin may be cleaner.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 15.0;
        }
    } else {
        // Mild bonus for filling existing bins as stream progresses.
        score -= 5.0 * (mean_residual / bin_capacity as f64) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear tightening
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late in the stream, penalize dead space quadratically
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += post * (0.6 * p2 + 1.2 * p3);

    // Non-linear fit-quality term: reward tight fits (post near zero) increasingly with progress
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * (1.0 + 2.0 * p3) * 10.0;

    // Penalize bins whose residual deviates from mean residual (non-linearly), keeping diversity
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving a residual that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack_fit = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack_fit * slack_fit);
        } else {
            // residual too small for next item: penalize proportionally to waste
            score += 3.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln() * (post / cap) * 2.0;

    // New-bin candidate: smooth penalty that grows with stream progress and item size
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress + 0.05 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: reward small, "harmonically useful" leftovers ---
    // Residual classes via integer division thresholds (capacity fractions).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_frac = pr / cap;

    // Dead-space penalty: residuals that are too small for typical items are bad.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Sweet-spot residuals (can host small items): strong reward.
    if post_residual >= 10 && post_residual <= 25 {
        score -= 18.0;
    }

    // Harmonic quantization: reward residuals near multiples of common item classes.
    let harmonic = |r: u32| -> f64 {
        let classes: [u32; 5] = [10, 20, 25, 33, 50];
        let mut best = f64::MAX;
        for c in classes.iter() {
            let d = (r as i64 % *c as i64).abs() as f64;
            let d = d.min((*c as f64) - d);
            if d < best { best = d; }
        }
        best
    };
    score += 0.6 * harmonic(post_residual);

    // --- Lookahead coupling: does post_residual fit next_item_size? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: this bin will also host the next item.
            let tightness = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 12.0 + 10.0 * tightness;
        } else {
            // Next item won't fit: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.25 * overshoot.min(50.0);
        }
        // Harmonic class of next item: big next items prefer this bin kept flexible.
        let next_class = (next_item_size / 20) as f64; // 0..5
        score += 1.5 * next_class * pr_frac;
    }

    // --- Last-chance logic: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate: penalize opening a new bin unless residual is tiny ---
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: proportional to stream progress and item size.
        score += 55.0 + 0.3 * item_size as f64;
        // Late in the stream, opening bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If many bins are open, prefer consolidation into existing bins.
        score += 0.4 * open_bins_count as f64;
        // Exception: next item is huge and current item is huge -> fresh bin may be right.
        if next_item_size >= 60 && item_size >= 60 {
            score -= 45.0;
        }
    }

    // --- Tight fit reward: nearly-full bins are excellent ---
    let fill = 1.0 - pr_frac;
    score -= 8.0 * fill * fill;

    // --- Mean residual context: prefer bins below mean residual (tighter bins) ---
    score += 0.15 * (mean_residual - pr);

    // --- Open bins pressure: with many open bins, discourage spreading ---
    score += 0.05 * open_bins_count as f64 * pr_frac;

    // --- Modulo-based tie-breaking on step for deterministic diversity ---
    let step_mod = (step_index % 7) as f64;
    score += 0.05 * step_mod * pr_frac;

    score
}

