                    score += (item_size - new_post) as f64 * 0.06;
                    if progress > 0.5 {
                        score += (item_size - new_post) as f64 * 0.05 * progress;
                    }
                }
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 10.0;
                    } else if post2 <= 5 {
                        score -= 6.0;
                    } else if post2 >= next_item_size {
                        let post3 = post2 - next_item_size;
                        if post3 == 0 {
                            score -= 7.0;
                        } else if post3 <= 4 {
                            score -= 4.0;
                        }
                    }
                }
                // triple-fill: item + 2x next nearly fills bin
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 14.0;
                }
                // near-mean alignment
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                // tiny unusable residual penalty
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
                // large leftover is still usable
                if new_post > 18 && (new_post as f64) > nx * 2.5 {
                    score += 6.0;
                }
                // usability vs mean residual — dead-space control late in stream
                if progress > 0.3 && (new_post as f64) < mean_residual * 0.5 && new_post < 12 {
                    score += 5.0 * progress;
                }
            }
            // next item fits elsewhere: safe to leave residual here
            let next_fits_elsewhere = mean_residual >= nx && open_bins_count > 1;
            if next_fits_elsewhere && new_post > 0 {
                score += 3.0;
            } else if !next_fits_elsewhere {
                score -= 12.0;
            }
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap * cap;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // Alignment with mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: neutral base so it only wins when open bins score poorly
    if bin_residual == bin_capacity {
        score = 57.0 + (pr / cap) * 10.0;
        if post_residual >= 56 {
            score -= 12.0;
        }
        if post_residual >= 85 {
            score -= 9.0;
        }
        if post_residual >= 96 {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 2000.0;
        }
        if progress > 0.85 {
            score -= 7.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            score += 16.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // near-perfect pair fill with next item: prefer this bin over a new one
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.45 {
            score -= 6.0;
        }
        // aggregate-space pressure: if total open slack is large, prefer reusing bins
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                score += 9.0;
            }
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            score -= 6.0;
        }
        if progress > 0.55 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 5.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (post_residual as f64 - it) / cap;
            if snug_fit <= 0.12 {
                score += 20.0;
            }
            if snug_fit > 0.12 && snug_fit <= 0.30 && open_bins_count > 2 {
                score += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            score += 6.0;
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 60.0;
        }
        // small item into a fresh bin wastes capacity unless stream is early
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            score += 12.0;
        }
        // MUTATION: scale new-bin base with fitting count and mean slack
        score += 60.0 * (fitting_bins_count as f64).min(5.0);
        score += 80.0 * progress * (mean_residual / cap);
        // MUTATION: strong next-item snugness reward on open bins (from best heuristic)
        if next_item_size > 0 && next_item_size <= post_residual {
            let diff = (pr - next_item_size as f64).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else if next_item_size > 0 {
            score += 40.0 * (next_item_size as f64 / cap);
            score += 30.0 * ((pr - next_item_size as f64) / cap);
        }
        // MUTATION: consolidate open slack late in the stream
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open-bins pressure: penalize spreading across many bins
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in post_residual and gap is small, penalize
    if next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 && post_residual < 30 {
        score += 10.0;
    }

    // New-bin candidate: make empty bins mildly attractive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fragmentation > 40.0 {
            score -= 20.0;
        } else {
            score += 15.0;
        }
    }

    // Mean residual alignment: prefer bins close to mean residual
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        score -= (item / cap) * 30.0;
    }

    // Lookahead coupling with chained-fit anticipation.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 700.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            // Bonus if residual after next item still accommodates a mid-size chunk.
            if post_residual >= 2 * next_item_size {
                score -= 25.0;
            }
        } else {
            // Penalize dead space relative to the near future, scaled by item size.
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
            // Extra penalty when residual can never fit the next item and is small.
            if post_residual < next_item_size && post_residual < 20 {
                score += 40.0;
            }
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin consolidation pressure grows over the stream.
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 140.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
            // Prefer new bin only if existing fits are loose.
            let best_possible_waste = (bin_residual - item_size) as f64;
            if best_possible_waste > mean_residual {
                score -= 30.0;
            }
        }
        score += 60.0 * progress * (mean_residual / cap);
    }

    // Mild mean-residual balancing.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 12.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when the next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // exact match is ideal
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    } else {
        // last item: prefer tightest fill
        score -= 10.0;
    }

    // Penalize dead space relative to mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 20.0 + 0.4 * item_size as f64;
    }

    // Mild progression scaling: tighten packing as stream advances
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 { let cap = bin_capacity as f64 ; let post = post_residual as f64 ; let item = item_size as f64 ; let mut score = post ; if post_residual == 0 { score -= 1000.0 ; } if next_item_size > 0 { let nxt = next_item_size as f64 ; if next_item_size <= post_residual { let diff = (post - nxt) . abs () ; score -= 900.0 * (1.0 - diff / cap) ; if diff == 0.0 { score -= 50.0 ; } } else { score += 40.0 * (nxt / cap) ; score += 30.0 * ((post - nxt) / cap) ; } } // penalize small leftover slivers that can rarely be reused
