pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit = post_residual as f64 / bin_capacity as f64;
    score += fit * fit * 40.0;

    // Reward using a bin that would otherwise leave awkward space.
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Dead space the next item can't use: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Penalize opening a new bin unless current fits are poor or many bins already fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_alternatives = if fitting_bins_count > 0 { (post_residual as f64) } else { 0.0 };
        // New bin baseline: slightly worse than a decent fit.
        score += 15.0;
        // Early in stream, opening bins is cheaper (more future use); late, avoid it.
        score += (1.0 - progress) * 20.0;
        // If many bins fit the item, opening a new one is wasteful.
        score += (fitting_bins_count as f64).min(5.0) * 6.0;
        // If mean residual across open bins is small (bins nearly full), new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 15.0;
        // If the item is large relative to typical residuals, new bin is safer.
        if item_size as f64 > mean_residual {
            score -= 8.0;
        }
        let _ = poor_alternatives;
    } else {
        // Prefer fuller bins: reward closeness of fill.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 8.0;
        // Slight penalty for spreading across too many bins.
        score += open_bins_count as f64 * 0.05;
    }

    // Global state coupling: high mean residual means space is plentiful; be pickier.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // Small deterministic tie-breaker favoring bins with residual close to item.
    let gap = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += gap * 0.02;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let post = post_residual as f64 ;
    let item = item_size as f64 ;
    let mut score = post ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs() ;
            score -= 900.0 * (1.0 - diff / cap) ;
            if diff == 0.0 { score -= 50.0 ; }
        } else {
            score += 40.0 * (nxt / cap) ;
            score += 30.0 * ((post - nxt) / cap) ;
        }
    }
    if bin_residual == bin_capacity {
        score += 150.0 ;
        score -= 120.0 * (item / cap) ;
        score += 1.0 * mean_residual ;
        let progress = step_index as f64 / total_items.max(1) as f64 ;
        score += 200.0 * progress ;
        if fitting_bins_count == 0 {
            score -= 2000.0 ;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0) ;
        }
        score += 80.0 * progress * (mean_residual / cap) ;
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64) ;
        score += 90.0 * progress * (1.0 - open_frac.min(1.0)) ;
        // Refined dead-space penalty: prefer opening a new bin when the item
        // would leave a residual too small to hold the next item or mean item.
        let dead = post_residual ;
        if dead > 0 && next_item_size > 0 && (dead as u32) < next_item_size {
            score += 25.0 * (1.0 - (dead as f64) / cap) ;
        }
        // Mild bias: when few bins fit the item, favor compacting into
        // existing bins rather than spreading residual space.
        if fitting_bins_count > 0 && fitting_bins_count <= 2 {
            score -= 15.0 ;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual (tight fit favored)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score -= pr * (0.35 * progress + 0.45 * p2 + 0.20 * p3);

    // Dead-space penalty: small residuals are hard to fill later
    let dead = if pr > 0.0 { (norm_pr * (1.0 - norm_pr)).powi(2) } else { 0.0 };
    score -= 18.0 * dead * (1.0 + progress);

    // Penalize near-full-but-not-full residuals quadratically
    if pr > 0 && pr < 10 {
        score += 6.0 * (10.0 - pr as f64);
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer it early or when existing bins fit poorly
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
        score -= 5.0 * (1.0 - progress) - 3.0 * crowding * progress;
        // don't open new bins when a tight fit exists elsewhere
        if pr == 0.0 && norm_item > 0.9 {
            score -= 15.0;
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score += 0.15 * (pr - mean_residual) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is worse
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual == 0 -> perfect fit, reward heavily
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 15 {
        score += 5.0;
    } else if post_residual <= 30 {
        score += 12.0;
    }

    // Harmonic pairing: does next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / cap);
            if post_residual % next_item_size == 0 {
                score -= 8.0; // divisible harmonic class
            }
        } else {
            score += 6.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening unless item is large relative to residual
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 6.0; // room to pair next item
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    score -= (1.0 - pr / cap) * 10.0 * (open_bins_count.min(20) as f64) / 20.0;

    // Deviation from mean residual: bins far below mean residual (fuller) preferred
    score -= (mean_residual - pr) * 0.15;

    // Late-stream tightening
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps.
    // A post_residual below the minimum possible item size (1..100 interface,
    // but typical stream floor ~10) is wasted space forever.
    let min_item = 10u32;
    if post_residual < min_item {
        // dead space: penalize proportionally to how much capacity is locked away
        score += 40.0 + (min_item - post_residual) as f64 * 3.0;
    } else if post_residual > 0 && post_residual < min_item * 2 {
        // borderline gap: likely dead space, mild penalty
        score += 8.0;
    }

    // Reward tight fits: the smaller the post_residual, the better (already
    // captured by base score), but give extra convex reward for near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chained tight packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap < min_item {
                score += 5.0; // would create fresh dead space
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot use this bin's remainder: remainder more likely dead
            score += 3.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // (avoid bin proliferation); with few open bins, new bins are cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        // existing bin: reward slightly more when many bins are open
        score -= 2.0 * pressure;
    } else {
        // new-bin candidate: penalize when many bins are already open
        score += 6.0 + 3.0 * pressure;
    }

    // Mean-residual context: if this bin's residual is far below the mean,
    // it is the "odd" bin; packing it keeps residuals homogeneous.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.05 * (mean_residual - resid);
    } else {
        score += 0.05 * (resid - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Late in the stream, prioritize consolidation of open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    } else {
        score += 3.0 * progress;
    }

    score
}

