pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is better.

    // 2-step lookahead: reward when the leftover space exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item seals this bin
        } else if post_residual >= next_item_size {
            // leftover can host next item: mild reward scaled by how well it matches
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize dead space proportional to leftover
            let waste = post_residual as f64;
            score += 0.5 * waste;
            // extra penalty if the waste is small and unusable (below min item size ~1..100 range)
            if waste < 10.0 {
                score += 10.0;
            }
        }
    }

    // Compare against mean residual: choosing a bin far below mean residual
    // preserves larger residual bins for harder items.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);
    score -= 0.1 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a neutral-ish score so it is
    // only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0;
        // late in the stream, discourage proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // but if next item is huge relative to item, a fresh bin may chain well
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Prefer filling bins that are already mostly full (fragmentation avoidance)
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: post residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    let progress_ramp = progress * progress * (3.0 - 2.0 * progress);
    score += 30.0 * progress_ramp * norm_pr * norm_pr;

    // Perfect-fit reward (strengthened: exact fill is always optimal)
    let fit_bump = (-norm_pr * norm_pr * 12.0).exp();
    score -= 25.0 * fit_bump;
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class bands
    let class: f64 = if post_residual == 0 {
        -72.0
    } else if post_residual <= 4 {
        -50.0
    } else if post_residual <= 8 {
        -45.0
    } else if post_residual <= 10 {
        -40.0
    } else if post_residual <= 20 {
        -22.0
    } else if post_residual <= 46 {
        0.0
    } else {
        28.0
    };
    score += class;

    // Round residuals are easier to fill later
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual % 20 == 0 {
        score -= 5.0;
    } else if post_residual % 15 == 0 {
        score -= 3.0;
    }

    // Dead-space ratio term
    if norm_pr > 0.55 {
        score += norm_pr * 6.0;
    } else if norm_pr < 0.08 {
        score -= 4.0 * (1.0 - norm_pr);
    }

    // Penalize leaving a residual that is too small for typical future items
    let mid = 0.25;
    score += 15.0 * (norm_pr - mid) * (norm_pr - mid);

    // Next-item lookahead with snug tiers (COMBINED: strong snugness from best heuristic)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // dominant snugness term: reward leaving residual exactly equal to next item
            let diff = (pr - nx).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 36.0;
            } else if new_post <= 10 {
                score -= 29.0;
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
                score += new_post as f64 * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 12.0;
            }
            // pair-fill bonus
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 46.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 24.0;
            }
            // divisibility: residual reusable in multiples of next item
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 9.0;
            }
            // second/third-order lookahead
            if new_post > 0 {
                if new_post < item_size {
                    score += (item_size - new_post) as f64 * 0.06;
                    if progress > 0.5 {
                        score += (item_size - new_post) as f64 * 0.05 * progress;
                    }
                }
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 10.0;
                    } else if post2 <= 5 {
                        score -= 6.0;
                    } else if post2 >= next_item_size {
                        let post3 = post2 - next_item_size;
                        if post3 == 0 {
                            score -= 7.0;
                        } else if post3 <= 4 {
                            score -= 4.0;
                        }
                    }
                }
                // triple-fill: item + 2x next nearly fills bin
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 14.0;
                }
                // near-mean alignment
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                // tiny unusable residual penalty
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
                // large leftover is still usable
                if new_post > 18 && (new_post as f64) > nx * 2.5 {
                    score += 6.0;
                }
                // usability vs mean residual — dead-space control late in stream
                if progress > 0.3 && (new_post as f64) < mean_residual * 0.5 && new_post < 12 {
                    score += 5.0 * progress;
                }
            }
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap * cap;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // Alignment with mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: adopt the best heuristic's proven new-bin scoring
    if bin_residual == bin_capacity {
        let mut nb = 150.0 - 120.0 * norm_it + mean_residual + 200.0 * progress;
        if fitting_bins_count == 0 {
            nb -= 2000.0;
        } else {
            nb += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        nb += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        nb += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // late-stream: resist opening new bins
        if progress > 0.85 {
            nb += 12.0;
        }
        // aggregate-space pressure: if total open slack is large, prefer reusing bins
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                nb += 9.0;
            }
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (pr - it) / cap;
            if snug_fit <= 0.12 {
                nb += 20.0;
            }
            if snug_fit > 0.12 && snug_fit <= 0.30 && open_bins_count > 2 {
                nb += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            nb += 60.0;
        }
        // small item into a fresh bin wastes capacity
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            nb += 12.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64).sqrt();
    }
    // Penalize leaving a gap that only a tiny next item could use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Penalize opening new bins when many open bins already have slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        // New bin is fine early or when open bins are nearly full.
        score += 10.0 * (1.0 - progress) + 25.0 * pressure * (open_bins_count as f64).ln().max(1.0);
        // But if nothing fits well anywhere, new bin should win.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer filling bins with larger residual when residuals are globally large.
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Mild time horizon coupling: late in stream, avoid waste more strongly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 { let cap = bin_capacity as f64 ; let post = post_residual as f64 ; let item = item_size as f64 ; let mut score = post ; if post_residual == 0 { score -= 1000.0 ; } if next_item_size > 0 { let nxt = next_item_size as f64 ; if next_item_size <= post_residual { let diff = (post - nxt) . abs () ; score -= 900.0 * (1.0 - diff / cap) ; if diff == 0.0 { score -= 50.0 ; } } else { score += 40.0 * (nxt / cap) ; score += 30.0 * ((post - nxt) / cap) ; } } if bin_residual == bin_capacity { score += 150.0 ; score -= 120.0 * (item / cap) ; score += 1.0 * mean_residual ; let progress = step_index as f64 / total_items . max (1) as f64 ; score += 200.0 * progress ; if fitting_bins_count == 0 { score -= 2000.0 ; } else { score += 60.0 * (fitting_bins_count as f64) . min (5.0) ; } score += 80.0 * progress * (mean_residual / cap) ; let open_frac = open_bins_count as f64 / (total_items . max (1) as f64) ; score += 90.0 * progress * (1.0 - open_frac . min (1.0)) ; // refine: penalize opening a new bin when the item is large and few bins can host it later
