    let mut score = norm_post.powf(1.7) * cap;

    // Smooth coupling: as stream progresses, tolerate less dead space
    let progress_pressure = 1.0 + 1.5 * progress * (1.0 - progress).powf(0.5);
    score += norm_post * norm_post * 40.0 * progress_pressure;

