    // Mild penalty when bin residual deviates from mean residual (balance keeping)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * (0.3 + progress);

    // Slight preference for opening new bins early vs late
    score += (1.0 - progress) * 2.0;

    score
}

