    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space by residue classes.
    let r = post_residual;
    let class = r % 10;
    // Residuals divisible by 5 are more reusable by typical item sizes -> reward.
    if class == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 4.0;
    } else if class == 1 {
        score += 6.0; // nearly-full bins are fine actually (tiny dead space)
        score -= 10.0;
    } else if class >= 8 {
        score += 3.0; // awkward sliver classes
    }

    // Perfect fit bonus via integer division thresholds.
    if r == 0 {
        score -= 50.0;
    } else if r <= 2 {
        score -= 35.0;
    }

    // Fraction-of-capacity harmonic: residual as a fraction of capacity.
    let frac = r as f64 / bin_capacity as f64;
    // Favor bins whose residual falls in "usable" bands: [0.1,0.3] or [0.5,0.8]
    if (frac >= 0.10 && frac <= 0.30) || (frac >= 0.50 && frac <= 0.80) {
        score -= 5.0;
    } else if frac > 0.80 {
        score += 4.0; // leaving a huge residual means poor packing
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Harmonic compatibility: same decade class rewards chaining.
            let compat = ((next_item_size / 10) == (r / 10)) as f64;
            score -= 6.0 + 4.0 * compat;
        } else {
            // Next item won't fit here; slight penalty scaled by how much it misses.
            let miss = (next_item_size - r) as f64;
            score += 0.05 * miss;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so that
    // only genuinely poor fits among open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = 45.0 - 0.10 * mean_residual;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            score -= 3.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - frac);

    // Mild pressure to reduce number of open bins early on.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (1..=min_item_seen proxy) are pure waste. Penalize hard if the leftover
    // gap is "dead" (positive but tiny relative to typical item sizes).
    let dead_threshold = 8.0; // gaps below ~8 are rarely reusable
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin completely.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    let waste_ratio = post_residual as f64 / bin_residual as f64;
    score += waste_ratio * 30.0;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when no open bin offers a good fit (high waste elsewhere) or the
    // lookahead item would benefit from a fresh large residual.
    if bin_residual == bin_capacity {
        let base_penalty = 18.0
            + open_bins_count as f64 * 0.3
            + mean_residual * 0.15;
        score += base_penalty;
        // If the next item is large and current residuals are tight, fresh bin helps.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 12.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Coupling with mean residual: prefer bins whose post-residual stays near
    // the fleet mean (keeps residuals homogeneous and reusable).
    let mean_gap = ((post_residual as f64) - mean_residual).abs();
    score += mean_gap * 0.25;

    // Lookahead synergy: if the next item exactly fits the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use the leftover: leftover is more likely dead space.
        score += (post_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // Dead space too small for the smallest item.
        score += 70.0;
    } else {
        // Reward tight fits.
        score -= (item / cap) * 30.0;
    }

    // Lookahead coupling: strongly favor residuals that fit the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0; // chained exact fit
            }
        } else {
            // Residual becomes dead space relative to the near future.
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling (empty bin: residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0; // no alternative: must open
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
    }

    // Mild mean-residual balancing.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 8.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how tightly it packs
            score -= 100.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize large dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: keep residuals balanced
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists
    if bin_residual == bin_capacity {
        score += 50.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        // opening new bin is fine if next item is large and residuals are small
        if next_item_size > 60 && mean_residual < 20.0 {
            score -= 60.0;
        }
    }

    // Slight preference for filling bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
