        // near-perfect pair fill with next item: prefer this bin over a new one
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            nb -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            nb += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            nb += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            nb -= 8.0;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.45 {
            nb -= 6.0;
        }
        // aggregate-space pressure: if total open slack is large, prefer reusing bins
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                nb += 9.0;
            }
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            nb -= 6.0;
        }
        if progress > 0.55 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            nb -= 5.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (pr - it) / cap;
            if snug_fit <= 0.12 {
                nb += 20.0;
            }
            if snug_fit > 0.12 && snug_fit <= 0.30 && open_bins_count > 2 {
                nb += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            nb += 6.0;
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            nb += 60.0;
        }
        // small item into a fresh bin wastes capacity unless stream is early
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            nb += 12.0;
        }
        // MUTATION: extra penalty when open aggregate slack can absorb many more items
        if open_bins_count > 2 && mean_residual * open_bins_count as f64 > cap * 2.0 {
            nb += 12.0 * (1.0 - progress);
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize large dead space quadratically
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.08 * dead * dead;
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // next item can't follow here: mild penalty scaled by how much is wasted
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 3 {
        score += 5.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Prefer bins tighter than average residual
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Discourage proliferation of open bins early; allow spreading later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * open_bins_count as f64;

    // New-bin candidate: only attractive when item is large or current fits are poor
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / bin_capacity as f64) > 0.6;
        if fitting_bins_count == 0 || (large && fitting_bins_count <= 2) {
            score -= 25.0;
        } else {
            score += 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling: waste penalty grows quadratically as residual shrinks
    let tight = 1.0 - norm_pr;
    score += 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits, more so late in the stream
    score -= 20.0 * tight * tight * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: bonus if next item fits into post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = pr - next_item_size as f64;
        score -= 8.0 * (1.0 - slack / cap) * (0.3 + 0.7 * progress);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - progress);
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize opening new bins early; encourage consolidation when many bins open
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 1.5 * (open_bins_count as f64).sqrt() * progress;
    }

    // Mean-residual alignment: prefer bins close to the mean residual (balanced usage)
    let dev = (pr - mean_residual).abs();
    score += 3.0 * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
