        if open_bins_count > 1 && (mean_residual * open_bins_count as f64) > it * 3.0 {
            score += 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (capacity fraction classes) ---
    // Class 0: perfect fit (0), Class 1: tiny dead space (1..=10),
    // Class 2: medium (11..=30), Class 3: large usable (31..=60), Class 4: near-empty (>60)
    let cls = if post_residual == 0 { 0u32 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 30 { 2 }
        else if post_residual <= 60 { 3 }
        else { 4 };

    match cls {
        0 => score -= 40.0,                       // perfect fit: strong reward
        1 => score += 15.0,                       // tiny dead space: heavily penalize
        2 => score += 5.0,                        // medium: mild penalty
        3 => score -= 5.0,                        // large usable: mild reward
        _ => {}                                   // near-empty: neutral
    }

    // Modulo-style coupling: residuals that are "awkward" (not multiples of a
    // harmonic quantum of 10) are harder to fill with integer-sized items.
    let q = post_residual % 10;
    if post_residual > 0 && q != 0 {
        score += 3.0 + q as f64 * 0.3;
    }

    // Lookahead harmony: reward if next item fits (or nearly fits) the residual,
    // penalize if residual is a trap (nonzero but < next item).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;                        // chain: next item seals this bin
        } else if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            score -= 8.0;
            if nxt_post <= 10 { score -= 6.0; }   // two items nearly seal the bin
        } else if post_residual > 0 {
            // residual too small for next item: dead space risk
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }
    // Many alternatives: prefer bins where fit is tightest; penalize wasteful fits.
    if fitting_bins_count > 1 && post_residual > 40 {
        score += 4.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item fits badly everywhere (large item, no tight option).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln_1p() * 3.0;
        // Baseline barrier; drop it for big items that leave nothing awkward.
        let mut nb = 18.0 + openness - progress * 5.0;
        if item_size >= 70 { nb -= 10.0; }        // huge items: fresh bin is fine
        if post_residual == 0 { nb -= 5.0; }      // (empty bin: item==capacity edge)
        score += nb;
    }

    // Mild coupling with mean residual: if open bins are generally loose,
    // slightly prefer tightening a bin (low post_residual already does this);
    // if bins are tight, avoid leaving awkward small residuals.
    if mean_residual < 15.0 && post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    score
}

