    // Consolidation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // Alignment with mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: adopt additive scoring from best heuristic
    if bin_residual == bin_capacity {
        let mut nb = 57.0 + (pr / cap) * 10.0;
        nb += 150.0;
        nb -= 120.0 * (it / cap);
        nb += 1.0 * mean_residual;
        nb += 200.0 * progress;
        if fitting_bins_count == 0 {
            nb -= 2000.0;
        } else {
            nb += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        nb += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        nb += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if post_residual >= 56 {
            nb -= 12.0;
        }
        if post_residual >= 85 {
            nb -= 9.0;
        }
        if progress > 0.9 && open_bins_count > 3 {
            nb += 16.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            nb -= 10.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (pr - it) / cap;
            if snug_fit <= 0.12 {
                nb += 20.0;
            }
            if snug_fit > 0.12 && snug_fit <= 0.30 && open_bins_count > 2 {
                nb += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            nb += 60.0;
        }
        // small item into a fresh bin wastes capacity unless stream is early
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            nb += 12.0;
        }
        // aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            nb += 6.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..10)
    // are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it could fit in the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize creating a gap that is *almost* big enough for the next item
    // (tempting but unusable next step).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Tight-fit bonus: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill * fill;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // offers a good fit (large post_residual waste there) and few bins are open.
    if bin_residual == bin_capacity {
        score += 15.0;
        score -= 2.0 * mean_residual.min(50.0) * 0.1; // slightly better when open bins are full-ish
    }

    // Mild preference for bins whose residual is close to the item (best fit).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        // Dead space too small for the smallest item.
        score += 70.0;
    } else {
        // Reward tight fits (combine fine-grained residual fitting).
        score -= (item / cap) * 40.0;
        score -= 60.0 * (1.0 - post / cap);
    }

    // Lookahead coupling: strongly favor residuals that fit the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 700.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 80.0; // chained exact fit
            }
        } else {
            // Residual becomes dead space relative to the near future.
            score += 40.0 * (nxt / cap) + 25.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling (empty bin: residual == capacity).
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0; // no alternative: must open
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
    }

    // Mild mean-residual balancing.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 10.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly or nearly
            score -= 300.0 / (1.0 + gap);
            if gap == 0.0 {
                score -= 500.0;
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted capacity
            score += 0.5 * gap;
        }
        // small bonus if next item is large and we preserve space for it elsewhere
        score += 0.1 * next_item_size as f64;
    }

    // Tightness reward: prefer bins that become very full relative to capacity
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 200.0 * fill * fill;

    // Penalize bins far from mean residual unless it's a great fit
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Many open bins: encourage consolidation into existing bins
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate penalty: only open a new bin when no open bin is a good fit
    if bin_residual == bin_capacity {
        score += 400.0;
        // allow new bin if lookahead suggests a big next item and current fit is poor
        if next_item_size > 60 && post_residual > 40 {
            score -= 350.0;
        }
    }

    // Late-stream pressure: pack tighter as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 50.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: post residual with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    let progress_ramp = progress * progress * (3.0 - 2.0 * progress);
    score += 30.0 * progress_ramp * norm_pr * norm_pr;

    // Perfect-fit reward
    let fit_bump = (-norm_pr * norm_pr * 12.0).exp();
    score -= 25.0 * fit_bump;
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class bands
    let class: f64 = if post_residual == 0 {
        -72.0
    } else if post_residual <= 4 {
        -50.0
    } else if post_residual <= 8 {
        -45.0
    } else if post_residual <= 10 {
        -40.0
    } else if post_residual <= 20 {
        -22.0
    } else if post_residual <= 46 {
        0.0
    } else {
        28.0
    };
    score += class;

    // Round residuals are easier to fill later
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual % 20 == 0 {
        score -= 5.0;
    } else if post_residual % 15 == 0 {
        score -= 3.0;
    }

    // Dead-space ratio term
    if norm_pr > 0.55 {
        score += norm_pr * 6.0;
    } else if norm_pr < 0.08 {
        score -= 4.0 * (1.0 - norm_pr);
    }

    // Penalize leaving a residual too small for typical future items
    let mid = 0.25;
    score += 15.0 * (norm_pr - mid) * (norm_pr - mid);

    // Next-item lookahead with snug tiers
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 900.0;
        } else if pr >= nx {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 36.0;
            } else if new_post <= 10 {
                score -= 29.0;
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
                score += new_post as f64 * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 12.0;
            }
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 10.0 * snug * snug;
            // pair-fill bonus
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 46.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 24.0;
            }
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 9.0;
            }
            if new_post > 0 {
                if new_post < item_size {
                    score += (item_size - new_post) as f64 * 0.06;
                    if progress > 0.5 {
                        score += (item_size - new_post) as f64 * 0.05 * progress;
                    }
                }
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 10.0;
                    } else if post2 <= 5 {
                        score -= 6.0;
                    } else if post2 >= next_item_size {
                        let post3 = post2 - next_item_size;
                        if post3 == 0 {
                            score -= 7.0;
                        } else if post3 <= 4 {
                            score -= 4.0;
                        }
                    }
                }
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 14.0;
                }
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
                if new_post > 18 && (new_post as f64) > nx * 2.5 {
                    score += 6.0;
                }
                if progress > 0.3 && (new_post as f64) < mean_residual * 0.5 && new_post < 12 {
                    score += 5.0 * progress;
                }
            }
            let next_fits_elsewhere = mean_residual >= nx && open_bins_count > 1;
            if next_fits_elsewhere && new_post > 0 {
                score += 3.0;
            } else if !next_fits_elsewhere {
                score -= 12.0;
            }
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap * cap;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: adopt best-heuristic's strong new-bin penalty
    if bin_residual == bin_capacity {
        let mut nb = 150.0
            - 120.0 * (it / cap)
            + 1.0 * mean_residual
            + 200.0 * progress;
        if fitting_bins_count == 0 {
            nb -= 2000.0;
        } else {
            nb += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        nb += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        nb += 90.0 * progress * (1.0 - open_frac.min(1.0));

        // Parent refinements layered on top
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            nb += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            nb -= 10.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            nb += 10.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            nb -= 8.0;
        }
        // aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            nb += 6.0;
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            nb += 60.0;
        }
        // small item into a fresh bin wastes capacity
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            nb += 12.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (pr - it) / cap;
            if snug_fit <= 0.12 {
                nb += 20.0;
            } else if snug_fit <= 0.30 && open_bins_count > 2 {
                nb += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // near-perfect pair fill with next item: prefer open bin over a new one
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            nb -= 16.0;
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Lookahead: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else if post_residual == next_item_size {
            // Perfect chain fit: strong reward.
            score -= 25.0;
        } else {
            // Next item fits into the leftover: mild reward scaled by how much is used.
            let used_next = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * used_next;
        }
    } else {
        // Last item: strongly prefer filling as much as possible.
        score -= 20.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // Many fitting bins: mild penalty for spreading too thin; encourage consolidation.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).sqrt();
    }

    // Compare against mean residual: bins with much less residual than average are precious,
    // bins with much more residual are better targets for this item.
    let resid_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * resid_gap;

    // Time horizon: early in the stream, be more willing to open new bins (score for new bin
    // relatively lower); late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins are open.
        score += 10.0 + 25.0 * progress + 1.5 * open_bins_count as f64;
        // But if item is large and would leave tiny residual, opening a fresh bin is fine.
        score -= 0.1 * post_residual as f64;
    } else {
        // Existing bin: reward more heavily as we near the end of the stream.
        score -= 5.0 * progress;
    }

    // Avoid leaving dead space that nothing (min item ~1..100 unknown) can use:
    // penalize very small post residuals slightly less than mid-size gaps? Actually
    // small post residual is good (nearly full bin).
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    // Mild stochastic-free tie-break: prefer earlier bins implicitly via residual ordering.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap; // normalized post residual
    let mut score = r;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Early in stream: mildly prefer tight fits (small residual). Late: strongly penalize
    // large residuals since fewer items remain to fill dead space.
    let poly = rn * rn * (1.0 - progress) * 30.0 + rn * progress * 60.0;
    score += poly * cap * 0.1;

    // Reward near-perfect fits smoothly (residual close to zero).
    let tightness = (1.0 - rn).powi(3);
    score -= tightness * 8.0;

    // Last-chance bin: strong smooth reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward bins whose post residual accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if r >= nxt {
            let slack = (r - nxt) / cap;
            score -= 6.0 * (1.0 - slack).powi(2);
        } else {
            let gap = (nxt - r) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Discourage scattering across many open bins when residuals are already small.
    let mean_rn = mean_residual / cap;
    score += (open_bins_count as f64).ln() * mean_rn * 2.0;

    // New-bin candidate: baseline penalty so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - rn * 0.0) + 25.0 * (1.0 - progress).powi(2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fill: zero leftover is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item fits: reward tightness strongly.
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0; // exact 2-step match
            }
        } else {
            // Next item won't fit here: penalize proportionally.
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
        }
    }

    // Last-chance bin: prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Consolidate waste: prefer bins tighter than the mean residual.
    if mean_residual > 0.0 {
        score -= 10.0 * (mean_residual - bin_residual as f64) / cap;
    }

    // Fragmentation penalty for tiny dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when open bins are quite full or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / cap;
        score = 150.0 - 120.0 * (item_size as f64 / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        score += 80.0 * progress * (mean_residual / cap);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host next item too
        }
        if fitting_bins_count == 0 {
            score -= 2000.0; // no alternative: must open new bin
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        let _ = avg_fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty grows when post_residual falls into "unusable" classes.
        // Class A: post_residual < 10 -> tiny sliver, nearly dead.
        if post_residual < 10 {
            score -= 25.0; // small sliver is fine, it's dead but tiny
        }
        // Class B: 10..20 -> dangerous zone: too small for most items (min size 1..100 now).
        else if post_residual < 20 {
            score += 12.0;
        }
        // Class C: divisible by 10 -> harmonically reusable.
        if post_residual % 10 == 0 {
            score -= 8.0;
        }
        // Class D: post_residual in [20, 50] is a good "medium" pocket.
        if post_residual >= 20 && post_residual <= 50 {
            score -= 5.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let nx = next_item_size as f64;
            score -= 15.0 * (nx / cap);
        } else {
            // next item cannot use this bin's remainder: penalize large leftovers
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when open bins are bad.
        score = 100.0 + 0.5 * open_bins_count as f64;
        // Late in stream, prefer closing out open bins rather than spawning more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If next item is huge, a fresh bin may be strategically useful.
        if next_item_size >= 70 {
            score -= 20.0;
        }
    }

    // Spread-aware tiebreak: prefer bins whose residual deviates from mean
    // in the direction that reduces fragmentation variance.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.03 * dev;

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps heavily.
    // A post_residual that is too small for typical future items (1..=100)
    // is "dead" unless it's near zero.
    let dead_threshold = 20.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fit: strongly reward
    }

    // Reward tight fits relative to item size
    score -= (item_size as f64) * 0.3;

    // Open bins pressure: discourage spreading into many bins when few items fit
    if fitting_bins_count > 1 {
        score -= 5.0;
    } else if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0; // last chance: strongly prefer using this bin
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are bad
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - post_residual as f64).abs();
        score += 25.0 + mean_gap * 0.2;
        if open_bins_count == 0 {
            score -= 40.0; // must open a bin
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0;
    }

    // Progression-based mild pressure to consolidate early
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: tiny unusable leftovers are worse than moderate space.
        if post_residual < 10 {
            score += 200.0;
        }

        // 2-step lookahead: strongly reward residuals that exactly match the next item.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 500.0;
            } else {
                let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
                // Penalty grows as the next item fits worse into the leftover space.
                if next_item_size > post_residual {
                    score += (next_item_size - post_residual) as f64 * 1.5;
                } else {
                    score += diff * 0.5;
                }
            }
        }

        // Compare against mean residual across open bins.
        let mean_gap = post_residual as f64 - mean_residual;
        score += mean_gap * 0.3;

        // Last-chance bin: if this is the only bin that fits, strongly prefer using it
        // over opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 300.0;
        }

        // Penalize opening new bins when open bins have plenty of room.
        if bin_residual == bin_capacity {
            let openness = open_bins_count as f64;
            let avg_free = mean_residual;
            let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - avg_free / bin_capacity as f64);
            score += 150.0 + openness * 20.0 - pressure * 100.0;
            // Early in the stream, opening bins is cheaper (spread items out).
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score -= (1.0 - progress) * 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Penalize dead space that cannot hold the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            score -= 2.0; // bin remains useful for the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Time horizon: early in the stream, keep bins flexible (penalize low residuals);
    // late in the stream, pack tightly regardless.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 8.0;

    // Penalize deviating from mean residual balance (keeps pool homogeneous early).
    score += 0.3 * (post_residual as f64 - mean_residual).abs() * (1.0 - progress);

    // Many open bins: discourage spreading; prefer filling existing bins deeper.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a new bin
        } else {
            // Opening a new bin is only good if existing fits are poor.
            score += 30.0 * fit_ratio + 2.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: minimize post residual, with non-linear emphasis on small leftovers.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, penalize large residuals more strongly
    // (waste compounds later), rewarding tight fits.
    score += 40.0 * progress * norm_pr * norm_pr * cap;

    // Dead-space penalty: residuals too small for typical future items are costly.
    let dead = if next_item_size > 0 {
        ((next_item_size as f64 - pr) / cap).max(0.0)
    } else {
        norm_pr
    };
    score += 25.0 * dead * dead * cap;

    // Reward using bins that are the only fitting option (avoid opening a new bin).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Slight preference for bins with residual below mean (consolidate emptiness).
    score += 5.0 * (mean_residual - pr) / cap;

    // Penalize opening a new bin when good fits exist, mildly more late in stream.
    if bin_residual == bin_capacity {
        score += 12.0 + 20.0 * progress;
    }

    // Non-linear item-bin interaction: prefer filling bins with relatively large items.
    score -= 10.0 * norm_item * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        // Tight-fit reward: combine fine-grained residual fitting.
        score -= (item / cap) * 45.0;
        score -= 65.0 * (1.0 - post / cap);
        // Penalize residuals too small for typical items (dead space).
        if post < 20.0 { score += 30.0; }
    }

    // Lookahead coupling: favor residuals that fit the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            // Stronger chained anticipation (borrowed from best heuristic).
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 80.0;
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // Discourage opening new bins when the item fits reasonably well elsewhere.
        if fitting_bins_count > 0 && post >= item * 0.5 {
            score += 40.0;
        }
    }

    // Mild mean-residual balancing.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 12.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition post_residual into residue classes mod 10
    // (capacity fractions). Residuals that are "perfectly consumable" by
    // typical item sizes are cheap; awkward residues are penalized.
    let r = post_residual % 10;
    let awkward = match r {
        0 => 0.0,          // perfectly divisible: highly reusable
        1 | 9 => 2.0,
        2 | 8 => 4.0,
        3 | 7 => 6.0,
        4 | 6 => 8.0,
        _ => 10.0,         // residue 5: only an exact-50 item fits well
    };
    score += awkward;

    // Reward small residuals (tight fits) with a non-linear squash.
    if post_residual <= 10 {
        score -= 15.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Lookahead coupling: if next_item_size fits exactly into post_residual,
    // strongly reward; if next_item_size cannot ever fit, penalize dead space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            // fraction of the lookahead consumable by this bin
            let fit_frac = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fit_frac;
        } else {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Integer-division threshold: bins whose remaining capacity can hold
    // at least (post_residual / 10) more small items are valuable.
    let small_slots = post_residual / 10;
    score -= 1.5 * small_slots as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin unless current bin is a
    // terrible fit (huge post_residual waste) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 + 20.0 * (1.0 - progress) + awkward * 0.5;
        if post_residual > 40 {
            score -= 15.0; // allow opening when item leaves big waste anyway
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't open when a last-chance bin exists
        }
    }

    // Mild load-balancing: prefer bins whose residual is near the mean.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

