        -72.0
    } else if post_residual <= 4 {
        -50.0
    } else if post_residual <= 8 {
        -45.0
    } else if post_residual <= 10 {
        -40.0
    } else if post_residual <= 20 {
        -22.0
    } else if post_residual <= 46 {
        0.0
    } else {
        28.0
    };
    score += class;

    // Dead-space ratio term (tightened to reduce wasted residual)
    if norm_pr > 0.55 {
        score += norm_pr * 10.0;
    } else if norm_pr < 0.08 {
        score -= 5.0 * (1.0 - norm_pr);
    }

    // Penalize residuals too small for typical future items
    score += 15.0 * (norm_pr - 0.25) * (norm_pr - 0.25);

    // Next-item lookahead with snug tiers
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 900.0;
        } else if pr >= nx {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 36.0;
            } else if new_post <= 10 {
                score -= 29.0;
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
                score += new_post as f64 * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 12.0;
            }
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 10.0 * snug * snug;
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 46.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 24.0;
            }
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 9.0;
            }
            if new_post > 0 {
                if new_post < item_size {
                    score += (item_size - new_post) as f64 * 0.06;
                    if progress > 0.5 {
                        score += (item_size - new_post) as f64 * 0.05 * progress;
                    }
                }
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 10.0;
                    } else if post2 <= 5 {
                        score -= 6.0;
                    } else if post2 >= next_item_size {
                        let post3 = post2 - next_item_size;
                        if post3 == 0 {
                            score -= 7.0;
                        } else if post3 <= 4 {
                            score -= 4.0;
                        }
                    }
                }
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 14.0;
                }
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
                if new_post > 18 && (new_post as f64) > nx * 2.5 {
                    score += 6.0;
                }
                if progress > 0.3 && (new_post as f64) < mean_residual * 0.5 && new_post < 12 {
                    score += 5.0 * progress;
                }
            }
            let next_fits_elsewhere = mean_residual >= nx && open_bins_count > 1;
            if next_fits_elsewhere && new_post > 0 {
                score += 3.0;
            } else if !next_fits_elsewhere {
                score -= 12.0;
            }
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap * cap;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }
    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // ---- NEW-BIN CANDIDATE LOGIC (adopted from best heuristic, simplified) ----
    if bin_residual == bin_capacity {
        let mut nb = 57.0 + (pr / cap) * 10.0;
        nb += 150.0;
        nb -= 120.0 * (it / cap);
        nb += 1.0 * mean_residual;
        nb += 200.0 * progress;
        if fitting_bins_count == 0 {
            nb -= 2000.0;
        } else {
            nb += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        nb += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        nb += 90.0 * progress * (1.0 - open_frac.min(1.0));

        // Guard: strong snug fit on an open bin blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.85 {
            let snug_fit = (pr - it) / cap;
            if snug_fit <= 0.12 {
                nb += 20.0;
            } else if snug_fit <= 0.30 && open_bins_count > 2 {
                nb += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // Never open a new bin if an open bin fits the item exactly
        if fitting_bins_count > 0 && post_residual == 0 {
            nb += 60.0;
        }
        // Small item into a fresh bin wastes capacity
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            nb += 12.0;
        }
        // Aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            nb += 6.0;
        }
        // Next-item snugness on open bins blocks new-bin opening
        if next_item_size > 0 && next_item_size <= post_residual {
            let diff = (pr - next_item_size as f64).abs();
            nb += 900.0 * (1.0 - diff / cap);
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        // Tight-fit reward: combine fine-grained residual fitting.
        score -= (item / cap) * 45.0;
        score -= 65.0 * (1.0 - post / cap);
        // Penalize residuals too small for typical items (dead space),
        // scaled by how much of the bin was consumed.
        if post < 20.0 {
            score += 30.0 + 20.0 * (1.0 - post / 20.0);
        }
    }

    // Lookahead coupling: favor residuals that fit the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 80.0;
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            // Stronger resistance to opening a new bin when alternatives exist;
            // scale resistance by how tight the best existing fit is.
            score += 80.0 * (fitting_bins_count as f64).min(5.0);
            // If the item would leave >= half its size as residual elsewhere,
            // opening a fresh bin may still be preferable for large items.
            if item > 0.6 * cap {
                score -= 50.0 * (item / cap);
            }
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // Discourage opening new bins when the item fits reasonably well elsewhere.
        if fitting_bins_count > 0 && post >= item * 0.5 {
            score += 60.0;
        }
    }

    // Mild mean-residual balancing.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 12.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of the stream completed (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward filling the bin snugly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Reward near-perfect fills (post_residual close to 0).
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let waste_after_pair = post_residual - next_item_size;
            score -= 8.0 * (1.0 - waste_after_pair as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; small penalty for leaving awkward gaps.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize bins whose residual deviates far below the mean (fragmented bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev * (0.5 + progress);

    // Many open bins: prefer consolidating into existing bins.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate logic: only attractive if the item is huge and fit elsewhere is bad.
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress; // early stream: more open to new bins
        let huge_item = item_size as f64 / bin_capacity as f64;
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let new_bin_bonus = 60.0 * openness * huge_item + 80.0 * poor_alternatives
            - 45.0 * (1.0 - huge_item) * (1.0 - openness);
        score += new_bin_bonus;
        // If a next item would pair well with this item in a fresh bin, encourage it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 { let cap = bin_capacity as f64 ; let post = post_residual as f64 ; let item = item_size as f64 ; let mut score = post ; if post_residual == 0 { score -= 1000.0 ; } if next_item_size > 0 { let nxt = next_item_size as f64 ; if next_item_size <= post_residual { let diff = (post - nxt) . abs () ; score -= 900.0 * (1.0 - diff / cap) ; if diff == 0.0 { score -= 50.0 ; } } else { score += 40.0 * (nxt / cap) ; score += 30.0 * ((post - nxt) / cap) ; } } if bin_residual == bin_capacity { score += 150.0 ; score -= 120.0 * (item / cap) ; score += 1.0 * mean_residual ; let progress = step_index as f64 / total_items . max (1) as f64 ; score += 200.0 * progress ; if fitting_bins_count == 0 { score -= 2000.0 ; } else { score += 60.0 * (fitting_bins_count as f64) . min (5.0) ; } score += 80.0 * progress * (mean_residual / cap) ; let open_frac = open_bins_count as f64 / (total_items . max (1) as f64) ; score += 90.0 * progress * (1.0 - open_frac . min (1.0)) ; // dead-space penalty: discourage leaving awkward small residuals that few future items can use
 if post_residual > 0 && post_residual < 25 { score += 35.0 * (1.0 - post / 25.0) ; } // prefer bins whose residual stays usable by the known next item even after this placement
