pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fills (low post_residual). Late: tolerate larger residuals
    // slightly more since consolidation matters less than bin count.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = 1.0 - 0.35 * progress - 0.15 * p2 + 0.10 * p3;
    score *= coupling.max(0.4);

    // Penalize residuals that cannot fit the next item (dead space) — smooth quadratic.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap * cap;
        } else {
            // Reward residuals that exactly or nearly fit the next item.
            let slack = (pr - nxt) / cap;
            score -= 3.0 * (1.0 - slack).max(0.0) * (1.0 - slack).max(0.0);
        }
    }

    // Reward near-perfect fits: smooth quadratic on post_residual relative to capacity.
    let fit_term = pr / cap;
    score -= 6.0 * (1.0 - fit_term) * (1.0 - fit_term) * (1.0 - fit_term);

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins that are relatively fuller among many candidates.
        score += 2.0 * (bin_residual as f64 / cap - 0.5).abs();
    }

    // Mild penalty for spreading across many open bins; encourages consolidation.
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins near the mean (balanced fills).
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: keep its baseline score so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    // Post-residuals divisible by large powers of 2 or by 10 are "harmonic"
    // (more likely to be exactly filled by future items) -> reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    if pr > 0 {
        if pr % 2 == 0 { harmonic_bonus += 3.0; }
        if pr % 4 == 0 { harmonic_bonus += 3.0; }
        if pr % 8 == 0 { harmonic_bonus += 2.0; }
        if pr % 10 == 0 { harmonic_bonus += 4.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 5.0; }
        if pr % 50 == 0 { harmonic_bonus += 8.0; }
        if pr == bin_capacity { harmonic_bonus += 0.0; } // empty handled below
        // Integer-division threshold: residual in the "dead zone" 1..=9 is nearly unusable
        if pr < 10 { harmonic_bonus -= 25.0; }
        else if pr < 20 { harmonic_bonus -= 8.0; }
    }
    score -= harmonic_bonus;

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        let n = next_item_size as f64;
        // reward if next item divides or nearly divides the post residual
        if pr % next_item_size == 0 {
            score -= 12.0;
        } else if pr % 10 == next_item_size % 10 {
            score -= 4.0;
        }
        // reward tight two-item packing: post_residual - next_item_size small
        let after_next = pr - next_item_size;
        if after_next < 10 {
            score -= 10.0;
        }
        // penalize if next item would leave a huge gap in this bin but fits better elsewhere
        if after_next as f64 > mean_residual {
            score += 2.0;
        }
        let _ = n;
    } else if next_item_size > pr && pr > 0 {
        // next item cannot use this residual -> residual likely wasted
        score += 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes open-bin capacity.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; cheap when few bins open, expensive when many
        score = 55.0 + 2.5 * open_bins_count as f64;
        // allow new bin if current item is large and would leave a bad fit in any open bin
        if item_size >= 70 { score -= 20.0; }
        // cheap new bin early in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        // if next item is tiny, a fresh bin wastes its harmony
        if next_item_size > 0 && next_item_size <= 15 { score += 10.0; }
        return score;
    }

    // Tightness reward: small post_residual relative to capacity is a good fit.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 20.0 * tightness * tightness;

    // Penalize bins whose residual deviates strongly from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fuller bins when many bins are open (bin consolidation)
    score += 0.3 * open_bins_count as f64 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.99;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to ever be useful (assume min item size 1,
    // but practically gaps below ~15 attract few future items) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 + (15.0 - post_residual as f64) * 3.0;
    } else if post_residual < 30 {
        score += (30.0 - post_residual as f64) * 0.8;
    }

    // Perfect fit reward: strong bonus for tight packing.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual closely matches the item (tight fit relative measure).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 10.0;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize placements that leave a gap slightly too small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate relatively).
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive if residual is huge relative to item
    // and mean residual across open bins is small.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.5 - open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // opening fresh bin may serve big next item better
        }
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-step chain: this bin becomes exactly full next step
        } else if post_residual >= next_item_size {
            // next item fits; the smaller the leftover after the lookahead, the better
            let lookahead_leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - lookahead_leftover / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (gap / 100.0);
        }
    }

    // Penalize creating unusable dead space (residual too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    if mean_residual > 0.0 {
        score += 8.0 * (post_residual as f64 - mean_residual) / mean_residual;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild pressure to consolidate into few bins when many are open
    score += 0.5 * open_bins_count as f64;

    // Slight preference for filling bins as the stream progresses
    score -= 5.0 * (item_size as f64 / bin_capacity as f64) * (1.0 + step_index as f64 / total_items.max(1) as f64);

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 45.0 - 20.0 * (1.0 - item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // small unusable slivers are wasted capacity
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to mismatch
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    } else {
        // Last item: just minimize post_residual aggressively.
        score -= 8.0 * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor and the item is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = (post_residual as f64 / bin_capacity as f64); // = 1 - item/cap
        let mean_tight = 1.0 - mean_residual / bin_capacity as f64;
        // Prefer new bin when item is large, open bins are already tight,
        // and we're late in the stream (fewer future chances to fill it).
        score = 40.0 + 60.0 * poor_fit - 30.0 * mean_tight - 20.0 * progress
            + 5.0 * (open_bins_count as f64).ln().max(0.0);
        // But if next item is small, a fresh bin wastes its big residual.
        if next_item_size > 0 && next_item_size <= 30 {
            score += 15.0;
        }
        // Early stream: opening bins is cheap, slightly encourage diversity.
        if progress < 0.2 {
            score -= 10.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer
    // consolidating into existing bins (penalize spreading).
    if bin_residual < bin_capacity {
        let spread = mean_residual / bin_capacity as f64;
        score += 4.0 * spread * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Mild tie-break noise-free deterministic jitter based on step to break
    // symmetric scores in favor of earlier bins.
    score += (step_index % 3) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        // Fine-grained residual fitting: reward proportional fill.
        score -= (item / cap) * 45.0;
        score -= 65.0 * (1.0 - post / cap);
        // Dead-space penalty scaled by item size: small leftovers are worse for big items.
        if post < 20.0 {
            score += 30.0 + 20.0 * (item / cap);
        }
    }

    // Lookahead coupling: favor residuals that fit the next item tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 80.0;
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // Discourage opening new bins when the item fits reasonably well elsewhere.
        if fitting_bins_count > 0 && post >= item * 0.5 {
            score += 40.0;
        }
    }

    // Mean-residual balancing: pull scores toward bins closer to the mean residual.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 12.0 * (1.0 - post / cap);

    // Waste-rate coupling: penalize bins whose residual is far below the next item
    // (dead space that cannot be reclaimed), stronger late in the stream.
    if next_item_size > 0 && next_item_size > post_residual && !is_new_bin && post_residual > 0 {
        score += 25.0 * (1.0 - post / cap) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with polynomial sharpening
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, small dead space matters more (bins get reused a lot);
    // later, tolerate residuals slightly more but reward near-perfect fits.
    let prn = pr / cap; // normalized post-residual in [0,1]
    let w = 1.0 + 0.8 * progress; // progress-dependent weight
    score += w * (prn * prn) * cap;          // quadratic penalty on wasted space
    score -= (1.0 - prn).powi(3) * 12.0 * (0.5 + progress); // cubic reward for tight fits, stronger later

    // Smooth coupling with mean residual across open bins:
    // if this bin's post-residual deviates above the mean, penalize (fragmentation risk)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap * (0.3 + 0.7 * (1.0 - progress));

    // Lookahead: if next item fits exactly into post_residual, big reward (smooth polynomial)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let gapn = gap / cap;
        score -= (1.0 - gapn).powi(2) * 15.0;
    } else {
        // last item: only post-residual matters, mild bonus for emptier bins
        score -= prn * 5.0;
    }

    // Last-chance bin: strongly reward using it (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty for having many open bins relative to progress (encourage consolidation early)
    score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize so it's only chosen when fits are truly poor
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + prn * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover: classify post_residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Dead-space penalty: leftovers that are too small to be useful for typical items.
    // Items in [1,100]; a residual below ~10 is nearly dead space.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Harmonic classes via integer division thresholds on post_residual:
    // class 0: post_residual > 50 (half bin or more left) -> good
    // class 1: 20 < post_residual <= 50 -> medium
    // class 2: 10 <= post_residual <= 20 -> risky small slot
    let class = if post_residual > 50 { 0 } else if post_residual > 20 { 1 } else { 2 };
    score += match class {
        0 => -20.0,
        1 => 5.0,
        _ => 25.0,
    };

    // Modulo arithmetic: leftover compatible with common item size residues gets a bonus.
    // If the leftover is an exact multiple of a plausible small item size (e.g. 10, 20, 25, 50),
    // future items can tile it perfectly.
    let pr = post_residual;
    if pr % 50 == 0 || pr % 25 == 0 || pr % 20 == 0 || pr % 10 == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits but leaves a remainder: penalize bad chains.
            let chain_res = post_residual - next_item_size;
            if chain_res < 10 {
                score += 20.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: mild penalty, this bin becomes dead after placement.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin unless the
    // fit is terrible (tiny leftover).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 30.0;
    }

    // Many open bins: prefer compacting into existing bins rather than spreading.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Progress-based nudge: later in the stream, waste matters more; tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += frac * 30.0 * (1.0 - progress);

    // New-bin candidate: empty bin. Prefer it only when the fit would leave a large usable
    // chunk AND existing fits are poor. Base score near residual (capacity) minus a bonus.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item is large (existing bins would be
        // shredded into small leftovers).
        score = bin_capacity as f64 - 40.0 + (100 - item_size) as f64 * 0.2;
        if item_size > 70 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever host the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 1000.0;
    } else if post_residual <= 15 {
        score += 300.0;
    } else if post_residual <= 25 {
        score += 80.0;
    }

    // Dead space relative to the lookahead item: if the leftover cannot
    // hold the next item, the gap is likely to become permanent waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 40.0;
    }

    // Perfect fit reward: leaving exactly zero or a near-perfect fill.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight-fit reward: using most of the bin's current space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fill_ratio;

    // Open-bin pressure: penalize spreading across many open bins,
    // but relax pressure as the stream progresses (endgame consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (8.0 * (1.0 - progress) + 3.0);

    // Last-chance bin: if this is the only bin that fits, strongly favor
    // using it over opening a new bin (unless dead space is severe).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    // An empty bin wastes its full residual; penalize unless open bins
    // are nearly full on average.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let pressure = mean_fill / bin_capacity as f64;
        // Reward opening a new bin only when existing bins are > 70% full.
        if pressure > 0.7 {
            score -= 120.0 * (pressure - 0.7);
        } else {
            score += 150.0 * (0.7 - pressure);
        }
        // If the item would leave severe dead space in every fitting bin,
        // opening a fresh bin becomes more attractive.
        if post_residual < 10 && post_residual > 0 {
            score -= 200.0;
        }
    }

    // Mild coupling with mean residual: prefer bins whose residual is
    // close to the item (best-fit flavor) relative to fleet average.
    let diff = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.2 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward bins whose post_residual will be tightly reused
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            // perfect match: next item exactly fills the bin afterwards
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // reward proportionally to how well next item fits the leftover
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // next item cannot use this leftover: mild penalty scaled by waste
            score += 0.15 * (next - pr);
        }
    } else {
        // last item: minimize leftover waste strongly
        score -= 20.0;
    }

    // tight fit now is good: small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness;

    // compare against mean residual: leaving this bin below mean wastes capacity
    if (post_residual as f64) < mean_residual {
        score += 0.3 * (mean_residual - post_residual as f64);
    } else {
        score -= 0.1 * ((post_residual as f64) - mean_residual);
    }

    // last-chance bin: strongly encourage using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // discourage opening a new bin when decent fitting bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 10.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Base: post residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    let progress_ramp = progress * progress * (3.0 - 2.0 * progress);
    score += 30.0 * progress_ramp * norm_pr * norm_pr;

    // Perfect-fit reward (exact fill is always optimal)
    let fit_bump = (-norm_pr * norm_pr * 12.0).exp();
    score -= 25.0 * fit_bump;
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space class bands
    let class: f64 = if post_residual == 0 {
        -72.0
    } else if post_residual <= 4 {
        -50.0
    } else if post_residual <= 8 {
        -45.0
    } else if post_residual <= 10 {
        -40.0
    } else if post_residual <= 20 {
        -22.0
    } else if post_residual <= 46 {
        0.0
    } else {
        28.0
    };
    score += class;

    // Round residuals are easier to fill later
    if post_residual % 10 == 0 {
        score -= 10.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    } else if post_residual % 20 == 0 {
        score -= 5.0;
    } else if post_residual % 15 == 0 {
        score -= 3.0;
    }

    // Dead-space ratio term
    if norm_pr > 0.55 {
        score += norm_pr * 6.0;
    } else if norm_pr < 0.08 {
        score -= 4.0 * (1.0 - norm_pr);
    }

    // Penalize leaving a residual that is too small for typical future items
    let mid = 0.25;
    score += 15.0 * (norm_pr - mid) * (norm_pr - mid);

    // Next-item lookahead: strong snugness reward (from best heuristic)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (pr - nx).abs();
            // strong snugness reward: leaving a residual exactly the next item size
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
            let new_post = post_residual - next_item_size;
            if new_post > 0 {
                if new_post <= 10 {
                    score -= 29.0;
                } else if new_post <= 25 {
                    score -= 15.0;
                } else {
                    score += new_post as f64 * 0.18;
                }
                if new_post < 4 {
                    score -= 12.0;
                }
                // divisibility: residual reusable in multiples of next item
                if next_item_size as u64 % new_post as u64 == 0 {
                    score -= 9.0;
                }
                // second/third-order lookahead
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 10.0;
                    } else if post2 <= 5 {
                        score -= 6.0;
                    } else if post2 >= next_item_size {
                        let post3 = post2 - next_item_size;
                        if post3 == 0 {
                            score -= 7.0;
                        } else if post3 <= 4 {
                            score -= 4.0;
                        }
                    }
                }
                // near-mean alignment
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                // tiny unusable residual penalty
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
                // usability vs mean residual late in stream
                if progress > 0.3 && (new_post as f64) < mean_residual * 0.5 && new_post < 12 {
                    score += 5.0 * progress;
                }
            }
            // next item fits elsewhere: safe to leave residual here
            let next_fits_elsewhere = mean_residual >= nx && open_bins_count > 1;
            if next_fits_elsewhere && new_post > 0 {
                score += 3.0;
            } else if !next_fits_elsewhere {
                score -= 12.0;
            }
        } else {
            let gap = (nx - pr) / cap;
            score += 40.0 * (nx / cap);
            score += 30.0 * ((pr - nx) / cap);
            score += 12.0 * gap * gap * cap;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // Alignment with mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate gating
    if bin_residual == bin_capacity {
        score = 57.0 + (pr / cap) * 10.0;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        }
        // MUTATION: strong fitting-count pressure — reuse open bins when possible
        score += 60.0 * (fitting_bins_count as f64).min(5.0);
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // large item prefers a fresh bin (no fragmentation of open bins)
        score -= 120.0 * norm_it;
        // snug current fit blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (pr - it) / cap;
            if snug_fit <= 0.12 {
                score += 20.0;
            } else if snug_fit <= 0.30 && open_bins_count > 2 {
                score += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            score += 6.0;
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 60.0;
        }
        // small item into a fresh bin wastes capacity unless stream is early
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            score += 12.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            score -= 6.0;
        }
        // MUTATION: late-stream, if a residual snugly fits the next item, prefer that bin over a new one
        if progress > 0.5 && next_item_size > 0 && open_bins_count > 1
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: minimize post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Reward bins whose residual is close to item_size (perfect packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness.abs()) * 12.0;

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: prefer reusing open bins when fit is decent.
        score += 8.0;
        // If item leaves a large unusable gap in an existing bin, opening a new bin
        // becomes attractive. Gap = post_residual; penalize existing bins with gaps.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // tiny dead space in new bin is fine
        }
        // Early in the stream, opening bins is cheap; later, conserve.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        // If many bins are open with large mean residual, prefer reusing them.
        score += (mean_residual / bin_capacity as f64) * 15.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    } else {
        // Penalize creating dead space that likely can't fit future items.
        if next_item_size > 0 {
            if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
                score += 15.0; // dead space smaller than smallest plausible item
            }
            // Bonus if the leftover exactly accommodates the lookahead item.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        }
        // Prefer fuller bins when many bins are open (consolidation pressure).
        score += (mean_residual - post_residual as f64).max(0.0) * 0.05;
    }

    // Mild preference for bins already below mean residual (balance avoidance:
    // pack into the emptiest usable bin to keep others for future mid-size items).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    }

    score
}

