            score -= 2.0 * (1.0 - pr / (pr + nxt));
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: mildly discourage early, encourage late
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - t) - 2.0 * t;
    }

    // Mild pressure against spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - fill);

    // Mean-residual alignment term
    score += 0.1 * (pr - mean_residual).abs();

    score
}

