        if post_residual >= 85 {
            score -= 9.0;
        }
        if post_residual >= 96 {
            score -= 6.0;
        }
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if progress > 0.9 && open_bins_count > 3 {
            score += 16.0;
        }
        if progress > 0.75 && fitting_bins_count >= 1 && post_residual <= 12 {
            score += 15.0;
        }
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // near-perfect pair fill with next item: prefer this bin over a new one
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.45 {
            score -= 6.0;
        }
        // aggregate-space pressure: if total open slack is large, prefer reusing bins
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                score += 9.0;
            }
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            score -= 6.0;
        }
        if progress > 0.55 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 5.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
