pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact quarter/half classes are valuable
    let cap = bin_capacity as f64;
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual % 25 == 0 {
        score -= 20.0;   // quarter-capacity classes are reusable
    } else if post_residual % 10 == 0 {
        score -= 8.0;    // decimal class residual
    } else {
        score += 3.0;    // awkward residue
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.8 + 15.0;
        } else {
            // penalize dead space next item cannot use
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Fractional capacity pressure: bins already near full are good targets
    let fill_frac = 1.0 - bin_residual as f64 / cap;
    score -= fill_frac * 10.0;

    // New-bin candidate: only attractive when existing fits are terrible
    if bin_residual == bin_capacity {
        score += 60.0 - fill_frac * 0.0;
        if mean_residual < 20.0 {
            score -= 30.0; // open bins nearly full, new bin reasonable
        }
    }

    // Stream progression: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
