    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and progress.
        score += 30.0 + 4.0 * open_bins_count as f64 + 40.0 * progress;
        // But if all fitting options are poor (big dead space), allow new bin.
        if post_residual as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Reusing an open bin reduces bin count pressure.
        score -= 2.0 * open_bins_count as f64 * (1.0 - progress);
