    let mid = 0.25;
    score += 15.0 * (norm_pr - mid) * (norm_pr - mid);

    // Next-item lookahead with snug tiers
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 900.0;
        } else if pr >= nx {
            let new_post = post_residual - next_item_size;
            if new_post == 0 {
                score -= 36.0;
            } else if new_post <= 10 {
                score -= 29.0;
            } else if new_post <= 25 {
                score -= 15.0;
            } else {
                score += new_post as f64 * 0.18;
            }
            if new_post > 0 && new_post < 4 {
                score -= 12.0;
            }
            let snug = 1.0 - ((pr - nx) / cap).abs();
            score -= 10.0 * snug * snug;
            // pair-fill bonus
            let pair = item_size as u64 + next_item_size as u64;
            if pair == bin_residual as u64 {
                score -= 46.0;
            }
            if bin_residual as u64 >= pair && (bin_residual as u64 - pair) <= 5 {
                score -= 24.0;
            }
            // divisibility: residual reusable in multiples of next item
            if new_post > 0 && next_item_size > new_post && (next_item_size as u64 % new_post as u64) == 0 {
                score -= 9.0;
            }
            // second/third-order lookahead
            if new_post > 0 {
                if new_post < item_size {
                    score += (item_size - new_post) as f64 * 0.06;
                    if progress > 0.5 {
                        score += (item_size - new_post) as f64 * 0.05 * progress;
                    }
                }
                if new_post % 5 == 0 {
                    score -= 3.0;
                }
                if new_post as u64 >= next_item_size as u64 {
                    let post2 = new_post - next_item_size;
                    if post2 == 0 {
                        score -= 10.0;
                    } else if post2 <= 5 {
                        score -= 6.0;
                    } else if post2 >= next_item_size {
                        let post3 = post2 - next_item_size;
                        if post3 == 0 {
                            score -= 7.0;
                        } else if post3 <= 4 {
                            score -= 4.0;
                        }
                    }
                }
                // triple-fill: item + 2x next nearly fills bin
                if item_size as u64 + next_item_size as u64 * 2 <= bin_residual as u64
                    && bin_residual as u64 - (item_size as u64 + next_item_size as u64 * 2) <= 3 {
                    score -= 14.0;
                }
                // near-mean alignment
                if (new_post as f64 - mean_residual).abs() < 3.0 {
                    score -= 7.0;
                }
                // tiny unusable residual penalty
                if (new_post as u64) * 4 < bin_residual as u64 && new_post < 8 {
                    score += 10.0;
                }
                // large leftover is still usable
                if new_post > 18 && (new_post as f64) > nx * 2.5 {
                    score += 6.0;
                }
                if progress > 0.3 && (new_post as f64) < mean_residual * 0.5 && new_post < 12 {
                    score += 5.0 * progress;
                }
            }
            // next item fits elsewhere: safe to leave residual here
            let next_fits_elsewhere = mean_residual >= nx && open_bins_count > 1;
            if next_fits_elsewhere && new_post > 0 {
                score += 3.0;
            } else if !next_fits_elsewhere {
                score -= 12.0;
            }
        } else {
            let gap = (nx - pr) / cap;
            score += 12.0 * gap * gap * cap;
            if post_residual > 60 {
                score += 6.0;
            }
            let gap_abs = next_item_size - post_residual;
            if gap_abs <= 5 && fitting_bins_count > 1 {
                score += 4.0;
            }
            if gap_abs > 5 && gap_abs <= 20 && mean_residual >= gap_abs as f64 && fitting_bins_count > 2 {
                score += 3.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 42.0;
    }

    // Consolidation pressure when many bins are open
    if open_bins_count > 6 && post_residual > 0 && post_residual * 3 < bin_capacity {
        score += 8.0;
    }

    if post_residual == 0 && fitting_bins_count > 1 {
        score -= 6.0;
    }

    // Alignment with mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: adopt strong progressive scoring (from best heuristic)
    if bin_residual == bin_capacity {
        score = 150.0
            - 120.0 * norm_it
            + mean_residual
            + 200.0 * progress
            + 80.0 * progress * (mean_residual / cap);
        let open_frac = (open_bins_count as f64 / total_items.max(1) as f64).min(1.0);
        score += 90.0 * progress * (1.0 - open_frac);
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        // exact fit available -> never open a new bin
        if post_residual == 0 {
            score += 60.0;
        }
        // snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (pr - it) / cap;
            if snug_fit <= 0.12 {
                score += 20.0;
            } else if snug_fit <= 0.30 && open_bins_count > 2 {
                score += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            score += 6.0;
        }
        // small item into a fresh bin wastes capacity
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            score += 12.0;
        }
        // near-perfect pair fill with next item: prefer open bins over a new one
        if progress < 0.7 && open_bins_count > 2 && next_item_size > 0
            && next_item_size <= post_residual
            && (post_residual as u64 - next_item_size as u64) <= 3 {
            score -= 16.0;
        }
        // late-stream: consolidate, don't open
        if progress > 0.85 && open_bins_count > 1 {
            score += 15.0;
        }
        // early stream with a big next item and low mean slack: opening may be right
        if progress < 0.6 && next_item_size > 60 && open_bins_count > 2 && mean_residual < 30.0 {
            score -= 10.0;
        }
        // aggregate-space pressure: if total open slack is large, prefer reusing bins
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                score += 9.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 { let cap = bin_capacity as f64 ; let post = post_residual as f64 ; let item = item_size as f64 ; let mut score = post ; if post_residual == 0 { score -= 1000.0 ; } if next_item_size > 0 { let nxt = next_item_size as f64 ; if next_item_size <= post_residual { let diff = (post - nxt) . abs () ; score -= 900.0 * (1.0 - diff / cap) ; if diff == 0.0 { score -= 50.0 ; } } else { score += 40.0 * (nxt / cap) ; score += 30.0 * ((post - nxt) / cap) ; } } // dead-space refinement: penalize residuals too small to be useful later
 let residual_frac = post / cap ; if residual_frac > 0.0 && residual_frac < 0.05 { score += 25.0 * (0.05 - residual_frac) / 0.05 ; } if bin_residual == bin_capacity { score += 150.0 ; score -= 120.0 * (item / cap) ; score += 1.0 * mean_residual ; let progress = step_index as f64 / total_items . max (1) as f64 ; score += 200.0 * progress ; if fitting_bins_count == 0 { score -= 2000.0 ; } else { score += 60.0 * (fitting_bins_count as f64) . min (5.0) ; } score += 80.0 * progress * (mean_residual / cap) ; let open_frac = open_bins_count as f64 / (total_items . max (1) as f64) ; score += 90.0 * progress * (1.0 - open_frac . min (1.0)) ; // prefer opening a new bin when the current mean residual is already tight
 score += 35.0 * (1.0 - (mean_residual / cap) . min (1.0)) ; } score }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (wasted space < 10).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    } else if post_residual > 60 {
        // Creating large dead space is bad unless bin was nearly full anyway.
        score += (post_residual as f64 - 60.0) * 0.5;
    }

    // Lookahead: reward if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 20.0; // perfect chain: item then next item
            } else {
                score -= 15.0 - (slack as f64 * 0.1);
            }
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins have large residuals
    // (i.e., existing bins fit poorly) or few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        // Penalize opening a new bin when existing bins could absorb the item decently.
        score += 15.0 + avg_fit_gap * 0.3 - progress * 10.0
                 - (open_bins_count as f64).min(10.0);
        // If mean residual is huge, existing bins are wasteful anyway; soften penalty.
        if mean_residual > 70.0 {
            score -= 20.0;
        }
    } else {
        // Mild bonus for filling bins that are already mostly used.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Global pressure: many open bins with small residuals -> consolidate tightly.
    if open_bins_count > 3 && mean_residual < 30.0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), non-linearly penalized.
    let x = pr / cap; // normalized post residual in [0,1]
    let mut score = 40.0 * x + 60.0 * x * x;

    // Smooth polynomial coupling of wasted space with stream progress:
    // later in the stream, dead space becomes progressively more costly.
    let coupling = (x * x * (1.0 - x)) * (progress * progress * (3.0 - 2.0 * progress));
    score += 80.0 * coupling;

    // Reward bins whose residual stays usable for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 12.0 * snug * (1.0 - progress);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Residual too small for the next item: penalize proportionally.
        score += 10.0 * x * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x);
    }

    // Mild pressure against spreading across many open bins.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for bins with residual near the mean (balanced packing).
    let dev = ((bin_residual as f64 - mean_residual) / cap).abs();
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize mildly so we only open when fits are poor,
    // with the penalty decaying as the stream progresses.
    if bin_residual == bin_capacity {
        score = 45.0 + 30.0 * progress + 20.0 * x * x;
        // If no open bin fits well, opening a new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        // Fine-grained residual fitting: reward proportional fill.
        score -= (item / cap) * 45.0;
        score -= 65.0 * (1.0 - post / cap);
        // Dead-space penalty scaled by item size: small leftovers are worse for big items.
        if post < 20.0 {
            score += 30.0 + 20.0 * (item / cap);
        }
    }

    // Lookahead coupling: favor residuals that fit the next item tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 80.0;
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling.
    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // Discourage opening new bins when the item fits reasonably well elsewhere.
        if fitting_bins_count > 0 && post >= item * 0.5 {
            score += 40.0;
        }
        // Extra guard: never open a new bin when any existing bin leaves a tighter
        // post-residual than half the item size.
        if fitting_bins_count > 0 && post_residual < item_size / 2 {
            score += 120.0;
        }
    }

    // Mean-residual balancing: pull scores toward bins closer to the mean residual.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 12.0 * (1.0 - post / cap);

    // Waste-rate coupling: penalize bins whose residual is far below the next item
    // (dead space that cannot be reclaimed), stronger late in the stream.
    if next_item_size > 0 && next_item_size > post_residual && !is_new_bin && post_residual > 0 {
        score += 25.0 * (1.0 - post / cap) * (0.5 + 0.5 * progress);
        // Stronger penalty when the wasted gap is small but unreclaimable:
        // prefer bins whose leftover stays usable for future items.
        let gap = (next_item_size - post_residual) as f64;
        if gap < 15.0 {
            score += 15.0 * (1.0 - gap / 15.0) * (0.5 + progress);
        }
    }

    // Fragmentation guard: mildly penalize bins whose residual is large but not
    // reusable by the next item, to keep residuals in reusable bands.
    if !is_new_bin && post_residual > 0 && next_item_size > 0 && next_item_size > post_residual {
        score += 8.0 * (post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot sizes" remain usable.
    // Items sizes 1..100; classify post_residual by integer division into
    // harmonic buckets (dead space if it can't hold a meaningful item).
    let pr = post_residual;
    let class = pr / 10; // harmonic bucket index 0..10
    // Penalize dead space: residuals too small for typical items (<=10)
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr == 0 {
        score -= 40.0; // perfect fit reward
    } else {
        // prefer residuals that match common item classes (multiples of 10)
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // mild penalty growing with class index (prefer tighter bins)
        score += class as f64 * 2.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size <= pr {
            score -= 15.0 - (pr - next_item_size) as f64 * 0.2;
        } else {
            // next item won't fit here: slight penalty if we leave a big gap
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // item is large (poor fit elsewhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fill = item_size as f64 / cap;
        score = cap - item_size as f64; // base: lower for larger items
        score -= (1.0 - progress) * 10.0; // slightly favor early opening
        if fill > 0.5 {
            score -= 20.0; // large items justify new bins
        }
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 25.0; // discourage opening when decent fits exist
        }
    }

    // Tie-break by mean residual: prefer bins below mean (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let post = post_residual as f64 ;
    let item = item_size as f64 ;
    let mut score = post ;
    if post_residual == 0 { score -= 1000.0 ; }
    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs() ;
            score -= 900.0 * (1.0 - diff / cap) ;
            if diff == 0.0 { score -= 50.0 ; }
            if post_residual - next_item_size < 8 { score -= 120.0 ; }
        } else {
            score += 40.0 * (nxt / cap) ;
            score += 30.0 * ((post - nxt) / cap) ;
            if nxt > post + 1.0 { score += 25.0 * (1.0 - post / cap) ; }
        }
    }
    if bin_residual == bin_capacity {
        score += 150.0 ;
        score -= 120.0 * (item / cap) ;
        score += 1.0 * mean_residual ;
        let progress = step_index as f64 / total_items.max(1) as f64 ;
        score += 200.0 * progress ;
        if fitting_bins_count == 0 {
            score -= 2000.0 ;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0) ;
        }
        score += 80.0 * progress * (mean_residual / cap) ;
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64) ;
        score += 90.0 * progress * (1.0 - open_frac.min(1.0)) ;
        if item >= 0.85 * cap { score -= 300.0 ; }
    } else {
        let tight = 1.0 - (post / cap) ;
        score -= 20.0 * tight * (item / cap) ;
        if post_residual > 0 && post_residual < item_size { score += 15.0 ; }
        if fitting_bins_count <= 2 && post_residual >= item_size {
            score -= 40.0 * (1.0 - post / cap) ;
        }
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size { score += 10.0 ; }
        // dead-space penalty: prefer bins where post residual stays reusable by the next item
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 35.0 * (post_residual as f64 / cap) ;
        }
        // reward near-perfect fills
        if post_residual > 0 && post_residual <= 4 { score -= 90.0 ; }
        // penalize leaving large stranded gaps when few fitting bins remain
        if fitting_bins_count <= 1 && post_residual > 0 { score += 25.0 * (post / cap) ; }
        // lookahead trade-off: if next item fits exactly the post residual, strongly prefer
        if next_item_size == post_residual { score -= 60.0 ; }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But opening a fresh bin is fine if no open bin fits well
        // (i.e., the best existing residual barely fits).
        if fitting_bins_count > 0 && (bin_residual - item_size) < 5 {
            score -= 20.0;
        }
    } else {
        // Reward bins whose residual is close to the item (tight fit).
        let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
        score -= 20.0 * (1.0 - tightness);
    }

    // Lookahead: if next item could use the post-residual, reward leaving it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (filling emptier bins less).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Late-stream: waste less, prefer tighter packing as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact match between
    // post_residual and the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong bonus when next item fits perfectly into the leftover space
        if post_residual >= next_item_size {
            score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        } else {
