pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: non-linear convex penalty on leftover space (dead space hurts quadratically).
    let mut score = (post / cap).powf(1.7) * 100.0;

    // Reward near-perfect fits strongly (smooth, not piecewise).
    let tightness = 1.0 - post / cap;
    score -= tightness.powf(3.0) * 60.0;

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && (next_item_size as f64) <= post {
        // Smooth reward proportional to how well the next item would use the leftover.
        let next_fit = 1.0 - (post - next_item_size as f64) / cap;
        score -= 25.0 * next_fit * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty growing with stream progress.
        score += 8.0 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer bins whose residual is below mean (consolidating fuller bins),
    // with a smooth interaction with stream progress.
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * rel * (0.5 + progress);

    // New-bin candidate handling: acceptable early, penalized later;
    // penalize more when other bins could fit the item.
    if bin_residual == bin_capacity {
        let others = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score = 30.0 + progress * 50.0 + others * 6.0;
