pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small residues are "dead space".
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit is golden
    } else if r <= 10 {
        score += 25.0; // tiny unusable sliver
    } else {
        // harmonic classes by residue modulo 10
        let m = r % 10;
        score -= match m {
            0 => 20.0,          // round residual: easy to fill with standard items
            1..=3 => 4.0,
            4..=6 => 0.0,
            7..=9 => -6.0,      // odd-ish residuals pair well with mid-size items
            _ => 0.0,
        };
        // integer-division threshold: residual that fits common item bands
        if r >= 10 && r <= 20 { score -= 8.0; }
        if r > 20 && r <= 40 { score -= 12.0; }
        if r > 40 && r <= 60 { score -= 6.0; }
    }

    // Lookahead coupling: does post_residual admit the next item?
    if next_item_size > 0 {
        if next_item_size <= r {
            score -= 18.0; // chain placement possible
            // exact chain (perfect next fit)
            if next_item_size == r { score -= 15.0; }
            // harmonic fraction: next item fills >= half of residual
            if (next_item_size as f64) >= r as f64 / 2.0 { score -= 6.0; }
        } else {
            score += (next_item_size - r) as f64 * 0.35; // next item won't fit here
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a bin when a decent fit exists.
    if bin_residual == bin_capacity {
        let tight = (bin_capacity - item_size) as f64;
        let pressure = open_bins_count as f64 * 4.0;
        score = score.max(0.0) + 45.0 + tight * 0.25 + pressure;
        if fitting_bins_count == 0 { score -= 70.0; } // no alternative
    }

    // Tight fit bonus relative to item size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 22.0;

    // Mild stream-progression damping toward mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * (0.15 + 0.1 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly unusable
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    } else if post_residual <= 35 {
        score += 5.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Perfect fit
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item can't use the gap -> penalize large leftover
            score += 5.0;
        }
    }

    // Open bin pressure: with many open bins, prefer filling existing ones
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 12.0 * pressure;

    // New-bin candidate: only attractive if item is large and would leave a
    // big, reusable residual, or no good existing option exists
    if bin_residual == bin_capacity {
        let base = 25.0;
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 15.0;
        let gap_penalty = if post_residual <= 20 { 30.0 } else { 0.0 };
        let mean_pull = (mean_residual - item_size as f64).max(0.0) * 0.3;
        score += base + big_item_bonus + gap_penalty + mean_pull;
    }

    score
}

