pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (1..=min item) are wasted.
    if post_residual > 0 {
        score += 12.0 * ((cap * 0.5 - post_residual as f64).abs() / cap);
    }
    if post_residual == 0 {
        score -= 30.0; // perfect closure is excellent
    }

    // 2-step lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chained perfect fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.15 * over;
        }
    }

    // Relative to mean residual: prefer bins that keep residual near the mean
    // (balanced packing) but heavily prefer below-mean residual for large items.
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    if item_size as f64 > mean_residual {
        score += 0.10 * dev; // large item: prefer tighter (smaller residual) bins
    } else {
        score += 0.04 * dev.abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or too many bins are already open with fragmented residuals.
    if bin_residual == bin_capacity {
        let base = cap * 0.35;
        score = base
            + 0.5 * open_bins_count as f64
            + 0.05 * mean_residual
            - if next_item_size > 0 && next_item_size <= bin_capacity { 5.0 } else { 0.0 };
        if fitting_bins_count <= 1 {
            score += 60.0; // an open bin fits; opening new bin is wasteful
        }
        if post_residual == 0 { score -= 10.0; }
    }

    // Mild stream-progression pressure: later in the stream, prefer closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - pr / cap);

    score
}

