    // Penalize dead space quadratically, amplified late in the stream
    let dead = post / cap;
    score += dead.powi(2) * (2.0 + 6.0 * progress);

    // Perfect/near-perfect fit bonus (smooth kernel around post_residual ~ 0)
    score -= 6.0 * (-post / 5.0).exp() * (1.0 + 2.0 * progress);

    // Penalize opening a new bin when other bins fit, especially early
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 10.0 + 12.0 * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            score -= 3.0 * (-gap / 15.0).exp();
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Mild penalty for scattering across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - post).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on residual space.
    // Residuals that are "harmonically useful" (divisible by small classes,
    // i.e. common future item sizes) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        // Class 1: residual exactly matching a "nice" fraction of capacity
        if pr == bin_capacity / 2 { harmony += 14.0; }
        if pr == bin_capacity / 3 { harmony += 11.0; }
        if pr == bin_capacity / 4 { harmony += 9.0; }
        // Class 2: small dead-space classes (<=10) are near-useless
        if pr <= 10 { harmony -= 18.0; }
        // Class 3: integer-division thresholds on post_residual
        let class = pr / 10; // harmonic bucket of width 10
        match class {
            0 => harmony -= 12.0,
            1 => harmony += 6.0,   // 10..19: fits small items
            2 => harmony += 10.0,  // 20..29
            3 => harmony += 12.0,  // 30..39
            4 => harmony += 13.0,  // 40..49
            5 => harmony += 11.0,
            6 => harmony += 9.0,
            7 => harmony += 7.0,
            _ => harmony += 4.0,
        }
        // Modulo bonus: residuals divisible by 10 are "aligned" slots
        if pr % 10 == 0 { harmony += 3.0; }
        if pr % 20 == 0 { harmony += 2.0; }
        if pr % 25 == 0 { harmony += 2.0; }
        score -= harmony;
    }

    // Lookahead coupling: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chained fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer filling bins that are already relatively full (tight packing).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    // Mild penalty for spreading across many open bins when residual is
    // far from mean (avoid fragmenting).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early in the stream, be slightly more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive if current bins are crowded.
        score -= 5.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
        // But penalize opening a new bin when a tight fit exists elsewhere.
        if post_residual == 0 { score -= 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
