    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits proportionally to how full the bin becomes.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 25.0;
    }

    // Penalize post_residual that cannot host the lookahead item while an
    // empty-ish alternative exists — wasted potential.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward residuals that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // else (large residual gap or the item is big relative to mean residual).
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = mean_residual - item_size as f64;
