pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score -= 100.0; // perfect fill
    } else if post_residual > 0 && post_residual < item_size.min(80).max(1) {
        score += 0.5 * (post_residual as f64);
    }

    // Lookahead: strongly reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain fill: bin becomes exactly full
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted space
            score += 8.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: opening a new bin wastes mean residual across open bins.
    if bin_residual == bin_capacity {
        let avg_waste = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // Opening new bins is cheap early, expensive late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = open_bins_count as f64 * 2.0;
        score += 20.0 + avg_waste * 0.4 + open_penalty + 30.0 * progress;
        // But if item is large and nothing fits well, a fresh bin is attractive:
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 18.0;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (bin consolidation).
    score -= 0.05 * (bin_residual as f64) * (open_bins_count.min(20) as f64) / 10.0;

    // Mild global pressure: as stream progresses, discourage leaving scattered residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        score -= (item / cap) * 45.0;
        score -= 65.0 * (1.0 - post / cap);
        if post < 20.0 {
            score += 30.0 + 20.0 * (item / cap);
        }
        // Very tight leftover reward (borrowed from best heuristic).
        if post < 5.0 {
            score -= 80.0;
        }
    }

    // Lookahead coupling: favor residuals that fit the next item tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 80.0;
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling.
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if fitting_bins_count > 0 && post >= item * 0.5 {
            score += 40.0;
        }
        // Penalize opening a new bin for large items when open bins exist.
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        // Extra pressure late in the stream: prefer consolidating into open bins.
        score += 60.0 * progress * (fitting_bins_count as f64).min(3.0);
    }

    // Mean-residual balancing.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 12.0 * (1.0 - post / cap);

    // Waste-rate coupling: dead space that cannot be reclaimed.
    if next_item_size > 0 && next_item_size > post_residual && !is_new_bin && post_residual > 0 {
        score += 25.0 * (1.0 - post / cap) * (0.5 + 0.5 * progress);
    }

    // Two-item lookahead: if this bin's residual minus item fits the next item exactly, reward hard.
    if next_item_size > 0 && post_residual >= item_size && (post_residual - item_size) == next_item_size {
        score -= 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
