    // New-bin candidate: bias by mean residual of open bins and progress
    if bin_residual == bin_capacity {
        score += 10.0 + 12.0 * (1.0 - progress) + 0.05 * mean_residual;
        if open_bins_count == 0 { score -= 25.0; }
        // discourage new bin if a decent fit exists elsewhere
        if fitting_bins_count > 0 && pr < cap * 0.25 {
