        nb -= 120.0 * norm_it;
        nb += 1.0 * mean_residual;
        nb += 200.0 * progress;
        if post_residual >= 56 {
            nb -= 12.0;
        }
        if post_residual >= 85 {
            nb -= 9.0;
        }
        if post_residual >= 96 {
            nb -= 6.0;
        }
