        }
        // aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            nb += 6.0;
        }
        // any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            nb += 60.0;
        }
        // small item into a fresh bin wastes capacity unless stream is early
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            nb += 12.0;
        }
        // scale new-bin base with fitting count and mean slack
        nb += 80.0 * progress * (mean_residual / cap);
        // consolidate open slack late in the stream
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        nb += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // MUTATION: penalize new-bin opening when item leaves large dead space and open bins exist
        if it > 0.5 * cap && open_bins_count > 2 {
            nb += 120.0 * (norm_it - 0.5);
        }
        // MUTATION: reward near-perfect fills in open bins harder (blocks new bin)
        if pr > 0.0 && pr < 5.0 && fitting_bins_count > 0 {
            nb += 80.0;
        }
        // MUTATION: if next item is large and aggregate slack cannot hold it, opening a
        // fresh bin now is fine; otherwise push reuse even harder
        if next_item_size > 0 && open_bins_count > 1 {
            let total_slack = mean_residual * open_bins_count as f64;
            if total_slack < next_item_size as f64 * 1.2 {
                nb -= 15.0;
            } else {
                nb += 12.0;
            }
        }
        score = nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable" classes
    // (large enough to hold common small items) get rewarded.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class A: residual in [1..=5] -> dead space, strong penalty (waste).
    if post_residual <= 5 {
        score += 25.0;
    }
    // Class B: residual in [6..=10] -> marginal, mild penalty.
    else if post_residual <= 10 {
        score += 6.0;
    }
    // Class C: residual exactly divisible by 10 -> harmonically clean, reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    // Class D: residual divisible by next_item_size (when known) -> next item fits exactly.
    if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Class E: residual can hold the lookahead item -> reward proportional to fit quality.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Lookahead cannot follow into this bin: penalize more if lookahead is small
        // (small stranded items are common and easy to pack elsewhere).
        score += 2.0 + (next_item_size as f64 / cap) * 4.0;
    }

    // Integer-division threshold on post_residual quartile: favor leaving half-capacity
    // or quarter-capacity residuals (harmonic fractions of C).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == half || post_residual == quarter {
        score -= 5.0;
    }

    // Tight fit reward: item fills most of the bin.
    if frac < 0.05 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New empty bin candidate: penalize mildly so it is chosen only when
    // open bins offer genuinely bad fits, and more so early in the stream
    // when accumulating bins is costly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 14.0 - 6.0 * progress;
        // Opening a new bin is more attractive if the item is large relative to capacity
        score -= (item_size as f64 / cap) * 6.0;
    }

    // Contextual: many open bins with high mean residual -> prefer consolidating
    // into bins below the mean residual (denser bins).
    if open_bins_count > 2 && (post_residual as f64) < mean_residual {
        score -= 1.5;
    } else if open_bins_count > 2 && (post_residual as f64) > mean_residual * 1.3 {
        score += 1.5;
    }

    score
}

