            score -= 16.0;
        }
        if next_item_size > 0 && open_bins_count > 1 && mean_residual >= next_item_size as f64 {
            score += 10.0;
        }
        if progress < 0.5 && open_bins_count > 8 {
            score += 7.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual && open_bins_count > 1 && progress < 0.7 {
            score -= 8.0;
        }
        if fitting_bins_count > 0 && mean_residual > cap * 0.45 {
            score -= 6.0;
        }
        // aggregate-space pressure: if total open slack is large, prefer reusing bins
        if open_bins_count > 1 {
            let aggregate = mean_residual * open_bins_count as f64;
            if aggregate > cap * 1.2 && progress < 0.8 {
                score += 9.0;
            }
        }
        if next_item_size >= 50 && next_item_size as f64 > mean_residual * 1.5 && open_bins_count > 1 {
            score -= 6.0;
        }
        if progress > 0.55 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 5.0;
        }
        // MUTATION: snug current fit strongly blocks new-bin opening
        if fitting_bins_count > 0 && progress < 0.8 {
            let snug_fit = (post_residual as f64 - it) / cap;
            if snug_fit <= 0.12 {
                score += 20.0;
            }
            if snug_fit > 0.12 && snug_fit <= 0.30 && open_bins_count > 2 {
                score += 9.0 * (1.0 - snug_fit / 0.30);
            }
        }
        // MUTATION: aggregate slack sufficient for next item -> avoid opening a new bin
        if open_bins_count > 1 && next_item_size > 0
            && mean_residual * open_bins_count as f64 > next_item_size as f64 * 2.0 {
            score += 6.0;
        }
        // MUTATION: any open bin can hold the item exactly -> never open a new bin
        if fitting_bins_count > 0 && post_residual == 0 {
            score += 60.0;
        }
        // MUTATION: small item into a fresh bin wastes capacity unless stream is early
        if it < 25.0 && open_bins_count > 1 && mean_residual >= it {
            score += 12.0;
        }
        // MUTATION (from best heuristic): large item into a fresh bin with open bins
        // leaves big dead space — penalize harder
        if it > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((it / cap) - 0.5);
        }
        // MUTATION: extra weight on open-bin count to consolidate packing
        if fitting_bins_count > 0 {
            score += 40.0 * (open_bins_count as f64).min(8.0) / 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward leaving a gap that can still accommodate typical future items.
    if post_residual >= 10 && post_residual <= 50 {
        score -= 12.0;
    }

    // Tight fit reward relative to bin size.
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    // Open bins pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mean residual coupling: prefer bins far below mean residual (fill emptier bins first).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        // Post-residual too small for next item: penalize dead space.
        score += 15.0;
    }

    // New-bin candidate handling: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with stream progression.
        score = bin_capacity as f64 * 0.6 + (step_index as f64 / total_items.max(1) as f64) * 20.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
