pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;

    // 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills post residual is best
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving medium dead space
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 8.0 * (dead / next_item_size as f64);
            }
        }
    }

    // Compare post residual against mean residual: prefer bins that keep residuals near/below mean
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when a decent fit exists, especially early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_item = (bin_capacity as f64) / 2.0;
        let waste = bin_capacity as f64 - item_size as f64;
        let poor_fit_elsewhere = fitting_bins_count > 0
            && mean_residual >= item_size as f64 + avg_item * 0.25;
        score += 30.0 + 20.0 * (1.0 - progress);
        if poor_fit_elsewhere {
            score += 25.0;
        }
        if waste as f64 > mean_residual {
            score += 10.0;
        }
    }

    // Slight preference for fuller bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Penalize small post-residuals only if the leftover is too small to be
    // useful for typical future items (dead space), but reward near-exact fits.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score += 25.0 * dead;
    } else {
        score -= 60.0; // perfect fit bonus
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly
    // (large dead space would result) or many bins are already open.
    if bin_residual == bin_capacity {
        let best_alt_dead = if fitting_bins_count > 0 {
            (bin_capacity.saturating_sub(item_size + (bin_capacity - mean_residual as u32).min(bin_capacity))) as f64
