            bin_capacity as f64
        };
        // Cost of opening a new bin decreases as stream progresses (horizon effect).
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        let open_cost = 45.0 * (1.0 - 0.5 * horizon);
        score += open_cost;
        // If existing bins would leave large dead space, discount the new bin.
        score -= 0.4 * best_alt_dead;
        // Encourage consolidation when few bins open.
        score += 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty for deviating from mean residual: prefer balanced bins.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Tie-break toward bins with more residual when late in the stream
    // (keep flexibility as stream ends approach).
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score -= horizon * 0.1 * bin_residual as f64;

    score
}

