    // dead-space penalty: tiny unusable leftover relative to smallest possible item
    let dead = (norm_pr - (1.0 / 100.0)).max(0.0);
    score -= 30.0 * (-dead * 60.0).exp() * (0.5 + progress);

    // last-chance bonus: if this is the only fitting bin, strongly favor using it
