pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // residue classes (multiples of common item sizes) are more valuable.
    let pr = post_residual;
    if pr > 0 {
        // Perfect fit reward
        if pr == 0 {
            score -= 1000.0;
        }
        // Reward residuals that are multiples of 10 or common sizes (harmonic classes)
        if pr % 10 == 0 {
            score -= 25.0;
        }
        if pr % 20 == 0 {
            score -= 15.0;
        }
        if pr % 25 == 0 {
            score -= 10.0;
        }
        // Penalize small dead-space classes (1..10 residual is nearly unusable)
        if pr < 10 {
            score += 60.0;
        } else if pr < 20 {
            score += 20.0;
        }
        // Integer-division threshold: residual >= half capacity is flexible
        if pr >= bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Exact fill is ideal
        score -= 1000.0;
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: strong reward, scaled by how snug the fit is
            let slack = (pr - next_item_size) as f64;
            score -= 40.0;
            if slack < 10.0 {
                score -= 30.0; // near-perfect chain
            }
            if (pr - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize more if this was the only fitting bin
            score += 15.0;
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin if mean residual is fragmented or few bins open
        let fragmented = mean_residual < (bin_capacity as f64) * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 20.0 + 30.0 * progress;
        } else {
            score += 40.0;
        }
        // Large items benefit from a fresh bin
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / bin_capacity as f64) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (items are >= 1, but small gaps < ~15 are
    // nearly unusable) are heavily penalized.
    let dead_threshold = 15.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = post_residual as f64 / item_size as f64;
        score += 20.0 * tightness;
    }

    // Perfect fit bonus: zero leftover is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new empty bin is more acceptable.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += 0.8 * bin_pressure;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly, more so late in the stream
        // or when many bins are already open.
        score += 25.0 + 2.0 * open_bins_count as f64 + 10.0 * progress;
        // But if the item is large and mean residual across bins is small,
        // a fresh bin is attractive.
        if (mean_residual < item_size as f64) && item_size >= 50 {
            score -= 45.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement strongly (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if (gap as f64) < dead_threshold {
            score -= 15.0;
        }
    }

    // Mild penalty for leaving residual far from mean residual
    // (fragmentation of residual distribution).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residual classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let diff = (post - next_item_size as f64).abs();
            score -= 700.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 25.0;
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 120.0;
            score += 1.0 * mean_residual;
            score += 150.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
        }
        // Large items leaving big dead space: prefer open bins when many exist
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
