    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = if (post_residual as i64 - next_item_size as i64).abs() as f64 {
            (post_residual as i64 - next_item_size as i64).abs() as f64
        } else { 0.0 };
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as u32 >= next_item_size {
            // Next item fits after this placement: reward tight coupling.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            // Perfect chain (post_residual == next_item_size) strongly favored.
            if gap < 0.5 { score -= 15.0; }
        } else {
            // Next item would not fit here: penalize proportionally to wasted potential.
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
        // Extra bonus when the chain continues: post_residual >= item+next combined match.
        if post_residual as u32 >= next_item_size && gap <= 10.0 {
            score -= 4.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 5.0;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter (smaller residual) than mean
    // when they fit, penalize bins far above mean (fragmentation risk).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 0.10 * (mean_residual - resid_f);
    } else {
        score += 0.05 * (resid_f - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make it unattractive unless post_residual would be very large
    // (i.e., current open bins would leave terrible dead space).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow opening a new bin late in the stream if open bins are nearly full anyway.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 35.0 * progress;
        }
    }

    // Slight preference for high fill ratio overall.
    score += 0.02 * (bin_capacity as f64 - resid_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly; small residuals are fine.
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.35) * 0.05;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Tightness: how well the item fills the bin relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: reward if the next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Penalize creating residuals that just barely miss the next item
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += gap * 1.2;
            }
        }
    } else {
        // Last item in stream: finishing cleanly matters more.
        score -= 10.0;
    }

    // Global state: many open bins with low mean residual -> consolidate.
    if open_bins_count > 2 {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += consolidation * 0.15;
        score -= open_bins_count as f64 * 0.8;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 12.0;

    // New-bin candidate: only attractive when current bins are crowded
    // or the item is huge and nothing fits well.
    if bin_residual == bin_capacity {
        let crowd_factor = if open_bins_count == 0 { 0.0 } else {
            (mean_residual / bin_capacity as f64).powi(2)
        };
        // New bin is good when open bins are nearly full on average.
        score -= crowd_factor * 40.0;
        // New bin is bad when plenty of room exists elsewhere.
        score += (open_bins_count as f64) * 1.5;
        // Late in stream, avoid opening bins wastefully.
        score += progress * 15.0;
        // Huge items: new bin is natural.
        if item_size > 70 {
            score -= 10.0;
        }
    }

    score
}

