        // prefer new bin if mean residual across open bins is already fragmented
        score += (mean_residual / cap) * 10.0;
    }

    // Mild preference for bins with residuals near the current item (smooth)
    let diff = (bin_residual as f64 - item) / cap;
    score += 5.0 * diff * diff;

    score
}

