pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that are "nice" multiples
    // of small divisors are more likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Reward residuals that fall into friendly harmonic classes (divisible by 10, 20, 25, 50)
    if pr == 0 {
        score -= 60.0; // perfect fill, best possible outcome
    } else {
        if pr % 50 == 0 { score -= 22.0; }
        else if pr % 25 == 0 { score -= 14.0; }
        else if pr % 20 == 0 { score -= 12.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        else { score += 6.0; } // awkward residual class
    }

    // Penalize small-but-not-zero dead space (unusable slivers)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead: does the next item fit in the post residual?
    if next_item_size > 0 && next_item_size <= pr {
        // exact match is golden
        if next_item_size == pr {
            score -= 55.0;
        } else {
            let n = next_item_size as f64;
            // reward proportional to how well next item consumes the residual
            score -= 18.0 * (n / (pr as f64)).min(1.0);
            // harmonic bonus if post residual after next item stays in a good class
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 6.0; }
        }
    } else if next_item_size > pr {
        // next item cannot use this bin: penalize proportionally
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Fraction-of-capacity coupling: bins with residual near half capacity are flexible
    let frac = post_residual as f64 / cap;
    score -= 10.0 * (1.0 - (2.0 * frac - 1.0).abs());

    // Prefer tighter bins overall (compare against mean residual of open bins)
    score += 0.05 * (mean_residual - post_residual as f64);

    // When many bins are open, be pickier about which one to use; early on be greedy
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // New-bin candidate: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, softened when stream is early or crowded
        score = cap * 0.75 + 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if post_residual as f64 > mean_residual + 20.0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 { let cap = bin_capacity as f64 ; let post = post_residual as f64 ; let item = item_size as f64 ; let mut score = post ; if post_residual == 0 { score -= 1000.0 ; } if next_item_size > 0 { let nxt = next_item_size as f64 ; if next_item_size <= post_residual { let diff = (post - nxt) . abs () ; score -= 900.0 * (1.0 - diff / cap) ; if diff == 0.0 { score -= 50.0 ; } } else { score += 40.0 * (nxt / cap) ; score += 30.0 * ((post - nxt) / cap) ; } } if bin_residual == bin_capacity { score += 150.0 ; score -= 120.0 * (item / cap) ; score += 1.0 * mean_residual ; let progress = step_index as f64 / total_items . max (1) as f64 ; score += 200.0 * progress ; if fitting_bins_count == 0 { score -= 2000.0 ; } else { score += 60.0 * (fitting_bins_count as f64) . min (5.0) ; } score += 80.0 * progress * (mean_residual / cap) ; let open_frac = open_bins_count as f64 / (total_items . max (1) as f64) ; score += 90.0 * progress * (1.0 - open_frac . min (1.0)) ; if item > 0.5 * cap && open_bins_count > 2 { score += 120.0 * ((item / cap) - 0.5) ; } else if post > 0.0 && post < 5.0 { score -= 80.0 ; } // dead-space ratio penalty: discourage opening a bin when item leaves large waste relative to capacity and open bins exist
 let waste_ratio = post / cap ; if open_bins_count > 0 && waste_ratio > 0.25 { score += 250.0 * (waste_ratio - 0.25) ; } // lookahead: if next item cannot fit post-residual, penalize proportionally to leftover gap
