 if bin_residual < bin_capacity { let tight = (bin_residual as f64 - item) / cap ; if tight >= 0.0 && tight < 0.05 { score -= 150.0 * (1.0 - tight / 0.05) ; } } } score }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1..=10) are wasted.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual > 50 {
        // Large leftover is fine only if next item can use it; otherwise mild penalty.
        if next_item_size > post_residual {
            score += 0.25 * (post_residual as f64 - 50.0);
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Next-item lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 0.3 * next_item_size as f64;
    }

    // Last-chance bin: prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: prefer bins with residual below mean (consolidation).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New empty bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Penalize mildly so it's chosen only when open bins score poorly,
        // but relieve pressure as stream progresses.
        score += 15.0 - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 20.0; // reserve fresh bin for large upcoming items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic residue classes: usable residuals are worth more
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 25.0;
        }
        if post_residual % 20 == 0 {
            score -= 15.0;
        }
        if post_residual % 25 == 0 {
            score -= 10.0;
        }
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 20.0;
        }
        if post_residual >= bin_capacity / 2 {
            score -= 10.0;
        }
        // tiny leftover dead space is very valuable
        if post_residual < 5 {
            score -= 80.0;
        }
    }

    // Lookahead: does next item chain into the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            // strong reward scaled by snugness of the chain
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // penalize opening a new bin for large items when open bins exist
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        // fragmented mean residual makes fresh bins more attractive
        if mean_residual < cap * 0.3 || open_bins_count == 0 {
            score -= 20.0 + 30.0 * progress;
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / cap) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            score -= 200.0 + (post_residual - next_item_size) as f64;
        } else {
            // next item does not fit; penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // last item: prefer minimal post residual
        score += 0.0;
    }

    // Compare post residual relative to mean residual: keep bins balanced
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless current open bins have poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // open new bin if lookahead would chain nicely into fresh capacity
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 60.0;
        }
    }

    // Slight preference for tighter bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / bin_capacity as f64) * (50.0 * (1.0 - progress));

