}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty scaled by capacity.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize creating dead space too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if we leave a big awkward gap.
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    let open_f = open_bins_count as f64;
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 2.5 * residual_gap / bin_capacity as f64 * (open_f / (open_f + 5.0));

    // Early in stream: be more exploratory, favor spreading into new bins;
    // late in stream: consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept early or when it's the only option / very poor fits elsewhere.
        let new_bin_bonus = 15.0 * (1.0 - progress) + (open_f * 0.4);
        score -= new_bin_bonus;
        // Never open a new bin for a tiny item if it fits comfortably elsewhere.
        if item_size <= 30 && fitting_bins_count > 0 {
            score += 40.0;
        }
    } else {
        score -= 6.0 * progress;
    }

    // Mild preference for bins whose residual is close to item (best-fit flavor).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fit_ratio * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
