    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear coupling: residual cost grows superlinearly with stream progress
    score += 6.0 * norm_pr * norm_pr * (0.5 + p);

    // Cubic interaction of progress with post residual
    score += 4.0 * p * p * p * norm_pr;

    // Favor tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.3 + 0.7 * p);

    // Last-chance bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 + p);
    }

    // Penalize bins far from mean residual (fragmentation signal)
    let dev = pr - mean_residual;
    score += 0.03 * dev * dev / cap;

    // Lookahead: reward residual that could fit next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 3.0 * (1.0 - (pr - n) / cap) * (0.5 + p);
        } else {
            score += 2.0 * (n - pr) / cap * (1.0 - p);
        }
    }

    // Mild penalty on too many open bins, scaled by progress
    score += 0.05 * open_bins_count as f64 * p;

    // New-bin candidate: penalize slightly unless current bin fit is bad
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * tightness * (1.0 - p);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual modulo capacity quarters:
    // residuals near 0 are excellent (tight fit); residuals in the "dead zone"
    // (just above half) are poor because few future items can use them.
    let q = post_residual % (bin_capacity / 4).max(1);
    let quarter = (post_residual / (bin_capacity / 4).max(1)) % 4;
    match quarter {
        0 => score -= 12.0,                      // nearly full bin: great
        1 => score += 3.0,                       // small usable sliver: risky
        2 => score += 10.0,                      // dead zone around half
        _ => score -= 2.0,                       // large residual, still flexible
    }
    // Fine-grained penalty for awkward slivers
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly or well,
    // reward strongly; if it cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= (10.0 - waste.min(10) as f64) * 0.8;
        } else {
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score = 100.0 - 60.0 * tightness;
        if post_residual % 2 == 0 { score += 1.0; } // tie-break noise via parity
    }

    // Slight preference to fill earlier bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

