pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible item
    // (1..=10) are worthless; anything <= 20 is nearly unusable dead space.
    let r = post_residual as f64;
    if r > 0.0 && r <= 10.0 {
        // Perfectly wasted space — heavy penalty.
        score += 40.0 * (1.0 - r / 10.0);
    } else if r > 10.0 && r <= 25.0 {
        // Awkward gap zone: nonlinear penalty peaking just above usable threshold.
        score += 15.0 * (1.0 - (r - 10.0) / 15.0);
    } else if r == 0.0 {
        // Perfect closure of the bin: reward strongly.
        score -= 30.0;
    } else {
        // Larger residual: mild reward for keeping usable space.
        score -= 3.0 * ((r - 25.0) / (bin_capacity as f64 - 25.0));
    }

    // Tight-fit reward: fraction of the bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins; encourage filling
    // existing bins when several are open, but ease pressure when few bins exist.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 2.5 * pressure * (1.0 - fill_ratio);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward; if next item cannot fit, this residual is truly dead.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Mean-residual alignment: prefer bins whose post-residual stays near the mean,
    // keeping the fleet of open bins homogeneous and packable.
    score += 0.15 * (r - mean_residual).abs();

    // Stream progression: late in the stream, be more conservative — penalize
    // leaving medium gaps since fewer items remain to fill them.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (r > 0.0 && r < 25.0) as i32 as f64;

    // New-bin candidate: an empty bin has residual == capacity; make it unattractive
    // unless the item is huge or no reasonable fit exists (handled by penalties above).
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * pressure;
        if fitting_bins_count <= 1 {
            // No other option: new bin must be competitive.
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
