        score += 10.0;
    }

    // Relative-to-mean coupling: prefer bins that are tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 120.0 - (item_size as f64 * 0.2);
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight progression bias: as stream advances, tighten packing further.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual is the primary term already).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that is hard to reuse (post_residual > 0 but tiny).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Dead space that exactly matches the next item is valuable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 4.0; // can still host next item
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5; // wasted vs lookahead
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the fit is bad elsewhere
    // or bins are crowded; otherwise penalize opening a new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 - 15.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        if fit_ratio >= 0.5 {
            score -= 20.0; // large item: fresh bin is fine
        }
    }

    // Prefer bins with below-average residual (consolidate emptier bins usage).
    if bin_residual < bin_capacity {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Mild preference to fill bins with more items already (fewer open bins).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        // Fine-grained residual fitting: reward proportional fill.
        score -= (item / cap) * 45.0;
        score -= 65.0 * (1.0 - post / cap);
        // Dead-space penalty scaled by item size.
        if post < 20.0 {
            score += 30.0 + 20.0 * (item / cap);
        }
    }

    // Lookahead coupling: favor residuals that fit the next item tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 80.0;
            }
            // Two-step chain: if residual after placing next item becomes tiny, bonus.
            let chain = post - nxt;
            if chain > 0.0 && chain < 5.0 {
                score -= 40.0 * (1.0 - progress);
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling.
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // Discourage opening new bins when the item fits reasonably well elsewhere.
        if fitting_bins_count > 0 && post >= item * 0.5 {
            score += 40.0;
        }
        // Borrowed refinement: large items into new bins when open bins exist are wasteful.
        if item > 0.5 * cap && open_bins_count > 2 && fitting_bins_count > 0 {
            score += 120.0 * ((item / cap) - 0.5);
        }
    }

    // Mean-residual balancing: pull scores toward bins closer to the mean residual.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 12.0 * (1.0 - post / cap);

    // Waste-rate coupling: penalize unreclaimable dead space, stronger late.
    if next_item_size > 0 && next_item_size > post_residual && !is_new_bin && post_residual > 0 {
        score += 25.0 * (1.0 - post / cap) * (0.5 + 0.5 * progress);
        // Extra penalty when dead space exceeds next item by a lot (wasted capacity).
        let waste = post - next_item_size as f64;
        if waste > 0.0 {
            score += 15.0 * (waste / cap) * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

