    let early = (1.0 - progress).max(0.0);
    score -= 8.0 * early * norm_pr * (1.0 - norm_pr);

    // Late stream: penalize leaving dead space quadratically
    score += 10.0 * progress * norm_pr * norm_pr;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Tight-fit reward via smooth gaussian-like coupling
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tightness = (-8.0 * (fit_ratio - 1.0) * (fit_ratio - 1.0)).exp();
    score -= 6.0 * tightness;

    // Lookahead: reward residual matching next item
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (pr - next) / cap;
        score -= 5.0 * (-20.0 * diff * diff).exp();
        // Penalize residual too small for next item
        if pr < next {
            score += 0.05 * (next - pr);
        }
    }

    // Discourage spreading across many open bins when mean residual is high
    score += 0.02 * open_bins_count as f64 * norm_pr;

    // Mild tie-break toward bins below mean residual (consolidation)
    score += 0.3 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
