            }
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 20.0 + 30.0 * progress;
        } else {
            score += 150.0;
            score += 200.0 * progress;
            score += 80.0 * progress * (mean_residual / cap);
        }
        // Penalize new-bin opening when item leaves large dead space and open bins exist
        if item > 0.5 * cap && open_bins_count > 2 {
