    // for common item sizes (multiples of 10, 20, 25).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit is best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo-10 harmonic class: residuals divisible by 10 are ideal slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Modulo-25 harmonic class.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Integer-division thresholds: how many average-sized items still fit.
    let avg_next = if next_item_size > 0 { next_item_size as f64 } else { 25.0 };
    let slots = (pr / avg_next.max(1.0)).floor();
    score -= slots * 6.0;

