    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin waste is large.
    if bin_residual == bin_capacity {
        score += cap * 0.35;
        if post_residual as f64 > cap * 0.5 {
            score -= 20.0; // item is small relative to bin; fresh bin acceptable
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for wasting capacity.
        score += pr * 0.05;
    }

    // Progress scaling: later in stream, tighten up (prefer compacting).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.02 * progress;

