        }
    }

    // Open-bin pressure: discourage opening new bins when few bins are open;
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaling with open bins.
        score += 15.0 + pressure * 2.0;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= pressure * 1.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 60.0;
        } else {
            score -= 25.0 * (1.0 - slack / 100.0);
        }
    }

    // Prefer bins with residual below mean (compact small bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual preferred.
    let fit_tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * fit_tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; penalize dead space left behind
            let dead = next_item_size - post_residual;
            score += (dead as f64).min(40.0) * 0.5;
        }
    }

    // Compare against mean residual: bins tighter than average are better choices.
    let rel = (post_residual as f64) - mean_residual;
    score += 0.25 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (open_bins_count as f64);
        // but if next item pairs perfectly with a fresh full bin, soften
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= (item_size as i64) {
            score -= 10.0;
        }
    }

    // Late in stream: prefer compacting into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

