pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Best-fit core: strong reward for tight fits.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize dead space relative to capacity, non-linearly.
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        score += frac * frac * 30.0;
    } else {
        score -= 10.0; // perfect fill bonus
    }

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving residue that next item cannot use
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.4;
    }

    // Last-chance bin: strong preference to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless
    // the current bin's residual would be wasteful.
    if bin_residual == bin_capacity {
        // fresh bin: only attractive when item is large relative to capacity
        let waste = (bin_capacity - item_size) as f64;
        score += waste * 0.5;
        score -= item_size as f64 * 0.3;
        // early in stream, opening bins is fine
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - t) * 10.0;
    } else {
        // using an existing bin is generally good
        score -= 5.0;
    }

    // Global state: many open bins with high mean residual -> prefer
    // consolidating into existing bins rather than opening new ones.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        if bin_residual != bin_capacity {
            score -= pressure * 6.0;
        }
    }

    // Prefer bins whose residual is close to item_size (tight fit again).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += gap * gap * 40.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, penalize waste more strongly
    let progress_coupling = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_coupling;

    // Non-linear penalty for post_residual that is unusable relative to the smallest plausible item
    // Reward post_residual that could still fit the lookahead item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (1.0 - (n / cap)) * (pr / cap).sqrt();
        } else {
            // dead space relative to lookahead item: quadratic penalty
            let gap = (n - pr) / cap;
            score += 25.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation early)
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good "filler" target
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev - 2.0 * dev;

    // Reward high fill ratio smoothly
    score -= 5.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
