pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // residue class (multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Modulo-class reward: leftover divisible by 10 (or 25/50) is reusable.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }
    if post_residual % 50 == 0 {
        score -= 4.0;
    }

    // Integer-division thresholds on post_residual: dead-space bands.
    let band = post_residual / 10; // 0..=10
    match band {
        0 => score += 20.0,             // near-perfect fill
        1 | 2 => score -= 8.0,          // small but classically reusable gaps
        3 | 4 => score += 3.0,          // awkward dead zone
        5 | 6 => score -= 2.0,          // half-bin: very reusable
        _ => {}                          // large leftover: neutral
    }

    // Capacity-fraction coupling: reward when item fills an exact fraction.
    let fill = item_size as f64 / cap;
    if (fill * 4.0).fract() < 1e-9 {
        score -= 3.0; // quarter-fills
    }
    if (fill * 3.0).fract() < 1e-9 {
        score -= 3.0; // third-fills
    }

    // Lookahead harmonic match: post_residual divisible by next item size class.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % next_item_size == 0 {
            score -= 10.0; // next item could exactly consume leftover
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 6.0; // next item leaves near-zero waste
        } else if next_item_size > post_residual {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: score it against mean residual of open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; attractive only if open bins are tight
        // or the item fits nothing well.
        score = cap * 0.9 - mean_residual * 0.5 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits: new bin is necessary
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score += 5.0; // prefer reusing bins when lookahead could also fit
        }
    }

    // Late-stream consolidation: favor tightening existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (post_residual near zero but still usable).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: prefer reusing bins when many are open,
    // but ease pressure when this bin is the last chance.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current
    // placement would create large dead space or no bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if post_residual > 30 {
            score -= 10.0;
        }
    }

    // Slight stream-progression nudge toward consolidation late in stream.
    score += (step_index as f64 / total_items.max(1) as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        // Fine-grained residual fitting: reward proportional fill.
        score -= (item / cap) * 55.0;
        score -= 70.0 * (1.0 - post / cap);
        // Dead-space penalty scaled by item size.
        if post < 20.0 {
            score += 30.0 + 20.0 * (item / cap);
        }
    }

    // Lookahead coupling: favor residuals that fit the next item tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 90.0;
            }
            // Two-step chain: if residual after placing next item becomes tiny, bonus.
            let chain = post - nxt;
            if chain > 0.0 && chain < 6.0 {
                score -= 50.0 * (1.0 - progress);
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 70.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling.
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // Discourage opening new bins when the item fits reasonably well elsewhere.
        if fitting_bins_count > 0 && post >= item * 0.5 {
            score += 55.0;
        }
        // Large items into new bins when open bins exist are wasteful.
        if item > 0.5 * cap && open_bins_count > 2 && fitting_bins_count > 0 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        // Extra: never open a bin when a near-perfect fit exists elsewhere.
        if fitting_bins_count > 0 && post_residual < 8 {
            score += 200.0;
        }
    }

    // Mean-residual balancing: pull scores toward bins closer to the mean residual.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 15.0 * (1.0 - post / cap);

    // Waste-rate coupling: penalize unreclaimable dead space, stronger late.
    if next_item_size > 0 && next_item_size > post_residual && !is_new_bin && post_residual > 0 {
        score += 25.0 * (1.0 - post / cap) * (0.5 + 0.5 * progress);
        let waste = post - next_item_size as f64;
        if waste > 0.0 {
            score += 18.0 * (waste / cap) * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero waste is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the leftover exactly matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff == 0.0 {
            score -= 500.0; // exact 2-chain match
        } else if pr >= nxt {
            // next item still fits here: reward closeness, penalize large slack
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize small dead space that wastes capacity
            score += 50.0 * (1.0 - pr / bin_capacity as f64);
        }
    }

    // Prefer tight fits relative to mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Early in the stream, be slightly more willing to open bins (spread risk).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when open bins are crowded.
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        score -= 80.0 * (1.0 - progress) * (1.0 - crowd);
        score += 120.0 * progress; // later, prefer filling existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Near-perfect fills rewarded strongly
    if post_residual > 0 && post_residual < 5 {
        score -= 80.0;
    }

    // Harmonic residual classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual >= 5 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 150.0;
            score -= 120.0 * (item / cap);
            score += 1.0 * mean_residual;
            score += 200.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            score += 80.0 * progress * (mean_residual / cap);
            let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
            score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        }
        // Large items leaving big dead space: prefer open bins when many exist
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size (1) is worthless; penalize moderate waste.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste * waste;

    // Lookahead: if the next item fits into the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Extra reward when the next item fills the bin almost exactly.
        let combo_gap = post_residual - next_item_size;
        score -= 4.0 * (1.0 - combo_gap as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: penalize small dead space.
        score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

