    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score -= 0.05 * diff;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large post_residual everywhere) or late in stream
    // with many open bins. Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count == 0) as i32 as f64;
        let poor_fits = (mean_residual - item_size as f64).max(0.0);
