pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose residual falls into
    // "usable" classes (multiples of common item sizes / large chunks) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = (bin_residual as f64 - post) / cap;
