        score -= 6.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Integer-division threshold classes on post_residual (bands of 25).
    let band = post_residual / 25;
    score += band as f64 * 7.0;

