                score -= 40.0;
            } else if post_residual % next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled by waste.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins are congested
    // or the fit would create large dead space.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap);
        let poor_fit = (post_residual as f64 / cap) > 0.5;
        if poor_fit && congestion > 0.5 {
            score -= 55.0;
        } else {
            score += 60.0; // prefer existing bins by default
