    }

    // Slight preference to consolidate into bins below mean residual
    // (keeps one tight bin and several loose ones rather than spreading).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    // Stream progression: later in the stream, favor closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
