    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 4.0;
    } else {
        score -= (open_bins_count as f64) * 1.5;
    }

    // Lookahead: favor bins whose leftover could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins tighter than the average residual.
