}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            // Perfect chain: item fits now, next item fills bin exactly.
            score -= 60.0;
        } else if gap <= 10.0 {
            score -= 30.0 - gap * 2.0;
        } else {
            // Penalize large leftover relative to next item (dead space risk).
            score += gap * 0.35;
        }
        // Bonus if next item also fits into this bin's residual after that placement.
        if next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Tight fit reward: small post_residual is good, but avoid useless slivers (<5).
    if post_residual > 0 && post_residual < 5 {
        score += 25.0; // sliver = dead space
    }

    // Relative-to-mean coupling: prefer bins tighter (less residual) than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits to avoid new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if lookahead suggests a fresh bin chains well, soften penalty.
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 5 {
            score -= 50.0;
        }
    }

    // Late-stream: consolidate, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that few future items can use (post_residual < 10 is perfect).
    if post_residual > 0 {
        let dead = post_residual as f64;
        let usable = if next_item_size > 0 && next_item_size <= post_residual { 0.6 } else { 1.0 };
        score += 8.0 * (dead / cap).powf(1.5) * usable;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: mildly discourage opening new bins early, allow it late
    // or when mean residual is low (existing bins are nearly full).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * progress;
        score += 0.05 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // fresh bin pairs well with a large next item
        }
    }

    // Prefer reusing bins with residual close to mean (keeps bin sizes balanced).
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
    }

    // Late in the stream, consolidate aggressively into fuller bins.
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress:
    // low progress => mild penalty on wasted space, high progress => strong penalty
