    let waste_coupling = pr * pr / (bin_capacity as f64 * (1.0 + 3.0 * progress));
    score += 0.5 * waste_coupling;

    // Reward tight fits (small post_residual) more strongly as stream advances
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: if next item can use the post-residual, reward this bin;
    // if post-residual is dead space for the next item, penalize smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 5.0 * snug * (0.4 + 0.6 * progress);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 0.08 * gap * gap / (1.0 + nxt);
        }
