    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 150.0;
            score -= 120.0 * (item / cap);
            score += 1.0 * mean_residual;
            score += 200.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            score += 80.0 * progress * (mean_residual / cap);
            let open_frac = (open_bins_count as f64 / total_items.max(1) as f64).min(1.0);
            score += 90.0 * progress * (1.0 - open_frac);
        }
        // Large items leaving big dead space: prefer open bins when many exist
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residuals divisible by common item sizes
    // (e.g. 10, 20, 25, 50) are more likely to be filled by future items.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit, best possible
    } else if pr % 50 == 0 {
        -18.0
    } else if pr % 25 == 0 {
        -12.0
    } else if pr % 20 == 0 {
        -10.0
    } else if pr % 10 == 0 {
        -7.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect chain placement
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            // penalize large leftover slack after next item
            score += (slack as f64) * 0.35;
            // harmonic slack classes are recoverable
            if slack % 10 == 0 || slack % 25 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; residual must survive later
            score += 6.0;
        }
    }

    // Dead-space penalty: tiny unusable residuals (modulo small classes)
    if pr > 0 && pr < 10 {
        score += 30.0;
    } else if pr >= 10 && pr < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        // new bin has full residual 100; base score is 100 already.
        // penalize slightly more if many bins are open and mean residual is healthy
        if mean_residual > 30.0 && open_bins_count > 1 {
            score += 12.0;
        }
        // early in the stream, opening bins is fine (bins will fill over time)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer tighter bins overall: compare residual against mean residual
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Slight pressure to use more-open-bins situation efficiently
    score += (open_bins_count as f64) * 0.3;

    score
}

