    score -= fill_ratio * 12.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // New-bin candidate: only attractive when current bins are crowded
    // or the fit would leave a dead gap.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 2.0 + mean_residual;
        score += pressure;
        if post_residual < 10 {
            score -= 20.0; // fresh bin absorbs item leaving no tiny gap issue... still penalize slightly
