pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly (dead-space minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can host the next item exactly or nearly so.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits after this placement: reward closeness to perfect chain.
            score -= 30.0 * (1.0 - gap / (bin_capacity as f64));
            if gap == 0.0 {
                score -= 25.0; // perfect 2-item chain
            }
        } else {
            // Next item won't fit here afterward: penalize proportional to overflow.
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin unless current item is large and
    // no existing bin can host it well (tight fit elsewhere preferred).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty, waived when the item is big
        // (large items leave little dead space in a fresh bin).
        let big_item_bonus = if item_size >= 60 { 45.0 } else if item_size >= 40 { 15.0 } else { 0.0 };
        score += 50.0 - big_item_bonus;
        // If lookahead item is large too, a fresh bin can chain them.
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 20.0;
        }
    }

    // Slight preference for filling bins early in the stream (keep bins open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never fit a typical future item.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - t);
    }

    // Lookahead: reward bins whose post-residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into fuller bins.
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fullness * (open_bins_count as f64).ln().max(0.0) * 6.0;

    // Deviation from mean residual: prefer bins near the mean to keep balance,
    // but slightly prefer emptier bins early on.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.3 - 0.2 * t);

    // New-bin candidate: only attractive when current item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 45.0 + 30.0 * (1.0 - t) - 50.0 * pressure
              - 20.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit: dominant reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 70.0;
    } else {
        // Fine-grained residual fitting: reward proportional fill.
        score -= (item / cap) * 45.0;
        score -= 65.0 * (1.0 - post / cap);
        // Dead-space penalty scaled by item size.
        if post < 20.0 {
            score += 30.0 + 20.0 * (item / cap);
        }
        // Combined refinement: quadratic dead-space ratio penalty, stronger late.
        let dead = 1.0 - post / cap;
        score += 25.0 * dead * dead * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: favor residuals that fit the next item tightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 80.0;
            }
            // Two-step chain: if residual after placing next item becomes tiny, bonus.
            let chain = post - nxt;
            if chain > 0.0 && chain < 5.0 {
                score -= 40.0 * (1.0 - progress);
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap).max(0.0);
        }
    }

    // Last-chance pressure: only fitting bin should generally be used.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Open-bin consolidation pressure.
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate handling.
    if is_new_bin {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // Discourage opening new bins when the item fits reasonably well elsewhere.
        if fitting_bins_count > 0 && post >= item * 0.5 {
            score += 40.0;
        }
        // Large items into new bins when open bins exist are wasteful.
        if item > 0.5 * cap && open_bins_count > 2 && fitting_bins_count > 0 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        // Refinement: extra penalty when an open bin leaves a near-perfect residual
        // that would host the next item — never open a new bin then.
        if fitting_bins_count > 0 && next_item_size > 0 && post_residual >= next_item_size {
            score += 300.0;
        }
    }

    // Mean-residual balancing: pull scores toward bins closer to the mean residual.
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.05;

    // Late-stream tightening toward perfect packing.
    score -= progress * 12.0 * (1.0 - post / cap);

    // Waste-rate coupling: penalize unreclaimable dead space, stronger late.
    if next_item_size > 0 && next_item_size > post_residual && !is_new_bin && post_residual > 0 {
        score += 25.0 * (1.0 - post / cap) * (0.5 + 0.5 * progress);
        // Extra penalty when dead space exceeds next item by a lot (wasted capacity).
        let waste = post - next_item_size as f64;
        if waste > 0.0 {
            score += 15.0 * (waste / cap) * (0.5 + progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth interaction: dead space penalty grows with stream progress
    let dead = norm_pr * norm_pr * norm_pr;
    score += 60.0 * dead * (0.4 + 0.6 * progress);

    // Lookahead coupling: reward residuals that can still host the next item,
    // smoothly scaled by how close post_residual is to next_item_size
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score -= 25.0 * (-diff * diff * 8.0).exp();
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
    }

    // Mild preference for consolidating into fewer bins / fuller bins
    if open_bins_count > 0 {
        score -= 5.0 * (bin_residual as f64 / cap) * (mean_residual / cap);
    }

    // New-bin candidate: penalize slightly so it only wins when open bins are poor
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress;
    }

    score
}

