pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 (capacity fractions)
    let r = post_residual % 10;
    // Dead-space penalty: small nonzero residuals are nearly useless
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64;
    }

    // Reward exact fits and harmonic post-residual classes that future items can reuse
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0; // likely reusable by small items
    } else if post_residual > 50 {
        score -= 5.0; // large residual stays flexible
    }

    // Integer-division threshold classes on post_residual
    let q = post_residual / 10;
    score -= 2.0 * (q as f64).ln().max(0.0);

    // Coupling with next item: does this bin also fit the lookahead item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Prefer bins where residual is a good match for next item (small leftover again)
            let next_post = post_residual - next_item_size;
            score -= 6.0;
            if next_post % 10 == 0 { score -= 4.0; }
        } else {
            // Next item won't fit here; residual becomes dead space
            score += 6.0;
            if post_residual < next_item_size / 2 { score += 8.0; }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // Mild penalty so a decent fit in an open bin wins
        score += 15.0;
