        // opening fresh is attractive
        if item_size > 60 { score -= 10.0; }
        if open_bins_count as f64 > 3.0 + 2.0 * mean_residual / bin_capacity as f64 {
            score -= 12.0;
        }
        // Late in stream, prefer consolidating into open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Slight penalty for spreading across many bins when this bin is above-average fullness
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for ANY item (1..100)
    // are pure waste -> heavy penalty proportional to how close we came to a perfect fit
    // but still left an unusable sliver.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // worst at post_residual=1
    }

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that the lookahead item could fill (k=2 synergy)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // gap too small for next item: mild penalty, likely dead space
        score += 8.0;
    }

    // Open-bin pressure: prefer reusing existing bins over opening new ones
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it unattractive unless the best available fit is poor.
    // It gets large post_residual, so base score is high already; add pressure that
    // grows with the number of open bins that could still absorb slack.
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if no open bin fits, the new-bin call is the only candidate anyway
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Slight preference for bins with below-average residual (tighter bins absorb
    // large items; loose bins stay flexible for future small ones)
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // Late in the stream, prioritize closing out bins cleanly (tight fits matter more)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

