    // preferred to be filled; bins looser than average should stay flexible.
    let mean_gap = pr - mean_residual;
    score += 0.35 * mean_gap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // (keeps a big, flexible residual) or no reasonable fit exists.
    if bin_residual == bin_capacity {
        // neutral baseline for a fresh bin
        score = item_size as f64 * 0.9 + 5.0;
        // a fresh bin is good if the item is large (large residual left is
        // valuable) or if few bins can fit the item
        if item_size >= 50 {
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
        // penalize opening new bins when many are open with slack
        if mean_residual > item_size as f64 + 20.0 {
            score += 25.0;
        }
    }

    // Penalize creating tiny dead space (< 10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual (lower score = better).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // wasted potential for the known next item
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is expensive; discourage unless
    // current bin would leave large unusable residual or mean residual is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_pressure = (mean_residual - post_residual as f64).max(0.0);
        score += 15.0 + 20.0 * progress - waste_pressure.min(20.0);
        // If the next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // With many open bins and poor fits elsewhere, allow new bin.
        if fitting_bins_count <= 2 {
            score -= 5.0;
        }
    }

    // Slight preference for filling bins among many open bins (reduce fragmentation).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in stream, favor tighter packing more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Penalize large dead space quadratically, scaled by progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) especially when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_pr);
    }

    // Prefer bins below mean residual slightly (balance load)
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Mild new-bin aversion growing with open bins count
    if bin_residual == bin_capacity {
        score += 4.0 + 0.3 * open_bins_count as f64 - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class rewards for usable residual classes
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 25.0; }
        if post_residual % 20 == 0 { score -= 15.0; }
        if post_residual % 25 == 0 { score -= 10.0; }
        if post_residual < 10 { score += 60.0; }
        else if post_residual < 20 { score += 20.0; }
        if post_residual >= bin_capacity / 2 { score -= 10.0; }
    }

    // Strong lookahead coupling: how snugly does the next item chain into this bin?
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post - next_item_size as f64;
        // Near-perfect chain reward dominates everything else
        score -= 900.0 * (1.0 - diff / cap);
        if diff == 0.0 { score -= 50.0; }
        if diff < 10.0 { score -= 30.0; }
        if (post_residual - next_item_size) % 10 == 0 { score -= 10.0; }
    } else if next_item_size > 0 {
        // Next item won't fit here
        score += 40.0 * (next_item_size as f64 / cap);
        if fitting_bins_count == 1 { score += 25.0; }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmented = mean_residual < cap * 0.3;

        // Base new-bin penalty: strongly discourage opening fresh bins
        score += 150.0;

        // Large items leaving big dead space in a fresh bin are wasteful
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * (item / cap - 0.5);
        }

        // But allow new bins when existing residuals are fragmented or none exist
        if fragmented || open_bins_count == 0 {
            score -= 180.0 + 30.0 * progress;
        }

        // Late in the stream, prefer consolidating into open bins even more
        score += 120.0 * progress * (mean_residual / cap);

        // Reward near-perfect fills in open bins harder than a fresh bin
        if post_residual > 0 && post < 5.0 {
            score -= 80.0;
        }

        // Fresh bin for a big item with no competition is acceptable
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_residual as f64 / cap) * 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: small dead space classes are penalized
    // more than proportionally (dead space < 10 is nearly unusable).
    let dead = post_residual as f64;
    if post_residual < 10 {
        score += (10.0 - dead) * 6.0; // unusable sliver penalty
    } else if post_residual <= 20 {
        score += (20.0 - dead) * 1.5;
    }

    // Integer division thresholds on post_residual: reward landing in
    // "reusable" harmonic classes (multiples of common item sizes).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual == half {
        score -= 8.0;
    } else if post_residual == quarter {
        score -= 4.0;
    }

    // Modulo arithmetic on residual vs common size classes (10..80 step 5).
    let mut best_fit = 999u32;
    for k in 1..=16u32 {
        let s = k * 5;
        if s <= post_residual && post_residual - s < best_fit {
            best_fit = post_residual - s;
        }
    }
    if best_fit != 999 {
        score -= (10 - best_fit.min(10)) as f64 * 0.8;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack * 0.2);
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current
    // fit is terrible or stream is early with many items remaining.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight_fit = post_residual == 0;
        if tight_fit {
            score -= 20.0; // fresh bin with perfect first placement
        } else {
            score += 15.0 + 25.0 * (1.0 - progress);
            if fitting_bins_count > 0 {
                score += 10.0; // some open bin can still take it
            }
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (concentrate packing into fuller bins).
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res_f) * 0.3;
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / cap_f) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

