    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, so its tightness bonus is minimal)
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.5;
    } else {
        score -= open_bins_count.min(20) as f64 * 0.5;
    }

    // Lookahead: if next item can use the post residual, reward leaving useful space
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // residual useless for lookahead item
    }

    // Early in stream: be more willing to open bins (exploration)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 5.0;
    }

    // Mild alignment with mean residual: prefer bins whose residual is near mean (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
