    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: avoid wasting it on small items.
    if fitting_bins_count == 1 {
        score -= 30.0;
        if item_size < 30 {
            score += 50.0;
        }
    }

    // New-bin candidate: penalize moderately so it's chosen only for poor fits,
    // but attract it when many bins are open and residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 120.0;
        score -= open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 40.0;
        }
    }

    // Slight late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
