        let mut open_penalty = 30.0 * (1.0 - progress);
        open_penalty += 2.0 * fitting_bins_count as f64;
        // Allow new bin when open bins are nearly full on average.
        let mean_tightness = 1.0 - mean_residual / bin_capacity as f64;
