pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // Smooth polynomial coupling: waste grows super-linearly with tiny residuals,
    // modulated by stream progress.
    let tight = (1.0 - norm_pr).powi(2);
    score += 30.0 * tight * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in the stream.
