    // Dead-space penalty: residual gaps too small for the minimum item size
    // (or too small for the lookahead item) are unusable waste.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap can't host the next item: penalize proportionally to how close
        // it is to fitting (near-miss waste is the worst kind).
        let gap_waste = post_residual as f64 / next_item_size as f64;
        score += 40.0 * (1.0 - gap_waste);
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; when few are open, new bins are cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive if the item would leave a very tight
    // residual elsewhere or open bins are badly fragmented (high mean_residual).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 60.0 - 50.0 * fragmentation;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // fresh bin can host the lookahead item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the post residual (partial lookahead match).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.3 * next_item_size as f64;
    }
