    // but reward residuals close to mean (balanced bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize mildly so we only open a new bin
    // when no open bin offers a decent fit; scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 10.0 * progress;
        // Opening a new bin is attractive if existing residuals are all too small.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 5.0;
        }
    }

    // Slight penalty for many open bins (encourage consolidation).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
