pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = (post_residual as f64) / cap;
    score += 12.0 * tightness * tightness;

    // Lookahead: if the next item can fit into the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 + 8.0 * chain_fit;
    }
