    let fill = (bin_residual as f64) / cap;
    score += 6.0 * (1.0 - fill);

    // Global state coupling: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > 0.5 * cap {
        score -= 2.0 * (mean_residual / cap);
    }

