        // but a new bin is fine if this item is large and fits poorly elsewhere
        score -= 6.0 * fit_norm * (1.0 - progress);
    }

    // Slight preference for bins below mean residual (keep balance of large gaps)
    score += 3.0 * ((mean_residual - bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
