    }

    // Penalize tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late in stream: prefer tight fits
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible by common
    // item-size classes (e.g. multiples of 10, 25, 50) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward leftovers that are "harmonic" with capacity fractions.
    if post_residual % 50 == 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 {
        score -= 6.0;
    } else if post_residual % 10 == 0 {
        score -= 3.0;
    } else {
        // Non-harmonic dead space penalty grows with smallness of leftover.
        score += (10.0 - pr / cap * 10.0).max(0.0);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead harmony: does next_item_size fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match of next item to leftover is gold.
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0;
            } else {
                score -= 8.0;
            }
        } else {
            // Leftover too small for the next item: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer tighter fits (competition is fine).
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is huge relative to capacity or nothing else fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fill > 0.5 {
            // Big item into empty bin wastes little: mild bonus.
            score -= (fill - 0.5) * 40.0;
        } else {
            // Small item into a fresh bin wastes capacity: heavy penalty.
            score += (0.5 - fill) * 60.0;
        }
        // If several open bins already fit, discourage new bin.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64);
        }
    }

