pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (1) —
    // practically, small positive residuals that can't fit the next item are bad.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            // Gap cannot host the lookahead item: dead space penalty, worse for tiny gaps.
            let gap = post_residual as f64;
            score += 40.0 * (1.0 - gap / 100.0);
        }
        if post_residual < 10 {
            // Tiny unusable sliver: strong penalty.
            score += 60.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 100.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (item_size as f64 + post_residual as f64 + 1.0);
    score -= 25.0 * tightness;

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading into new bins,
    // favor filling existing ones; a new empty bin candidate gets penalized.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure.
        score += 15.0 + pressure;
    } else {
        // Existing bin: mild reward scaled by pressure to consolidate.
        score -= 0.3 * pressure;
    }

    // Prefer bins whose residual is below mean residual (denser bins) when packing.
    if bin_residual != bin_capacity {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Lookahead synergy: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    score
}

