pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically, scaled by capacity.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * (post * post) / cap;

    // Reward filling bins to near-capacity (small waste fraction).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: penalize if post_residual can't host the next item,
    // reward if it can (keeps useful space for the future).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * nx;
        } else {
            score += 5.0 + 0.30 * nx;
        }
        // If next item exactly fits post_residual, strongly prefer this bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer minimal waste, strongly prefer already-open bins.
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 0.2 * (item_size as f64);
    }

    // Penalize bins whose residual deviates far from the mean residual
    // (keeps diversity of usable gaps across the bin pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.06 * dev;

    // Mild penalty for many open bins (consolidation pressure), relaxed over time.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (1.2 - 0.8 * t);

    // New-bin candidate handling: empty bin is a fallback; make it slightly
    // unattractive early (prefer packing), more acceptable late or when item
    // is huge relative to typical residuals.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / cap;
        score += 10.0 - 6.0 * t - 8.0 * size_frac;
        // If item barely fits anywhere else (large item), new bin is fine.
        if size_frac > 0.7 {
            score -= 12.0;
        }
    }

    // Small deterministic tie-breaker based on bin residual parity structure.
    score += ((bin_residual % 7) as f64) * 0.01;

    score
}

