pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear shaping.
    let mut score = pr as f64;

    // Non-linear polynomial coupling: tight fits (small x) get extra reward,
    // moderate dead space gets penalized super-linearly.
    score += 18.0 * x * x * (1.0 - x) * (1.0 - x) * cap * 0.1; // bump near mid residuals
    score -= 30.0 * (1.0 - x).powi(4); // strong reward for very tight fits

    // Stream progress coupling: early on, keep bins flexible (penalize tiny residuals less),
    // later, pack tightly more aggressively.
    let tightness_bonus = 12.0 * (1.0 - x).powi(2) * (0.5 + progress);
    score -= tightness_bonus;

    // Lookahead coupling: if the next item fits the post residual exactly-ish, reward strongly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs() / cap;
        score -= 25.0 * (1.0 - diff.min(1.0)).powi(3) * (0.4 + 0.6 * progress);
        // penalize if next item cannot fit (dead space likely)
        if pr < nx {
            score += 8.0 * (1.0 - progress) * x;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New empty bin candidate: penalize mildly unless residual would be very small
    // (i.e., item nearly fills a fresh bin) or stream is early and bins are few.
    if bin_residual == bin_capacity {
        score += 10.0;
        score -= 20.0 * (1.0 - x).powi(6); // near-full fresh bin is great
        score -= 10.0 * (1.0 - progress) * (1.0 - open_bins_count.min(10) as f64 / 10.0);
    }

    // Mean residual coupling: prefer bins below mean residual (get rid of small leftovers),
    // smooth quadratic term.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the leftover space (integer division on post_residual) ---
    // Class 0: post_residual == 0 -> perfect fit, strongly reward.
    // Class 1: 1..=9  -> near-perfect, dead space is unusable for min item 1 but tiny.
    // Class 2: 10..=19 -> potentially usable by small future items.
    // Class 3+: large leftovers, prefer bins that keep big usable chunks only if next item fits.
    let post_class = if post_residual == 0 { 0 } else if post_residual < 10 { 1 } else if post_residual < 20 { 2 } else { 3 };

    match post_class {
        0 => score -= 60.0,
        1 => score -= 25.0,
        2 => score -= 8.0,
        _ => {
            // Big leftover: only attractive if the lookahead item can consume it.
            if next_item_size > 0 && next_item_size <= post_residual {
                score -= 15.0;
            } else if next_item_size > 0 {
                // Next item won't fit in the leftover: penalize creating stranded space.
                score += 10.0;
            }
        }
    }

    // Modulo-10 harmonic band of the leftover: leftovers in [10,20) and [30,40) etc.
    // are the most reusable; odd/awkward bands get a slight penalty.
    let band = post_residual % 10;
    if post_residual > 0 {
        if band == 0 {
            score -= 3.0; // round leftover, easy to reason about reuse
        } else if band >= 5 {
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline so it wins only when all open fits are bad.
    if bin_residual == bin_capacity {
        // Opening fresh is fine early when few bins exist; penalize slightly mid-stream
        // so we consolidate into existing bins when reasonable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.9 + 15.0 * progress;

        // If the next item is huge, a fresh bin keeps flexibility for it.
        if next_item_size > 60 {
            score -= 12.0;
        }
        // If many bins are open with slack, discourage yet another one.
        if mean_residual > 30.0 && open_bins_count > 3 {
            score += 20.0;
        }
        return score;
    }

    // Prefer packing into bins whose residual is already small (consolidation),
    // scaled mildly by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - (bin_residual as f64) / (bin_capacity as f64));

    // Lookahead synergy: exact consumption of leftover by next item is excellent.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum plausible future item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (small usable post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin; if post-residual is unusable for the next
    // item, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 12.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourage closing out nearly-full bins.
    score += 0.8 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is well below the mean,
    // it is a good "filler" bin; prefer using it.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.5 * dev;
    } else {
        score += 0.3 * (-dev);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin
    // offers a reasonable fit (item is large relative to residuals).
    if bin_residual == bin_capacity {
        if item_size >= 50 && fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 45.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Slight progression term: later in the stream, be more conservative
    // about dead space since less opportunity remains to recover it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Lookahead: reward bins whose post_residual matches next item
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot fit: penalize leaving dead space
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
        }
    } else {
        // Last item: prefer minimal waste
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling
    score += (mean_residual - bin_residual as f64) * 0.6;

    // NEW-BIN CANDIDATE handling: make opening a new bin costly unless necessary
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += mean_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // Penalize new-bin opening more when item leaves large dead space and open bins exist
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        // Reward near-perfect fills in open bins harder
        else if post > 0.0 && post < 5.0 {
            score -= 80.0;
        }
    }

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late in stream: be more conservative, prefer tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

