pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact / tight fits (post_residual near zero).
    score -= 30.0 * (-post_residual as f64 / 8.0).exp();

    // 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item can follow: reward closeness of exact match.
            score -= 20.0 * (-gap / 10.0).exp();
        } else {
            // Next item cannot fit in the leftover: penalize unusable dead space,
            // worse when the leftover is small (fragmentation).
            score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize deviating from the mean residual: prefer bins near the average fill
    // (balanced packing), unless it's a tight fit which already got rewarded.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, but allow it when the item
    // fits poorly everywhere else (large item, few fitting bins) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_penalty = 35.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            // Fresh bin perfectly chains the next item: soften penalty.
            open_penalty -= 10.0 * (-(post_residual - next_item_size) as f64 / 12.0).exp();
        }
        if item_size > bin_capacity / 2 {
            open_penalty -= 8.0;
        }
        if progress > 0.8 {
            open_penalty -= 5.0 * progress;
        }
        score += open_penalty;
    }

    // Mild penalty proportional to wasted capacity fraction.
    score += 0.05 * post_residual as f64 * (item_size as f64 / bin_capacity as f64);

    score
}

