pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0; // creating a residual that wastes the bin for the next item
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Global state coupling: when many bins are open with slack, prefer reusing
    // existing bins (penalize the new-bin candidate implicitly via mean residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64 / (total_items.max(1) as f64) * 10.0;
    score += openness * 0.5 * (1.0 - progress);

    // Mean-residual alignment: prefer bins whose residual is close to the mean
    // (balanced packing) unless the fit is tight.
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * residual_gap * (1.0 - tightness);

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and would leave a well-usable residual, or no bin fits well.
    if bin_residual == bin_capacity {
        let usable = post_residual as f64 / bin_capacity as f64;
        let new_bin_penalty = 30.0
            - 20.0 * (1.0 - usable)
            - 10.0 * progress;
        score += new_bin_penalty.max(0.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;                 // normalized post residual in [0,1]
    let norm_item = item_size as f64 / cap;
    let norm_next = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    let mut score = pr;

    // Smooth non-linear coupling: penalize large dead space more as stream progresses
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post residual) with a cubic bonus
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Interaction: prefer bins whose residual after placement matches the next item smoothly
    let match_term = (norm_pr - norm_next).abs();
    score -= 6.0 * (1.0 - match_term) * (1.0 - match_term) * (0.4 + 0.6 * progress);

    // Penalize deviation from mean residual to keep bin load balanced
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it when it is the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference for reusing open bins over opening new ones early in the stream
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + 3.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
