pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // New-bin candidate: keep it unattractive unless nothing fits
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += mean_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        return score;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
        }
    } else {
        // last item: prefer minimal waste
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 40.0;
    }

    // Late in stream: be more conservative, prefer tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and large post-residuals
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit, always prioritize
    } else {
        // classify post_residual into harmonic bands of capacity
        let frac = pr as f64 / cap;
        if frac <= 0.05 {
            score -= 60.0; // near-perfect fit, tiny dead space
        } else if frac <= 0.15 {
            score -= 10.0; // usable small gap
        } else if frac <= 0.35 {
            score += 5.0; // awkward middle gap
        } else {
            score -= 25.0; // large residual keeps bin useful
        }
        // modulo arithmetic: residuals divisible by common item classes are reusable
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 && (pr as f64) >= next_item_size as f64 {
        score -= 15.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to waste
        score += 0.2 * (next_item_size as f64 - pr as f64);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: prefer opening a new bin when current fits are poor
    if bin_residual == bin_capacity {
        // neutral baseline; subtract slightly when open bins are crowded
        score = cap - 20.0 - 5.0 * (open_bins_count as f64).min(6.0);
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0;
        }
