    // Stream progression: later in stream, be greedier (favor tight fits)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - (post_residual as f64 / cap));

    // Mean residual coupling: if open bins are already roomy, penalize adding waste here
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A post_residual that is too small for the smallest plausible item (>=1)
    // but too small to be useful is pure waste.
    if post_residual > 0 {
        // Dead zone: residual below ~10 is nearly unusable for typical items.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
        // Perfect fit gets a strong reward.
        if post_residual == 0 {
            score -= 100.0;
        }
