        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Post-residual can host the next item: mild reward.
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer tight fills.
    let pressure = open_bins_count as f64;
    score += pressure * 1.5;

    // Prefer bins tighter than the mean residual (below-mean residual = well-filled bin).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Make the empty bin costly unless item is large relative
    // to typical residuals.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score += 40.0;
        // Large items justify a fresh bin more readily.
        if item_size > 50 {
            score -= 15.0;
        }
        // Late in the stream, opening new bins is less valuable (leftover waste).
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 20.0;
        }
        // If the next item is large and this bin would be nearly emptied by
        // the current item, a new bin is attractive.
        if next_item_size > 0 && item_size >= 70 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
