    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Competition exists: reward tighter fits relatively more.
        score -= 2.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it lose
    // against any reasonable existing fit, but win when existing bins would be
    // badly fragmented (large post_residual classes).
    if bin_residual == bin_capacity {
        // Opening a new bin: neutral-ish baseline; scale with stream progress
        // (late in stream, prefer consolidating into open bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap_f * (0.9 + 0.4 * progress);
        // If many bins are open already, opening yet another is costlier.
        score += open_bins_count as f64 * 1.5;
        // But if mean residual across open bins is small (all bins nearly full),
        // a new bin is genuinely needed.
        if mean_residual < 15.0 {
            score -= 60.0;
        } else if mean_residual < 30.0 {
            score -= 20.0;
        }
        // Big next item coming: opening a fresh bin preserves flexibility.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Slight preference for filling fuller bins as the stream progresses
    // (classic best-fit bias with time coupling).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is one of the "tight" bins — prefer consuming those first.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= residual_gap.clamp(-50.0, 50.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are unusable dead space -> heavy penalty
    // so we prefer bins where the leftover is either 0 or still usable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward perfect closure.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits (small waste relative to item size).
    score -= (item_size as f64) / (bin_residual as f64 + 1.0) * 8.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (keeps a perfect slot for it).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 40.0 + open_bins_count as f64 * 4.0;
        // Late in the stream, opening fresh bins is relatively cheaper than
        // fragmenting; early on, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 15.0;
        // If mean residual across open bins is high, opening a new bin wastes
        // potential; penalize more.
        score += mean_residual * 0.3;
    } else {
        // Mild preference for using fuller bins (smaller residual first).
        score += (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward small post_residual (tight fits) with a strong non-linear term.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Reward near-exact fits (post_residual very small).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // 2-step lookahead: if the NEXT item fits the post_residual, this placement
    // chains perfectly — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            // Reward tight chaining, penalize sloppy chains.
            score -= 15.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Compare against mean residual: placing in a bin with residual below mean
    // (smaller-than-average bin) preserves big residual bins for future items.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else if (bin_residual as f64) > mean_residual + 20.0 {
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity (big items deserve fresh space) or
    // early in the stream.
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins moderately; discount when item is large or stream is early.
        score += 12.0 - 18.0 * item_ratio - 6.0 * (1.0 - progress);
        // A new bin is great if the item nearly fills it exactly.
        if post_residual <= 5 {
            score -= 20.0;
        }
        // Avoid hoarding many open bins.
        score += 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0;
    }

    // Lookahead: strong reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward leftover.
            let waste = post_residual as f64 / next_item_size as f64;
            score += 8.0 * waste.min(3.0);
        }
    } else {
        // Last item: minimize leftover absolutely.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // Many alternatives: mild penalty to prefer best fits elsewhere.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(6.0);
    }

    // New-bin candidate handling: only attractive when no good fit exists
    // (i.e., this empty bin call coincides with large item or fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Fresh bin gives full residual; base cost high so it only wins on bad fits.
        score += 55.0;
        // Late in stream or many open bins: opening new bin is cheaper than fragmenting.
        score -= 20.0 * progress;
        score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual across bins is small, open bins are nearly full -> new bin good.
        score -= 0.35 * mean_residual;
        // Big items fit anywhere in an empty bin; slight extra push.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing) mildly.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: reward tight fits (small post_residual), with non-linear emphasis
    let mut score = post * (1.0 + 0.6 * norm_post * norm_post);

    // Smooth polynomial coupling with stream progress:
    // early on, prefer filling existing bins aggressively; late, tolerate spreading
    let coupling = 1.0 - 0.8 * progress * progress * (3.0 - 2.0 * progress);
    score *= coupling;

    // Penalize bins far from mean residual (non-quadratic smooth term)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev * dev.abs();

    // Last-chance bonus: strongly favor the only bin that fits (smoothly scaled by progress)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.3 * progress);
    }

    // Lookahead: penalize if post_residual can't fit the next item smoothly
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 4.0 * (gap / cap);
        } else {
            score += 3.0 * (-gap / cap) * (-gap / cap);
        }
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual as f64 == cap {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt();
    }

    // Small crowding term
    score += 0.05 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in the "usable" band
    // (roughly >= smallest item class) keep the bin valuable for future items.
    let small_item = 1u32.min(bin_capacity);
    let usable_threshold = bin_capacity / 10; // ~10% of capacity as dead-space floor

    // Reward tight fits strongly (post_residual near 0 is excellent).
    if post_residual == 0 {
        score -= bin_capacity as f64 * 2.0;
    } else if post_residual <= usable_threshold {
        // Perfect-ish fit: residual below the smallest useful item class.
        score -= bin_capacity as f64 * 1.5 * (1.0 - post_residual as f64 / usable_threshold as f64);
    } else {
        // Penalize residual that cannot host the next item (dead space).
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Harmonic penalty: residual in awkward mid-band classes.
        let band = post_residual / (bin_capacity / 4).max(1); // quarter-capacity classes
        score += band as f64 * 2.0;
    }

    // Lookahead bonus: if the next item fits exactly in the post residual,
    // this bin is a two-item chain — strongly favor it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_leftover = post_residual - next_item_size;
        if next_leftover == 0 {
            score -= bin_capacity as f64 * 1.2;
        } else if next_leftover <= usable_threshold {
            score -= bin_capacity as f64 * 0.6;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has high intrinsic score; only
    // prefer it when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Encourage opening fresh bins early in the stream (more future items
        // to fill them), discourage late when few items remain.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        // If mean residual is large, existing bins are roomy — new bin less needed.
        score += mean_residual * 0.3;
    }

    // Mild preference for filling bins that are already below-average residual
    // (concentrate waste rather than spreading it).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.2;
        } else {
            score += (-diff) * 0.1;
        }
    }

    // Small penalty for opening bins when many are already open (fragmentation).
    if bin_residual == bin_capacity && open_bins_count > 8 {
        score += (open_bins_count as f64 - 8.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: tiny gaps (< 10, min item size) are unusable.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0 * (20 - post_residual) as f64 / 10.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: only attractive if current bin would leave
        // bad dead space and other bins can't help.
        score += open_bins_count as f64 * 3.0;
        if post_residual < 10 {
            score += 30.0;
        }
    } else {
        // Mild preference for existing bins as stream progresses.
        score -= 2.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Lookahead: if next item fits snugly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 10.0;
        }
    }

    // Prefer bins below mean residual (consolidating space).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward residual classes that stay reusable (>= 20 leaves room for common items)
        let post_frac = post / cap;
        score -= 300.0 * (1.0 - post_frac) * post_frac;
        if post_residual >= 20 && post_residual <= 60 {
            score -= 25.0 * progress;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 50.0 + 30.0 * progress; // dead sliver, penalize more late
        } else if post_residual >= 10 && post_residual < 20 {
            score += 15.0;
        }
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 700.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 25.0;
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 120.0;
            score += 1.0 * mean_residual;
            score += 150.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            // Dead-space control: penalize new bins opened for large items more strongly
            let frac = item / cap;
            if frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            }
            // Discourage a new bin whose leftover cannot hold the next item
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
            }
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
    } else {
        // Open-bin branch: reward near-perfect fits late; prefer bins whose residual
        // closely matches the next item even if it doesn't fit now
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

