pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward residual that is a small fraction of capacity (good compaction)
        score -= 200.0 * (1.0 - post / cap) * (post / cap);
    }

    // Harmonic residual classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 800.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item doesn't fit in the leftover: penalize dead space more as stream progresses
            score += 25.0 + 40.0 * progress * ((nxt - post) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 120.0;
            score += 1.0 * mean_residual;
            score += 150.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            // Penalize new-bin leftover that cannot hold the next item (dead-space control)
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                score += 50.0 * ((next_item_size - post_residual) as f64 / cap) * (1.0 + progress);
            }
            // Reward opening a new bin when the item nearly fills it exactly
            if item / cap > 0.9 {
                score -= 250.0 * (item / cap - 0.9);
            }
        }
        // Large items leaving big dead space: prefer open bins when many exist
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 120.0 * ((item / cap) - 0.5);
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
    } else {
        // Open-bin branch: reward tiny residuals harder late in the stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // Prefer bins whose residual closely matches the next item even if it doesn't fit now
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // Mild penalty for mid-range residuals that few items can fill
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    }

    // Penalize residual that is small but nonzero (dead space).
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 10.0 + 0.3 * post_residual as f64;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin late in stream or when next item is large.
        if next_item_size > 60 || (total_items > 0 && step_index as f64 / total_items as f64 > 0.8) {
            score -= 20.0;
        }
    }

    score
}

