    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else {
        // Many fitting bins: slight penalty for wasting an option.
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to wasted potential
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Time horizon: early in stream, prefer keeping residuals large (flexibility);
    // late in stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += (1.0 - progress) * 0.08 * post_residual as f64;
    score -= progress * 10.0 * fit_ratio;

    // Global state: if mean residual is high, we have slack; prefer tight placements less urgently.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Discourage spreading across many bins when few bins open.
    if open_bins_count > 1 {
        score -= 3.0 / open_bins_count as f64;
    }

    // New-bin candidate: penalize so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.15 * item_size as f64;
        // But if current bin would leave a huge awkward residual, opening fresh is fine.
        if post_residual > 0 && (post_residual as f64) < 0.25 * bin_capacity as f64 && fitting_bins_count <= 2 {
            score -= 45.0;
        }
    }

    score
}

