    // Stream-progress coupling: early on, keep bins flexible (penalize tiny residuals);
    // late in stream, commit to tight packing aggressively.
    let flexibility = 4.0 * (1.0 - progress) * (1.0 - progress);
    score += flexibility * (1.0 - norm_pr) * norm_pr * cap * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * fit;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 3.0 * (nx / cap) * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * (nx / cap) * (1.0 - norm_pr);
        }
    }

    // Crowd control: many open bins -> prefer filling existing ones over opening new
    score += (open_bins_count as f64) * 0.05 * (1.0 - fit);

    // Mean-residual coupling: if this bin is below-mean residual (well used), reward
    let dev = (mean_residual - pr) / cap;
    score += 2.0 * dev * (1.0 + progress);

    // New-bin candidate handling: empty bin gets a moderate cost so it only wins
    // when no open bin fits well
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it belongs to
    let item_class = (item_size * 4) / bin_capacity; // 0..3 harmonic class (quarter bands)
    let next_class = if next_item_size == 0 { 0 } else { (next_item_size * 4) / bin_capacity };

    // Reward near-perfect fills (dead space below 1/16 of capacity)
    if post_residual < bin_capacity / 16 {
        score -= 40.0;
    }
    // Penalize dead space in the awkward band (just over 1/3 capacity): unusable for most items
    if post_residual > bin_capacity / 3 && post_residual < bin_capacity / 2 {
        score += 12.0;
    }

    // Coupling: does the next item fit into the post residual? Reward chain fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 + (post_residual - next_item_size) as f64 * 0.5;
        // Extra reward if next item is in the same or complementary harmonic class
        if next_class == item_class || item_class + next_class == 3 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize slightly more if post residual is large waste
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish, but discourage opening new bins early
    // or when the item fits well elsewhere; encourage when residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open new bin when existing residuals are small and fragmented, or stream is late
        score += 30.0 - fragmentation * 40.0 - progress * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    }

    // Modulo-class bonus: residual that is a multiple of 8 tends to pair with
    // common item sizes; reward divisible residuals slightly.
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Mild global pressure: prefer filling existing bins as open count grows
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps too small for the minimum item (1..100 interface,
    // but treat gaps below a small threshold as dead weight).
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness reward: fraction of residual consumed by this item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing ones.
    let pressure = (open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0)).min(8.0);
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize slightly under pressure so we only open when fit is bad.
        score += pressure * 1.5;
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 18.0;
        } else if slack < dead_threshold {
            score += 10.0; // would create dead space next step
        }
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 5.0;
    }

