pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // reward residual sizes that are "harmonic" (usable), penalize awkward mid residuals
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // next item cannot fit here: penalize dead space, worse late
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
            score += 45.0 * ((nxt - post) / cap) * (1.0 + progress);
        }
    } else {
        // last item: prefer minimal waste
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }
    if fitting_bins_count == 0 {
        score -= 2000.0;
    } else {
        score += 60.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Penalize creating tiny unusable residuals (below min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // NEW-BIN branch: make opening a bin costly unless the item nearly fills it
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += mean_residual;
        score += 200.0 * progress;
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // large items opening a fresh bin are fine; small items are wasteful
        let frac = item / cap;
        if open_bins_count > 2 {
            if frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            } else if post_residual > 0 && post_residual < 5 {
                score -= 90.0;
            }
        }
        // reward opening a bin when the item nearly fills it exactly
        if frac > 0.9 {
            score -= 300.0 * (frac - 0.9);
        }
        // discourage new bin whose leftover can't hold the next item
        if next_item_size > 0 && next_item_size > post_residual {
            score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    } else {
        // open-bin branch: reward tiny residuals even harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals few items can fill
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Late in stream: be more conservative, prefer tight fits
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual close to 0 is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Penalize leaving a residual just below the next item size (wasted).
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap <= 20.0 {
                score += gap * 0.8;
            }
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * 8.0 * (1.0 + open_bins_count as f64 / 10.0);

    // New-bin candidate penalty: discourage opening new bins unless current
    // residuals are poor relative to the item.
    if bin_residual == bin_capacity {
        let avg_usable = mean_residual.max(0.0);
        if avg_usable >= item_size as f64 {
            score += 20.0 + avg_usable * 0.3;
        } else {
            score -= 5.0;
        }
    }

    // Time horizon: early in the stream, be more selective (keep flexibility);
    // late in the stream, just fill bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0 * (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (minimal waste).
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.1 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual (tight fit), with smooth quadratic decay
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are more acceptable (bins can be filled later);
    // late in the stream, residual waste becomes increasingly costly (quartic growth).
    let waste_penalty = norm_post * norm_post * (1.0 + 3.0 * progress * progress * progress);
    score += waste_penalty * cap * 0.25;

    // Reward tight fits: smooth bump when post_residual is small relative to capacity
    let tightness = (1.0 - norm_post).powi(2);
    score -= 8.0 * tightness * (1.0 + progress);

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((post - nxt) / cap).max(0.0);
        score += 6.0 * unusable * unusable * cap;
        // Reward bins where next item fits exactly well
        if nxt <= post {
            let nxt_fit = 1.0 - ((post - nxt) / cap);
            score -= 5.0 * nxt_fit * nxt_fit;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Slight preference for consolidating into fewer bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_post) * 0.5;

    // Mild pull toward bins with residuals near the mean (balanced packing)
    let dev = (post - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * cap;

    // New-bin candidate bias: make empty bin slightly less attractive unless
    // no open bin fits well (its post_residual == cap makes base score high already)
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }

    score
}

