    // next item (next_item_size divides post_residual), the bin remains
    // perfectly harvestable -> reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 12.0;
        }
        // If next item fits exactly into the leftover, huge reward.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > post_residual {
        // Leftover too small for the next item: penalize dead space,
        // scaled by how close the next item is to fitting.
        let gap = (next_item_size - post_residual) as f64;
        score += gap.min(30.0) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when open bins are congested (mean residual low) or
    // many bins already exist. Otherwise push it away so existing bins
    // get filled first.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
