        if next_item_size as f64 > 0.6 * cap {
            score -= 10.0;
        }
    }

    // Small global tie-breaker: prefer bins with residual above the mean
    // (keeps a spread of usable leftovers across bins).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 1.0;
    }

    score
}

