    // New-bin candidate should only win when it is genuinely attractive.
    if bin_residual == bin_capacity {
        score += 6.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fill reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    } else if post_residual < 20 {
        score -= 80.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or snugly -> great
            let snug = (post_residual as f64 - next_item_size as f64).abs();
            score -= 60.0 - snug.min(60.0);
        } else {
            // wasted space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
