pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward bins that leave post_residual too small for typical future items
    // (dead space is only bad if it stays dead; killing residual is fine).
    let dead = post_residual > 0 && post_residual < 10;
    if dead {
        score -= 15.0; // small unusable slivers are acceptable, even good
    } else {
        // penalize residuals in the awkward 11..=30 range where items rarely fit
