            score += 12.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score -= 10.0;
        } else if next_item_size > post_residual && next_item_size > bin_residual {
            // next item won't fit here anyway; leave residual for it if possible
            if next_item_size <= bin_residual && post_residual > 0 {
                score += 8.0;
            }
        }
        // avoid wasting a bin that could hold the (large) next item instead
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 6.0;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals clean); late in the stream, pack aggressively.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= progress * 10.0 * (post_residual as f64) / (bin_capacity as f64);

    // Global state: many open bins with high mean residual -> prefer filling
    // existing bins rather than adding more.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 8.0;
    }
    // Few open bins and large mean residual -> new bin is cheap.
    if open_bins_count <= 2 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Mild penalty for opening a brand-new bin when good alternatives exist.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0 + 0.05 * open_bins_count as f64;
    }

    score
}

