        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap
    } else {
        norm_pr * norm_pr
    };
    score += 40.0 * dead * (1.0 + progress);

    // Reward tight fits (small post_residual relative to item) with smooth term
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness;

    // Penalize waste relative to mean residual across open bins (smooth divergence)
