    score += 5.0 * div * div;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins, smoothed by progress
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Prefer keeping room for a large next item when this bin has leftover
    if next_item_size > 0 && pr > 0 {
        let usable = (pr as f64 / next_item_size as f64).min(1.0);
        score -= 8.0 * usable * usable * (1.0 - progress);
    }

    score
}

