pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 and 20
    let res_mod10 = post_residual % 10;
    let res_mod20 = post_residual % 20;
    let res_div = post_residual / 20; // coarse harmonic band

    // Penalize dead space that is not a "nice" size (small odd residues)
    let residue_penalty = match res_mod10 {
        0 => -6.0,           // perfectly harmonic residual
        5 => -2.0,           // half-harmonic
        _ => (res_mod10 as f64) * 0.8, // awkward leftover
    };
    score += residue_penalty;

    // Very small post-residual is wasted space unless it's exactly 0
    if post_residual > 0 && post_residual <= 5 {
        score += 12.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let fit_quality = (post_residual - next_item_size) % 10;
            score -= 8.0 - (fit_quality as f64) * 0.5;
        } else {
            score += 5.0; // next item won't chain here
        }
        // harmonic pairing: next_item + item_size divides capacity nicely
        if (item_size + next_item_size) % 50 == 0 {
            score -= 6.0;
        }
    } else {
        // last item: prefer fullest fill
        score -= 10.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost that shrinks
    // as the stream progresses, but rises when open bins are well-populated
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 60.0 * (1.0 - progress) + (open_bins_count as f64) * 2.0;
    }

    // Mild preference for bins below mean residual (keep balance, avoid fragmenting full bins)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Integer-division threshold: bands of residual desirability
    match res_div {
        0 => score += 4.0,   // residual < 20: mostly dead
        1 => score += 0.0,   // 20..39
        2 => score -= 2.0,   // 40..59
        3 => score -= 4.0,   // 60..79
        _ => score -= 6.0,   // large residual
    }

    // mod20 even/odd harmonic adjustment
    if res_mod20 == 10 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it's below the smallest plausible item threshold (10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps that can't fit the lookahead item are less useful; penalize mildly.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, favor consolidating
    // into existing bins (penalize opening new bins).
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if this is the only fitting bin, opening a new bin is necessary.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && !new_bin_candidate {
        score -= 30.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a tight bin — prefer using it up.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Late in the stream, avoid leaving tiny residuals behind.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits via concave waste curve
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // next item cannot fit here: penalize dead space scaled by progress
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 40.0 * (nxt / cap);
            score += 45.0 * deadness * (1.0 + progress);
        }
    } else {
        // last item: prefer minimal waste
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize creating tiny unusable residuals (below min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // ---- New-bin branch: decide when opening a fresh bin is justified ----
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if next_item_size > 0 && next_item_size <= item_size {
            score += 25.0 * progress * (next_item_size as f64 / cap);
        }
        // discourage new bin when item is large (fewer wasted large-bin openings)
        if open_bins_count > 2 {
            let frac = item / cap;
            if frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            } else if post > 0.0 && post < 5.0 {
                score -= 90.0;
            }
        }
        // reward opening when item nearly fills it exactly
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // open-bin branch: reward tiny residuals harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item even if it doesn't fit now
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals few items can fill
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Late in stream: be more conservative, prefer tight fits
    score *= 1.0 + 0.3 * progress;

    score
}

