pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let mut score = post_residual as f64;

    // Reward bins whose leftover can host the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * next_item_size as f64;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        // Tiny dead space is nearly a perfect fit but unusable; mild penalty.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize by default, but relax early in the stream
    // and for large items where fragmenting an open bin is costly.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 35.0;
        new_bin_penalty -= (1.0 - progress) * 15.0;
        new_bin_penalty += 0.4 * item_size as f64;
        // With many open bins, prefer consolidating into them.
        new_bin_penalty += 1.5 * open_bins_count as f64;
        score += new_bin_penalty;
    }

    // Discourage placing into bins whose residual deviates wildly from the mean
    // (keeps the residual landscape homogeneous and future-friendly).
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // Mild preference for fuller bins (best-fit flavor).
    score += 0.15 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize residual, scaled by progress (early stream: less strict)
    let mut score = pr * (0.6 + 0.8 * progress);

    // Smooth non-linear coupling: quadratic dead-space term grows with progress
    score += 30.0 * norm_pr * norm_pr * (0.3 + progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        let match_quality = 1.0 - diff / cap;
        score -= 20.0 * match_quality.max(0.0) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Mean residual coupling: prefer bins deviating from mean (keep balance)
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * progress;

    // New-bin candidate: mild penalty so it's only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0;
    }

    // Cubic smooth interaction between fill level and progress
    let fill = 1.0 - norm_pr;
    score -= 10.0 * fill * fill * fill * progress;

