            let nxt_class = (post_residual - next_item_size) / 10;
            if nxt_class == 0 {
                score -= 15.0;
            } else if nxt_class >= 5 {
                score += 5.0;
            }
        } else {
            // next item won't fit here regardless; slight penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
