    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (bin_residual < bin_capacity) as i32 as f64;

    // Slight tie-break toward bins below mean residual (balance consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

