    // Open-bin pressure: with many open bins, avoid spreading; favor existing bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New empty bin candidate: penalize unless it enables a much better future fit.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        if next_item_size > 0 && next_item_size <= post_residual {
