    // "tighter" — prefer filling tighter bins to keep wide bins flexible.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate handling: only open a new bin when no open bin fits
    // well (high post_residual waste) or when it enables a perfect next match.
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        score = waste as f64;
        if next_item_size > 0 && next_item_size <= waste {
