    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // reward residuals near half capacity (easier to fill later)
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
        }
    } else {
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Tiny unusable residual penalty
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // New-bin branch: make opening a new bin appropriately costly
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if next_item_size > 0 && next_item_size <= item_size {
            score += 25.0 * progress * (next_item_size as f64 / cap);
        }
        // discourage opening new bin for large items
        if open_bins_count > 2 {
            let frac = item / cap;
            if frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            } else if post > 0.0 && post < 5.0 {
                score -= 90.0;
            }
        }
        // new-bin leftover that can't hold next item
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
        }
        // dead-space deadness penalty
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 45.0 * deadness * (1.0 + progress);
        }
        // reward near-full opening
        if post_residual > 0 && item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // open-bin branch: reward tiny residuals late
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals early
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Late-stream conservatism: scale score to prefer tight fits
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic waste penalty (dead space grows super-linearly in badness)
    let mut score = pr * (1.0 + 0.9 * pr / cap);

    // Smooth interaction: waste matters more as the stream progresses
    score += 0.6 * pr * (progress * progress);

    // Reward tight fits (small post_residual) with a saturating bonus
    score -= 25.0 * (-pr / (0.25 * cap)).exp();

    // Penalize bins whose residual is far from the mean (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * fit_ratio;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 12.0 * (-slack * 4.0).exp();
    } else if next_item_size > 0 {
        // Penalize leaving space the next item cannot use
        score += 6.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins are open
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Concave reward: bins left near-full are much better than mid-range leftovers
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // Harmonic residual classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
            if item_size > bin_capacity / 2 {
                score -= 20.0;
            }
        } else {
            score += 150.0;
            score -= 120.0 * (item / cap);
            score += 1.0 * mean_residual;
            score += 200.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            score += 80.0 * progress * (mean_residual / cap);
            if next_item_size > 0 && next_item_size <= item_size {
                score += 25.0 * progress * (next_item_size as f64 / cap);
            }
            // dead-space control: penalize new bins by waste fraction
            if open_bins_count > 2 {
                let frac = item / cap;
                if frac > 0.5 {
                    score += 140.0 * (frac - 0.5);
                } else if post > 0.0 && post < 5.0 {
                    score -= 90.0;
                }
            }
            // discourage new bin whose leftover can't hold the next item
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                let deadness = (next_item_size - post_residual) as f64 / cap;
                score += 55.0 * deadness * (1.0 + progress);
            }
            // reward near-perfect opening fits
            if item / cap > 0.9 {
                score -= 30.0 * (item / cap - 0.9) * 10.0;
            }
            // avoid opening a bin when an existing bin would be left with an unusable sliver
            if fitting_bins_count > 0 && mean_residual < 10.0 && post_residual > 20 {
                score += 35.0;
            }
        }
    } else {
        // open-bin branch: reward tiny residuals harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item even if it doesn't fit now
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals few items can fill
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
        // combined feature: extra tightness pressure when many bins compete for the item
        if fitting_bins_count > 3 {
            score += 6.0 * (post / cap) * (1.0 - progress);
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity fractions.
    let post = post_residual as u32;
    let class = post / 10; // 0..10 harmonic band
    let phase = post % 10; // intra-class phase

    // Penalize residuals that are awkward: large but not reusable by common sizes.
    // Dead-space bands: residual in (0..10) is near-waste; (10..20) fits only tiny items.
    if post > 0 && post < 10 {
        score += 12.0 - (post as f64) * 0.5; // pure dead space penalty
    } else if post < 20 {
        score += 4.0;
    }

    // Reward exact-fit harmonic classes: residual that matches multiples of 25/50.
    if post % 25 == 0 {
        score -= 3.0;
    }
    if post % 50 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            // harmonic class of resulting slack after hypothetical next placement
            let next_slack_class = slack as u32 / 10;
            score -= 10.0 - next_slack_class as f64 * 0.6;
            if (post % 10) == (next_item_size % 10) {
                score -= 2.0; // same harmonic phase: good complementarity
            }
        } else {
            // next item cannot use this residual: penalize proportional to wasted class
            score += 2.0 + phase as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: empty bin gets baseline near mean residual pressure.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when open bins are fragmented.
        score = cap - post_residual as f64; // = 0 for empty bin base
        score += open_bins_count as f64 * 0.5;
        score -= mean_residual * 0.3;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 4.0; // big next item: fresh bin attractive
        }
        // discourage opening new bins early in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 3.0;
    }

    // Fragmentation pressure: when many bins open, prefer tighter fits.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 6.0;

    // Mild bias toward bins below mean residual (consolidating small leftovers).
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..10) are heavily penalized,
    // since they can never host items of size >= 1 in practice.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving residual that can exactly fit the lookahead item (k=2).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize creating a gap too small for the lookahead item but large enough to be "wasted".
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: prefer consolidating into existing bins when many are open.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when existing bins are very fragmented
    // (mean residual low relative to item) or this bin is empty and item is large.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score so it loses to decent fits.
        score = bin_capacity as f64 * 0.6;
        let fragmentation = mean_residual / (open_bins_count.max(1) as f64);
        if open_bins_count > 0 && fragmentation < item_size as f64 {
            score -= 10.0; // existing bins are tight; new bin is reasonable
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
    }

    // Slight preference for tighter bins overall (residual close to item).
    score += 0.2 * (bin_residual - item_size) as f64;

    // Mild stream-progression tiebreak: later in the stream, be more conservative
    // about opening bins (favor reuse).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

