    let mut score = post_residual as f64;

    // Strong reward for exact / near-exact fits (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this is a perfect chain — heavily reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            // Next item fits but leaves more slack: mild reward proportional
            // to how tight the chain is.
            score -= 40.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item will NOT fit in the leftover: penalize creating
            // unusable-for-next-item dead space, worse for large leftovers.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 30.0 * waste;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual below the mean
    // are "tight" — using them is good (consolidate space). Bins above mean
    // have plenty of room; slightly deprioritize them.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit. Base penalty
    // for opening a new bin grows as the stream matures.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 150.0 + 100.0 * progress;
        // But if the next item is large and current post-residual would be
        // too small for it anyway, opening a fresh bin is less bad.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
            score -= 100.0;
        }
    }

    // Mild penalty when many bins are open: encourage closing bins out
    // (filling existing ones) rather than spreading across many.
    score += 2.0 * open_bins_count as f64;

    score
}

