        score -= 25.0 + 50.0 * progress;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= (pr - nx) * (1.0 + progress) * 0.3;
        } else {
            score += (nx - pr) * 0.2 * (1.0 - progress);
        }
    }

    // Mean-residual deviation: penalize bins far from the mean (fragmentation)
    let dev = (pr - mean_residual).abs();
    score += dev * dev / cap * 0.2;

    // Mild penalty for spreading across too many bins
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: discourage opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 60.0 - 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // "harmonic" chunk sizes (50, 25, 20, 10) are more reusable.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward (subtract) when post_residual lands in a highly reusable class.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, close the bin
    } else {
        if post_residual % 50 == 0 { score -= 22.0; }
        else if post_residual % 25 == 0 { score -= 15.0; }
        else if post_residual % 20 == 0 { score -= 12.0; }
        else if post_residual % 10 == 0 { score -= 8.0; }
        else if post_residual % 5 == 0 { score -= 4.0; }
        // dead-space penalty: very small unusable fragments
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // Lookahead: if the next item exactly fills the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward, scaled by tightness
            let tight = (next_item_size as f64 / post as f64).min(1.0);
            score -= 10.0 + 15.0 * tight;
        } else {
            // next item cannot fit here: penalize more when the gap is small
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap) * 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing bins would leave bad fits.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 25.0;
        // more attractive early in the stream or when few bins are open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
