pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's post residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits but not exactly: mild reward proportional to tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack);
    }
    // Next item cannot fit in the leftover: penalize dead space creation.
    else if next_item_size > 0 {
        score += 0.5 * (next_item_size as f64 - post_residual as f64).min(80.0);
    }

    // Compare post_residual relative to the mean residual of open bins:
    // leaving less than average leftover is good (compact packing).
