    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Slight bias against opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.2 * open_bins_count as f64;
    }

    // Late in the stream, compactness matters more: tighten toward small residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    score
}

