pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): prefer tight fits strongly (dead space penalized superlinearly).
    // Late (progress ~ 1): residual dominance softens slightly to keep bins open for lookahead.
    let tightness = (pr / c).powi(2) * (1.0 + 3.0 * (1.0 - progress));
    score += 40.0 * tightness;

    // Smooth cubic decay term: small residuals get extra reward (perfect packing).
    let x = pr / c;
    score -= 25.0 * x * (1.0 - x) * (1.0 - 2.0 * x);

    // Lookahead coupling: penalize post_residual that cannot fit the next item,
    // reward when next item fits smoothly; smooth polynomial rather than piecewise.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_gap = (pr - n) / c;
        let sig = 1.0 / (1.0 + (-8.0 * fit_gap).exp());
        score += 15.0 * (sig - 0.5) * (1.0 + progress);
    }

    // Last-chance bonus: strongly favor this bin if it is the only one that fits.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Mild penalty for scattering across many open bins; smooth in open count.
    score += 2.0 * ((open_bins_count as f64).ln_1p()) * (x * (1.0 - x));

    // Alignment with mean residual: bins far from mean residual get slight penalty (smooth).
    let dev = (pr - mean_residual) / c;
    score += 5.0 * dev * dev * (0.5 + progress);

    // New-bin candidate: only attractive when progress is low or fit is terrible.
    if bin_residual == bin_capacity {
        let badness = (pr / c).powi(2);
        score += 18.0 * (1.0 - progress) * (1.0 - badness) + 5.0 * badness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // reward small leftover waste (combined fine-grained residual shaping)
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // Harmonic residual classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 150.0;
            score -= 120.0 * (item / cap);
            score += 1.0 * mean_residual;
            score += 200.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            score += 80.0 * progress * (mean_residual / cap);
            // large items leaving big dead space: prefer open bins when many exist
            if item > 0.5 * cap && open_bins_count > 2 {
                score += 140.0 * ((item / cap) - 0.5);
            }
            if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
                score -= 20.0;
            }
            // reward near-perfect opening fill
            if post_residual > 0 && item / cap > 0.9 {
                score -= 300.0 * (item / cap - 0.9);
            }
            // penalize new-bin leftover that likely becomes dead space
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                let deadness = (next_item_size - post_residual) as f64 / cap;
                score += 45.0 * deadness * (1.0 + progress);
            }
        }
    } else {
        // open-bin branch: reward tiny residuals harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals that few items can fill
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.15;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual (modulo 10 classes).
    let class = post_residual % 10;
    // Residuals in "dead" classes (1..9, non-zero, small) are less reusable;
    // class 0 (perfect fit) and classes that are multiples of 10 are best.
    if post_residual == 0 {
        score -= 60.0; // perfect fill: strongly reward
    } else if class == 0 {
        score -= 15.0; // round residual: reusable by decile-sized items
    } else if post_residual < 10 {
        score += 12.0; // tiny dead space: penalize mildly
    } else {
        score += (class as f64) * 0.4; // odd-class penalty
    }

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportionally to how snugly the next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.5;
            if post_residual == next_item_size {
                score -= 25.0; // chain of perfect fits
            }
        } else {
            // Next item won't fit: this bin's leftover becomes dead space.
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: prefer filling as much as possible.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when the current fit is bad
    // (large item leaving little room anywhere) or few bins fit the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 40.0;
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
        // Late in the stream, consolidating into open bins matters more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If this item nearly fills a fresh bin, a new bin is fine.
        if item_size >= 70 {
            score -= 35.0;
        }
        // If next item is large and no open bin could chain, new bin ok.
        if next_item_size > 0 && next_item_size + item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Prefer using bins whose residual is already small (tighten full bins).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to reduce open bin count when many are open.
    if open_bins_count > 8 {
        score += 2.0;
    }

    // Integer-division threshold: bins whose residual / 10 is small are precious.
    let decile = bin_residual / 10;
    if decile <= 2 && bin_residual >= item_size {
        score -= 5.0;
    }

    score
}

