pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual gap that cannot fit even the smallest plausible item is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual > 60 {
        score += 4.0; // large leftover is flexible, mild penalty
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if the gap is just barely too small for the lookahead item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity)
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
    }

    // Prefer filling bins that are already well-utilized (low residual relative to mean)
    if bin_residual < bin_capacity {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space).
    if post_residual <= 5 {
        score -= 60.0 * (1.0 - post_residual as f64 / 6.0);
    }

    // 2-step lookahead: reward leaving exactly room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 55.0 - 8.0 * slack; // perfect chain: post_residual == next_item_size
        } else {
            score += 0.05 * slack; // mild penalty for over-large leftover
        }
    }

    // Penalize dead space that can never fit the next item (wasted capacity).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let has_good_fit = next_item_size > 0 && post_residual >= next_item_size
            && (post_residual - next_item_size) <= 5;
        if fitting_bins_count > 0 && !has_good_fit {
            score += 50.0 + 30.0 * (1.0 - progress);
        } else if has_good_fit {
            score += 5.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Mild preference for fewer open bins when stream is late.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

