pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that no plausible future item can use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 6.0; // residual too small for the lookahead item -> likely waste
        } else {
            score -= 4.0; // residual can host the next item: good pairing
            let slack = (post_residual - next_item_size) as f64;
            score -= 3.0 * (-slack / 20.0).exp(); // bonus for snug two-item packing
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Base cost of a fresh bin; shrinks late in the stream or when many bins are open anyway.
        let mut new_bin_cost = 40.0 - 15.0 * progress;
        if open_pressure > 4.0 {
            new_bin_cost -= 2.0 * (open_pressure - 4.0).min(6.0);
        }
        // If the current bin leaves a large unusable remainder, opening fresh is fine.
        if post_residual < 10 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    }

    // Slight preference for bins whose residual is below the mean (consolidate emptier space).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild penalty for leaving residuals in the awkward 1..=9 range.
    if post_residual >= 1 && post_residual <= 9 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // reward residuals that are a balanced fraction of the bin
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // next item cannot fit here: penalize dead space scaled by progress
            let deadness = (nxt - post) / cap;
            score += (40.0 + 45.0 * progress) * deadness;
        }
    } else {
        // last item: prefer minimal waste
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // NEW-BIN branch: control when opening a new bin is acceptable
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        // discourage new bin whose leftover can't hold the next item
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
        }
        // reward opening when item nearly fills the bin exactly
        if item / cap > 0.9 {
            score -= 300.0 * (item / cap - 0.9);
        }
        // big items late: strong penalty for opening new bins
        if open_bins_count > 2 && item / cap > 0.5 {
            score += 140.0 * (item / cap - 0.5) * (1.0 + progress);
        }
    } else {
        // open-bin branch: reward tiny residuals harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals few items can fill
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Late in stream: be more conservative, prefer tight fits
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize large post-residual (wasted space), with non-linear growth
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, keep residuals flexible.
    let coupling = (norm_pr - 0.5) * (norm_pr - 0.5) * (2.0 * progress - 1.0);
    score += 30.0 * coupling;

    // Lookahead: reward if next item fits in the resulting residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + 0.5 * progress);
        } else {
            score += 6.0 * (1.0 - progress);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty proportional to openness count to encourage consolidation
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // Prefer bins whose residual deviates from the mean in a useful way
    score -= 0.5 * (mean_residual - pr) / cap;

    // New-bin candidate: neutral-ish, penalized mildly so it's chosen only when
    // open bins create very bad residuals.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quantization.
    // Residuals divisible by common item sizes are more reusable.
    if post_residual > 0 {
        let mut class_bonus = 0.0;
        if post_residual % 10 == 0 { class_bonus += 6.0; }
        else if post_residual % 5 == 0 { class_bonus += 3.0; }
        if post_residual % 20 == 0 { class_bonus += 2.0; }
        // Harmonic divisor count of post_residual (small ints 1..100)
        let mut divisors = 0u32;
        let mut d = 1;
        while d <= post_residual {
            if post_residual % d == 0 { divisors += 1; }
            d += 1;
        }
        class_bonus += divisors as f64 * 0.8;
        score -= class_bonus;
    } else {
        // Perfect closure: reward strongly.
        score -= 25.0;
    }

    // Coupling with next item: post_residual that exactly or nearly fits next_item_size is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 { score -= 10.0; }
            else { score -= (10.0_f64.min(slack as f64 / 8.0)); }
        } else {
            // next item cannot use this residual: penalize large leftover
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the item
    // fits terribly everywhere. Penalize the fresh bin moderately.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // Prefer filling bins with low mean residual (tighten nearly-full bins).
    score += (mean_residual - post_residual as f64) * 0.05;

    // Slight preference for bins tighter than the mean.
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Modulo-class harmony between item and residual capacity:
    // bins whose residual is a harmonic multiple of the item pack cleanly.
    if bin_residual % item_size.max(1) == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (1..=9) are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0; // dead-space penalty, worst for tiny gaps
