    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 45.0;
        if slack < 10 {
            score -= 25.0; // perfect chaining
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for the next item: dead space confirmed
        score += 20.0;
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Open bins pressure: too many open bins -> discourage spreading, encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 2.0 * (0.3 + 0.7 * progress);

    // Penalize bins with residual far from mean (keep residuals homogeneous).
    score += 0.5 * ((post_residual as f64) - mean_residual).abs();

    // New-bin candidate handling: an empty bin is a fallback; prefer filling existing bins
    // unless the fit would be terrible.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0 + 3.0 * (open_bins_count as f64);
        // but if placing here wastes little (large item), it's acceptable
        score -= 25.0 * tightness;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // room to chain next item in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
