    // with below-average residual (tight bin) is good consolidation.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize creating small unusable residuals relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    // Early in the stream, be slightly more willing to open fresh bins for
    // large items (keeps future flexibility); late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if the item is large or open bins
        // are all quite full (mean residual small).
        score += 60.0; // base reluctance to open a new bin
        if item_size >= 60 {
