    score += prog_term * npr * npr * npr * cap;

    // Reward filling a bin almost exactly (post residual near zero)
    let exactness = (1.0 - npr).powi(6);
    score -= 12.0 * exactness * (0.5 + progress);

    // Lookahead: penalize leaving residuals that cannot fit next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            // next item still fits here: mild reward proportional to wasted potential
            score -= 2.0 * (ni / cap) * (1.0 - npr);
        } else {
            // next item won't fit: penalize dead space, more if next item is small (waste)
            let waste = (pr / cap) * (1.0 - ni / cap);
            score += 8.0 * waste * (0.6 + 0.8 * progress);
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening new bins when open bins exist,
    // unless current bin residual is very small relative to item
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        let tightness = 1.0 - (it / cap);
        score += 10.0 * openness * (0.4 + 0.6 * progress) * (0.5 + 0.5 * tightness);
        // allow new bin late in stream if mean residual is low (fragmentation)
        score -= 4.0 * (1.0 - mean_residual / cap) * progress;
    } else {
        // Mild preference for bins with residuals close to item size (good fit)
        let fit_gap = ((bin_residual as f64) - it) / cap;
        score += 3.0 * fit_gap * fit_gap;
        // Reward using bins whose residual is below mean (consolidating small spaces)
        let rel = (bin_residual as f64) / (mean_residual.max(1.0));
        if rel < 1.0 {
            score -= 2.0 * (1.0 - rel) * (1.0 - rel);
        }
    }

    // Small global smoothing toward mean residual to balance bin set
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Penalize residuals that fall into "dead zones" — too big to waste, too small to use.
    // Class boundaries via integer division thresholds (capacity / k).
    let q = post_residual / 10; // decade class
    match q {
        0 => score -= 12.0,          // post_residual < 10 : near-perfect fit, great
        1 => score -= 4.0,           // 10..19 : small but usable
        2 => score += 6.0,           // 20..29 : awkward dead zone
        3 => score += 3.0,           // 30..39 : mildly awkward
        4 => score -= 5.0,           // 40..49 : half-bin class, flexible
        5 => score -= 2.0,           // 50..59
        6 => score += 1.0,           // 60..69
        _ => score += 0.5,           // large residual, low priority anyway
    }

    // Modulo harmony: residuals divisible by common item sizes are reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.0; }
        else if pr % 5 == 0 { score -= 1.5; }
        else { score += 1.0; }
    }

    // Lookahead coupling: reward leaving space the next item can use exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 { score -= 4.0; }
            else { score -= 2.0 / (1.0 + slack as f64 / 20.0); }
        } else {
            // next item can't fit here; penalize proportionally to wasted potential
            score += 2.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless nothing else fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if current bins are all crowded (mean residual small), new bin is fine.
        if mean_residual < 0.25 * cap {
            score -= 20.0;
        }
    }

    // Tightness bonus: prefer bins where the item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (post < 15.0) as i32 as f64;

    // Mild preference to keep a pool of open bins balanced vs mean residual.
    score += 0.05 * ((post - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste. Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize post residuals that are too small for the lookahead item but
    // large enough to look "usable" — they tempt but fail next step.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward residuals that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate handling: an empty bin has high post_residual, which
    // already scores poorly; add a small extra tax so it only wins when all
    // open bins are genuinely bad fits (large mean_residual spread).
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.2;
    }

    // Prefer bins whose residual is close to the item (tight fit) —
    // coupling with mean residual: bins below mean residual are "drier".
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Slight preference for tighter fits overall.
    score += (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 120.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover space -> penalize dead space
            score += 60.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Prefer filling bins that are already relatively full relative to mean residual
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize new-bin candidate mildly unless residuals are large/dead
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Late-stream consolidation: prefer reusing bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize large unusable leftovers (below typical min item size granularity)
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize large waste relative to item size.
    if item_size > 0 {
        score += (post_residual as f64 / item_size as f64) * 8.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64 / bin_capacity as f64) * 25.0;
        } else {
            // Next item won't fit here; penalize leaving moderately large leftovers
            // that are likely unusable.
            score += (post_residual as f64 / bin_capacity as f64) * 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than spreading.
    let mean_fill_pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += mean_fill_pressure * 20.0;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Time horizon: early in the stream, be more willing to open new bins
    // (lower score for new bin) to preserve flexibility; late in the stream,
    // consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus time-dependent penalty.
        score = bin_capacity as f64 * 0.9 + progress * 40.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 20.0; // next item can't fit in a fresh bin either? impossible, but guard
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // few alternatives -> new bin is fine
        }
    } else {
        // Existing bin: slight bonus late in stream for consolidation.
        score -= progress * 10.0;
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // reward concave residual usage (mid-size residuals are flexible)
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
        }
    } else {
        // last item: prefer minimal waste
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling
    score += (mean_residual - bin_residual as f64) * 0.6;

    // NEW-BIN CANDIDATE branch (empty bin detected by residual == capacity)
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        // discourage opening a new bin when an existing bin would be left unusable
        if open_bins_count > 2 {
            let frac = item / cap;
            if frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            } else if post > 0.0 && post < 5.0 {
                score -= 90.0;
            }
        }
        // big items near capacity: opening a fresh bin is fine
        if item / cap > 0.9 {
            score -= 300.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // open-bin branch
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches the next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals that few items can fill
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Penalize tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Late in stream: be more conservative, prefer tight fits
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
