    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: waste after placement, with non-linear (quadratic) penalty growth
    let mut score = norm_pr + 0.8 * norm_pr * norm_pr;

    // Reward tight fits: item filling bin well (post residual small relative to item)
    let tightness = fit_ratio * (1.0 - norm_pr);
    score -= 6.0 * tightness * (1.0 + progress);

    // Cubic coupling between post residual and stream progress:
    // late in stream, dead space is more costly
    let prog3 = progress * progress * progress;
    score += 4.0 * norm_pr * (0.5 + prog3);

    // Interaction: post_residual vs mean residual — prefer bins diverging from mean
    // (leave other bins with average space intact)
    let dev = (mean_residual - pr) / cap;
    score -= 0.5 * dev * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    } else {
        // slight penalty when many bins compete: prefer the fullest among them
        score += 2.0 * (1.0 - fit_ratio) / fitting_bins_count.max(1) as f64;
    }

    // Lookahead: penalize if post residual cannot fit next item but almost could
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            // good: next item fits here too — reward proportional to how well
            let next_tight = 1.0 - ((pr - n) / cap);
            score -= 3.0 * next_tight * (1.0 - progress);
        } else {
            // penalize stranding: post residual too small for next item
            let gap = (n - pr) / cap;
            score += 3.0 * gap * gap * (1.0 + progress);
        }
    }

    // New-bin candidate handling: empty bin should only win for large items
    // or when no good open-bin fit exists
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - fit_ratio) * (1.0 - progress) + 2.0;
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Mild penalty for proliferating open bins early in the stream
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

