    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward compactness as a smooth function of waste fraction.
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
        if post_residual <= 5 {
            score -= 150.0;
        }
    }

    // Two-step lookahead chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
