pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by small
    // "harmonics" (10, 20, 25, 50) are more reusable for future items.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        60.0 // perfect fill
    } else if pr % 50 == 0 {
        40.0
    } else if pr % 25 == 0 {
        30.0
    } else if pr % 20 == 0 {
        24.0
    } else if pr % 10 == 0 {
        18.0
    } else if pr % 5 == 0 {
        8.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: small non-harmonic leftovers are hard to reuse.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead: strongly reward if the next item fits the post residual,
    // penalize when it almost fits (tempting but wasteful).
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 - slack * 0.3; // tight follow-up is best
        } else if next_item_size > pr && next_item_size <= pr + 10 {
            score += 12.0; // near-miss creates temptation / fragmentation
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 0.2 * (bin_residual - item_size) as f64;
    }

    // New-bin candidate handling: an empty bin has large post_residual,
    // which already scores high; add extra penalty so we only open a new
    // bin when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
    }

    // Waste-ratio coupling: penalize placements that leave residual far
    // from the mean residual (fragmenting the bin population).
    let drift = (post_residual as f64 - mean_residual).abs();
    score += 0.1 * drift;

    // Late-stream tightness: as the stream progresses, favor tighter fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold on item size: mid-size items (25..50)
    // pair well with medium residuals; very large items should grab any fit.
    let size_class = item_size / 20;
    match size_class {
        0 => score += 5.0,          // tiny items: flexible, mild penalty
        1 => score -= 3.0,          // small-mid: fits many residuals
        2 => score -= 6.0,          // mid: prioritize placement
        _ => score -= 10.0,         // large: place almost anywhere it fits
    }

    // Slight penalty for proliferating bins.
    score += 0.05 * open_bins_count as f64;

    score
}

