    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted when few bins exist.
        score += 55.0 + pressure;
        // Late in the stream, opening new bins is worse.
        score += progress * 20.0;
    } else {
