            nb -= 6.0; // big items deserve fresh bins
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size && pr > 0 {
            nb += 4.0; // poor chain fit -> opening new bin less bad
        }
        score += nb.max(-5.0);
    }

    // Tightness reward: favor bins where item fills a large fraction of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill * fill;

    // Mild penalty for very loose bins with large residual (harmonic threshold at half capacity)
    if pr > bin_capacity / 2 && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // parabolic reward for small residuals (best-heuristic style)
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // Two-step lookahead: chain placement if next item fits post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // dead space risk: residual too small for next item
            let miss = nxt - post;
            score += 40.0 * (nxt / cap);
            score += 30.0 * (miss / cap);
        }
    }

    // Tight-bin consolidation: prefer bins with below-average residual.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate branch (empty bin).
    if bin_residual == bin_capacity {
        score += 150.0; // base reluctance
        score -= 120.0 * (item / cap); // large items justify new bins
        score += 1.0 * mean_residual;
        score += 200.0 * progress; // late in stream, consolidate hard
        if fitting_bins_count == 0 {
            score -= 2000.0; // no alternative: must open
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if next_item_size > 0 && next_item_size <= item_size {
            score += 25.0 * progress * (next_item_size as f64 / cap);
        }
        // large items filling most of a fresh bin are fine
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // open-bin branch: tiny residual handling
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range slivers few items can fill
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Dead-space control: penalize new bins whose leftover can't hold next item.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        let deadness = (next_item_size - post_residual) as f64 / cap;
        score += 45.0 * deadness * (1.0 + progress);
    }

    // Avoid opening a bin when an existing bin would be left with a sliver.
    if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual < 10.0 && post_residual > 20 {
        score += 35.0;
    }

    // Mild spread-load term.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps that cannot hold a
    // meaningful item (below the minimum plausible item footprint) are
    // pure waste. Penalize tiny unusable gaps super-linearly.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item.max(0.0) {
        score += 1000.0;
    }

    // Dead-space curve: residuals that are too small to be reusable later
    // (e.g. < 10 when items are typically larger) are heavily penalized,
    // while generous residuals are mildly rewarded.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64; // tiny gap = wasted capacity
    } else if post_residual == 0 {
        score -= 20.0; // perfect fill is excellent
    }

    // Reward leaving room for the lookahead item (k=2 lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Exact match with lookahead: strongly prefer this bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }
    // Penalize placements that leave a gap just barely too small for the
    // next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Open-bins pressure: when many bins are open, prefer tightening
    // existing ones over spreading; when few are open, be pickier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: a bin whose post-residual deviates far below
    // the current mean is being "finished off" — that's good if it closes
    // the bin; bad if it strands a mid-size gap.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        if ratio < 0.35 {
            score -= 5.0 * (0.35 - ratio); // consolidating a low bin
        } else if ratio > 1.6 {
            score += 4.0 * (ratio - 1.6); // leaving a fat bin barely touched
        }
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — strong reward.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer the new bin when every existing fit would be terrible
    // (very tight fit leaving a sliver, or the item barely fits at all).
    if bin_residual == bin_capacity {
        // Base handicap so open bins with decent fits win.
        score += 18.0;
        // If item almost fills a fresh bin exactly, opening is great.
        if post_residual <= 5 {
            score -= 40.0;
        }
        // If no open bin could fit the item at all, new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, avoid proliferating bins unnecessarily.
        if progress > 0.8 {
            score += 10.0;
        }
    }

    // Tight-fit penalty: item leaving a sliver gap in a partially-filled
    // bin creates unusable dead space.
    if bin_residual < bin_capacity && post_residual > 0 && post_residual < 5 {
        score += 18.0;
    }

    // Gentle preference for filling the emptiest bins first when open-bin
    // count is high (bin consolidation pressure).
    if open_bins_count > 4 {
        score -= 0.3 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly favored.
    if post_residual == 0 {
        score -= bin_capacity as f64 * 3.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement chains perfectly — reward it heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but imperfectly: reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit in this bin after placement: penalize
            // proportionally to how much space is wasted relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.5 * waste;
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average residual is good (tight packing).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize creating large unusable dead space (post_residual too small
    // for the smallest plausible future item but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are tight
    // or this bin would leave a bad residual.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins unless they're poor fits.
        score += 30.0;
        // Early in the stream, opening bins is cheap; later, prefer filling.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
        // If many bins are open and residuals are low, new bin is reasonable.
        if open_bins_count > 0 {
            score -= 10.0 * (mean_residual / bin_capacity as f64);
        }
    }

    // Mild preference for bins with less residual overall (fill fullest first).
    score += 0.3 * bin_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, penalize awkward dead space.
    if post_residual > 0 {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fit_ratio * fit_ratio;
    } else {
        score -= 30.0; // perfect fill
    }

    // Penalize post_residual that is small but non-zero (unusable sliver),
    // especially if the next item cannot use it.
    if post_residual > 0 && next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // Reward leaving room that fits the next item
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should be chosen only when open bins
    // fit poorly. Make the empty bin moderately attractive by default but
    // penalize opening new bins when we already have many bins with slack.
    if bin_residual == bin_capacity {
        score += 8.0;
        score += 0.6 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item: a fresh bin may be useful
        }
    }

    // Global slack awareness: if mean residual across open bins is large,
    // discourage spreading items and instead fill existing slack.
    score += 0.05 * mean_residual;

    // Slight preference for bins with residuals close to the item (best-fit core).
    score += 0.15 * ((bin_residual - item_size) as f64).abs().sqrt();

    // Mild noise-free tie-breaking via bin index proxy (residual hash-free).
    score += (bin_residual % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

