pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth non-linear scaling by stream progress.
    // Early on, tight fits matter (low residual good); later, keep flexibility.
    let base = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear penalty for dead space that is too small to be useful,
    // smoothly interpolated across the stream.
    let dead = if pr > 0.0 { (1.0 - norm_pr).powi(6) } else { 0.0 };
    let dead_penalty = 12.0 * dead * (1.0 - progress) + 6.0 * dead * progress;

    // Perfect fit reward (smooth exponential).
    let perfect = -15.0 * (-pr / 5.0).exp() * (1.0 + 0.5 * progress);

    // Lookahead coupling: reward if next item fits in post-residual (smooth).
    let lookahead = if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as f64;
        let ratio = next_item_size as f64 / cap;
        -8.0 * fits * (1.0 - (ratio - norm_pr).abs())
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using this bin if it's the only fitting one.
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -20.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Coupling with mean residual: penalize bins far from the mean (smooth quadratic).
    let spread = (pr - mean_residual) / cap;
    let spread_penalty = 4.0 * spread * spread;

    // New-bin candidate: mild penalty so we prefer reusing, unless residuals are all bad.
    let new_bin = if bin_residual == bin_capacity {
        3.0 + 5.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 0.5
    } else {
        0.0
    };

    base + dead_penalty + perfect + lookahead + last_chance + spread_penalty + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Small classes are "good" (tight fit),
    // large classes are wasteful dead space.
    let quarter = bin_capacity / 4;          // 25
    let eighth = bin_capacity / 8;           // 12
    let class = post_residual / eighth;      // 0..=12 harmonic class

    // Reward tight fits: post_residual in the lowest classes.
    if post_residual == 0 {
        score -= 60.0;                       // perfect fill
    } else if post_residual <= eighth {
        score -= 40.0;
    } else if post_residual <= quarter {
        score -= 20.0;
    } else if post_residual <= 2 * quarter {
        score -= 5.0;
    } else {
        // Large dead space: penalize superlinearly.
        score += (post_residual as f64) * 0.35;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common item sizes (10, 20, 25, 50) are reusable by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 20 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        if post_residual % 50 == 0 { score -= 10.0; }
        // Odd, awkward residuals are hard to fill.
        if post_residual % 10 != 0 && post_residual < quarter {
            score += 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: mild penalty scaled by
            // how much of the residual goes unused.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.10 * waste.min(60.0);
        }
    } else {
        // Last item: prefer zero residual, otherwise nearly indifferent.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 0.1 * (post_residual as f64);
    }

    // New-bin candidate: opening a bin should only win when no open bin
    // gives a decent fit. Penalize the empty-bin call proportional to
    // stream progress and how many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // But if the item is large and mean residual is small, a new bin
        // is more attractive.
        if (item_size as f64) > mean_residual {
            score -= 30.0;
        }
    }

    // Mild pressure toward bins below mean residual (consolidation).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are worthless; residuals below the typical small-item threshold are
    // heavily penalized dead space.
    if post_residual > 0 {
        // unusable for anything: pure waste
        score += 0.0; // post_residual already counts waste linearly
        // small-gap dead space (<= 15) is quadratic waste
        if post_residual <= 15 {
            score += (16 - post_residual) as f64 * 3.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward if the leftover residual exactly accommodates the lookahead item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if leftover cannot fit the lookahead item but is large
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin
        score = bin_capacity as f64;
        score += open_bins_count as f64 * 2.0;
        // allow new bin early in stream or when open bins are nearly full on average
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 15.0;
        if mean_residual < item_size as f64 * 1.2 && open_bins_count > 0 {
            score -= 20.0;
        }
        // never open a new bin if this item fits snugly somewhere already handled
        // (handled by subtracting enough from fitting bins above)
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score += 50.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward balanced residuals (mid-size post_residual is most reusable)
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // next item cannot fit here: penalize dead space
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
        }
    } else {
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // ---- NEW-BIN branch handling ----
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if next_item_size > 0 && next_item_size <= item_size {
            score += 25.0 * progress * (next_item_size as f64 / cap);
        }
        // discourage new bin for large items
        if open_bins_count > 2 {
            let frac = item / cap;
            if frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            } else if post > 0.0 && post < 5.0 {
                score -= 90.0;
            }
        }
        // discourage new bin whose leftover can't hold the next item
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
        }
        // penalize new-bin leftover that is likely dead space
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 45.0 * deadness * (1.0 + progress);
        }
        // reward new bin when item nearly fills it exactly
        if post_residual > 0 && item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // open-bin branch: reward tiny residuals even harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals that few items can fill
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Late in stream: be more conservative, prefer tight fits
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fit (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // perfect chain
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits
    // well (large post_residual everywhere) and the next item is large.
    if bin_residual == bin_capacity {
        let waste = item_size as f64; // fresh bin wastes item_size of capacity vs perfect fit
        let open_pressure = if open_bins_count == 0 { 0.0 }
            else { (mean_residual / bin_capacity as f64).powi(2) * 400.0 };
        let lookahead_penalty = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64) * 80.0
        } else { 0.0 };
        score = waste + open_pressure + lookahead_penalty;
        if fitting_bins_count == 1 {
            score += 500.0; // never open a new bin when a bin fits and it's the only one
        }
    }

    // Mild progression bias: later in the stream, prefer consolidating items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64;

    score
}

