    score -= fill_ratio * 12.0;

    // Dead-space penalty: residuals too small for any plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves more fragmentation: mild reward scaled by fit quality
            let fit_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
