        } else {
            // next item won't fit here: penalize slightly, worse if post residual is large
            score += (post_residual as f64) * 0.08;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are mostly full or none exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // discourage new bin early / when open bins still have room
        score += 20.0 + (open_bins_count as f64) * 2.0;
