    // Mild preference for bins tighter than average (better global packing).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Late in the stream, consolidate: penalize spreading across many bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * 0.5 * progress;

    score
}

