    // Reward residuals that form perfect-fit classes (multiples of quarter/eighth)
    if post_residual > 0 {
        if post_mod_q == 0 {
            score -= 12.0;
        }
        if post_mod_e == 0 {
            score -= 6.0;
        }
    }

    // Exact fit is always excellent
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this bin strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // extra reward if next item exactly fills post_residual (perfect chain)
        if next_item_size == post_residual {
            score -= 30.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize proportionally to wasted class
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make empty bin neutral-to-slightly-costly
    if bin_residual == bin_capacity {
        score = cap * 0.5;
        // open a new bin only if current open bins are crowded or item is huge
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if item_size > bin_capacity * 3 / 4 {
            score -= 15.0;
        }
        if fitting_bins_count <= 1 && open_bins_count > 0 {
            // last chance exists; new bin should lose unless mean residual is tiny
            score += (mean_residual / cap) * 50.0;
        }
        // early stream: allow opening bins more freely
        score -= (1.0 - progress) * 10.0;
    }

    // Mild preference for fuller bins (small post_residual) scaled by stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post_residual as f64 / cap) * (5.0 + 10.0 * progress);

    // Tie-break by mean residual alignment: prefer bins near the mean residual class
    let diff = (post_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else {
        // curved reward for compact residuals
        score -= 120.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead with chaining reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 500.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 100.0;
            }
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 2.0;
            score += 40.0 * (nxt / cap) * progress;
        }
    }

    // Consolidation: prefer tight bins (below-average residual).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 200.0;
    } else if fitting_bins_count > 1 {
        score += 25.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Penalize tiny unusable residuals.
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: reluctance scaled by progress and mean residual.
        score += 60.0 + 200.0 * progress;
        if item_size >= 60 {
            score -= 60.0 * (1.0 - progress);
        }
        if mean_residual < 15.0 {
            score -= 90.0;
        }
        score += 1.0 * mean_residual;
        // large items nearly filling a fresh bin are good openings
        let frac = item / cap;
        if frac > 0.9 {
            score -= 30.0 * (frac - 0.9) * 10.0;
        } else if frac > 0.5 && open_bins_count > 2 {
            score += 140.0 * (frac - 0.5);
        }
        if fitting_bins_count == 0 {
            score -= 2000.0;
        }
        // dead-space lookahead for the new bin's residual
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 45.0 * deadness * (1.0 + progress);
        }
    } else {
        // open-bin branch: extra hard reward for slivers, especially late
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // penalize mid-range residuals early (few items can fill them later)
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild load-spreading term.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small to fit even the smallest item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Penalize if the lookahead item cannot fit in the post residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 60.0 + (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving room for the next item.
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 25.0;
    if bin_residual != bin_capacity {
        score -= pressure;
    } else {
        // New-bin candidate: penalize opening a new bin, more so with many open bins.
        score += 80.0 + pressure;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Tight-fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 40.0 * fill_ratio;
    }

    // Penalize wasteful residuals relative to mean residual across bins.
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 20.0;
    }

    score
}

