pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual more strongly as it approaches 0.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for typical future items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; mildly penalize leaving large gaps
            score += 0.05 * post_residual as f64;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so new bins are opened only with reason.
        score += 8.0;
        // Early in stream, opening bins is cheaper (more future items to fill them).
        score -= 6.0 * (1.0 - progress);
        // If mean residual across open bins is low, open bins are congested -> new bin ok.
        score -= 0.15 * (cap - mean_residual).max(0.0);
        // If no open bin fits (this is the only candidate), strongly favor opening.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        // Few open bins with large mean residual -> prefer reusing existing bins.
        score += 0.3 * open_bins_count as f64 * (mean_residual / cap);
    } else {
        // Prefer bins whose residual is closest to item size (best-fit flavor).
        let gap = (bin_residual - item_size) as f64;
        score += 0.02 * gap * gap / cap;

        // Prefer bins below mean residual (fill emptier bins first keeps big bins flexible).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 0.5;
        }
    }

    // Mild time-varying exploration pressure.
    let phase = ((step_index as f64 * 0.017).sin()) * 0.5;
    score += phase * (post_residual as f64 / cap);

    score
}

