    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = (pr / cap).clamp(0.0, 1.0);
    let t = progress.clamp(0.0, 1.0);
    let coupling = x * x * (1.0 - t) + x * t * t;
    score += 12.0 * coupling * (0.5 + t);

    // Penalize large dead space more than proportionally (quadratic waste).
    score += 0.35 * pr * pr / cap;

    // Reward tight fits: small post_residual gets subtractive bonus.
    if pr > 0.0 {
        score -= 18.0 * (-pr / 12.0).exp();
    }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fit_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 14.0 * fit_quality * fit_quality;
        } else {
            // Next item won't fit here: penalize residual that blocks nothing.
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into fuller bins.
    let fullness = 1.0 - x;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * fullness;

    // Mean residual context: penalize bins far above mean residual (wasteful outliers).
    score += 2.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 30.0 * (1.0 - t) - 10.0 * t;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= cap - item_size as f64 {
            score -= 5.0;
        }
    }

    score
}

