        2 => 20.0,
        3 => 10.0,
        4 => 4.0,
        _ => 0.0,
    };

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how well it uses the leftover
            let nxt_class = (post_residual - next_item_size) / 10;
            score -= 25.0 - (nxt_class as f64) * 4.0;
        } else {
            // next item cannot use this residue: penalize large leftover classes
            score += (post_residual / 20) as f64 * 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins with large mean residual: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score -= pressure * 12.0;
    }

    // New-bin candidate (empty bin): penalize unless residue classes make it attractive.
    if bin_residual == bin_capacity {
