pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead: chain fits.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // dead space risk: next item won't fit in the leftover
            let miss = (nxt - post) / cap;
            score += 45.0 * miss * (1.0 + progress);
        }
        // prefer bins whose residual closely matches next item
        let gap = (post - nxt).abs();
        if gap < 8.0 {
            score -= 15.0 * progress;
        }
    }

    // Consolidation: prefer tighter bins relative to the mean.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Small unusable sliver penalty.
    if post_residual > 0 && post_residual < 4 {
        score -= 40.0 + 70.0 * progress;
    } else if post_residual > 0 && post_residual < 25 {
        score += 8.0 * (1.0 - progress);
    }

    // NEW-BIN CANDIDATE branch.
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        score += 80.0 * progress * (mean_residual / cap);
        let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        if next_item_size > 0 && next_item_size <= item_size {
            score += 25.0 * progress * (next_item_size as f64 / cap);
        }
        // large items early: allow fresh bins to preserve flexibility
        if item / cap > 0.5 {
            score += 140.0 * (item / cap - 0.5);
        }
        // near-perfect opening: item almost fills the new bin
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
        // if mean residual is large, open bins are wasteful — prefer consolidation
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        // discourage new bin whose leftover can't hold next item
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    } else {
        // open-bin branch: mild penalty for mid-range residuals early on
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Slight spreading cost with many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "unusable" if it is smaller than the smallest plausible item (1)
    // relative to typical item scale; treat gaps < 10 as near-dead, < 20 as risky.
    let gap = post_residual as f64;
    if gap > 0.0 {
        if gap < 10.0 {
            score += 60.0; // completely wasted space
        } else if gap < 20.0 {
            score += 25.0; // risky dead space, few items can fit
        } else if gap < 35.0 {
            score += 8.0; // mildly awkward gap
        }
    }

    // Reward tight fits: the smaller the gap relative to bin capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading items; with few bins, consolidation is naturally favored.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        // existing bin: reward using it when many bins are open
        score -= 6.0 * pressure;
    } else {
        // new-bin candidate: penalize opening a bin when open bins exist
        score += 18.0 + 10.0 * pressure;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward it
    // (perfect chaining); if next item cannot fit anywhere else well, avoid
    // leaving a gap that blocks it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size > post_residual {
            score += 10.0; // this placement strands the next item
        } else {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 20.0; // next item leaves near-perfect fill
            }
        }
    }

    // Progress-based refinement: later in the stream, be more aggressive at
    // closing bins (favor small post_residual even more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // Mean residual coupling: if open bins already have lots of space on
    // average, mildly discourage adding to the clutter unless fit is tight.
    if bin_residual != bin_capacity && mean_residual > 40.0 && gap > 30.0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
