    }

    // Compare against mean residual of open bins: bins with residual below mean
    // are "almost full" -> prefer filling them.
    if (post_residual as f64) < mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fits win.
        score += 150.0;
