        // Few open bins and large item: opening fresh may be wise.
        if open_bins_count <= 2 && item_size > bin_capacity / 2 {
            score -= 80.0;
        }
    }

    // Mild penalty for leaving a residual that exactly matches a large chunk of capacity
    // wasted when the bin could have absorbed a bigger item later.
    if post_residual > 0 && post_residual < item_size {
        score += 5.0;
    }

    score
}

