            score += 140.0 * (frac - 0.5);
        }
        // Near-full opening of a new bin is efficient.
        if frac > 0.9 {
            score -= 30.0 * (frac - 0.9) * 10.0;
        }
        // Dead-space penalty for new-bin leftover that can't hold next item.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let deadness = ((next_item_size - post_residual) as f64) / cap;
            score += 45.0 * deadness * (1.0 + progress);
        }
        // Low mean residual pressure: opening a new bin is acceptable.
        if mean_residual < 15.0 {
            score -= 80.0;
        }
    } else {
        // Open-bin branch: reward tiny residuals harder late in stream.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // Prefer bins whose residual closely matches next item even if not fitting now.
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // Mild penalty for mid-range residuals few items can fill.
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild load spreading.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize creating dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space relative to lookahead: worse when very small.
            let dead = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.5 * dead;
        } else if post_residual >= next_item_size && next_item_size > 0 {
            // Reward leaving room exactly for the lookahead item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize placing into nearly-full bins when many alternatives exist.
    if open_bins_count > 1 && fitting_bins_count > 1 {
        let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score += 8.0 * fill_frac * (fitting_bins_count as f64).ln().max(1.0);
    }

    // Global pressure: when mean residual is low, conserve space (penalize waste).
    let mr_norm = mean_residual / bin_capacity as f64;
    score += 10.0 * (1.0 - mr_norm) * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, be more willing to spread items
    // (penalize opening new bins less); late in the stream, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * tightness;

    // New-bin candidate handling: only attractive when existing fits are poor
    // (i.e., post_residual here is large for a fresh bin, and few bins fit).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || next_item_size == 0 {
            score -= 10.0;
        } else {
            // Fresh bin wastes capacity; make it moderately unattractive
            // unless it enables a perfect lookahead pairing.
            if post_residual == next_item_size {
                score -= 30.0; // perfect pairing: item + next item fills bin
            } else {
                score += 18.0 + 0.2 * (open_bins_count as f64);
            }
        }
    }

    // Mild preference for bins whose residual is close to the mean
    // (keeps the bin profile balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly damped
    let mut score = pr * (0.9 + 0.2 * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 40.0 * poly * (0.5 + t);

    // Penalize large residuals late in the stream (dead space matters more)
    score += 30.0 * norm_pr * norm_pr * t;

    // Reward tight fits (small post residual) via smooth saturating term
    score -= 25.0 * (-norm_pr * 8.0).exp();

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 20.0 * (1.0 - (nxt / cap)) * (0.5 + t);
        } else {
            // penalize residuals that waste space relative to next item
            score += 10.0 * (pr - nxt).max(0.0) / cap * t;
        }
    }

    // Slight preference to fill bins when many bins are open
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Deviation from mean residual: prefer bins near the mean (balanced packing)
    score += 5.0 * (pr - mean_residual).abs() / cap;

    score
}

