pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain classes.
    // Residuals that are "small and awkward" (1..=9) are nearly unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else {
        // Modulo-class penalty: residuals mod 10 near 0 are "harmonic" (easy to fill
        // with typical items), residuals in mid-class (mod 10 in 4..=6) are awkward.
        let m = post_residual % 10;
        if m >= 4 && m <= 6 {
            score += 4.0;
        } else {
            score -= 2.0;
        }
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 15.0;
            } else {
                score -= 8.0 * (1.0 - gap / cap);
            }
        } else {
            // Next item cannot follow here: penalize mildly, worse if this was
            // the only fitting bin (last-chance logic handled separately).
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 0.5 * (item_size as f64);
    }

    // New-bin candidate handling: empty bin should only win when current bin fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open early in stream when few bins exist? Actually penalize
        // opening when many open bins have slack already.
        score += 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is wasteful.
        score += 0.6 * mean_residual;
        // But if next item is huge and current fit would leave tiny residue,
        // opening fresh may be right: discount slightly.
        if next_item_size > 0 && next_item_size >= post_residual + 60 {
            score -= 15.0;
        }
        // Late in stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild preference for fuller bins overall (compare against mean residual).
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Integer-division threshold: bins whose residual can hold exactly two more
    // typical items (residual/2 >= 10 and residual % 2 == 0) are flexible.
    if post_residual >= 20 && post_residual % 2 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are almost unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to item size.
    let tightness = (bin_residual - item_size) as f64 / item_size as f64;
    score -= 25.0 / (1.0 + tightness);

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here: post residual becomes dead space.
            score += 10.0 + 0.2 * post_residual as f64;
        }
    }

    // Open-bin pressure: discourage scattering across many bins.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins are quite full.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when worthwhile.
        score += 30.0;
        // If mean residual of open bins is small (bins nearly full), new bin is fine.
        score -= mean_residual * 0.5;
        // Early in the stream, opening a bin is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    } else {
        // Prefer bins whose residual is close to the mean (balanced packing).
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

