pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // Next item fits: penalize by the leftover slack after the next item
            // (tighter two-item packing is better), but still favor it.
            let after_next = (post_residual - next_item_size) as f64;
            score -= 200.0;
            score += after_next * 0.8;
        } else {
            // Next item does NOT fit in the leftover: leftover is likely dead space
            // unless it's small. Penalize proportionally.
            let dead = post_residual as f64;
            score += dead * 0.5;
        }
    }

    // Coupling with mean residual: bins whose post residual is far below the
    // mean residual are being "used up" — that's good (drives bins to closure).
    let mean_post = mean_residual - item_size as f64;
    score -= (mean_post - post_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: empty bin should only win when no open bin gives a
    // decent fit. Penalize the fresh bin, more so early on when open bins exist.
    if bin_residual == bin_capacity {
        let newbin_penalty = 120.0 + 200.0 * progress;
        score += newbin_penalty;
        // But if the item is large and would leave a large residual elsewhere,
        // opening fresh is fine — soften penalty for big items.
        score -= (item_size as f64 - 50.0).max(0.0) * 1.5;
    }

    // Slight preference for filling fuller bins as stream progresses.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill of the bin by this item: reward tight fits.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill * fill;

    // Penalize large absolute post-residual relative to capacity (dead space).
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * dead * dead * dead;

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 80.0;
        } else if next_item_size as u32 <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            let over = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 15.0 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large and fits poorly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so existing bins are preferred.
        score += 55.0;
        // Relax penalty late in the stream or when few bins fit the item.
        score -= 30.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
