        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + 2.0 * progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap) * progress;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild penalty for proliferation of open bins relative to mean residual
    score += 0.5 * (open_bins_count as f64) * (1.0 - norm_pr) * (1.0 - progress);

    // Prefer bins with residual below mean (consolidation of space)
