    // New-bin candidate: penalize slightly unless current residuals are large
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" are more likely to be closed out efficiently.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                 // perfect fit
        1..=5 => 1.0,             // near-perfect dead space (hard to reuse)
        6..=15 => 2.0,            // awkward gap
        16..=30 => 3.0,           // reusable by small items
        31..=60 => 4.0,           // reusable by medium items
        _ => 5.0,                 // large residual, very reusable
    };
    score += class * 3.0;

    // Perfect fit bonus: heavily reward exact closure.
    if pr == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead-space classes proportionally harder.
        if pr <= 5 {
            score += 25.0;
        } else if pr <= 15 {
            score += 10.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr && (pr - next_item_size) <= 5 {
            score -= 20.0;
        } else if next_item_size <= pr {
            // next fits but leaves residue: mild reward scaled by reuse class
            let nxt_class = match pr - next_item_size {
                0 => 0.0,
                1..=5 => 1.0,
                6..=15 => 2.0,
                _ => 3.0,
            };
            score -= 12.0 - nxt_class * 2.0;
        } else {
            // next item cannot use this residual: slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when
    // decent fitting bins exist. Penalize the empty-bin call unless the
    // item is large relative to residual of typical open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin early (bins are cheap) or when mean residual is tight
        // (existing bins are fragmented).
        let fragmentation = (mean_residual / cap) - (post_residual as f64 / cap);
        let mut new_bin_score = 40.0 - 30.0 * progress;
        if fragmentation > 0.0 {
            new_bin_score += 15.0 * fragmentation;
        }
        if item_size >= 60 {
            new_bin_score += 10.0; // big items deserve fresh bins
        }
        score += new_bin_score;
    } else {
