    // A residual below ~10 is essentially dead space; penalize it heavily.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward: strongly favor bins that end up (nearly) full.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead space relative to the smallest plausible item: if the gap is smaller
    // than a typical small item, it is wasted capacity.
    let dead = (post_residual as f64) * ((post_residual as f64) / 10.0).min(3.0);
    score += dead * 0.5;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // rather than spreading; add a mild penalty that scales with open_bins_count
    // for leaving large residuals behind.
    let pressure = (open_bins_count as f64 / 20.0).min(2.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Only prefer opening a new bin when existing bins would leave very poor fits.
