    // Penalize leaving dead space that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits post_residual perfectly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = (post_residual - next_item_size) as f64;
            score -= (30.0 - next_fit.min(30.0)) * 0.8;
