        let nx = next_item_size as f64 / cap;
        let coupling = fits_next * (1.0 - nx) * (1.0 - nx);
        score -= 10.0 * coupling * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and mean residual is usable
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let usable = (mean_residual / cap).min(1.0);
        score += 8.0 + 20.0 * usable * usable * (1.0 - progress);
    }

    // Mild pressure toward consolidating bins as stream progresses
    score += 0.02 * open_bins_count as f64 * (0.2 + 0.8 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are exact divisors of capacity
    // are "perfect" dead space classes; reward hitting them.
    let perfect = post_residual == 0 || bin_capacity % post_residual.max(1) == 0;
    if perfect {
        score -= 12.0;
    }

    // Integer-division threshold classes on post_residual (dead-space bands)
    let cls = post_residual / 10; // classes 0..10
    score += match cls {
        0 => -20.0,           // perfect fit
        1 => -8.0,            // tiny leftover, likely reusable
        2 | 3 => -2.0,
        4 | 5 => 4.0,
        6 | 7 => 9.0,
        _ => 14.0,            // large wasted space
    } as f64;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_cls = (post_residual - next_item_size) / 10;
            score -= (10 - nxt_cls.min(9)) as f64 * 1.5;
        } else {
            // next item won't fit here; residual becomes dead unless perfect class
            if !perfect {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad;
    // but allow it late in the stream or when many bins are already open with
    // low mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * progress - (mean_residual / bin_capacity as f64) * 10.0;
        if perfect {
            score += 5.0; // don't open new bin if some bin hits a perfect class
        }
    }

    // Modulo-2 parity harmonic of post_residual (even residuals pair better with
    // typical item sizes)
    if post_residual % 2 == 0 {
        score -= 1.0;
    }

    // Small global pressure: more open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item (min 1)
    // can use are pure waste; residuals below typical small-item sizes are
    // likely dead. Penalize tiny-but-nonzero gaps superlinearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr <= 10.0 {
            // unusable / near-unusable gap: heavy penalty
            score += 60.0 * (10.0 - pr + 1.0) / 11.0;
        } else if pr <= 25.0 {
            // awkward mid gap: moderate penalty
            score += 15.0 * (25.0 - pr) / 15.0;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize if post_residual is slightly larger than next item (teasing gap)
    if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score += 10.0;
    }

    // Tight-fit reward: fraction of bin consumed by this placement
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac;

    // Open-bin pressure: with many open bins, prefer packing into existing
    // bins rather than spreading; penalize placements that keep many bins alive.
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    // Opening a new bin is only attractive when existing fits are terrible
    // (large dead space would result) or no bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 45.0;
        // early in stream, opening bins is cheaper (we need bins anyway)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // if many bins open and mean residual is high, discourage new bin
        score += open_bins_count as f64 * 1.5;
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
    } else {
        // existing bin: encourage reuse especially when mean residual is high
        score -= 5.0;
    }

    // Prefer bins whose residual is close to item (best-fit core), scaled
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            score -= 25.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            // penalize leaving awkward mid-range residual after two steps
            if next_post > 0 && next_post < 10 {
                score += 15.0;
            }
        } else {
            // next item cannot fit here; penalize proportionally to the shortfall
            let shortfall = (next_item_size - post_residual) as f64;
            score += 8.0 + 0.15 * shortfall;
        }
    } else {
        // last item: strongly prefer minimal post_residual
        score += 20.0;
    }

    // Tight-fit reward on the current placement
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness;
    if post_residual == 0 {
        score -= 40.0; // perfectly closed bin
    } else if post_residual < 10 {
        score -= 10.0; // near-perfect fill, dead space is tiny
    } else if post_residual < 20 {
        score += 3.0;
    }

    // Relative to mean residual: prefer filling bins that are already low
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.35 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early,
    // cheap late when many bins are open and residuals are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - res).abs();
        score += 25.0 + 60.0 * (1.0 - progress);
        if fragmentation > 25.0 && open_bins_count > 2 {
            score -= 20.0; // allow new bin when existing bins are fragmented
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 100.0; // impossible, but guard
        }
    }

    // Slight preference for bins with more residual consumed overall
    score += 0.05 * (bin_capacity - bin_residual) as f64 * -0.0;
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches item size.
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    let fit_ratio = slack / bin_capacity as f64;
    score -= 30.0 * (1.0 - 2.0 * fit_ratio).max(0.0) * (1.0 - fit_ratio);

    // Penalize leaving awkward dead space (small but unusable residuals).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins that can also host the next item after this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= item_size + next_item_size {
            score -= 6.0;
        } else {
            score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // New-bin candidate logic: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { fit_ratio.min(1.0) };
        score += 15.0;               // default cost of opening a new bin
        score += 20.0 * (1.0 - poor_fit); // discount when open bins fit badly
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;            // pair potential in a fresh bin
        }
    }

    // Global state coupling: many open bins with large mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (open_bins_count as f64).ln() * mean_residual / bin_capacity as f64;
    score += consolidation * (2.0 + 3.0 * progress);

    // Mild time pressure: later in the stream, prefer tighter placements even more.
    score -= 10.0 * progress * (1.0 - fit_ratio);

    score
}

