pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Strong reward for exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else {
        // Smooth reward peaking for small residuals.
        score -= 120.0 * (1.0 - post / cap) * (post / cap);
    }

    // Two-step lookahead chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 700.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 400.0;
            }
        } else {
            // Next item won't fit after this placement: dead-space risk.
            let miss = (nxt - post) / cap;
            score += miss * 250.0 * (1.0 + progress);
        }
    }

    // Consolidation: prefer tighter (below-average residual) bins.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: strong preference.
    if fitting_bins_count == 1 {
        score -= 220.0;
    }

    // New-bin candidate branch.
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 130.0 * (item / cap); // large items justify a fresh bin
        score += 1.0 * mean_residual;
        score += 180.0 * progress; // late in stream, avoid new bins
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        // New bin opening that leaves a residual the next item can fill is fine.
        if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
            score -= 60.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap);
        }
        // Discourage opening a bin that leaves dead space vs. next item.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 60.0 * progress + 25.0 * ((next_item_size - post_residual) as f64 / cap);
        }
        // Very large item nearly filling a fresh bin: attractive.
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // Open-bin branch: punish sliver residuals that few future items fill.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
        // Prefer bins whose residual is close to the next item even if it won't fit now.
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
    }

    // Mild load-spreading term.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth polynomial coupling: residual penalty grows non-linearly with progress
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 12.0 * poly;

    // Reward tight fits, more strongly late in the stream
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 * (1.0 - tightness.abs() * 0.5);
    }

    // Lookahead: penalize leaving residuals that can't fit the next item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let smooth = 1.0 / (1.0 + (-(post_residual as f64 - next_item_size as f64) / 10.0).exp());
        score += 5.0 * (1.0 - smooth) * (1.0 - fits_next * 0.8);
    }

    // Penalize opening new bins when many open bins exist, smoothly with progress
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    } else {
        score -= 2.0 * (mean_residual / bin_capacity as f64 - norm_pr).abs();
    }

    // Mild global residual dispersion penalty
    score += 0.02 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by 10 are
    // "harmonic" (likely to be exactly filled by future items).
    let harmonic = (post_residual % 10 == 0) as f64;
    score -= harmonic * 6.0;

    // Perfect fit: zero waste is always best.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize small non-harmonic dead space (1..9) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division class of post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let q_class = post_residual / quarter; // 0..4
    score -= q_class as f64 * 2.0;

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // Bonus if next item exactly fills post-residual.
            if next_item_size == post_residual {
                score -= 15.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // current bin fits are poor (large post_residual waste) or none exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Mild penalty so real bins are preferred unless waste is big.
        score += 5.0 + 10.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 6.0; // pairing potential in fresh bin
        }
    }

    // Prefer filling bins below the current mean residual (tighter bins first).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Reward compacting many open bins rather than spreading.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5 * harmonic;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range,
    // but min item ~10 historically; be conservative with < 12) are heavily penalized.
    let dead_threshold = 11.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward fits that leave a still-usable gap (>= next item size if known).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of all open bins; penalize
        // proportionally to open bins and their average residual.
        score += 20.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3;

        // But if this bin is the only option, allow opening a new bin.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }

        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    } else {
        // Using an existing bin: mild reward, stronger when it's the last fitting bin.
        score -= 5.0;
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Slight preference for bins with tighter residuals (best-fit coupling).
    score += (bin_residual as f64 - post_residual as f64 - item_size as f64).abs() * 0.0
        + (bin_capacity as f64 - bin_residual as f64) * 0.05;

    // Mean-residual coupling: if this bin is far above mean residual, prefer it
    // (drain large-residual bins first to consolidate space).
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward residual classes that stay reusable
        let post_frac = post / cap;
        score -= 300.0 * (1.0 - post_frac) * post_frac;
        if post_residual >= 20 && post_residual <= 60 {
            score -= 25.0 * progress;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 50.0 + 30.0 * progress; // dead sliver, penalize more late
        } else if post_residual >= 10 && post_residual < 20 {
            score += 15.0;
        }
        // mid-range residuals that few items can fill: mild penalty early
        if post_residual >= 10 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 30.0 * ((post - nxt) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 120.0;
            score += 1.0 * mean_residual;
            score += 170.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            // Dead-space control: penalize new bins opened for large items
            let frac = item / cap;
            if frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            }
            // reward near-perfect fills of a fresh bin (low dead-space opening)
            if frac > 0.9 {
                score -= 300.0 * (frac - 0.9);
            }
            // Discourage a new bin whose leftover cannot hold the next item
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                let deadness = (next_item_size - post_residual) as f64 / cap;
                score += 60.0 * progress + 45.0 * deadness * (1.0 + progress);
            }
            // open-bin pressure: fewer open bins relative to stream -> prefer reuse
            let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
            score += 90.0 * progress * (1.0 - open_frac.min(1.0));
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
        // avoid opening a bin when an existing bin would be left with unusable sliver
        if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual < 10.0 && post_residual > 20 {
            score += 35.0;
        }
    } else {
        // Open-bin branch: reward near-perfect fits late; prefer bins whose residual
        // closely matches the next item even if it doesn't fit now
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // reward bins that become nearly full (post residual small relative to capacity)
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 250.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here: penalize dead space, stronger late
            score += (40.0 + 60.0 * progress) * ((next_item_size - post_residual) as f64 / cap);
        }
    } else {
        // last item: prefer minimal waste
        score += (bin_residual - item_size) as f64 * 0.5;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += (mean_residual - bin_residual as f64) * 0.6;

    // NEW-BIN CANDIDATE handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        score += 150.0;
        // large items justify a new bin more (less likely to fit elsewhere well)
        score -= 120.0 * (item / cap);
        // late in the stream, opening bins is worse (fragmentation)
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            // no alternative: must open
            score -= 2000.0;
        } else {
            // many alternatives: opening is risky
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        // discourage new bin whose leftover can't hold the next item
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
        }
        // reward opening when item nearly fills it exactly
        if item / cap > 0.9 {
            score -= 300.0 * (item / cap - 0.9);
        }
    } else {
        // open-bin branch
        // last-chance bin bonus: avoid opening new bins unnecessarily
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
        // reward tiny residuals, stronger late
        if post_residual > 0 && post_residual < 4 {
            score -= 40.0 + 70.0 * progress;
        }
        // penalize creating tiny unusable residuals (below min item size range)
        if post_residual > 0 && post_residual < 10 {
            score += 150.0 * (1.0 - 0.5 * progress);
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals that few items can fill, early only
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Late in stream: be more conservative, prefer tight fits
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

