    // (consolidating space), penalize leaving this bin above-average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large relative to capacity or no open bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - large_item); // penalize new bin for small items
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity - item_size) as f64 {
            score -= 30.0; // new bin can host the chained pair
