        if gap > 0.0 && gap < 10.0 {
            score += 5.0 * (1.0 - gap / 10.0);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean residual alignment: prefer bins close to mean residual (smooth)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 4.0 * dev * dev * cap * 0.1;

