        if post_residual > 0 && post_residual < 10 {
            score += 50.0 + 30.0 * progress;
        } else if post_residual >= 10 && post_residual < 20 {
            score += 15.0;
        }
        // NEW: penalize mid-range residuals that few items can fill
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 150.0;
            score -= 120.0 * (item / cap);
            score += 1.0 * mean_residual;
            score += 200.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            score += 80.0 * progress * (mean_residual / cap);
            let open_frac = open_bins_count as f64 / (total_items.max(1) as f64);
            score += 90.0 * progress * (1.0 - open_frac.min(1.0));
            if next_item_size > 0 && next_item_size <= item_size {
                score += 25.0 * progress * (next_item_size as f64 / cap);
            }
            // Dead-space control for large items
            let frac = item / cap;
            if open_bins_count > 2 && frac > 0.5 {
                score += 140.0 * (frac - 0.5);
            }
            // Reward near-perfect new-bin openings
            if post_residual > 0 && frac > 0.9 {
                score -= 300.0 * (frac - 0.9);
            }
            // Discourage new bin whose leftover cannot hold the next item
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                let deadness = (next_item_size - post_residual) as f64 / cap;
                score += (60.0 * progress + 20.0 * deadness) * (1.0 + 0.5 * progress);
            }
            // Avoid opening a bin when existing bins would be left with unusable slivers
            if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual < 10.0 && post_residual > 20 {
                score += 35.0;
            }
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
    } else {
        // Open-bin branch: reward near-perfect fits late; prefer bins whose residual
        // closely matches the next item even if it doesn't fit now
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small moduli.
    // Small post-residuals that are "harmonically useful" (divisible by common
    // item size classes 10/20/25/50) are rewarded; awkward residues penalized.
    let pr = post_residual;
    if pr > 0 {
        // class penalty: awkward leftover space
        let mut class_pen = 0.0;
        if pr % 10 == 0 { class_pen -= 4.0; }
        if pr % 20 == 0 { class_pen -= 2.0; }
        if pr % 25 == 0 { class_pen -= 2.0; }
        if pr % 50 == 0 { class_pen -= 3.0; }
        // dead-space threshold classes via integer division
        let q = pr / 10;
        if q == 0 { class_pen += 8.0; }        // 1..9 : nearly dead
        else if q <= 2 { class_pen += 3.0; }   // 10..29: hard to fill
        else if q <= 4 { class_pen -= 1.0; }   // 30..49: moderate
        else { class_pen -= 2.0; }             // >=50: flexible
        score += class_pen;
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 && pr >= next_item_size {
        let nxt = next_item_size as f64;
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 25.0; // chain perfect fit
        } else {
            // fractional coupling: how much of the residual the next item consumes
            let fill = nxt / pr as f64;
            score -= 10.0 * fill;
            if slack % 10 == 0 { score -= 3.0; }
        }
    } else if next_item_size > 0 && pr > 0 {
        // next item cannot use this residual: penalize proportional to waste
        score += (next_item_size as f64 - pr as f64).min(20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are already tight on average.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = mean_residual / bin_capacity as f64;
        // opening a new bin costs ~1 bin; make it score like a mediocre fit
        let mut new_bin_score = 55.0;
        new_bin_score -= 30.0 * (1.0 - tightness); // tight open bins -> prefer new bin
        new_bin_score -= 20.0 * progress;          // late stream -> prefer new bin
        new_bin_score += 5.0 * (open_bins_count as f64).ln_1p();
        score = score.min(new_bin_score) * 0.0 + new_bin_score.max(score.min(new_bin_score));
        // ensure a genuinely good existing fit still beats a new bin
        if post_residual == 0 { score = -100.0; }
    }

    // Mild preference to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

