pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item
    // (items in 1..=100, so any residual < 1 is impossible; treat tiny residuals
    // as "perfect fit" reward, but small-but-nonzero gaps as dead space).
    if post_residual == 0 {
        // Perfect fit: strongly favor closing this bin exactly.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable sliver: penalize heavily beyond its raw size.
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that blocks the next item: mild dead-space penalty scaled by gap size.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading items
    // into fresh bins; prefer filling existing ones.
    score += open_bins_count as f64 * 0.3;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight — favor placing here to consolidate.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.4;
    } else {
        score += (resid_f - mean_residual) * 0.2;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 80.0;
    }

    // Slight tightness bonus proportional to fill ratio.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Progress term: late in the stream, closing bins cleanly matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual == 0 {
        score -= progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward when the next item exactly fills the post-residual (perfect 2-step match)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // exact 2-item completion
        } else if post_residual > next_item_size {
            // next item fits; penalize leftover after that hypothetical placement
            let two_step_left = post_residual - next_item_size;
            score += two_step_left as f64 * 0.5;
        } else {
            // next item won't fit in this bin afterwards
            score += 6.0;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Penalize large dead space that nothing typical can use
    if post_residual > 0 && post_residual < 10 {
        score -= 4.0; // near-perfect fill
    }
    if post_residual >= 10 && post_residual < item_size.min(80) {
        score += 3.0; // dead space too small for typical next items
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 5.0; // fresh bin allows a clean 2-item pairing
        }
        if fitting_bins_count <= 1 {
            score -= 18.0; // opening new bin is reasonable when fits are scarce
        }
    }

    // Late-stream tightening: prefer tight fills as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

