pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            score += 4.0 * ((next_item_size - post_residual) as f64 / item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state: when many bins are open, prefer filling existing ones.
    let open_pressure = (open_bins_count as f64).ln() + 1.0;
    score += 6.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins close to mean residual (balanced packing),
    // unless a very tight fit exists.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    // Time horizon: early in stream, be conservative about new bins;
    // late in stream, prefer closing out bins with large residuals.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well or bin is very full.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by stream progress and open count.
        let mut new_bin_score = 55.0 + 40.0 * (1.0 - t) + 3.0 * open_bins_count as f64;
        // If this is the only fitting option, new bin is necessary -> neutral score.
        if fitting_bins_count == 1 {
            new_bin_score -= 60.0;
        }
        // Large items relative to capacity favor fresh bins.
        new_bin_score -= 15.0 * (item_size as f64 / bin_capacity as f64);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + progress) + norm_pr * progress * progress;
    score += 12.0 * coupling;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize leaving dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) * (0.5 + progress);
        } else {
            score -= 2.0 * (1.0 - (pr - nxt) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - norm_pr) * (0.5 + progress);
    }

    // Slight preference to fill bins when many bins are open
    score -= 2.0 * (1.0 - norm_pr) * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));

    // Smooth mean-residual alignment bonus
    let align = (mean_residual - pr).abs() / cap;
    score -= 3.0 * (1.0 - align).max(0.0) * progress;

    // New-bin candidate: penalize mildly unless current bin fit is poor
    if bin_residual == bin_capacity {
        score += 10.0 - 18.0 * norm_pr.min(1.0) * 0.0; // empty bin: norm_pr=1
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class decomposition of post_residual ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction remaining

    // Perfect fit: zero residual is ideal
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space classes: tiny residuals (1..=5) are nearly useless
    if post_residual > 0 && post_residual <= 5 {
        score += 120.0;
    }
    // Modulo-10 harmonic band: residuals that are multiples of 10
    // (aligned with the classical size grid) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    }
    // Integer-division threshold classes on post_residual
    let class = post_residual / 20; // 0..5 classes: [0,20),[20,40),...
    score -= (class as f64) * 12.0;

    // --- Lookahead coupling: next item exactly fills the residual ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // next item fits here: residual mod next_item_size closeness
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 90.0;
            }
            score -= 25.0;
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 0.15 * (next_item_size as f64 - pr).min(60.0);
        }
    }

    // --- Last-chance pressure: only this bin fits the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when current residual is
        // large (item is small) or open-bin pool is bloated.
        score = 60.0 + frac * 40.0;
        if open_bins_count > 6 {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size.min(bin_capacity) {
            // item nearly fills a fresh bin: good to open
            score -= 80.0;
        }
        // Never open a new bin when a perfect fit exists elsewhere is
        // handled by the -500 above; also discourage if residual here is tiny.
        if bin_residual as f64 - item_size as f64 <= 5.0 {
            score += 150.0;
        }
    }

    // --- Mean residual coupling: prefer bins below mean residual
    // (tighter bins first, keeping loose bins flexible) ---
    score += 0.4 * (mean_residual - pr);

    // --- Slight preference for tighter fill as stream progresses ---
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - frac);

    score
}

