pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact / near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else {
        // reward compact two-step residual curve
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // Lookahead chaining: next item fits after this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // next item doesn't fit: dead-space risk scaled by miss distance
            let miss = (nxt - post) / cap;
            score += 60.0 * progress + 30.0 * miss;
        }
    }

    // Tight-bin consolidation vs mean residual
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Sliver waste penalty
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: reluctant by default
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        // discourage opening bins whose leftover can't hold next item
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 45.0 * deadness * (1.0 + progress);
        }
        // reward opening when item nearly fills the bin exactly
        if post_residual > 0 && item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // Open-bin branch: extra reward for tiny residuals late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // penalize mid-range residuals few items can fill
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild spread-load term
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items
    // (1..=9) are almost unusable dead space -> heavy penalty.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Small-but-usable gap: mild penalty, tighter fit is worse.
        score += 0.5 * (20 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // Reward good tight fits relative to bin residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Lookahead: if the next item fits exactly in the post residual, reward;
    // if next item is slightly larger than post_residual, penalize wasting it.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 12.0; // near miss: this gap will likely become dead space
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible, handled above).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: penalize adding to bins when many are open,
    // encouraging consolidation rather than spreading.
    score += 0.15 * open_bins_count as f64;

    // Mean residual coupling: bins far below mean residual are "loose" fits;
    // prefer bins whose residual is closer to the item (already partly via fit_ratio).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: an empty bin is attractive early in the
    // stream or when existing fits are poor; make the empty bin a strong
    // default but beatable by tight fits / last-chance placements.
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its post_residual is large, so add a
        // calibrated offset so only genuinely good placements into open
        // bins beat it.
        score += 25.0 - 10.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Progression: later in the stream, slightly favor using existing space.
    score -= 5.0 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // concave reward for leaving mid-sized residuals (usable, not slivers)
        score -= 250.0 * (1.0 - post / cap) * (post / cap);
    }

    // Harmonic residual classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 - 30.0 * progress; // slivers less harmful late
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 800.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 40.0 * (nxt / cap);
            score += 25.0 * ((post - nxt) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 150.0;
            score -= 120.0 * (item / cap);
            score += 1.0 * mean_residual;
            score += 200.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            score += 80.0 * progress * (mean_residual / cap);
        }
        // Large items leaving big dead space: prefer open bins when many exist
        if item > 0.5 * cap && open_bins_count > 2 {
            score += 140.0 * ((item / cap) - 0.5);
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
        // near-perfect opening: item almost fills new bin
        if post_residual > 0 && item / cap > 0.9 {
            score -= 300.0 * (item / cap - 0.9);
        }
        // new-bin leftover that next item can't use: dead-space penalty
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 50.0 * deadness * (1.0 + progress);
        }
    } else {
        // open-bin branch: reward tiny residuals harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item even if it doesn't fit now
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // penalize mid-range residuals few items can fill
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

