            score -= (10.0 - gap) * 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when plenty of bins can fit the item.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score += 45.0;
        // If many open bins fit, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 10.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
