    if bin_residual != bin_capacity && post_residual > bin_capacity / 2 {
        score += (post_residual as f64 - bin_capacity as f64 / 2.0) * 0.2;
    }

    // Global pressure: when many bins are open, favor filling existing ones.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean (tighter than average).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

