pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 / 25 create
    // "usable" vs "dead" leftover classes.
    let pr = post_residual;
    let pr_class = if pr == 0 {
        0.0 // perfect fit: strongly reward
    } else if pr % 10 == 0 {
        1.0 // round decade leftover: reusable by common sizes
    } else if pr % 25 == 0 {
        1.5
    } else if pr < 10 {
        3.0 // dead space below minimum item size
    } else {
        2.0
    };
    score += pr_class * (pr as f64) * 0.35;

    // Reward near-full bins (waste minimization): fraction of capacity used.
    let used_frac = (bin_residual - item_size.min(bin_residual)) as f64 / cap;
    score -= used_frac * 18.0;

    // Integer-division threshold on next_item_size vs post_residual:
    // if the lookahead item fits exactly into the post residual, big reward.
