            score -= 12.0 * compat * (next_item_size as f64 / cap);
        } else {
            // post residual too small for next item: penalize dead leftover
            score += 6.0 * (1.0 - (pr as f64 / cap));
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // current open bins are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - cap * 0.5).max(0.0);
        score += 40.0 - 0.25 * open_bins_count as f64 + fragmentation * 0.3;
        // early in stream, prefer reusing bins more strongly
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    // Small tie-breaker toward tighter fits among similar residuals.
    score += (item_size as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
