    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 - two_step_waste;
