pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item size.
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let diff = (post_residual as f64 - look).abs();
        // Perfect 2-step match: strong bonus (subtract heavily).
        if diff < 0.5 {
            score -= 60.0 + 0.5 * look;
        } else if post_residual as f64 >= look {
            // Next item still fits: mild bonus scaled by tightness.
            score -= 10.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leaving near-miss dead space.
            score += 8.0 * (diff / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize creating tiny unusable residuals (dead space < 10).
    if post_residual < 10 {
        score += 5.0;
    }

    // Late in the stream, slightly prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep it attractive only when residuals are all tight.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - mean_residual / bin_capacity as f64;
        score = 30.0 + 40.0 * avg_tightness;
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64).abs() < 0.5 {
            score -= 20.0; // fresh bin perfectly fits next item too
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the last usable bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use:
    // if post_residual is nonzero but smaller than the smallest item (1), it's waste.
    // More generally, penalize residuals far below the next item size when next item can't fit.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual as u32).min(60) as f64;
        } else {
            // Reward bins that can also hold the lookahead item (chaining)
            score -= 2.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins with residual close to item size (exact-ish packing)
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * gap;

    // Time horizon: early on, be conservative (favor filling existing bins);
    // late in the stream, allow opening new bins for cleaner packing.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount late
        let new_bin_penalty = 20.0 * (1.0 - progress);
        // Extra penalty if many open bins still have usable space
        score += new_bin_penalty + 0.3 * open_bins_count as f64 * (1.0 - progress);
        // If mean residual is large, existing bins are roomy; avoid new bin
        score += 0.4 * mean_residual * (1.0 - progress);
    } else {
        // Existing bin: mild reward scaled by how full it already is
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 4.0 * fullness * (1.0 - progress);
    }

    // Penalize creating post residuals that match no typical item band
    // (dead-space shaping: residuals in [1, 9] are nearly unusable)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Coupling: when open bin count is high, prefer consolidating into full bins
    if open_bins_count > 8 {
        score -= 0.5 * fullness_proxy(bin_residual, bin_capacity);
    }

    score
}

