    // Last-chance bin: strong reward if this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits snugly into post-residual
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fits = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= fits * 10.0 * (1.0 - gap / cap);
        // Penalize leaving space that neither fits next item nor is tiny
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 3.0 * pr_norm;
