pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: chain perfect fits, penalize dead space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let two_step_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 - two_step_waste;
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 2.0 * (1.0 + progress);
        }
    }

    // Consolidation: prefer tight bins relative to mean residual.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (residual_f - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize small unusable residuals relative to capacity.
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

