        // New-bin candidate: base reluctance, modulated by item size,
        // progress, mean residual, and number of fitting alternatives.
        score += 60.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if item_size >= 60 {
