        } else if open_bins_count > 2 && post > 0.0 && post < 5.0 {
            score -= 90.0; // near-perfect opening bonus
        }
        if item_size > bin_capacity / 2 && (fragmented || open_bins_count == 0) {
            score -= 20.0;
        }
        // new-bin leftover that next item can't use: dead-space penalty
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += (50.0 * (1.0 + progress) + 20.0) * deadness;
        }
        // avoid opening a bin when an existing bin would be left with unusable sliver
        if fitting_bins_count > 0 && open_bins_count > 0 && mean_residual < 10.0 && post_residual > 20 {
            score += 35.0;
        }
    } else {
        // open-bin branch: reward tiny residuals harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item even if it doesn't fit now
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // penalize mid-range residuals few items can fill
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic class of post_residual: small residues in low classes are dead space
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;
    if post_residual > 0 {
        if post_residual < quarter {
            score += 25.0; // tiny unusable sliver
        } else if post_residual < third {
            score += 10.0;
        } else if post_residual < half {
            score -= 5.0; // still useful for mid-size items
        } else {
            score -= 12.0; // large residual is valuable
        }
    }

    // Modulo-10 class coupling: residue divisible by common item granularity is reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead: penalize if next item can't fit into post_residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 8.0;
        } else if next_item_size == post_residual {
            score -= 25.0; // chain perfect fit
        } else {
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * ratio; // tight lookahead fit is good
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive late in stream or when no good fits exist
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= half {
            score -= 5.0; // big upcoming item: fresh bin useful
        }
    }

    // Prefer filling crowded bins when many bins are open
    if open_bins_count > 3 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 4.0 * tightness;
    }

    // Tie-break toward bins below mean residual (fill emptier space first)
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

