    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the leftover -> dead space likely
            score += (next_item_size - post_residual).min(30) as f64 * 0.5;
        }
    }

    // Open-bin pressure: prefer consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: if the fleet of open bins already has large residuals,
    // discourage stuffing this bin and leaving another large gap unused.
    if mean_residual > 30.0 && post_residual > 25 {
        score += (mean_residual - 30.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a fresh bin costly unless current bins are crowded.
    if bin_residual == bin_capacity {
        score += 35.0 + open_bins_count as f64 * 2.0;
        // but if no open bin fits well (item large relative to mean residual), allow it
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild stream-progression calibration: later in stream, be slightly more
    // conservative about spreading across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else {
        // Parabolic reward: residuals near half-capacity are the most reusable.
        let r = post / cap;
        score -= 120.0 * (1.0 - (2.0 * r - 1.0) * (2.0 * r - 1.0));
    }

    // Two-step lookahead chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 550.0;
        } else if next_item_size < post_residual {
            let two_step_waste = post - nxt;
            score -= 160.0 - two_step_waste;
        } else {
            // Dead space risk: residual too small for the next item.
            let miss = nxt - post;
            score += miss * 2.0;
            score += 45.0 * (miss / cap) * (1.0 + progress);
        }
    }

    // Tight-bin consolidation relative to mean residual.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize unusable slivers.
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: base reluctance, modulated by item size and state.
        score += 60.0;
        score -= 120.0 * (item / cap);
        if item_size >= 60 {
            score -= 40.0 * (1.0 - progress);
        }
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Opening a bin for a nearly-full item is cheap.
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
        // Large items late: discourage fragmenting open bins.
        if open_bins_count > 2 && item / cap > 0.5 {
            score += 140.0 * (item / cap - 0.5);
        }
    } else {
        // Open-bin branch: extra hard reward for tiny residuals late in stream.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // Prefer bins whose residual closely matches the next item.
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // Mild penalty for mid-range small residuals that few items can fill.
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (low post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain: this bin becomes exactly right for next item
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / (bin_capacity as f64)); // next item fits well
        } else {
            // next item won't fit here; penalize wasted potential
            let leftover = (next_item_size - post_residual) as f64;
            score += 0.35 * leftover;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 5.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins tighter than average when residuals are large.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.08 * rel;
    score -= 0.05 * (mean_residual / bin_capacity as f64) * (bin_residual as f64);

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize creating very small dead space that no item (min size 1..) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Mild penalty for opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 6.0;
        // But prefer a new bin over a very poor fit (huge post residual waste).
        if post_residual as f64 > mean_residual + 40.0 {
            score -= 10.0;
        }
    }

    // Late in the stream: prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * tightness;

    score
}

