pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, strong bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score -= pressure * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Time horizon: early in stream, be more liberal opening bins (favor new bins slightly);
    // late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / many bins open.
        score += 18.0 * progress + 1.5 * (open_bins_count as f64);
        if item_size > bin_capacity / 2 {
            score -= 6.0; // big items are fine in fresh bins
        }
    } else {
        score -= 3.0 * progress; // consolidate more over time
    }

    // Waste ratio: relative leftover compared to what a fresh bin would leave.
    score += 0.05 * (post_residual as f64 - (bin_capacity - item_size).min(post_residual) as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual shaped by stream progress
    let pr_norm = pr / cap;
    let phase = progress * std::f64::consts::PI;
    let coupling = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress;
    score += 20.0 * coupling;

    // Reward tight fits smoothly (quadratic in post_residual, scaled by capacity)
    score -= (cap - pr) * pr / cap * 0.5;

    // Penalize dead space that can't hold the lookahead item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let waste = gap / cap;
            score += 15.0 * waste * waste * cap * (0.5 + 0.5 * progress);
        } else {
            // lookahead fits: reward smooth bonus
            score -= 8.0 * (1.0 - pr / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: reward using it
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Mean residual deviation penalty (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * cap * (0.3 + 0.7 * progress);

    // New-bin candidate: penalize mildly, more early when open bins exist
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress) * (open_bins_count as f64).min(10.0) / 10.0;
    }

    score
}

