pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic class logic: partition post_residual into capacity-fraction classes.
    // Classes (mod 4 on residual quarters): class 0 = perfect/tight, class 3 = large usable, class 1/2 = dead-ish space.

    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let q = (post_residual * 4 / bin_capacity) as i32; // 0..4 harmonic class of leftover

    // Base: leftover space (minimize waste), scaled mildly sub-linearly to tolerate big leftovers early.
    let mut score = post;

    // Harmonic class adjustments on the leftover.
    match q {
        0 => { score -= 18.0; }              // residual <= C/4: excellent fit, strongly favored
        1 => { score -= 2.0; }               // C/4 < residual <= C/2: mediocre, near neutral
        2 => { score += 3.0; }               // C/2 < residual <= 3C/4: half-empty bin, mildly penalized
        _ => { score += 6.0; }               // residual > 3C/4: nearly untouched bin, penalized
    }

    // Fine-grained exact-fit resonance: leftover that is a multiple of common small sizes
    // (i.e., divisible by 10 within 1..=10) is likely to be filled by a future item.
    if post_residual > 0 && post_residual <= 10 {
        score -= 8.0; // tiny leftover: near-perfect packing
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0; // leftover divisible by 10: harmonic with typical item sizes
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 22.0; // chain of perfect fits
        } else if slack <= 10 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead leftover that next item cannot use: penalize, worse for small leftovers.
        score += 3.0 + 10.0 / post;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it less attractive
    // than good fits but attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline plus a mild pressure term depending on stream progress
        // and how many bins are already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + 6.0 * progress + 0.35 * open_bins_count as f64;
        // If the current item alone leaves a very tight class in a fresh bin, that's fine later.
        if item_size as f64 / cap > 0.8 {
            score -= 10.0; // big items belong in fresh bins
        }
        // If next item is huge and current item is small, better to combine elsewhere.
        if next_item_size > 60 && item_size < 30 {
            score += 5.0;
        }
    }

    // Mean residual coupling: when open bins are on average quite full (small mean residual),
    // prefer keeping tight fits; when bins are loose, tolerate spreading.
    if mean_residual > 0.0 {
        let mean_ratio = mean_residual / cap;
        if mean_ratio < 0.25 {
            score -= 2.0; // bins nearly full: squeeze harder
        } else if mean_ratio > 0.6 {
            score += 1.5; // bins loose: slight penalty for adding to tight fits
        }
    }

    // Late-stream tightening: as the stream ends, reduce waste more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post / cap);

    score
}

