pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (or the lookahead item) are "dead space".
    let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual < min_useful {
        // Waste penalty grows super-linearly as the gap becomes truly useless.
        score += 12.0 + (min_useful - post_residual) as f64 * 2.5;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap can't fit the next item: mildly penalize, but keep as reserve.
        score += 3.0 + (next_item_size - post_residual) as f64 * 0.4;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= tightness * 8.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual == next_item_size && next_item_size > 0 {
        score -= 10.0; // leaves exact room for the lookahead item
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin
    // only when the fit is bad; encourage consolidation otherwise.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = open_bins_count as f64 * (0.05 + 0.1 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: an empty bin has huge residual; make it attractive
    // only when no good fit exists (i.e., this bin's post_residual is dead space).
    if bin_residual == bin_capacity {
        let good_fit_available = fitting_bins_count > 1 && post_residual >= min_useful;
        if good_fit_available {
            score += 20.0; // keep using existing bins
        } else {
            score -= 6.0; // fresh bin beats dead-space placement
        }
        // Early in the stream, opening bins is cheap and useful.
        if progress < 0.2 {
            score -= 4.0;
        }
    }

    // Slight preference for bins below mean residual (balancing loads).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

