pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (post_residual as f64 - next_item_size as f64).min(20.0);
        } else {
            // next item won't fit here; penalize large dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Prefer keeping large residual bins for large items
    if item_size >= 50 {
        score += 0.2 * (post_residual as f64);
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        score += 150.0 / scarcity;
        if next_item_size > 0 && bin_capacity >= next_item_size && post_residual >= next_item_size {
            score -= 100.0; // fresh bin chains well with next item
        }
    }

    // Late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum plausible item size is worthless.
    let dead = if post_residual < 10 { post_residual as f64 } else { 0.0 };
    score += dead * 3.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves more fragmentation if gap is large.
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.5;
        } else {
            // Next item cannot use the leftover: penalize proportionally.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Prefer filling bins that are already relatively full
    // (low residual relative to mean residual means this bin is tighter).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Mild penalty for spreading across many open bins when early in stream;
    // later in stream, consolidate more aggressively to close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = 0.3 + 0.7 * progress;
    score += (open_bins_count as f64).ln().max(0.0) * consolidation * 2.0;

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when current bin waste is high.
        let waste = (bin_residual - item_size) as f64;
        score += 30.0 - waste * 0.2 - (fitting_bins_count == 0) as i32 as f64 * 25.0;
    }

    score
}

