    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual weighted by progress polynomial
    let progress_weight = 0.5 + 1.5 * progress * progress; // quadratic in progress
    score *= progress_weight;

    // Penalize residuals that are "just barely" unusable for typical future items
    let pr = post_residual as f64;
    let deadness = (pr / bin_capacity as f64) * (1.0 - pr / bin_capacity as f64);
    score += 8.0 * deadness * (1.0 - progress);

    // Reward tight fits: small post_residual gets a bonus
    score -= 6.0 * (1.0 - pr / bin_capacity as f64) * (pr as f64).powi(2) / (bin_capacity as f64).powi(2);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good options exist
    if bin_residual == bin_capacity {
        let fits = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        score += 10.0 / fits + 5.0 * (1.0 - progress);
    }

    // Lookahead coupling: prefer bins whose post_residual can still host the next item
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 3.0 * (1.0 - (next_item_size as f64 / bin_capacity as f64));
        }
    }

    // Mild preference to fill bins below mean residual (balance spreading)
    score += 0.5 * (mean_residual - post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands (0..8). Small classes (tight fits) are good.
    let band = (post_residual * 8 / bin_capacity.max(1)) as f64;
    score += band * band * 0.9;

    // Exact-fill harmony: post_residual that divides cleanly into small
    // future item sizes is valuable.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 4.0;
            }
        }
    } else {
        score -= 30.0; // perfect fit
    }

    // Lookahead coupling: reward if next item fits the post residual,
    // penalize harmonic mismatch classes.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            let gap = post_residual - next_item_size;
            if gap * 8 / bin_capacity.max(1) <= 1 {
                score -= 5.0; // near-perfect two-item packing
            }
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * (fitting_bins_count as f64).min(8.0);
        if post_residual as f64 > cap * 0.2 {
            score += 5.0;
        }
    }

    // Dead-space penalty: residuals too small for the minimum item size (1..100
    // interface, but typical small items) are waste; scale by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 + 10.0 * progress;
    }

    // Mild preference to fill bins with larger residuals when many bins open.
    score -= (bin_residual as f64 - mean_residual) * 0.05;

    score
}

