pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, ideal
    } else {
        // Non-linear penalty for unusable gaps: a residual of 1..=10 is dead space.
        let dead = (min_item..=10).contains(&post_residual);
        if dead {
            score += 500.0 * (11.0 - post_residual as f64);
        }
    }

    // Reward tight fits: the closer post_residual is to 0, the better.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 50.0;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            score -= 15.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: penalize spreading across many bins slightly.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate handling: an empty bin is a fallback; make it mildly
    // attractive only when no open bin gives a good fit (post_residual large).
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral score, slightly worse than a good fit
        // but better than a dead-space placement in a partially used bin.
        score = 45.0
            - (mean_residual - item_size as f64).abs() * 0.05
            + open_bins_count as f64 * 0.2;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can serve the next item too
        }
    }

    // Mild progress term to break ties deterministically over the stream.
    score += (step_index as f64) * 1e-6;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by capacity fraction.
    score = post_residual as f64 * (1.0 + 0.5 * (post_residual as f64 / bin_capacity as f64));

    // Lookahead: reward if the next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains perfectly: strong reward proportional to how well it fits.
            let chain_waste = post_residual as f64 - next_item_size as f64;
            score -= 30.0 - 0.4 * chain_waste;
        } else {
            // Next item cannot fit here: slight penalty if post_residual becomes dead space.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.25 * dead;
            }
        }
    }

    // Reward leaving residuals close to mean_residual (balanced bin states).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when good open bins exist; new-bin candidate gets a handicap
    // that shrinks late in the stream (consolidation pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * progress;
        // If next item is large, opening a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with larger residual when many bins are open.
    score -= 0.05 * bin_residual as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // Aggressive 2-step lookahead: reward when next item fits post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // Dead-space risk: next item won't fit in the leftover.
            let miss = (nxt - post) / cap;
            score += 60.0 * progress + 40.0 * miss;
        }
    }

    // Consolidation: prefer tight (below-mean-residual) bins.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Small unusable sliver penalty.
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    // New-bin candidate branch.
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Open new bin early for large items; consolidate late.
        if item / cap > 0.5 {
            score -= 90.0 * (1.0 - progress) * (item / cap - 0.5);
        }
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        // Penalize new bins whose leftover can't hold the next item.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 45.0 * deadness * (1.0 + progress);
        }
        // Reward opening a bin that the item nearly fills exactly.
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // Open-bin branch: extra reward for tiny residuals late in stream.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // Prefer bins whose residual closely matches next item.
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // Mild penalty for mid-range residuals few items can fill.
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild spreading term when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= 40.0 * (1.0 - tight * 8.0).max(0.0);

    // Penalize dead space that cannot host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 + (next_item_size - post_residual) as f64;
        }
        // Reward leaving exactly enough room for the lookahead item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins: slight penalty to encourage diversity of choice.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (bin_residual - item_size).min(100) as f64 / 100.0;
        // Open a new bin if current fit leaves lots of waste and many open bins are fragmented.
        let openness = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 - 35.0 * poor_fit - 10.0 * openness + 5.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0; // opening new bin better than wasting last-chance bin? no—prefer existing
            score += 20.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor) scaled by global mean.
        let gap = (bin_residual as f64 - item_size as f64).abs();
        score += 0.3 * gap - 0.15 * (mean_residual - bin_residual as f64).abs();
    }

    // Mild time-horizon coupling: early in stream, consolidate; late, accept waste.
    let horizon = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * horizon * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let base = pr as f64;
    // Smooth polynomial coupling: dead-space penalty grows super-linearly with progress
    let mut score = base * (1.0 + 1.5 * progress * norm_pr * norm_pr);
    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * cap * (0.4 + 0.6 * progress);
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }
    // Prefer bins below mean residual (balance / preserve large gaps)
    score += 0.3 * (pr - mean_residual);
    // Lookahead: penalize if next item can't fit in post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 + 0.2 * (nx - pr);
        } else {
            score -= 0.1 * (pr - nx).min(20.0);
        }
    }
    // Mild new-bin resistance: opening new bins early is costly
    let is_new = bin_residual == bin_capacity && post_residual == 0 && item_size == 0;
    if is_new {
        score += 30.0 * (1.0 - progress) + open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
