        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Discourage opening a bin whose leftover can't hold the next item.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 60.0 * progress + 20.0 * ((next_item_size - post_residual) as f64 / cap);
        }
        // Reward opening a bin for near-full items (low dead-space opening).
        if item / cap > 0.9 {
            score -= 300.0 * (item / cap - 0.9);
        }
    } else {
        // Open-bin branch: extra reward for tiny residuals, especially late.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
