}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: how "usable" the leftover space is ---
    // Class 0: post_residual is a multiple of 10 -> highly reusable by typical items.
    let post_class = post_residual % 10;
    score += match post_class {
        0 => -8.0,
        1 | 9 => 6.0,          // nearly dead space
        2 | 8 => 4.0,
        3 | 7 => 2.5,
        4 | 6 => 1.0,
        _ => 0.0,
    };

    // Integer-division thresholds: leftover big enough for a whole "block"
    let block = post_residual / 10;
    if block >= 5 {
        score -= 4.0; // leftover >= 50 is a half-bin: very valuable
    } else if block >= 2 {
        score -= 1.5;
    } else {
        score += 3.0; // leftover < 20: mostly dead space
    }

    // --- Coupling with next_item_size (lookahead k=2) ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // this bin could also serve the next item: reward
            score -= (post_residual - next_item_size) as f64 * 0.3;
            // exact chain fit (harmonic pair)
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // placing here leaves next item stranded: penalize by overshoot
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.2;
        }
        // modulo harmony: next item aligns with leftover in 10-grid
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    }

    // --- Last-chance bin: strongly prefer using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // fresh bin: attractive early, or when no good fit exists,
        // but discourage when many open bins already exist and item fits well elsewhere
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = score.max(0.0) + 5.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 8.0; // big next item: a fresh bin is fine
        }
    }

    // --- Mean-residual pressure: prefer bins below mean residual (tighter fill) ---
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    // Mild exact-fill bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // "Awkward gap" zone: small enough to be nearly unusable later.
        score += 25.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    if item_size > 0 {
        score -= 0.8 * (item_size as f64) * (1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0));
    }

    // Dead-space coupling: if post_residual can't fit the lookahead item but the
    // lookahead would fit elsewhere, this bin's leftover is likely stranded.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Conversely, reward bins whose post_residual exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a good fit exists.
    score += 0.6 * (open_bins_count as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // is large or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are used only when justified.
        score += 18.0;
        // Large items justify fresh bins (avoids fragmenting many open bins).
        if item_size >= 50 {
            score -= 22.0;
        }
        // Many open bins with low mean residual => fragmentation risk; new bin OK.
        if open_bins_count > 3 && mean_residual < 25.0 {
            score -= 10.0;
        }
    }

    // Slight late-stream conservatism: waste less early, tolerate slack late.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelmingly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward when the leftover exactly hosts the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // Reward tight-but-sufficient leftovers for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack);
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Penalize small dead space (unusable gaps) superlinearly.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Compare against mean residual: placing into a large-residual bin is cheaper.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer tighter fits; small post_residual is better.
        score += 0.2 * post_residual as f64;
    }

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 { 0.0 } else { 1.0 };
        score += 200.0 * desperation - 0.5 * (open_bins_count as f64);
        if open_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Early stream: be slightly more willing to open bins (spread load).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Bell-shaped reward peaking for very small residuals.
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // Two-step lookahead chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            // Dead-space risk: penalize residuals too small for the next item.
            let miss = nxt - post;
            score += miss * 2.0 + 40.0 * (nxt / cap);
            score += 45.0 * (miss / cap) * (1.0 + progress);
        }
    }

    // Tight-bin consolidation relative to mean residual.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: reluctance, eased by large items and progress.
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        // Reward opening a bin for near-full items (low dead-space opening).
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
        // Penalize new bins when item is large but leaves mid-range dead space.
        if open_bins_count > 2 && item / cap > 0.5 {
            score += 140.0 * (item / cap - 0.5);
        }
    } else {
        // Open-bin branch: extra reward for tiny residuals, harder late.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // Prefer bins whose residual closely matches the next item.
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // Mild penalty for mid-range slivers that few items can fill.
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild spread-load term.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus when post_residual is small.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize post_residual that is too small to hold any plausible item (dead space).
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving a large leftover anyway.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: early in the stream, be more open to spreading items (favor new bins);
    // later, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / when many bins open.
        let pressure = progress * 20.0 + (open_bins_count as f64).ln().max(0.0) * 6.0;
        // But if mean residual across open bins is small (fragmented), a new bin is fine.
        let fragmentation = (mean_residual - item_size as f64).abs();
        score = 35.0 + pressure - fragmentation.min(20.0) * 0.8;
    } else {
        // Existing bin: reward consolidation later in the stream.
        score -= progress * 6.0;
        // Prefer bins whose residual is close to mean (balanced packing).
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // Slight preference for bins with larger residual when item is large.
    score -= 0.02 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

