pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, penalize large residuals mildly; later, penalize them strongly.
    let p = progress;
    let coupling = norm_post * norm_post * (0.5 + 2.5 * p * p) + norm_post * (1.0 - p) * 0.5;
    score += 30.0 * coupling;

    // Reward tight fits (small post_residual) with a smooth cubic term.
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * tightness;

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_frac = next_item_size as f64 / cap;
        score -= 8.0 * fit_frac * (1.0 + p);
    } else if next_item_size > 0 {
        let miss = (next_item_size as f64 - post) / cap;
        score += 6.0 * miss * miss;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - norm_post);
    }

    // New-bin candidate: discourage opening a new bin unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        score += 15.0 + 2.0 * crowding.sqrt() - 20.0 * p * p;
        // If next item is large, opening fresh may be fine.
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.1;
        }
    }

    // Slight penalty for bins with residual far from mean (fragmentation).
    score += 0.05 * (post - mean_residual).abs();

    score
}

