 if post_residual > 0 && post_residual > 10 && post_residual < 30 { score += 12.0 * (1.0 - progress) * (post_residual as f64 / cap) * 10.0 ; } // reward new bins whose post residual is a common small value (easy to fill later)
 if post_residual > 0 && post_residual <= 10 { score -= 20.0 * (1.0 - post_residual as f64 / 10.0) ; } } else { let progress = step_index as f64 / total_items . max (1) as f64 ; if post > 0.0 && post < 4.0 { score -= 40.0 + 70.0 * progress ; } if next_item_size > 0 && post_residual > 0 { let gap = ((post_residual as f64) - (next_item_size as f64)) . abs () ; if gap < 8.0 { score -= 15.0 * progress ; } } if post_residual > 0 && post_residual < 25 && post_residual >= 4 { score += 8.0 * (1.0 - progress) ; } // refined open-bin branch: stronger reward for near-perfect residual match to next item
