pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low modulo classes is worse
    let pr = post_residual;
    if pr > 0 {
        let class = (pr % 10) as f64;
        score += 0.8 * class;
        // perfectly divisible residuals are "harmonic" and reusable
        if pr % 10 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 50 == 0 { score -= 4.0; }
    } else {
        score -= 12.0; // perfect fill
    }

    // Favor tight fits: fraction of bin consumed
    let fill = item_size as f64 / cap;
    score -= 20.0 * fill * fill;

    // Penalize large post_residual relative to typical item sizes (dead space)
    if (post_residual as f64) > mean_residual * 1.5 {
        score += 6.0;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits the post_residual exactly or harmonically, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score += gap as f64 * 0.3;
            if gap % 10 == 0 { score -= 2.0; }
        } else {
            score += 3.0; // next item cannot use leftover anyway
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = open_bins_count as f64 * (mean_residual / cap);
        score = cap * 0.9 + 10.0 * (1.0 - progress) - pressure;
        if item_size as f64 > mean_residual * 0.9 && fitting_bins_count > 0 {
            score += 40.0; // open bins fit fine; discourage new bin
        }
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size && fitting_bins_count <= 1 {
            score -= 20.0; // fresh bin pairs this and next item well
        }
    }

    // Slight preference for fuller bins when many bins are open
    score -= 0.05 * open_bins_count as f64 * fill;

    score
}

