pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // Dead space = residual too small to fit even the smallest item (assume min size ~10, but adapt to next item).
        let min_useful = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
        if post_residual < min_useful {
            // Fully dead gap: heavy penalty proportional to tightness.
            score += 40.0 * (1.0 - post_residual as f64 / min_useful as f64);
        } else {
            // Usable gap: mild reward for larger remaining space, decayed.
            score -= 0.05 * post_residual as f64;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Reward tight fits: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Open bins pressure: when many bins are open, favor consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 50.0);
    score -= 0.3 * open_pressure;

    // Last chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of the current bin.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; neutral baseline but penalize if good fits exist.
        score = 60.0 - 10.0 * fill_ratio;
        if fitting_bins_count == 0 {
            score -= 50.0; // No alternative: must open new bin.
        }
        // If many open bins with large mean residual, discourage new bin.
        score += 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: reward exact fits (post_residual near zero)
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize dead space relative to bin capacity, non-linearly
        let dead_frac = post_residual as f64 / bin_capacity as f64;
        score += dead_frac * dead_frac * 30.0;
    }

    // 2-step lookahead: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportionally to how tight the chain fit is
            let chain_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * (1.0 - chain_tight);
        } else {
            // next item won't fit here: penalize wasting space the next item could have used
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    }

    // Relative to mean residual: bins with less residual than average are "drier";
    // placing here when residual is large vs mean wastes capacity.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate handling: penalize opening a new bin unless the current
    // item fits very poorly everywhere (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin, softened late in the stream
        score += 35.0 - 10.0 * progress;
        // If next item is large, a fresh bin is more attractive
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // If this is a last-chance situation elsewhere, don't open a new bin
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    }

    // Mild tie-break: prefer bins with more residual consumed (smaller residual)
    score += bin_residual as f64 * 0.05;

    score
}

