pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: squared post-residual penalty scaled down, plus bonus for exact/near-exact fills
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 0.35 * tightness * (bin_residual as f64);

    // Exact fit is heavily rewarded
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Penalize leaving dead space that no future item (min size 1..10 typical) can use
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // small dead slivers are wasted
    }

    // Lookahead: if the next item fits exactly in the post-residual, favor this bin strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            let chained = post_residual - next_item_size;
            if chained < 10 {
                score -= 8.0;
            }
            score -= 0.1 * (next_item_size as f64);
        } else {
            // next item cannot follow in this bin: mild penalty if post_residual is large
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible)
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins -> we can afford to be picky; penalize loose fits more
    if fitting_bins_count > 2 {
        score += 0.15 * (fitting_bins_count as f64) * tightness * 10.0;
    }

    // Global state: prefer filling bins when many bins are open (consolidation)
    if open_bins_count > 3 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is an outlier
    // worth emptying (fill it up); if above mean, mildly penalize
    let this_residual = post_residual as f64;
    let dev = this_residual - mean_residual;
    score += 0.08 * dev;

    // New-bin candidate handling: an empty bin gets a moderate default score.
    // It should only win when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 40.0
            - 0.3 * (item_size as f64)
            + 10.0 * progress
            + if fitting_bins_count == 0 { -20.0 } else { 0.0 }
            + if next_item_size > 0 && next_item_size >= item_size { -3.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact fill is ideal
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // parabolic reward for residuals that are small but not slivers
        let r = post / cap;
        score -= 300.0 * (1.0 - r) * r;
    }

    // Harmonic residual classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 20.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: next item fits snugly -> strong reward scaled by snugness
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            score += 40.0 * (nxt / cap) + 30.0 * ((post - nxt) / cap);
            if fitting_bins_count == 1 {
                score += 25.0;
            }
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let fragmented = mean_residual < cap * 0.3;
        if fragmented || open_bins_count == 0 {
            score -= 30.0 + 40.0 * progress;
            if item_size > bin_capacity / 2 {
                score -= 20.0;
            }
        } else {
            score += 150.0;
            score -= 120.0 * (item / cap);
            score += 1.0 * mean_residual;
            score += 200.0 * progress;
            if fitting_bins_count == 0 {
                score -= 2000.0;
            } else {
                score += 60.0 * (fitting_bins_count as f64).min(5.0);
            }
            score += 80.0 * progress * (mean_residual / cap);
            // large items leaving big dead space: prefer open bins when many exist
            if item > 0.5 * cap && open_bins_count > 2 {
                score += 140.0 * ((item / cap) - 0.5);
            }
            // near-perfect opening fits
            if item / cap > 0.9 {
                score -= 30.0 * (item / cap - 0.9) * 10.0;
            }
            // discourage new bin whose leftover can't hold the next item
            if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
                let deadness = (next_item_size - post_residual) as f64 / cap;
                score += 45.0 * deadness * (1.0 + progress);
            }
        }
    } else {
        // open-bin branch: reward tiny residuals harder late in stream
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = ((post_residual as f64) - (next_item_size as f64)).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mild penalty for mid-range residuals that few items can fill
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild pressure toward tighter bins as stream progresses
    score -= (bin_residual as f64 / cap) * 6.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
