    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // Two-step lookahead chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            let miss = nxt - post;
            score += miss * 2.0;
            score += 30.0 * (miss / cap) * (1.0 + progress);
        }
    }

    // Tight-bin consolidation relative to mean residual.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: strong preference to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Small unusable residual penalty.
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: base reluctance scaled by progress.
        score += 150.0 + 120.0 * progress;
        // Large items justify fresh bins early.
        if item / cap > 0.5 {
            score -= 140.0 * (item / cap - 0.5) * (1.0 - progress);
        }
        if item / cap > 0.9 {
            score -= 300.0 * (item / cap - 0.9) * 10.0;
        }
        // If open bins are nearly all full, a new bin is fine.
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        // New-bin leftover that cannot hold the next item is dead space.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 45.0 * deadness * (1.0 + progress);
        }
        // Sliver control: if open bins are tight, discourage mid-range leftovers.
        if open_bins_count > 2 && post > 0.0 && post < 5.0 {
            score -= 90.0;
        }
    } else {
        // Open-bin branch: reward tiny residuals harder late in the stream.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // Prefer bins whose residual closely matches the next item.
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // Mild penalty for mid-range residuals that few items can fill.
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild spread-load term with many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = x * x * (1.0 + t) - x * (1.0 - 0.5 * t);
    let mut score = post + 20.0 * poly;

    // Tight fit reward, stronger later in the stream.
    let tight = (item_size as f64 / bin_residual.max(1) as f64).min(1.0);
    score -= 15.0 * tight * tight * (0.5 + t);

    // Penalize dead space relative to mean residual of open bins.
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bin: strongly reward using it to avoid a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward; else penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 10.0 * (nx / post.max(1.0));
        } else {
            score += 8.0 * ((nx - post) / cap);
        }
    }

    // Slight bias toward opening new bins early (spread load), packing tightly late.
    score += 10.0 * (0.5 - t) * (x - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
