    if fitting_bins_count > 0 && open_bins_count > 0 {
        if mean_residual.min(cap) < 10.0 && post_residual > 20 {
            score += 35.0;
        }
    }

    // Mild spreading preference when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by residue classes.
    let pr = post_residual;
    let class_penalty = match pr % 10 {
        0 => -6.0,                     // perfectly divisible space (e.g. 50, 60) reusable
        5 => -4.0,                     // half-decade residuals also friendly
        1 | 9 => 3.0,                  // near-boundary awkward slivers
        2 | 8 => 1.5,
        3 | 7 => 0.5,
        _ => 2.0,                      // 4 | 6 mid-class
    };
    score += class_penalty;

    // Integer-division threshold: big residual chunks are valuable.
    if pr / 20 >= 2 {
        score -= 4.0;
    } else if pr / 20 == 1 {
        score -= 1.0;
    } else {
        score += 5.0; // tiny dead space < 20
    }

    // Perfect-fit reward.
    if pr == 0 {
        score -= 100.0;
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += (next_item_size - pr).min(40) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it available but not dominant unless existing fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.15;
        if pr == bin_capacity {
            score -= 10.0; // item itself tiny relative to capacity
        }
    }

    // Progress-based modulation: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.2;

    // Penalize bins far from mean residual (fragmentation avoidance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    score
}

