pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that no future item (min size 1) could be too small for is moot;
    // instead penalize gaps that are large but awkward relative to mean residual.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Open-bin pressure: penalize placements in bins when many bins are open,
    // encouraging consolidation; scale with progress.
    score += open_bins_count as f64 * 0.35 * (1.0 + progress);

    // Reward using bins whose residual is close to the item (tight fits).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 12.0;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by open-bin pressure.
        score += 15.0 + open_bins_count as f64 * 0.5;
        // If the item fits well in a fresh bin (large item), a new bin is attractive.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // If this bin is a last chance anyway, opening a new bin is fine.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Lookahead: penalize creating a residual that cannot fit the next item when it could have.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 18.0;
    }
    // Reward leaving exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) mildly.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

