pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of small
    // divisors is more reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 25 == 0 { bonus += 5.0; }
        if pr % 20 == 0 { bonus += 3.0; }
        if pr % 5 == 0 { bonus += 1.5; }
        score -= bonus;
    }

    // Penalize residuals in "dead zones": too small for any plausible item
    // (items 1..100, but small items are rare-ish; treat <15 as nearly dead).
    if pr > 0 && pr < 15 {
        score += 20.0 * (15.0 - pr as f64) / 15.0;
    }

    // Coupling with lookahead: reward residuals that exactly (or nearly) fit
    // the next item via integer division classes.
    if next_item_size > 0 && next_item_size <= pr {
        let rem = pr % next_item_size;
        if rem == 0 {
            score -= 12.0;
        } else if rem <= 5 {
            score -= 6.0;
        } else {
            score += rem as f64 * 0.3;
        }
    }
    // Penalize leaving a residual that can't hold the next item at all.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 8.0;
    }

    // Perfect fit is always excellent.
    if pr == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is
    // chosen only when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        // Prefer fuller bins (tight packing): compare residual to mean.
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;
    }

    // Mild pressure to consolidate as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Strong reward for exact and near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0 + 70.0 * progress;
    }

    // Two-step lookahead chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 { score -= 50.0; }
        } else {
            let miss = nxt - post;
            score += miss * 2.0;
            score += 30.0 * (miss / cap);
        }
    }

    // Consolidation: prefer below-average-residual (tight) bins.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: strong preference.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize tiny unusable slivers.
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: base reluctance, tuned by item size, progress,
        // mean residual and number of fitting alternatives.
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        // Opening a bin whose leftover cannot hold the next item is costly.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 45.0 * ((next_item_size - post_residual) as f64 / cap) * (1.0 + progress);
        }
        // Nearly-full item: opening a bin is fine (low dead space).
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        }
        // Large items early: keep flexibility.
        if item_size >= 60 {
            score -= 40.0 * (1.0 - progress);
        }
        let open_frac = open_bins_count as f64 / total_items.max(1) as f64;
        score += 90.0 * progress * (1.0 - open_frac.min(1.0));
    } else {
        // Open-bin branch: extra reward for tiny residuals, stronger late.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // Prefer bins whose residual is close to next item even if it won't fit now.
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // Mild penalty for mid-range residuals few items can fill.
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild spread-load term.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    let min_item = 10u32; // smallest plausible item; smaller gaps are dead space
    if post_residual < min_item {
        score -= 120.0; // perfect closure: gap is unusable anyway, reward heavily
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap cannot fit the known next item: potential dead space, penalize
        score += 25.0 + 0.5 * post_residual as f64;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0; // gap exactly matches lookahead item
    } else {
        // usable gap: mild reward proportional to how well next item slots in
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.05;
        }
    }

    // Reward tight fits (waste minimization relative to bin size)
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when many bins are already open and a decent fit exists
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of adding a bin
        score = 90.0 + open_bins_count as f64 * 2.0;
        // allow new bin only if it would otherwise be a poor fit everywhere:
        if post_residual < min_item {
            score -= 200.0; // item exactly fills a fresh bin
        }
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    } else {
        // mild pressure to consolidate into fewer bins
        score += open_bins_count as f64 * 0.3;
    }

    // Prefer bins whose residual is close to the item (best-fit core)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.2;

    // Alignment with mean residual: prefer bins that bring mean down
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += tightness * 20.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            // Perfect chain: post_residual == next_item_size -> strong reward
            if gap == 0.0 {
                score -= 60.0;
            } else {
                // Partial coupling reward, decaying with gap
                score -= 40.0 * (-gap / 25.0).exp();
            }
        } else {
            // Next item cannot use this residual: penalize proportionally to wasted potential
            score += 0.5 * (nxt - pr);
        }
    }

    // Compare residual against mean residual across open bins
    let dev = (post_residual as f64) - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless current bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 30.0 - 3.0 * crowded;
        // If next item pairs perfectly with this item in a fresh bin, ease the penalty
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 15.0;
        }
    }

    // Late-stream consolidation: prefer reusing bins as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

