pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small unusable leftovers (dead space < 10 or awkward mid gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score -= 4.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // If next item is large, prefer leaving a small residual (waste less on big items).
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: only attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5
            && mean_residual > item_size as f64 * 1.6;
        if poor_fit {
            score -= 25.0;
        } else {
            score += 35.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Global state: prefer filling bins when many bins are open (bin-count pressure).
    let pressure = open_bins_count as f64 / (1.0 + step_index.max(1) as f64);
    score += 10.0 * pressure * (1.0 - fit_ratio);

    // Mean residual coupling: if this bin's residual is below average, it's a good filler.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * fit_ratio;

    score
}

