pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fractions.
    // Classes: [0] perfect, [1] tiny (<=10), [2] small (<=25), [3] medium (<=50), [4] large (>50).
    let pr = post_residual;
    let class = if pr == 0 { 0u32 }
        else if pr <= 10 { 1 }
        else if pr <= 25 { 2 }
        else if pr <= 50 { 3 }
        else { 4 };

    // Reward tight fits strongly (harmonic-style discounts per class).
    let class_reward: [f64; 5] = [60.0, 40.0, 20.0, 8.0, 0.0];
    score -= class_reward[class as usize];

    // Modulo structure: leftovers divisible by common item granularities (5,10,20)
    // are more reusable by future items -> subtract a bonus.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr % 20 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: does the next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Perfect chain: next item exactly fills leftover is ideal.
            if next_item_size == pr { score -= 25.0; }
            else { score -= 10.0 * (next_item_size as f64 / pr as f64); }
        } else {
            // Dead space for the next item: penalize proportionally to waste.
            let waste = (next_item_size - pr) as f64;
            score += 0.4 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. Penalize the fresh bin mildly, but
    // reward it when current bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 18.0; // base cost of opening a new bin
        // If the item is small relative to capacity, prefer existing bins.
        score += 0.3 * (item_size as f64);
        // If many bins are open and mean residual is large, opening new bins is wasteful.
        score += 0.1 * mean_residual;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
    } else {
        // Existing bin: slight preference for fuller bins (small residual before placement).
        score += 0.1 * (bin_residual as f64 - item_size as f64).max(0.0);
    }

    // Spread load when too many bins would otherwise be nearly empty:
    // if mean residual is high and this bin is below average fullness, slight penalty.
    let fullness = (bin_capacity - bin_residual) as f64 / cap;
    if fullness < (1.0 - mean_residual / cap) {
        score += 2.0;
    }

    score
}

