pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small unusable dead space (1..=9) heavily
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    }
    // Mild penalty for moderately small gaps that only fit tiny items
    else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (small but usable residual)
    if post_residual > 0 && post_residual <= 10 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Pressure against opening new bins when many bins are already open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // If lookahead item fits in the residual a new bin would leave, dampen penalty
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 25.0;
        }
    }

    // Slight preference for bins with residual below mean (consolidating fuller bins)
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

