    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect 2-step match
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward good chain fits, penalize large slack after chaining
            score -= 18.0 * (1.0 - slack / bin_capacity as f64);
            score += 0.15 * slack;
        } else {
            // next item won't fit here; penalize dead space more strongly
            let dead = (next_item_size - post_residual) as f64;
            score += 0.25 * dead;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably from mean
    let mean_r = mean_residual;
    if mean_r > 0.0 {
        let dev = (bin_residual as f64 - mean_r) / mean_r;
        score += 4.0 * dev; // prefer below-mean residual bins (tighter than average)
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // leaves a large residual (poor fit everywhere) or few bins exist early on.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score += 30.0;               // default penalty for opening new bin
        score -= 20.0 * poor_fit;    // more attractive if lots of space left
        score -= 15.0 * (1.0 - progress); // early in stream, opening is cheaper
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
