pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 + 2.0 * progress * progress);
    score += 3.0 * coupling * coupling;

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    let dead = (pr as f64 - mean_residual) / cap;
    score += 5.0 * dead * dead.abs();

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits the post-residual, penalize otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (0.5 + progress);
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: discourage opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let mean_waste = mean_residual / cap;
        score += 15.0 * (1.0 - mean_waste) * (1.0 - progress) + 6.0;
    }

    score
}

