pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let q = (pr / cap * 4.0).floor(); // quarter classes: 0,1,2,3

    // Reward tight fits: small post_residual gets harmonic discount
    score -= (cap - pr) / cap * 12.0;

    // Modulo-10 class of post_residual: residuals that are exact multiples
    // of common item sizes are reusable; penalize odd/dead classes
    let m10 = post_residual % 10;
    if m10 == 0 {
        score -= 6.0;
    } else if m10 <= 2 {
        score -= 2.0;
    } else if m10 >= 8 {
        score += 3.0;
    } else {
        score += 1.5;
    }

    // Quarter-class coupling: prefer leaving residuals in classes that
    // match typical small-item sizes (multiples of 10/20)
    match q as u32 {
        0 => score -= 8.0,                    // nearly full: excellent
        1 => score += 2.0,                    // 25-50% left: mediocre
        2 => score += 5.0,                    // 50-75% left: wasteful
        _ => score += 1.0,                    // mostly empty: fine
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / pr.max(1.0);
            score -= 4.0 * fill;
            // harmonic pairing: next_item_size + item_size near capacity
            let pair = (item_size + next_item_size) as f64;
            if (pair - cap).abs() <= 5.0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: slight penalty for tight fits
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if all open
    // bins would leave large dead space and we're early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // fresh bin: baseline score, penalize late in stream or when
        // open bins have decent mean residual to absorb the item
        score = 55.0 + progress * 20.0 + (open_bins_count as f64).min(20.0);
        if mean_residual > item_size as f64 + 15.0 {
            score += 10.0; // existing bins are roomy; don't open new
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 8.0; // next item pairs with fresh capacity
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.15;

    // Small dead-space quadratic term
    score += (pr * pr) / (cap * cap) * 3.0;

    score
}

