pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        // A gap is "dead" if no plausible future item (>=1, but realistically small)
        // would fit well; weight quadratically for small residuals.
        let dead = (bin_capacity as f64 / 10.0) - (post_residual as f64).min(bin_capacity as f64 / 10.0);
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 12.0; // tiny slivers are worst
        }
        let _ = dead;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64 / post_residual.max(1) as f64) * 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only open a new bin when current fit is bad
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // New bin: base score = full capacity residual; discount if open bins are crowded.
        score = bin_capacity as f64 - 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
        if post_residual as f64 > mean_residual {
            score += 2.0;
        }
    } else {
        // Existing bin: reward keeping residual above next item's need when possible.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8; // blocks lookahead item
        }
