    // 2-step lookahead: reward when next item exactly fits the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 900.0; // chain fit: item + next item fills bin perfectly
