pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post-residual is good.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness;

    // Penalize dead space that cannot plausibly be filled later.
    // Typical future items average ~half capacity; dead space below the
    // smallest plausible item is wasted.
    let dead = post_residual as f64;
    if dead < 10.0 {
        score -= 25.0; // nearly full bin, excellent
    } else if dead < 25.0 {
        score -= 6.0;
    } else {
        // large leftover space: penalize proportionally
        score += 0.15 * dead;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let chain_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 20.0 * chain_fit;
    } else if next_item_size > 0 {
        // next item won't chain: mild penalty, stronger when this bin was a good fit anyway
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral-ish baseline so that poor fits into
    // existing bins are preferred over opening new bins, but a new bin beats
    // very bad placements (huge leftover waste).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 10.0; // large item first, small item can chain after
        }
        return score;
    }

    // Global state coupling: prefer filling bins when many bins are open
    // (consolidation pressure), scaled by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 0.02 * open_bins_count as f64 * (0.5 + progress);

    // Prefer bins whose residual is below the mean residual (fill the emptier ones less,
    // keep flexible bins open): penalize placing into bins with large residual.
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late-stream: consolidate aggressively, avoid leaving many partial bins.
    if progress > 0.8 {
        score -= 8.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
        if post_residual <= 5 {
            score -= 150.0 + 70.0 * progress;
        }
    }

    // Two-step lookahead: chaining with next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 50.0;
            }
        } else {
            let miss = nxt - post;
            score += miss * 2.0 + 40.0 * progress;
        }
    }

    // Consolidation: prefer tighter bins relative to mean residual.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: keep it attractive.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize small unusable slivers on open bins.
    if bin_residual != bin_capacity && post_residual > 0 && post_residual < 25 {
        score += 8.0 * (1.0 - progress);
    }

    // ---- New-bin candidate branch ----
    if bin_residual == bin_capacity {
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += 1.0 * mean_residual;
        score += 200.0 * progress;

        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }

        // Open a fresh bin for large items early (flexibility), consolidate late.
        if item / cap > 0.9 {
            score -= 30.0 * (item / cap - 0.9) * 10.0;
        } else if item_size >= 60 {
            score -= 40.0 * (1.0 - progress);
        }

        // All open bins nearly full: opening a new bin is fine.
        if mean_residual < 15.0 {
            score -= 80.0;
        }

        // Discourage new bin whose leftover can't hold the next item.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 45.0 * deadness * (1.0 + progress) + 20.0 * deadness;
        }

        // Avoid opening a bin when an existing bin would be left with an unusable sliver.
        if fitting_bins_count > 0 && mean_residual < 10.0 && post_residual > 20 {
            score += 35.0;
        }
    } else {
        // Open-bin branch: late-stream sliver cleanup.
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // Prefer bins whose residual closely matches the next item.
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
    }

    // Mild spread-load term when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Smooth non-linear coupling of post_residual with stream progress
    let t = post / cap;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like shaping of residual
    let mut score = post * (1.0 + 0.6 * progress * (1.0 - poly));

    // Penalize large post-residual more aggressively late in the stream
    score += 8.0 * progress * t * t;

    // Reward tight fits (small post residual) with a smooth quadratic bonus
    score -= (1.0 - t) * (1.0 - t) * 10.0;

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // New-bin candidate: prefer it only when post-residual would be very large
    // relative to mean residual; smooth penalty otherwise.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * mean_residual - 20.0 * t;
        if next_item_size > 0.0 as u32 {
            let nx = next_item_size as f64;
            // opening a new bin is attractive if next item fits the fresh bin perfectly
            score -= 12.0 * (1.0 - ((nx - post).abs() / cap));
        }
    }

    // Lookahead: reward placements leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (post - nx).abs();
        score += 0.15 * fit_gap;
        if post >= nx {
            score -= 6.0 * (1.0 - fit_gap / cap);
        }
    }

    // Mild pressure against spreading across many open bins
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of 10) are more reusable -> reward.
    let pr = post_residual;
    if pr > 0 {
        let r10 = pr % 10;
        if r10 == 0 {
            score -= 6.0; // perfectly harmonic leftover
        } else if r10 <= 2 {
            score -= 2.0;
        } else if r10 >= 8 {
            score += 3.0; // nearly-full bin, small awkward gap
        } else {
            score += 1.5; // mid-class dead space
        }
    } else {
        score -= 10.0; // perfect closure
    }

    // Integer-division threshold: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead-compatible: reward, scaled by how tight the future fit is.
            let tightness = (pr - next_item_size) as f64;
            score -= 5.0 + 4.0 * (1.0 - tightness / bin_capacity as f64);
            // Harmonic pairing: next item leaves a multiple-of-10 remainder too.
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 && pr2 > 0 {
                score -= 3.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally.
            score += 2.0 + 0.05 * (next_item_size as f64 - pr as f64);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current bins are crowded
    // or the fit here is terrible.
    if bin_residual == bin_capacity {
        let mean_fit_gap = mean_residual - item_size as f64;
        if mean_fit_gap < 0.0 {
            // Item doesn't fit average open bin well -> new bin is good.
            score -= 8.0 + 0.5 * (-mean_fit_gap);
        } else {
            score += 10.0 + mean_fit_gap * 0.3; // prefer existing bins
        }
        // Early stream: keep open-bin count low.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt();
    }

    // Prefer tighter fits among open bins (fraction of capacity consumed).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill_frac;

    // Coupling with mean residual: placing into a bin below-mean residual
    // reduces fragmentation spread.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    score
}

