        score -= 18.0 / (1.0 + gap);
    }
    // If next item would leave this bin's leftover dead, penalize mildly.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // New-bin candidate handling: only open a new bin when all open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base reluctance to open new bins, scaled by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 30.0 * progress;
        // But if current open bins are all tight, opening is fine.
        if mean_residual < item_size as f64 * 0.6 {
