pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (waste minimization)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Penalize leftover space the next item cannot use
            score += gap * 0.6;
            // Bonus if next item still fits comfortably
            score -= 40.0;
        } else {
            // Next item cannot fit in the residual: dead space penalty
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 1.2;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual above the mean
    // (keeps small residuals consolidated).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fits badly
    if bin_residual == bin_capacity {
        score += 120.0;
