pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large
    // common item sizes (e.g. 25, 50, 20, 10) are more reusable.
    let r = post_residual;
    let mut reusability = 0.0;
    if r % 50 == 0 { reusability += 12.0; }
    else if r % 25 == 0 { reusability += 8.0; }
    else if r % 20 == 0 { reusability += 6.0; }
    else if r % 10 == 0 { reusability += 4.0; }
    score -= reusability;

    // Perfect fit is ideal.
    if r == 0 { score -= 200.0; }

    // Penalize small dead-space classes that are hard to fill later.
    if r > 0 && r < 10 { score += 30.0; }
    else if r >= 10 && r < 20 { score += 12.0; }

    // Lookahead coupling: if the next item fits the post residual, reward.
    if next_item_size > 0 && next_item_size <= r {
        score -= 15.0 + (next_item_size as f64) * 0.2;
    } else if next_item_size > r {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when few bins fit the item or the
    // best available fit would waste a lot of space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else { 0.0 };
        score += 60.0
            - (fitting_bins_count as f64) * 15.0
            - waste_penalty * 0.5
            - progress * 10.0;
    }

    // Prefer bins whose residual is close to the item (tight packing),
    // expressed via integer-division thresholds.
    let gap = bin_residual - item_size;
    let tight_class = bin_residual / item_size.max(1);
    if tight_class == 1 { score -= 10.0; }
    if gap as f64 > mean_residual { score += 6.0; }

    // Mild encouragement to consolidate into fewer bins.
    score -= 1.0 / (open_bins_count as f64 + 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 100.0;
    } else {
        // Prefer tighter residual packing overall (superlinear in leftover).
        score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;
    }

    // Reward using bins that will otherwise be wasted; penalize spreading.
    if fitting_bins_count == 1 {
        score -= 30.0; // last-chance bin: use it before opening a new one
    }
    score += open_bins_count as f64 * 2.0;

    // If the next item fits exactly into this bin's post_residual, bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If post_residual is small but nonzero and next item can't use it, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        if post_residual >= 50.0 && fitting_bins_count > 0 && mean_residual > item_size as f64 {
            score -= 20.0; // open a fresh bin rather than wreck a large residual
        } else {
            score += 25.0; // prefer reusing open bins normally
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual == 0 as u32 as u32) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item would leave a tiny residual.
    if next_item_size > 0 && post_residual > next_item_size {
        let two_step_residual = post_residual - next_item_size;
        if two_step_residual <= 10 {
            score -= 40.0 - (two_step_residual as f64) * 3.0;
        } else {
            // Penalize large two-step leftovers less as they may still be usable.
            score -= 4.0;
        }
    }
    // Penalize leaving dead space that nothing can fill (below min item size 1 is impossible,
    // but tiny residuals are hard to use).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 {
        score -= 15.0; // tight fit relative to fleet average
    } else if pr > mean_residual * 1.5 {
        score += 10.0; // wasteful relative to fleet average
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: encourage only when current item is large and fit is poor elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0 + (item_size as f64) * 0.2;
        // If next item is small, a fresh bin is more valuable for it.
        if next_item_size > 0 && next_item_size <= item_size / 2 {
            score -= 20.0;
        }
    }

    // Late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: nonlinear bonus for small post_residual
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Dead-space penalty for large unusable leftovers
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // penalize leaving a gap that nothing can use
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.15 * gap;
            }
        }
    }

    // Last-chance bonus: only bin that fits => strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin if existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 70.0;
        // cheaper to open early when few bins open; expensive when many bins idle
        score += 2.0 * open_bins_count as f64;
        // if many bins can fit, discourage opening yet another
        if fitting_bins_count > 0 {
            score += 25.0 * fitting_bins_count as f64;
        }
        // if current item is small, opening wastes capacity
        score += 0.5 * (bin_capacity - item_size) as f64;
    } else {
        // reward filling bins that are already partly used
        score -= 0.3 * (bin_residual - post_residual) as f64;
    }

    // Prefer bins with residual below mean (compact nearly-full bins first)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Time horizon: as stream progresses, be more conservative about opening bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
