    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: prefer bins whose post_residual can't fit next item (avoid wasting)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score += 5.0 + pr_norm * 10.0;
        } else if pr > 0.0 {
            score -= (nx - pr).min(cap) / cap * 8.0 * (1.0 - progress);
