    }

    // Lookahead coupling: if the next item would fit snugly in the
    // post-residual, reward leaving exactly that much space.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0;
        } else if gap > 0 && (gap as f64) < dead_threshold {
            score += gap as f64 * 3.0;
        } else if gap < 0 {
            score += 5.0; // next item won't fit here; mild penalty
        }
    }

    // Late-stream consolidation: as the stream ends, avoid leaving many
    // partially filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
