pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit, but weight residual by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score = post_residual as f64 * (0.6 + 0.8 * progress);

    // 2-step lookahead: reward when next item fits perfectly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect chain match gets a big bonus.
            if gap == 0.0 {
                score -= 40.0 + 30.0 * (1.0 - progress);
            } else {
                // Reward proportionally to how well next item fills the leftover.
                let fill_ratio = next_item_size as f64 / post_residual as f64;
                score -= 20.0 * fill_ratio * fill_ratio;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space, more so early on.
            score += 5.0 + 10.0 * (1.0 - progress);
        }
    } else {
        // Last item: only the immediate fit matters; strongly prefer tightest fit.
        score -= 50.0;
    }

    // Compare post_residual relative to mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        // Leaving much more than the average leftover is wasteful.
        if rel > 1.0 {
            score += 8.0 * (rel - 1.0);
        } else {
            score -= 4.0 * (1.0 - rel);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly encourage using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Opening a new bin is only attractive if the item fits poorly everywhere
        // else; penalize so tight fits in existing bins win.
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 15.0 * (1.0 - tightness);
        // But if the item is large, a fresh bin is reasonable.
        score -= 10.0 * tightness;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
