pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // smooth reward: prefer small post residual, weighted by fill fraction
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
        if post_residual <= 5 {
            score -= 150.0 * (1.0 - progress);
        }
    }

    // Lookahead chaining: next item fits into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = post - nxt;
            score -= 900.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
        } else {
            // dead space risk: residual too small for upcoming item
            let miss = (nxt - post) / cap;
            score += 45.0 * miss * (1.0 + progress);
            score += 20.0 * progress;
        }
    }

    // Tight-bin consolidation via mean residual comparison.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 220.0;
    }

    // Penalize tiny unusable slivers.
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    if bin_residual == bin_capacity {
        // New-bin candidate: reluctant by default.
        score += 150.0;
        score -= 120.0 * (item / cap);
        score += mean_residual;
        score += 200.0 * progress;
        if fitting_bins_count == 0 {
            score -= 2000.0;
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        // near-perfect opening: item almost fills a fresh bin
        if item / cap > 0.9 {
            score -= 300.0 * (item / cap - 0.9) * 10.0;
        }
        // open new bin when all open bins are nearly full
        if mean_residual < 15.0 {
            score -= 80.0;
        }
        // large items early: keep flexibility
        if item_size >= 60 {
            score -= 40.0 * (1.0 - progress);
        }
    } else {
        // open-bin branch
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress;
        }
        // prefer bins whose residual closely matches next item
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress;
            }
        }
        // mid-range residuals that few items can fill: mild penalty early
        if post_residual > 0 && post_residual < 25 && post_residual >= 4 {
            score += 8.0 * (1.0 - progress);
        }
    }

    // Mild spread-load preference when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 30.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: penalize leaving residuals that can't hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0; // residual stays useful
        } else {
            score += 10.0; // residual becomes dead space
        }
        // Bonus if residual exactly matches next item (perfect pairing).
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins with
    // less residual than average (fill the fullest bins first).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Time horizon: early in stream, be conservative (penalize near-full bins
    // less); late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: default moderate score; only attractive when no
    // open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let open_fit_quality = if fitting_bins_count > 0 {
            (bin_capacity as f64 - mean_residual) / bin_capacity as f64
        } else {
            0.0
        };
        // Opening a new bin is penalized, but less if existing fits are poor
        // (large post_residual) or very few bins can fit the item.
        score = 55.0
            - open_fit_quality * 20.0
            - (fitting_bins_count as f64) * 2.0
            + (open_bins_count as f64) * 0.8;
        // Late in stream, opening new bins is cheaper than wasting space.
        score -= progress * 10.0;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mean_r = mean_residual / cap;
    let next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 30.0 * poly;

    // Reward tight fits more strongly late in the stream (smooth coupling)
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + t);

    // Penalize residual that wastes capacity relative to mean residual
    score += 5.0 * (norm_pr - mean_r) * (norm_pr - mean_r);

    // Lookahead: reward residual that can host the next item smoothly
    if next > 0.0 {
        let fit_next = if norm_pr >= next { 1.0 } else { 0.0 };
        let gap = (norm_pr - next).abs();
        score -= 8.0 * fit_next * (1.0 - gap).max(0.0);
        score += 6.0 * (1.0 - fit_next) * gap;
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + t);
    }

    // Mild penalty for spreading across many open bins, growing with progress
    score += 0.5 * (open_bins_count as f64).ln() * (0.5 + t);

    // Prefer larger item fraction placed (denser packing), smoothly weighted
    score -= 10.0 * norm_item * (1.0 - norm_pr);

    // Brand-new bin candidate: baseline cost with smooth decay over stream
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - 0.5 * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste quantized by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Penalize residuals that fall into "dead space" classes:
    // residuals below the smallest plausible item (assume ~10% of capacity)
    if frac < 0.10 {
        score += 40.0 * (0.10 - frac);
    }

    // Reward residuals that are harmonic multiples of small item classes
    // (residual divisible by 10 or 25 is more likely reusable)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
        if post_residual == next_item_size {
            score -= 15.0; // perfect chain
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; penalize slightly less if residual tiny (dead anyway)
        if frac >= 0.10 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        // If mean residual across bins is small, opening fresh bin is fine
        score = 45.0 - 30.0 * crowded;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // Early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins overall
    score -= 0.05 * (bin_residual - post_residual) as f64;

    // Tie-break: prefer bins whose residual is close to mean (balanced packing)
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
