pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // smooth parabola: tightest residuals get the biggest reward
        score -= 300.0 * (1.0 - post / cap) * (post / cap);
    }

    // Two-step lookahead chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let diff = (post - nxt).abs();
            score -= 700.0 * (1.0 - diff / cap);
            if diff == 0.0 {
                score -= 60.0;
            }
        } else {
            // next item won't fit: penalize dead space scaled by miss and progress
            let miss = (nxt - post) / cap;
            score += (40.0 + 60.0 * progress) * miss + 30.0 * miss;
        }
    }

    // Tight-bin consolidation relative to mean residual.
    if mean_residual > 0.0 {
        score += (bin_residual as f64 - mean_residual) * 0.8;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize creating tiny unusable slivers.
    let waste_ratio = post / cap;
    if waste_ratio > 0.0 && waste_ratio < 0.1 {
        score += 50.0 * (0.1 - waste_ratio) * 10.0;
    }

    if bin_residual == bin_capacity {
        // NEW-BIN CANDIDATE branch
        score += 150.0; // base reluctance
        score -= 120.0 * (item / cap); // large items justify fresh bins
        score += 1.2 * mean_residual; // full open bins make new bins attractive
        score += 200.0 * progress; // late in stream, strongly avoid new bins
        if fitting_bins_count == 0 {
            score -= 2000.0; // no alternative: must open
        } else {
            score += 60.0 * (fitting_bins_count as f64).min(5.0);
        }
        if mean_residual < 15.0 {
            score -= 90.0;
        }
        // discourage new bin whose leftover can't hold the next item
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            let deadness = (next_item_size - post_residual) as f64 / cap;
            score += 45.0 * deadness * (1.0 + progress);
        }
        // reward opening a bin when item nearly fills it exactly
        if item / cap > 0.9 {
            score -= 300.0 * (item / cap - 0.9) * 10.0;
        }
    } else {
        // OPEN-BIN branch
        if post > 0.0 && post < 4.0 {
            score -= 40.0 + 70.0 * progress; // tiny residuals are gold late
        }
        if next_item_size > 0 && post_residual > 0 {
            let gap = (post - next_item_size as f64).abs();
            if gap < 8.0 {
                score -= 15.0 * progress; // residual close to next item
            }
        }
        if post_residual >= 4 && post_residual < 25 {
            score += 8.0 * (1.0 - progress); // mid-range slivers mildly bad early
        }
    }

    // Slight spread-load preference when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already favored).
    // Strongly reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover2 = post_residual - next_item_size;
        score -= 60.0 + (leftover2 as f64) * 0.3;
        // Perfect chain: item + next fills bin exactly
        if leftover2 == 0 {
            score -= 400.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving a gap next item can't use, scaled by gap size.
        let gap = post_residual as f64;
        score += gap * 0.5;
        // Extra penalty if next item is small enough that gap is pure waste
        if (next_item_size as f64) < gap * 0.5 {
            score += gap * 0.5;
        }
    }

    // Relative-to-mean residual: bins with residual far below mean are tight;
    // filling them is good. Bins above mean residual have slack.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        if rel < 0.5 {
            score -= 30.0; // very tight bin: use it
        } else if rel > 1.5 {
            score += 20.0; // loose bin: keep slack
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize unless current fit is bad
    // or lookahead suggests a better packing in a fresh bin.
    if bin_residual == bin_capacity {
        score += 80.0;
        // Opening a new bin is attractive if this item barely fits elsewhere
        // or if the next item is large and would need a fresh bin anyway.
        if next_item_size > 0 && next_item_size > post_residual && item_size > bin_capacity / 2 {
            score -= 120.0;
        }
    }

    // Early in stream: keep bins open a bit more aggressively consolidated.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 10.0 * (open_bins_count.min(20) as f64).recip();

    // Slight preference for many-open-bins consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

