pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the leftover space: residues divisible by large
    // chunk sizes are more reusable. Reward post_residual in "good" classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit, best possible outcome
    } else {
        // classify residual by gcd-like harmonic classes
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 10.0; }
        else if pr % 10 == 0 { score -= 7.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        // very small unusable slivers are dead space
        if pr < 10 {
            score += 25.0 * (10 - pr) as f64 / 10.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let leftover = pr - next_item_size as f64;
            score -= 12.0 - 0.25 * leftover.min(40.0);
        } else {
            // next item won't fit here: mild penalty proportional to gap
            let gap = (next_item_size as f64 - post).min(50.0);
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins: deviation from mean residual.
    let dev = post - mean_residual;
    score += 0.08 * dev;

    // New-bin candidate handling: opening a new bin is attractive only if
    // this item fits poorly everywhere (post_residual large) and many bins open.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = 55.0;
        // cheaper to open a new bin early when few bins are open
        score -= 3.0 * (open_bins_count.min(8) as f64);
        // if item is large relative to capacity, new bin is fine
        score -= 0.1 * item_size as f64;
        // late in the stream, avoid opening new bins
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // if many bins fit the item, opening new bin is wasteful
        score += 4.0 * (fitting_bins_count as f64);
        // if item leaves a nice reusable residual class, new bin slightly better
        if item_size % 10 == 0 { score -= 5.0; }
    }

    // Tie-break: prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals that are too small to fit typical
    // future items (>= 10) are wasted space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    }

    // Slight preference for bins tighter than the mean residual (better fill).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

